/* STABLE HEADER TYPEWRITER (Step 83)
   Works on both phone and desktop Practice Mode / logged-in Editor.
   Important fix: the animation now uses a canonical session title instead of
   reading the live DOM text while it is typing. This prevents partial text
   like "A" or a single stuck letter from becoming the next animation source. */
let phoneHeaderTypewriterRunId = 0;
let phoneHeaderTypewriterTimer = null;
let phoneHeaderTypewriterLastKey = '';
let desktopHeaderTypewriterRunId = 0;
let desktopHeaderTypewriterTimer = null;
let desktopHeaderTypewriterLastKey = '';
let desktopHeaderLogoSaveSpinTimer = null;

function isPhoneHeaderTypewriterUi() {
  return Boolean(
    document.documentElement.dataset.deviceMode === 'phone' ||
    window.__mcsianPhonePreviewMode === true ||
    window.matchMedia?.('(max-width: 820px)')?.matches
  );
}

function isDesktopHeaderTypewriterUi() {
  const explicitPhone = document.documentElement?.dataset?.deviceMode === 'phone';
  const phonePreview = window.__mcsianPhonePreviewMode === true;
  const desktopWidth = !window.matchMedia || window.matchMedia('(min-width: 821px)').matches;
  return Boolean(!explicitPhone && !phonePreview && desktopWidth);
}

function getHeaderEditorModeForTypewriter() {
  const activeMode = document.body.classList.contains('student-session-active')
    ? 'student'
    : (document.body.classList.contains('guest-session-active') ? 'guest' : '');

  const blocked = activeMode === 'student' && (
    document.body.classList.contains('student-dashboard-active') ||
    document.body.classList.contains('student-auth-open') ||
    document.body.classList.contains('student-route-lock')
  );

  return blocked ? '' : activeMode;
}

/* USER-DIRECTED FIX STEP 84
   Keep the animated header safe when the first + second given names are long.
   The app still uses the first name plus one safe second name; this only makes
   the visible header label shorter when needed so the header buttons/layout do
   not move or wrap. */
function shortenHeaderStudentNameForDisplay(name = '') {
  const clean = String(name || '').replace(/\s+/g, ' ').trim() || 'Student';
  const phoneLimit = 14;
  const desktopLimit = 24;
  const limit = isPhoneHeaderTypewriterUi() ? phoneLimit : desktopLimit;
  if (clean.length <= limit) return clean;

  const [first = clean, second = ''] = clean.split(/\s+/, 2);
  const ellipsis = '...';

  if (isPhoneHeaderTypewriterUi()) {
    const safeFirstLimit = Math.max(6, limit - ellipsis.length);
    return `${first.slice(0, safeFirstLimit)}${ellipsis}`;
  }

  if (second) {
    const availableSecond = Math.max(1, limit - first.length - 1 - ellipsis.length);
    if (first.length + 1 + availableSecond + ellipsis.length <= limit) {
      return `${first} ${second.slice(0, availableSecond)}${ellipsis}`;
    }
  }

  return `${clean.slice(0, Math.max(6, limit - ellipsis.length))}${ellipsis}`;
}

function makeStudentHeaderTitleParts(rawName = '') {
  const fullStudentDisplayName = getStudentFirstName(rawName);
  const visibleStudentDisplayName = shortenHeaderStudentNameForDisplay(fullStudentDisplayName);
  return {
    fullName: fullStudentDisplayName,
    visibleName: visibleStudentDisplayName,
    text: `A tool for ${visibleStudentDisplayName}, Let's Code!`,
    ariaText: `A tool for ${fullStudentDisplayName}, Let's Code!`
  };
}

function makeHeaderTypewriterPayload() {
  const activeMode = getHeaderEditorModeForTypewriter();
  if (!activeMode) return null;

  if (activeMode === 'student' && appSession?.student) {
    const titleParts = makeStudentHeaderTitleParts(appSession.student.name);
    return {
      mode: activeMode,
      text: titleParts.text,
      ariaText: titleParts.ariaText,
      key: `${activeMode}|${titleParts.text}|${titleParts.fullName}`,
      makeFinalNodes() {
        const nameHighlight = document.createElement('span');
        nameHighlight.className = 'header-student-name-highlight';
        nameHighlight.textContent = titleParts.visibleName;
        nameHighlight.title = titleParts.fullName;
        return [
          document.createTextNode('A tool for '),
          nameHighlight,
          document.createTextNode(", Let's Code!")
        ];
      }
    };
  }

  const guestHeaderText = activeMode === 'guest'
    ? 'A tool for every Grade 8 MCSian.'
    : 'ICT 8 Connect';
  return {
    mode: activeMode,
    text: guestHeaderText,
    key: `${activeMode}|${guestHeaderText}`,
    makeFinalNodes() {
      return [document.createTextNode(guestHeaderText)];
    }
  };
}

function setHeaderTypewriterFinalTitle(payload) {
  if (!appTitleText || !payload) return;
  appTitleText.replaceChildren(...payload.makeFinalNodes());
  appTitleText.setAttribute('aria-label', payload.ariaText || payload.text);
}

function stopPhoneHeaderTypewriter(clearKey = false) {
  phoneHeaderTypewriterRunId += 1;
  window.clearTimeout(phoneHeaderTypewriterTimer);
  phoneHeaderTypewriterTimer = null;
  if (clearKey) phoneHeaderTypewriterLastKey = '';
  if (appTitleText) {
    appTitleText.classList.remove('mcs-phone-typewriter-active', 'mcs-phone-typewriter-done');
    delete appTitleText.dataset.mcsPhoneTypewriterKey;
  }
}

function schedulePhoneHeaderTypewriter(force = false) {
  if (!appTitleText) return;

  const payload = makeHeaderTypewriterPayload();
  if (!isPhoneHeaderTypewriterUi() || !payload) {
    stopPhoneHeaderTypewriter(true);
    return;
  }

  const runKey = `phone|${payload.key}`;
  if (force) phoneHeaderTypewriterLastKey = '';

  // If the same phone animation is already running or already finished, do not
  // restart from whatever partial text is currently visible.
  if (!force && runKey === phoneHeaderTypewriterLastKey) {
    return;
  }

  phoneHeaderTypewriterLastKey = runKey;
  const runId = ++phoneHeaderTypewriterRunId;
  window.clearTimeout(phoneHeaderTypewriterTimer);
  phoneHeaderTypewriterTimer = null;

  const fullText = payload.text;
  const typeDelay = fullText.length > 38 ? 24 : 30;
  let index = 0;

  appTitleText.dataset.mcsPhoneTypewriterKey = runKey;
  appTitleText.classList.remove('mcs-phone-typewriter-done');
  appTitleText.classList.add('mcs-phone-typewriter-active');
  appTitleText.setAttribute('aria-label', payload.ariaText || fullText);
  appTitleText.textContent = '';

  const typeNextCharacter = () => {
    if (runId !== phoneHeaderTypewriterRunId) return;
    if (!isPhoneHeaderTypewriterUi() || !makeHeaderTypewriterPayload()) {
      stopPhoneHeaderTypewriter(true);
      return;
    }

    index = Math.min(index + 1, fullText.length);
    appTitleText.textContent = fullText.slice(0, index);

    if (index < fullText.length) {
      const typedChar = fullText.charAt(index - 1);
      const pause = /[,.!]/.test(typedChar) ? 90 : typeDelay;
      phoneHeaderTypewriterTimer = window.setTimeout(typeNextCharacter, pause);
      return;
    }

    setHeaderTypewriterFinalTitle(payload);
    appTitleText.classList.add('mcs-phone-typewriter-done');
    phoneHeaderTypewriterTimer = window.setTimeout(() => {
      if (runId !== phoneHeaderTypewriterRunId) return;
      appTitleText.classList.remove('mcs-phone-typewriter-active', 'mcs-phone-typewriter-done');
      delete appTitleText.dataset.mcsPhoneTypewriterKey;
      phoneHeaderTypewriterTimer = null;
    }, 520);
  };

  phoneHeaderTypewriterTimer = window.setTimeout(typeNextCharacter, force ? 80 : 140);
}

function getDesktopHeaderLogoTargets() {
  if (!isDesktopHeaderTypewriterUi()) return [];
  return Array.from(document.querySelectorAll('.topbar .logo-mark.app-coded-eight'))
    .filter(logo => logo && logo.offsetParent !== null);
}

function isDesktopEditorHeaderActive() {
  if (!isDesktopHeaderTypewriterUi()) return false;
  const guestEditor = document.body.classList.contains('guest-session-active');
  const studentEditor = document.body.classList.contains('student-session-active')
    && !document.body.classList.contains('student-dashboard-active')
    && !document.body.classList.contains('student-auth-open')
    && !document.body.classList.contains('student-route-lock');
  return Boolean(guestEditor || studentEditor);
}

function shouldSpinDesktopLogoForEditorEdit() {
  if (!isDesktopEditorHeaderActive()) return false;
  if (document.body.classList.contains('guest-session-active')) return true;
  return Boolean(isStudentProjectActive() && isStudentAutoSaveAllowed());
}

function triggerDesktopHeaderLogoSaveSpin(options = {}) {
  if (!isDesktopEditorHeaderActive()) return;
  const force = options === true || options?.force === true;
  const now = Date.now();
  if (!force && triggerDesktopHeaderLogoSaveSpin.lastAt && now - triggerDesktopHeaderLogoSaveSpin.lastAt < 140) return;
  triggerDesktopHeaderLogoSaveSpin.lastAt = now;

  const logos = getDesktopHeaderLogoTargets();
  if (!logos.length) return;
  logos.forEach(logo => {
    logo.classList.remove('mcs-desktop-logo-save-spin');
    void logo.offsetWidth;
    logo.classList.add('mcs-desktop-logo-save-spin');
  });
  window.clearTimeout(desktopHeaderLogoSaveSpinTimer);
  desktopHeaderLogoSaveSpinTimer = window.setTimeout(() => {
    getDesktopHeaderLogoTargets().forEach(logo => logo.classList.remove('mcs-desktop-logo-save-spin'));
  }, 1450);
}

function stopDesktopHeaderTypewriter(clearKey = false) {
  desktopHeaderTypewriterRunId += 1;
  window.clearTimeout(desktopHeaderTypewriterTimer);
  desktopHeaderTypewriterTimer = null;
  if (clearKey) desktopHeaderTypewriterLastKey = '';
  if (appTitleText) {
    appTitleText.classList.remove(
      'mcs-desktop-typewriter-looping',
      'mcs-desktop-typewriter-active',
      'mcs-desktop-typewriter-done'
    );
    delete appTitleText.dataset.mcsDesktopTypewriterKey;
    getDesktopHeaderLogoTargets().forEach(logo => logo.classList.remove('mcs-desktop-logo-save-spin'));
  }
}

function scheduleDesktopHeaderTypewriter(force = false) {
  if (!appTitleText) return;

  const payload = makeHeaderTypewriterPayload();
  if (!isDesktopHeaderTypewriterUi() || !payload) {
    stopDesktopHeaderTypewriter(true);
    return;
  }

  const runKey = `desktop|${payload.key}|loop`;
  if (force) desktopHeaderTypewriterLastKey = '';

  // Prevent resize/update events from restarting the loop using partial text.
  if (!force && runKey === desktopHeaderTypewriterLastKey && appTitleText.classList.contains('mcs-desktop-typewriter-looping')) {
    return;
  }

  desktopHeaderTypewriterLastKey = runKey;
  const runId = ++desktopHeaderTypewriterRunId;
  window.clearTimeout(desktopHeaderTypewriterTimer);
  desktopHeaderTypewriterTimer = null;

  const fullText = payload.text;
  const typeDelay = fullText.length > 38 ? 28 : 34;
  const restartDelay = 10000;

  appTitleText.dataset.mcsDesktopTypewriterKey = runKey;
  appTitleText.classList.add('mcs-desktop-typewriter-looping');
  appTitleText.setAttribute('aria-label', payload.ariaText || fullText);

  const startCycle = () => {
    if (runId !== desktopHeaderTypewriterRunId) return;
    const freshPayload = makeHeaderTypewriterPayload();
    if (!isDesktopHeaderTypewriterUi() || !freshPayload || freshPayload.key !== payload.key) {
      stopDesktopHeaderTypewriter(true);
      if (freshPayload) setHeaderTypewriterFinalTitle(freshPayload);
      return;
    }

    let index = 0;
    appTitleText.classList.remove('mcs-desktop-typewriter-done');
    appTitleText.classList.add('mcs-desktop-typewriter-active');
    appTitleText.textContent = '';

    const typeNextCharacter = () => {
      if (runId !== desktopHeaderTypewriterRunId) return;
      const latestPayload = makeHeaderTypewriterPayload();
      if (!isDesktopHeaderTypewriterUi() || !latestPayload || latestPayload.key !== payload.key) {
        stopDesktopHeaderTypewriter(true);
        if (latestPayload) setHeaderTypewriterFinalTitle(latestPayload);
        return;
      }

      index = Math.min(index + 1, fullText.length);
      appTitleText.textContent = fullText.slice(0, index);

      if (index < fullText.length) {
        const typedChar = fullText.charAt(index - 1);
        const pause = /[,.!]/.test(typedChar) ? 110 : typeDelay;
        desktopHeaderTypewriterTimer = window.setTimeout(typeNextCharacter, pause);
        return;
      }

      setHeaderTypewriterFinalTitle(payload);
      appTitleText.classList.remove('mcs-desktop-typewriter-active');
      appTitleText.classList.add('mcs-desktop-typewriter-done');
      desktopHeaderTypewriterTimer = window.setTimeout(startCycle, restartDelay);
    };

    desktopHeaderTypewriterTimer = window.setTimeout(typeNextCharacter, 80);
  };

  desktopHeaderTypewriterTimer = window.setTimeout(startCycle, force ? 90 : 420);
}


function makeIct8ConnectBrandCycleElement(extraClass = '') {
  const wrapper = document.createElement('span');
  wrapper.className = `brand-cycle ${extraClass}`.trim();
  wrapper.setAttribute('aria-label', 'ICT 8 Connect. Learn, Code, Connect');

  const name = document.createElement('span');
  name.className = 'brand-cycle-face brand-cycle-name';
  name.textContent = 'ICT 8 Connect';

  const tagline = document.createElement('span');
  tagline.className = 'brand-cycle-face brand-cycle-tagline';
  tagline.textContent = 'Learn, Code, Connect';

  wrapper.append(name, tagline);
  return wrapper;
}

function renderIct8ConnectBrandTitle() {
  if (!appTitleText) return;
  appTitleText.classList.add('ict8-brand-title');
  appTitleText.replaceChildren(makeIct8ConnectBrandCycleElement());
  appTitleText.setAttribute('aria-label', 'ICT 8 Connect. Learn, Code, Connect');
  if (appSubtitleText) appSubtitleText.textContent = 'Grade 8 ICT learning hub';
}

function updateAppHeaderForSession({ forceTypewriter = false } = {}) {
  const isStudent = appSession.mode === 'student' && appSession.student;
  const isGuest = appSession.mode === 'guest';

  document.body.classList.toggle('student-session-active', isStudent);
  document.body.classList.toggle('guest-session-active', isGuest);
  studentAccountStrip?.classList.toggle('hidden', !isStudent);
  guestAccountStrip?.classList.toggle('hidden', !isGuest);
  studentMenuBtn?.classList.toggle('hidden', !isStudent);
  if (!isStudent) closeStudentAccountMenu();

  if (appTitleText) appTitleText.classList.remove('ict8-brand-title');

  if (isStudent) {
    const titleParts = makeStudentHeaderTitleParts(appSession.student.name);
    const editorGreetingParts = getStudentEditorGreetingParts();
    const editorGreetingText = editorGreetingParts.text;
    if (appTitleText) {
      const nameHighlight = document.createElement('span');
      nameHighlight.className = 'header-student-name-highlight';
      nameHighlight.textContent = titleParts.visibleName;
      nameHighlight.title = titleParts.fullName;
      appTitleText.replaceChildren(
        document.createTextNode('A tool for '),
        nameHighlight,
        document.createTextNode(", Let's Code!")
      );
      appTitleText.setAttribute('aria-label', titleParts.ariaText);
    }
    if (appSubtitleText) appSubtitleText.textContent = 'Developed by Sir JR';
    if (headerStudentGreeting) {
      renderStudentEditorGreeting(headerStudentGreeting, editorGreetingParts);
    }
    if (menuStudentGreeting) {
      renderStudentEditorGreeting(menuStudentGreeting, editorGreetingParts);
    }
    if (!appSession.currentProjectId) studentProjectDirty = false;
    setStudentSaveState(appSession.currentProjectId ? (studentProjectDirty ? 'Unsaved' : 'Saved') : 'Choose a project', studentProjectDirty ? 'unsaved' : '');
  } else if (isGuest) {
    if (appTitleText) appTitleText.textContent = 'A tool for every Grade 8 MCSian.';
    if (appSubtitleText) appSubtitleText.textContent = 'Learn, Code, Connect';
  } else {
    if (appTitleText) appTitleText.textContent = 'A tool for every Grade 8 MCSian.';
    if (appSubtitleText) appSubtitleText.textContent = 'Developed by Sir JR';
  }

  schedulePhoneHeaderTypewriter(forceTypewriter);
  scheduleDesktopHeaderTypewriter(forceTypewriter);
}


function hideAllStudentScreens() {
  studentLoginOverlay?.classList.add('hidden');
  changePasswordOverlay?.classList.add('hidden');
  projectNameOverlay?.classList.add('hidden');
  studentDashboard?.classList.add('hidden');
  document.body.classList.remove('student-auth-open', 'student-dashboard-active');
}

function showEntryGate() {
  hideAllStudentScreens();
  entryGate?.classList.remove('hidden');
  document.body.classList.add('entry-gate-active');
  updateAppHeaderForSession();
}

function hideEntryGate() {
  entryGate?.classList.add('hidden');
  document.body.classList.remove('entry-gate-active');
}

function openStudentLogin() {
  setStudentLoginError('');
  studentLoginOverlay?.classList.remove('hidden');
  document.body.classList.add('student-auth-open');
  window.setTimeout(() => studentLoginId?.focus(), 40);
}

function closeStudentLogin() {
  studentLoginOverlay?.classList.add('hidden');
  document.body.classList.remove('student-auth-open');
}

function showPasswordChange() {
  hideEntryGate();
  studentLoginOverlay?.classList.add('hidden');
  studentDashboard?.classList.add('hidden');
  changePasswordOverlay?.classList.remove('hidden');
  document.body.classList.add('student-auth-open');
  setChangePasswordError('');
  if (studentNewPassword) studentNewPassword.value = '';
  if (studentConfirmPassword) studentConfirmPassword.value = '';
  window.setTimeout(() => studentNewPassword?.focus(), 40);
}

function normalizeProjectCodeByActivity(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return { scratch: normalizeCodeStore(starterCode) };
  }
  if ('html' in raw || 'css' in raw || 'js' in raw || 'files' in raw) {
    return { scratch: normalizeCodeStore(raw) };
  }
  const entries = Object.entries(raw)
    .filter(([, value]) => value && typeof value === 'object')
    .map(([key, value]) => [key || 'scratch', normalizeCodeStore(value)]);
  return entries.length ? Object.fromEntries(entries) : { scratch: normalizeCodeStore(starterCode) };
}

function resetWorkspaceState({ blank = false } = {}) {
  codeByActivity = {};
  selectedActivityId = '';
  activity = null;
  const baseCode = blank ? { html: '', css: '', js: '' } : starterCode;
  codeStore = normalizeCodeStore(baseCode);
  codeByActivity.scratch = normalizeCodeStore(codeStore);
  codeFileNames = normalizeCodeFileNames(DEFAULT_CODE_FILE_NAMES);
  activeLanguage = 'html';
  lastRubricResult = null;
  saveJSON(STORAGE_KEYS.selectedActivityId, '');
  saveCodeByActivity();
  saveCodeFileNames();
  renderActivitySummary();
  renderActivitySelector();
  resetResultPanel();
  loadActiveEditor();
  runCode(false, { scroll: false });
}

function continueAsGuest() {
  appSession.mode = 'guest';
  appSession.student = null;
  appSession.currentProjectId = '';
  appSession.currentProject = null;
  appSession.projects = [];

  // Important: hide the welcome gate before any editor reset work.
  // If reset/render code ever throws, Practice Without Login must still open the editor.
  hideEntryGate();
  hideAllStudentScreens();
  document.body.classList.remove('entry-gate-active', 'student-auth-open', 'student-dashboard-active', 'student-route-lock');
  updateAppHeaderForSession();
  setStatus('Practice mode');

  try {
    resetWorkspaceState();
  } catch (error) {
    console.error('Could not fully reset guest workspace, but practice mode was opened.', error);
    try {
      loadActiveEditor();
      runCode(false, { scroll: false });
    } catch (fallbackError) {
      console.error('Guest fallback render failed.', fallbackError);
    }
  }

  requestAnimationFrame(() => {
    entryGate?.classList.add('hidden');
    document.body.classList.remove('entry-gate-active', 'student-auth-open', 'student-dashboard-active', 'student-route-lock');
  });
}

async function recordStudentLogin() {
  const user = firebaseSync.auth?.currentUser || firebaseSync.currentUser;
  const student = appSession.student;
  if (!user || !student || user.uid !== student.uid) return;
  const sessionKey = `mcsian.student.loginRecorded.${user.uid}`;
  if (sessionStorage.getItem(sessionKey) === '1') return;
  try {
    const { setDoc, serverTimestamp, increment } = firebaseSync.modules;
    await setDoc(getStudentDocRef(user.uid), {
      lastLoginAt: serverTimestamp(),
      lastActivityAt: serverTimestamp(),
      loginCount: increment(1),
      updatedAt: serverTimestamp()
    }, { merge: true });
    sessionStorage.setItem(sessionKey, '1');
    appSession.student.loginCount = Number(appSession.student.loginCount || 0) + 1;
    appSession.student.lastLoginAt = new Date();
    appSession.student.lastActivityAt = new Date();
  } catch (error) {
    console.warn('Could not update student login tracker.', error);
  }
}

async function activateStudentSession(profile, { showDashboard = true } = {}) {
  if (!profile) return;

  // Keep the editor hidden while login is being promoted to the correct
  // student route. Previously, the app removed the login/gate first and
  // then waited for Firebase login tracking, so the editor could flash for
  // a moment before the Projects page appeared.
  document.body.classList.add('student-route-lock');

  appSession.mode = 'student';
  appSession.student = profile;
  appSession.lastStudentProfile = { ...profile };
  appSession.existingStudentUser = getFirebaseActiveUser();
  persistLastStudentSession('student-activated');
  updateAppHeaderForSession();
  startStudentPresenceHeartbeat();

  const loginTracker = recordStudentLogin().catch(error => {
    console.warn('Could not record student login before showing the dashboard.', error);
  });

  try {
    if (profile.mustChangePassword !== false) {
      showPasswordChange();
      await loginTracker;
      return;
    }

    if (showDashboard) {
      await showStudentDashboard();
    } else {
      hideEntryGate();
      closeStudentLogin();
    }
    await loginTracker;
  } finally {
    document.body.classList.remove('student-route-lock');
  }
}

async function deleteCurrentAuthUserQuietly(user) {
  if (!user) return;
  try {
    const deleteUser = firebaseSync.authModule?.deleteUser;
    if (deleteUser) {
      await deleteUser(user);
      return;
    }
    if (typeof user.delete === 'function') await user.delete();
  } catch (error) {
    console.warn('Could not remove an unused student Authentication account.', error);
  }
}

async function createOrRepairStudentProfileFromRoster(user, studentId, existingProfile = null) {
  if (!user) throw new Error('Student account is not available. Try logging in again.');
  const roster = await findStudentRosterRecordById(studentId);
  if (!roster || !areStudentIdsEquivalent(roster.studentId || roster.studentIdNormalized || roster.id, studentId)) {
    throw new Error('This Student ID is not registered in the class list. Ask your teacher to import or add it first.');
  }
  if (roster.accountStatus === 'disabled') {
    throw new Error('This student account is disabled. Ask your teacher for help.');
  }

  const { setDoc, serverTimestamp } = firebaseSync.modules;
  const rosterStudentId = normalizeStudentId(roster.studentId || roster.studentIdNormalized || roster.id || studentId);
  const profile = {
    ...(existingProfile || {}),
    studentId: rosterStudentId,
    studentIdNormalized: rosterStudentId,
    authUid: user.uid,
    authEmail: String(user.email || existingProfile?.authEmail || studentIdToAuthEmail(rosterStudentId)).toLowerCase(),
    name: roster.name || existingProfile?.name || 'Student',
    nameLower: String(roster.name || existingProfile?.name || 'Student').toLowerCase(),
    gender: roster.gender || existingProfile?.gender || '',
    section: roster.section || existingProfile?.section || '',
    sectionLower: String(roster.section || existingProfile?.section || '').toLowerCase(),
    accountStatus: roster.accountStatus || existingProfile?.accountStatus || 'active',
    mustChangePassword: existingProfile && existingProfile.mustChangePassword === false ? false : true,
    loginCount: Number(existingProfile?.loginCount || 0),
    projectCount: Number(existingProfile?.projectCount || 0),
    createdAt: existingProfile?.createdAt || serverTimestamp(),
    updatedAt: serverTimestamp(),
    rosterActivatedAt: existingProfile?.rosterActivatedAt || serverTimestamp(),
    repairedFromRosterAt: serverTimestamp(),
    createdBy: existingProfile?.createdBy || 'student-login-repair'
  };

  const savedProfile = await writeStudentProfileDoc(user, profile, { merge: true, context: 'student profile repair' });
  try {
    await setDoc(getStudentRosterDocRef(rosterStudentId), {
      authUid: user.uid,
      authEmail: profile.authEmail,
      updatedAt: serverTimestamp(),
      profileRepairedAt: serverTimestamp()
    }, { merge: true });
  } catch (rosterUpdateError) {
    console.warn('Student roster repair marker was not updated.', rosterUpdateError);
  }
  return { uid: user.uid, ...savedProfile, updatedAt: new Date() };
}

async function signInStudentWithCandidateEmails(studentId, password, roster = null) {
  const candidates = getStudentAuthEmailCandidates(studentId, roster);
  let lastError = null;
  for (const candidateEmail of candidates) {
    try {
      const credential = await firebaseSync.authModule.signInWithEmailAndPassword(firebaseSync.auth, candidateEmail, password);
      return { credential, authEmail: candidateEmail };
    } catch (error) {
      lastError = error;
      if (!isAuthMissingOrWrongPasswordError(error)) throw error;
    }
  }
  throw lastError || new Error('Student ID or password is incorrect.');
}

async function createFirebaseStudentCredential(studentId) {
  const candidates = getStudentAuthEmailCandidates(studentId);
  let lastEmailInUseError = null;
  for (const candidateEmail of candidates) {
    try {
      const credential = await firebaseSync.authModule.createUserWithEmailAndPassword(firebaseSync.auth, candidateEmail, DEFAULT_STUDENT_PASSWORD);
      return { credential, authEmail: candidateEmail };
    } catch (error) {
      if (isAuthEmailAlreadyInUseError(error)) {
        lastEmailInUseError = error;
        continue;
      }
      throw error;
    }
  }
  const conflictError = new Error('This Student ID has a stuck login record. Ask the teacher to delete or reset the old Firebase Authentication user for this Student ID, then try 123456 again.');
  conflictError.code = 'mcsian/auth-email-conflict';
  conflictError.originalError = lastEmailInUseError;
  throw conflictError;
}

async function createStudentAccountFromRoster(studentId, password) {
  if (password !== DEFAULT_STUDENT_PASSWORD) {
    throw new Error('This Student ID is registered, but the account is not activated yet. Use the default password 123456 first.');
  }
  if (!firebaseSync.authModule?.createUserWithEmailAndPassword) {
    throw new Error('Student account activation is not available yet. Refresh the page and try again.');
  }

  const { credential, authEmail } = await createFirebaseStudentCredential(studentId);
  firebaseSync.currentUser = credential.user;
  let roster = null;
  try {
    roster = await findStudentRosterRecordById(studentId);
    if (!roster || !areStudentIdsEquivalent(roster.studentId || roster.studentIdNormalized || roster.id, studentId)) {
      await deleteCurrentAuthUserQuietly(credential.user);
      throw new Error('This Student ID is not registered in the class list. Ask your teacher to import or add it first.');
    }
    if (roster.accountStatus === 'disabled') {
      await deleteCurrentAuthUserQuietly(credential.user);
      throw new Error('This student account is disabled. Ask your teacher for help.');
    }
    if (roster.authUid && roster.authUid !== credential.user.uid) {
      await deleteCurrentAuthUserQuietly(credential.user);
      throw new Error('This Student ID is already connected to another login. Use the password you created, or ask your teacher for reset help.');
    }

    const { setDoc, serverTimestamp } = firebaseSync.modules;
    const profile = {
      studentId: normalizeStudentId(roster.studentId || roster.studentIdNormalized || roster.id || studentId),
      studentIdNormalized: normalizeStudentId(roster.studentId || roster.studentIdNormalized || roster.id || studentId),
      authUid: credential.user.uid,
      authEmail,
      name: roster.name || 'Student',
      nameLower: String(roster.name || 'Student').toLowerCase(),
      gender: roster.gender || '',
      section: roster.section || '',
      sectionLower: String(roster.section || '').toLowerCase(),
      accountStatus: roster.accountStatus || 'active',
      mustChangePassword: true,
      loginCount: 0,
      projectCount: 0,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
      rosterActivatedAt: serverTimestamp(),
      createdBy: 'student-first-login'
    };
    await writeStudentProfileDoc(credential.user, profile, { merge: false, context: 'student first login' });
    try {
      await setDoc(getStudentRosterDocRef(profile.studentIdNormalized || studentId), {
        authUid: credential.user.uid,
        authEmail,
        authCreatedAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      }, { merge: true });
    } catch (rosterUpdateError) {
      console.warn('Student roster activation marker was not updated.', rosterUpdateError);
    }
    return { uid: credential.user.uid, ...profile, createdAt: new Date(), updatedAt: new Date() };
  } catch (error) {
    if (firebaseSync.auth?.currentUser?.uid === credential.user?.uid) {
      try { await firebaseSync.authModule.signOut(firebaseSync.auth); } catch (_) {}
    }
    throw error;
  }
}

function getStudentAuthErrorMessage(error) {
  const code = String(error?.code || '');
  if (code.includes('mcsian/auth-email-conflict')) return 'This Student ID has a stuck login record. Ask your teacher to delete or reset the old Firebase Authentication user, then try 123456 again.';
  if (code.includes('email-already-in-use')) return 'This Student ID already has an activated account. Log in using the new password you created.';
  if (code.includes('weak-password')) return 'The password must contain at least 6 characters.';
  if (code.includes('invalid-credential') || code.includes('wrong-password') || code.includes('user-not-found')) {
    return 'Student ID or password is incorrect. New accounts use 123456 as the default password.';
  }
  if (code.includes('too-many-requests')) return 'Too many login attempts. Wait a few minutes and try again.';
  if (code.includes('network-request-failed')) return 'Internet connection problem. Please reconnect and try again.';
  if (code.includes('operation-not-allowed')) return 'Student login is not enabled yet. The teacher must enable Email/Password in Firebase Authentication.';
  if (code.includes('unauthorized-domain')) return 'This website domain must be added to Firebase Authentication authorized domains.';
  if (isFirestorePermissionError(error)) return 'Login setup was blocked by Firestore permissions. Refresh after uploading the latest files, then try again with 123456. If it still appears, ask the teacher to publish the updated firestore.rules.';
  return error?.message || 'Login failed. Check your Student ID and password.';
}

async function loginStudent() {
  setStudentLoginError('');
  const studentId = normalizeStudentId(studentLoginId?.value);
  const password = String(studentLoginPassword?.value || '');
  const authEmail = studentIdToAuthEmail(studentId);
  if (!studentId || !password) {
    setStudentLoginError('Enter your Student ID and password.');
    return;
  }
  if (!authEmail) {
    setStudentLoginError('Student ID is invalid.');
    return;
  }
  const ready = await initFirebaseSync();
  if (!ready || !firebaseSync.authModule) {
    setStudentLoginError('Firebase is not ready. Check the internet connection and try again.');
    return;
  }
  try {
    if (studentLoginBtn) {
      studentLoginBtn.disabled = true;
      studentLoginBtn.textContent = 'Logging in...';
    }
    let credential = null;
    let profile = null;
    try {
      const signedIn = await signInStudentWithCandidateEmails(studentId, password);
      credential = signedIn.credential;
      firebaseSync.currentUser = credential.user;
      profile = await loadStudentProfile(credential.user.uid);
      if (!profile) {
        profile = await createOrRepairStudentProfileFromRoster(credential.user, studentId, null);
      } else if (!areStudentIdsEquivalent(profile.studentId || profile.studentIdNormalized, studentId)) {
        const sameAuthEmail = getStudentAuthEmailCandidates(studentId).includes(String(profile.authEmail || '').toLowerCase());
        if (sameAuthEmail || areStudentIdsEquivalent(profile.studentIdNormalized, studentId)) {
          profile = await createOrRepairStudentProfileFromRoster(credential.user, studentId, profile);
        }
      }
    } catch (signInError) {
      if (!isAuthMissingOrWrongPasswordError(signInError)) throw signInError;
      if (password !== DEFAULT_STUDENT_PASSWORD) throw signInError;
      profile = await createStudentAccountFromRoster(studentId, password);
    }
    if (!profile || !areStudentIdsEquivalent(profile.studentId || profile.studentIdNormalized, studentId)) {
      await firebaseSync.authModule.signOut(firebaseSync.auth);
      throw new Error('This login has no registered student profile. Ask your teacher to register the Student ID again.');
    }
    if (profile.accountStatus === 'disabled') {
      await firebaseSync.authModule.signOut(firebaseSync.auth);
      throw new Error('This student account is disabled. Ask your teacher for help.');
    }
    if (studentLoginPassword) studentLoginPassword.value = '';
    await activateStudentSession(profile);
  } catch (error) {
    console.error('Student login failed', error);
    setStudentLoginError(getStudentAuthErrorMessage(error));
  } finally {
    if (studentLoginBtn) {
      studentLoginBtn.disabled = false;
      studentLoginBtn.textContent = 'Log In';
    }
  }
}

async function saveStudentNewPassword() {
  setChangePasswordError('');
  const newPassword = String(studentNewPassword?.value || '');
  const confirmPassword = String(studentConfirmPassword?.value || '');
  if (newPassword.length < 6) {
    setChangePasswordError('Password must contain at least 6 characters.');
    return;
  }
  if (newPassword === DEFAULT_STUDENT_PASSWORD) {
    setChangePasswordError('Choose a password different from the default 123456.');
    return;
  }
  if (newPassword !== confirmPassword) {
    setChangePasswordError('The two passwords do not match.');
    return;
  }
  const user = firebaseSync.auth?.currentUser || firebaseSync.currentUser;
  if (!user || !appSession.student) {
    setChangePasswordError('Your login session expired. Log in again.');
    return;
  }
  try {
    saveNewPasswordBtn.disabled = true;
    saveNewPasswordBtn.textContent = 'Saving...';
    await firebaseSync.authModule.updatePassword(user, newPassword);
    const { setDoc, serverTimestamp } = firebaseSync.modules;
    await setDoc(getStudentDocRef(user.uid), {
      mustChangePassword: false,
      passwordChangedAt: serverTimestamp(),
      updatedAt: serverTimestamp()
    }, { merge: true });
    appSession.student.mustChangePassword = false;
    changePasswordOverlay?.classList.add('hidden');
    document.body.classList.remove('student-auth-open');
    await showStudentDashboard();
  } catch (error) {
    console.error('Could not update student password', error);
    setChangePasswordError(error?.code === 'auth/requires-recent-login'
      ? 'Please log out and log in again before changing the password.'
      : (error?.message || 'Could not change the password. Try again.'));
  } finally {
    saveNewPasswordBtn.disabled = false;
    saveNewPasswordBtn.textContent = 'Save New Password';
  }
}

async function handleStudentAuthObserver(user) {
  appSession.authReady = true;
  if (!user) {
    if (appSession.mode === 'student') {
      persistLastStudentSession('firebase-signed-out');
      stopStudentPresenceHeartbeat();
      appSession.mode = 'pending';
      appSession.student = null;
      appSession.currentProjectId = '';
      appSession.currentProject = null;
      showEntryGate();
    }
    const cachedProfile = getLastStudentProfile();
    if (cachedProfile) {
      if (resumeStudentText) resumeStudentText.textContent = `Continue as ${getStudentFirstName(cachedProfile.name)}`;
      resumeStudentBtn?.classList.remove('hidden');
    } else {
      appSession.existingStudentUser = null;
      resumeStudentBtn?.classList.add('hidden');
    }
    return;
  }

  if (isAllowedTeacherEmail(user.email)) {
    const cachedProfile = getLastStudentProfile();
    if (cachedProfile) {
      appSession.lastStudentProfile = { ...cachedProfile };
      if (resumeStudentText) resumeStudentText.textContent = `Continue as ${getStudentFirstName(cachedProfile.name)}`;
      resumeStudentBtn?.classList.remove('hidden');
    } else {
      resumeStudentBtn?.classList.add('hidden');
    }
    return;
  }
  try {
    const profile = await loadStudentProfile(user.uid);
    if (!profile) {
      resumeStudentBtn?.classList.add('hidden');
      return;
    }
    appSession.existingStudentUser = user;
    if (appSession.mode !== 'student') appSession.student = profile;
    if (resumeStudentText) resumeStudentText.textContent = `Continue as ${getStudentFirstName(profile.name)}`;
    resumeStudentBtn?.classList.remove('hidden');
  } catch (error) {
    console.warn('Could not prepare saved student session.', error);
  }
}

async function resumeExistingStudentSession() {
  const user = getFirebaseActiveUser() || appSession.existingStudentUser;
  if (user && isTeacherUser(user)) {
    const cachedProfile = getLastStudentProfile();
    if (cachedProfile?.uid) {
      await activateStudentSession(cachedProfile);
      return;
    }
    openStudentLogin();
    return;
  }
  if (!user) {
    const cachedProfile = getLastStudentProfile();
    if (cachedProfile?.studentId && studentLoginId) studentLoginId.value = cachedProfile.studentId;
    openStudentLogin();
    return;
  }
  const profile = await loadStudentProfile(user.uid);
  if (!profile) {
    openStudentLogin();
    return;
  }
  await activateStudentSession(profile);
}

async function logoutStudent() {
  const hasPendingSave = Boolean(studentProjectDirty || studentProjectSaveTimer || studentProjectSaveInFlight || studentProjectSaveQueued);
  if (hasPendingSave && appSession.mode === 'student' && appSession.currentProjectId) {
    const shouldContinue = await appConfirm('Some recent changes may still be saving. Save now and log out?', {
      title: 'Log out safely',
      confirmText: 'Save & Log Out'
    });
    if (!shouldContinue) return;
  }
  try {
    clearTimeout(studentProjectSaveTimer);
    if (appSession.mode === 'student' && appSession.currentProjectId) {
      const saved = await flushStudentProjectSave('logout');
      if (!saved && navigator.onLine !== false) {
        const leaveAnyway = await appConfirm('The cloud save did not finish. A recovery copy is safe on this device. Log out anyway?', {
          title: 'Cloud save incomplete',
          confirmText: 'Log Out Anyway',
          danger: true
        });
        if (!leaveAnyway) return;
      }
    }
  } catch (error) {
    console.warn('Final student save skipped.', error);
  }
  try {
    if (appSession.mode === 'student' && appSession.student?.uid) {
      await writeStudentPresence({ currentView: 'signed_out', activityGroup: 'Signed out', activityLabel: 'Signed out' }, { force: true, critical: true });
    }
  } catch (error) {
    console.warn('Student sign-out presence update skipped.', error);
  }
  try {
    if (firebaseSync.auth && firebaseSync.authModule) await firebaseSync.authModule.signOut(firebaseSync.auth);
  } catch (error) {
    console.warn('Student logout failed.', error);
  }
  stopStudentPresenceHeartbeat();
  appSession.mode = 'pending';
  appSession.student = null;
  appSession.existingStudentUser = null;
  appSession.lastStudentProfile = null;
  try { localStorage.removeItem(LAST_STUDENT_SESSION_KEY); } catch (_) {}
  appSession.currentProjectId = '';
  appSession.currentProject = null;
  appSession.projects = [];
  resumeStudentBtn?.classList.add('hidden');
  updateAppHeaderForSession();
  showEntryGate();
}

async function showStudentDashboard() {
  if (!appSession.student) {
    openStudentLogin();
    return;
  }
  hideEntryGate();
  studentLoginOverlay?.classList.add('hidden');
  changePasswordOverlay?.classList.add('hidden');
  projectNameOverlay?.classList.add('hidden');
  document.body.classList.remove('student-auth-open');
  studentDashboard?.classList.remove('hidden');
  document.body.classList.add('student-dashboard-active');
  const firstName = getStudentFirstName(appSession.student.name);
  if (dashboardGreeting) dashboardGreeting.textContent = `Hi, ${firstName}! Your saved work is ready.`;
  queueStudentPresenceUpdate({ currentView: 'dashboard', activityGroup: 'My Projects', activityLabel: 'On My Projects' }, { force: true });
  await Promise.allSettled([
    loadStudentProjects(),
    loadStudentComplianceStatus()
  ]);
}

function closeStudentDashboard() {
  studentDashboard?.classList.add('hidden');
  document.body.classList.remove('student-dashboard-active');
}

async function loadStudentProjects(options = {}) {
  const student = appSession.student;
  if (!student) return [];
  const ready = await initFirebaseSync();
  if (!ready) {
    if (projectDashboardStatus) projectDashboardStatus.textContent = 'Could not connect to saved projects.';
    return [];
  }
  try {
    if (projectDashboardStatus) projectDashboardStatus.textContent = 'Loading projects...';
    const { getDocs } = firebaseSync.modules;
    const projectDocs = await withSelectiveFirestoreCache(`studentProjects:${student.uid}`, SELECTIVE_CACHE_SHORT_MS, async () => {
      const snapshot = await withTimeout(
        getDocs(getStudentProjectsCollectionRef(student.uid)),
        APP_NETWORK_TIMEOUT_MS,
        'Loading projects is taking too long. Please check the internet connection, then try again.'
      );
      return (snapshot.docs || []).map(docSnapshot => ({
        id: docSnapshot.id,
        ...snapshotData(docSnapshot)
      }));
    }, options);
    appSession.projects = projectDocs.map(project => ({ ...project })).sort((a, b) => {
      const aTime = timestampToDate(a.updatedAt)?.getTime() || 0;
      const bTime = timestampToDate(b.updatedAt)?.getTime() || 0;
      return bTime - aTime;
    });
    persistStudentProjectsCache();
    renderStudentProjects();
    return appSession.projects;
  } catch (error) {
    console.error('Could not load projects', error);
    const cachedProjects = loadStudentProjectsCache();
    if (cachedProjects.length) {
      appSession.projects = cachedProjects;
      renderStudentProjects();
      if (projectDashboardStatus) projectDashboardStatus.textContent = `Offline copy · ${cachedProjects.length} project${cachedProjects.length === 1 ? '' : 's'}`;
      setStatus('Showing saved offline copy');
      return cachedProjects;
    }
    if (projectDashboardStatus) projectDashboardStatus.textContent = error?.message || 'Could not load projects. Check the internet connection.';
    studentProjectsGrid.innerHTML = `<div class="empty-projects-card"><h3>Projects unavailable</h3><p>${escapeHTML(error?.message || 'Please reconnect and refresh.')}</p><button class="primary-btn" type="button" data-project-action="retry-load">Try Again</button></div>`;
    return [];
  }
}

function getProjectStatus(project) {
  if (project?.lastResult?.passed === true || project?.status === 'passed') return 'passed';
  if (project?.lastResult || project?.status === 'checked') return 'checked';
  return 'in-progress';
}

function getProjectStatusLabel(status) {
  if (status === 'passed') return 'Passed';
  if (status === 'checked') return 'Checked';
  return 'In Progress';
}


function getLatestTeacherCommentRecord(project = {}) {
  const records = [];
  if (typeof project.teacherComment === 'string' && project.teacherComment.trim()) {
    records.push({ text: project.teacherComment, updatedAt: project.teacherCommentUpdatedAt || project.updatedAt, activityTitle: 'Project comment' });
  }
  const comments = project.teacherComments && typeof project.teacherComments === 'object' ? project.teacherComments : {};
  Object.entries(comments).forEach(([key, value]) => {
    const record = typeof value === 'string' ? { text: value } : value;
    if (!record || typeof record !== 'object' || !String(record.text || '').trim()) return;
    records.push({
      ...record,
      activityKey: key,
      activityTitle: record.activityTitle || (key === 'scratch' ? 'Practice project' : getActivityById(key)?.title || 'Project activity')
    });
  });
  if (!records.length) return null;
  records.sort((a, b) => {
    const aTime = timestampToDate(a.updatedAt)?.getTime() || 0;
    const bTime = timestampToDate(b.updatedAt)?.getTime() || 0;
    return bTime - aTime;
  });
  return records[0] || null;
}

function getProjectRecoveryInfo(project = {}) {
  if (!project?.id) return null;
  const recovery = getStudentProjectRecovery(project.id);
  if (!recovery?.payload) return null;
  const cloudTime = getProjectUpdatedAtMs(project);
  const recoveryTime = Number(recovery.savedAt || 0);
  if (recoveryTime <= cloudTime + 1000) return null;
  return {
    ...recovery,
    savedText: formatStudentDate(recoveryTime, 'local backup')
  };
}

function updateStudentDashboardSaveFeedbackPanel() {
  if (!dashboardSaveFeedbackPanel) return;
  const hasProjects = Array.isArray(appSession.projects) && appSession.projects.length > 0;
  dashboardSaveFeedbackPanel.classList.toggle('hidden', !appSession.student);
  if (!appSession.student) return;

  const recoveryProjects = (appSession.projects || []).filter(project => getProjectRecoveryInfo(project));
  const feedbackProjects = (appSession.projects || []).filter(project => getLatestTeacherCommentRecord(project));
  const activeProjectName = appSession.currentProject?.name || appSession.projects?.find?.(project => project.id === appSession.currentProjectId)?.name || '';
  const saveText = String(studentSaveState?.textContent || '').trim() || (appSession.currentProjectId ? (studentProjectDirty ? 'Unsaved' : 'Saved') : 'No project open');

  if (dashboardSaveStatusTitle) {
    dashboardSaveStatusTitle.textContent = recoveryProjects.length ? 'Recovery Backup Available' : 'Save Status';
  }
  if (dashboardSaveStatusText) {
    if (recoveryProjects.length) {
      const names = recoveryProjects.slice(0, 2).map(project => project.name || 'Untitled Project').join(', ');
      dashboardSaveStatusText.textContent = `${recoveryProjects.length} project${recoveryProjects.length === 1 ? '' : 's'} have a newer local backup${names ? `: ${names}` : ''}. Open the project to restore it.`;
    } else if (appSession.currentProjectId) {
      dashboardSaveStatusText.textContent = `${activeProjectName ? `${activeProjectName}: ` : ''}${saveText}. Local recovery is active while you work.`;
    } else if (hasProjects) {
      dashboardSaveStatusText.textContent = 'Your project list is loaded. Open a project to see live save status.';
    } else {
      dashboardSaveStatusText.textContent = 'Create a project and your work will be protected with auto-save and local recovery.';
    }
  }

  if (dashboardFeedbackTitle) {
    dashboardFeedbackTitle.textContent = feedbackProjects.length ? 'Teacher Feedback Available' : 'Teacher Feedback';
  }
  if (dashboardFeedbackText) {
    if (feedbackProjects.length) {
      const latest = feedbackProjects
        .map(project => ({ project, record: getLatestTeacherCommentRecord(project) }))
        .sort((a, b) => (timestampToDate(b.record?.updatedAt)?.getTime() || 0) - (timestampToDate(a.record?.updatedAt)?.getTime() || 0))[0];
      const latestName = latest?.project?.name || 'a project';
      const latestTime = timestampToDate(latest?.record?.updatedAt);
      dashboardFeedbackText.textContent = `${feedbackProjects.length} project${feedbackProjects.length === 1 ? '' : 's'} with teacher feedback. Latest: ${latestName}${latestTime ? ` · ${formatStudentDate(latestTime)}` : ''}.`;
    } else {
      dashboardFeedbackText.textContent = 'No teacher project comments yet. New feedback will show here and on the project card.';
    }
  }
}


