let adminProjectViewerState = {
  student: null,
  projects: [],
  project: null,
  codeByActivity: {},
  activityKey: 'scratch',
  language: 'html'
};

function getAdminProjectActivityLabel(key, project = adminProjectViewerState.project) {
  if (!key) return 'Practice project';
  const activityTitle = project?.activityTitle || '';
  if (key === project?.selectedActivityId && activityTitle) return activityTitle;
  if (key === 'scratch') return 'Practice project';
  const knownActivity = activities.find(item => item.id === key);
  return knownActivity?.title || key;
}

function getAdminProjectActiveStore() {
  const stores = adminProjectViewerState.codeByActivity || {};
  const key = stores[adminProjectViewerState.activityKey] ? adminProjectViewerState.activityKey : Object.keys(stores)[0] || 'scratch';
  adminProjectViewerState.activityKey = key;
  return stores[key] || normalizeCodeStore(starterCode);
}

function getAdminProjectFileMap(language, store = getAdminProjectActiveStore()) {
  if (language === 'css') return store.cssFiles && typeof store.cssFiles === 'object' ? store.cssFiles : { [DEFAULT_CODE_FILE_NAMES.css]: store.css || '' };
  if (language === 'js') return store.jsFiles && typeof store.jsFiles === 'object' ? store.jsFiles : { [DEFAULT_CODE_FILE_NAMES.js]: store.js || '' };
  return store.pages && typeof store.pages === 'object' ? store.pages : { [DEFAULT_CODE_FILE_NAMES.html]: store.html || '' };
}

function getAdminProjectFileNames(language, store = getAdminProjectActiveStore()) {
  const meta = getLanguageFileMeta(language);
  const files = getAdminProjectFileMap(language, store);
  const names = Object.keys(files || {}).sort((a, b) => {
    if (a === meta.defaultName) return -1;
    if (b === meta.defaultName) return 1;
    return a.localeCompare(b);
  });
  return names.length ? names : [meta.defaultName];
}

function getAdminProjectActiveFileName(language = adminProjectViewerState.language) {
  const store = getAdminProjectActiveStore();
  if (language === 'css') return store.activeCssFile && getAdminProjectFileMap('css', store)[store.activeCssFile] !== undefined ? store.activeCssFile : getAdminProjectFileNames('css', store)[0];
  if (language === 'js') return store.activeJsFile && getAdminProjectFileMap('js', store)[store.activeJsFile] !== undefined ? store.activeJsFile : getAdminProjectFileNames('js', store)[0];
  return store.activeHtmlPage && getAdminProjectFileMap('html', store)[store.activeHtmlPage] !== undefined ? store.activeHtmlPage : getAdminProjectFileNames('html', store)[0];
}

function setAdminProjectActiveFileName(language, name) {
  const store = getAdminProjectActiveStore();
  if (language === 'css') store.activeCssFile = name;
  else if (language === 'js') store.activeJsFile = name;
  else store.activeHtmlPage = name;
}

function createAdminProjectStyleBlock(store) {
  const cssFiles = getAdminProjectFileMap('css', store);
  return Object.entries(cssFiles || {})
    .filter(([, css]) => typeof css === 'string' && css.trim())
    .map(([name, css]) => `<style data-admin-file="${escapeAttribute(name)}">\n${css}\n</style>`)
    .join('\n');
}

function createAdminProjectScriptBlock(store) {
  const jsFiles = getAdminProjectFileMap('js', store);
  return Object.entries(jsFiles || {})
    .filter(([, js]) => typeof js === 'string' && js.trim())
    .map(([name, js]) => `<script data-admin-file="${escapeAttribute(name)}">\n${String(js).replace(/<\/script/gi, '<\\/script')}\n<\/script>`)
    .join('\n');
}

function buildAdminProjectPreviewCode(pageName = '') {
  const store = getAdminProjectActiveStore();
  const pages = getAdminProjectFileMap('html', store);
  const safePageName = pageName && pages[pageName] !== undefined ? pageName : getAdminProjectActiveFileName('html');
  const rawHtml = stripAppPreviewHelperLeak(String(pages[safePageName] || ''));
  const styleBlock = createAdminProjectStyleBlock(store);
  const scriptBlock = createAdminProjectScriptBlock(store);
  const looksLikeFullDocument = /<!doctype/i.test(rawHtml) || /<html(\s|>)/i.test(rawHtml) || /<head(\s|>)/i.test(rawHtml) || /<body(\s|>)/i.test(rawHtml);
  const hasCompleteDocumentShell = hasCompletePreviewDocumentShell(rawHtml);

  if (looksLikeFullDocument && hasCompleteDocumentShell) {
    return injectAssetsIntoHTML(injectRuntimeReporterEarly(rawHtml, ''), styleBlock, scriptBlock);
  }

  if (looksLikeFullDocument && !hasCompleteDocumentShell) {
    return injectAssetsIntoHTML(rawHtml, styleBlock, scriptBlock);
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  ${styleBlock}
</head>
<body>
${rawHtml}
${scriptBlock}
</body>
</html>`;
}

function runAdminProjectViewerPreview(pageName = '') {
  if (!adminProjectViewerFrame) return;
  const store = getAdminProjectActiveStore();
  const page = pageName || getAdminProjectActiveFileName('html');
  adminProjectViewerFrame.srcdoc = buildAdminProjectPreviewCode(page);
  adminProjectViewerFrame.dataset.currentPage = page;
  if (adminProjectViewerPreviewNote) adminProjectViewerPreviewNote.textContent = `Previewing ${page}`;
}

function getAdminProjectViewerCurrentCodeDetails() {
  const language = adminProjectViewerState.language || 'html';
  const fileName = getAdminProjectActiveFileName(language);
  const files = getAdminProjectFileMap(language);
  const content = typeof files[fileName] === 'string' ? files[fileName] : '';
  return { language, fileName, content };
}

function openAdminProjectFullscreen(mode = 'code') {
  if (!adminProjectFullscreenOverlay) return;
  const project = adminProjectViewerState.project || {};
  const student = adminProjectViewerState.student || {};
  const isPreview = mode === 'preview';
  const codeDetails = getAdminProjectViewerCurrentCodeDetails();
  const activePage = getAdminProjectActiveFileName('html');

  if (adminProjectFullscreenKicker) adminProjectFullscreenKicker.textContent = isPreview ? 'Full Output Preview' : 'Full Code View';
  if (adminProjectFullscreenTitle) adminProjectFullscreenTitle.textContent = project.name || 'Student Project';
  if (adminProjectFullscreenSubtitle) {
    const owner = student.name || 'Student';
    const subject = isPreview ? `Previewing ${activePage}` : `${codeDetails.language.toUpperCase()} · ${codeDetails.fileName}`;
    adminProjectFullscreenSubtitle.textContent = `${owner} · ${subject}`;
  }

  adminProjectFullscreenCodePanel?.classList.toggle('hidden', isPreview);
  adminProjectFullscreenPreviewPanel?.classList.toggle('hidden', !isPreview);

  if (isPreview) {
    if (adminProjectFullscreenFrame) {
      adminProjectFullscreenFrame.srcdoc = buildAdminProjectPreviewCode(activePage);
      adminProjectFullscreenFrame.dataset.currentPage = activePage;
    }
    if (adminProjectFullscreenPreviewNote) adminProjectFullscreenPreviewNote.textContent = `Previewing ${activePage}`;
  } else {
    if (adminProjectFullscreenFrame) adminProjectFullscreenFrame.srcdoc = '';
    if (adminProjectFullscreenCodeTitle) adminProjectFullscreenCodeTitle.textContent = codeDetails.fileName || 'Code';
    if (adminProjectFullscreenCode) adminProjectFullscreenCode.textContent = codeDetails.content || '/* Blank file */';
  }

  adminProjectFullscreenOverlay.classList.remove('hidden');
  document.body.classList.add('student-auth-open', 'admin-project-fullscreen-open');
}

function closeAdminProjectFullscreen() {
  adminProjectFullscreenOverlay?.classList.add('hidden');
  if (adminProjectFullscreenFrame) adminProjectFullscreenFrame.srcdoc = '';
  document.body.classList.remove('admin-project-fullscreen-open');
  const viewerOpen = Boolean(adminProjectViewerOverlay && !adminProjectViewerOverlay.classList.contains('hidden'));
  const trackerOpen = Boolean(adminStudentProjectsOverlay && !adminStudentProjectsOverlay.classList.contains('hidden'));
  document.body.classList.toggle('student-auth-open', viewerOpen || trackerOpen);
}

function attachAdminProjectViewerPreviewLinks() {
  if (!adminProjectViewerFrame) return;
  let doc = null;
  try {
    doc = adminProjectViewerFrame.contentDocument || adminProjectViewerFrame.contentWindow?.document || null;
  } catch (error) {
    doc = null;
  }
  if (!doc || doc.__adminProjectViewerLinksReady) return;
  doc.__adminProjectViewerLinksReady = true;
  doc.addEventListener('click', event => {
    const link = event.target && event.target.closest ? event.target.closest('a[href]') : null;
    if (!link) return;
    const href = String(link.getAttribute('href') || '').trim();
    if (!href || /^(https?:|mailto:|tel:|javascript:|data:|blob:|#)/i.test(href)) return;
    const fileName = href.split('#')[0].split('?')[0].split('/').pop();
    if (!/\.html?$/i.test(fileName)) return;
    const page = cleanLanguageFileName(fileName, 'html');
    const pages = getAdminProjectFileMap('html');
    if (!hasOwnFile(pages, page)) return;
    event.preventDefault();
    setAdminProjectActiveFileName('html', page);
    populateAdminProjectViewerFileSelect();
    updateAdminProjectViewerCode();
    runAdminProjectViewerPreview(page);
  }, true);
}

function populateAdminProjectViewerActivitySelect() {
  if (!adminProjectViewerActivitySelect) return;
  const stores = adminProjectViewerState.codeByActivity || {};
  const keys = Object.keys(stores).length ? Object.keys(stores) : ['scratch'];
  adminProjectViewerActivitySelect.innerHTML = keys.map(key => `<option value="${escapeAttribute(key)}">${escapeHTML(getAdminProjectActivityLabel(key))}</option>`).join('');
  adminProjectViewerActivitySelect.value = keys.includes(adminProjectViewerState.activityKey) ? adminProjectViewerState.activityKey : keys[0];
  adminProjectViewerState.activityKey = adminProjectViewerActivitySelect.value;
}

function populateAdminProjectViewerFileSelect() {
  if (!adminProjectViewerFileSelect) return;
  const language = adminProjectViewerState.language;
  const names = getAdminProjectFileNames(language);
  const active = getAdminProjectActiveFileName(language);
  adminProjectViewerFileSelect.innerHTML = names.map(name => `<option value="${escapeAttribute(name)}">${escapeHTML(name)}</option>`).join('');
  adminProjectViewerFileSelect.value = names.includes(active) ? active : names[0];
  setAdminProjectActiveFileName(language, adminProjectViewerFileSelect.value);
}

function updateAdminProjectViewerLanguageTabs() {
  if (!adminProjectViewerLangTabs) return;
  const language = adminProjectViewerState.language;
  adminProjectViewerLangTabs.querySelectorAll('[data-admin-viewer-lang]').forEach(button => {
    const active = button.dataset.adminViewerLang === language;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', active ? 'true' : 'false');
  });
}

function updateAdminProjectViewerCode() {
  const language = adminProjectViewerState.language;
  const fileName = getAdminProjectActiveFileName(language);
  const files = getAdminProjectFileMap(language);
  const content = typeof files[fileName] === 'string' ? files[fileName] : '';
  if (adminProjectViewerFileTitle) adminProjectViewerFileTitle.textContent = fileName;
  if (adminProjectViewerCode) adminProjectViewerCode.textContent = content || '/* Blank file */';
  populateAdminProjectViewerFileSelect();
  updateAdminProjectViewerLanguageTabs();
}


function getAdminProjectCommentKey() {
  return adminProjectViewerState.activityKey || 'scratch';
}

function getAdminProjectCommentRecord(key = getAdminProjectCommentKey()) {
  const project = adminProjectViewerState.project || {};
  const comments = project.teacherComments && typeof project.teacherComments === 'object' ? project.teacherComments : {};
  const record = comments[key] || comments.scratch || null;
  if (record && typeof record === 'object') return record;
  if (typeof record === 'string') return { text: record };
  if (typeof project.teacherComment === 'string' && project.teacherComment.trim()) return { text: project.teacherComment };
  return { text: '' };
}

function getAdminProjectCommentUpdatedText(record) {
  const updatedAt = timestampToDate(record?.updatedAt);
  if (!record?.text) return 'No comment yet';
  return updatedAt ? `Saved ${formatStudentDate(updatedAt)}` : 'Saved';
}

function setAdminProjectCommentStatus(message, tone = '') {
  if (!adminProjectCommentStatus) return;
  adminProjectCommentStatus.textContent = message || '';
  adminProjectCommentStatus.classList.toggle('saving', tone === 'saving');
  adminProjectCommentStatus.classList.toggle('saved', tone === 'saved');
  adminProjectCommentStatus.classList.toggle('error', tone === 'error');
}

function renderAdminProjectTeacherComment() {
  const record = getAdminProjectCommentRecord();
  if (adminProjectTeacherComment) adminProjectTeacherComment.value = record?.text || '';
  setAdminProjectCommentStatus(getAdminProjectCommentUpdatedText(record), record?.text ? 'saved' : '');
}

function setAdminAiReviewStatus(message, tone = '') {
  if (!adminAiReviewStatus) return;
  adminAiReviewStatus.textContent = message || '';
  adminAiReviewStatus.classList.remove('running', 'ready', 'error');
  if (tone) adminAiReviewStatus.classList.add(tone);
}

function resetAdminAiReviewPanel() {
  adminLatestAiReview = null;
  if (adminSaveAiReviewBtn) adminSaveAiReviewBtn.disabled = true;
  if (adminUseAiFeedbackBtn) adminUseAiFeedbackBtn.disabled = true;
  if (adminApplyAiScoreBtn) adminApplyAiScoreBtn.disabled = true;
  setAdminAiReviewStatus('Not reviewed');
  if (adminAiReviewOutput) {
    adminAiReviewOutput.innerHTML = `
      <div class="admin-ai-empty">
        <strong>No smart review yet.</strong>
        <p>Run the project preview first, then click Smart Review. The result will stay teacher-controlled.</p>
      </div>`;
  }
}

function renderSavedAdminAiReviewForCurrentProject() {
  const project = adminProjectViewerState.project || {};
  const key = getAdminProjectCommentKey();
  const reviews = project.aiRubricReviews && typeof project.aiRubricReviews === 'object' ? project.aiRubricReviews : {};
  const saved = reviews[key] || reviews.scratch || null;
  if (saved && typeof saved === 'object') {
    adminLatestAiReview = saved;
    renderAdminAiRubricReview(saved);
    setAdminAiReviewStatus('Saved review', 'ready');
  } else {
    resetAdminAiReviewPanel();
  }
}

function getAdminProjectRubricForAi() {
  const project = adminProjectViewerState.project || {};
  const key = adminProjectViewerState.activityKey || project.selectedActivityId || 'scratch';
  const known = activities.find(item => item.id === key) || activities.find(item => item.id === project.selectedActivityId) || null;
  if (known) return normalizeActivity(known);
  const resultCriteria = Array.isArray(project.lastResult?.results) ? project.lastResult.results : [];
  return {
    id: key,
    title: project.activityTitle || getAdminProjectActivityLabel(key) || 'Practice project',
    description: 'Rubric details were not found in the current activity list. Use available saved result data and evaluate carefully.',
    passingScore: Number(project.lastResult?.percent || 75) || 75,
    criteria: resultCriteria.length ? resultCriteria.map(item => ({
      id: createId(),
      title: item.title || 'Criterion',
      points: Number(item.points || item.possible || item.max || 1) || 1,
      rule: item.rule || 'smart_rubric',
      target: item.target || '',
      levels: item.levels || {}
    })) : [
      { id: createId(), title: 'Completeness based on teacher instruction', points: 10, rule: 'smart_rubric', target: '' },
      { id: createId(), title: 'Correct HTML/CSS/JavaScript use', points: 10, rule: 'smart_rubric', target: '' },
      { id: createId(), title: 'Output quality and readability', points: 10, rule: 'smart_rubric', target: '' }
    ]
  };
}

function getAdminProjectAllCodeForAi() {
  const store = getAdminProjectActiveStore();
  const htmlFiles = getAdminProjectFileMap('html', store);
  const cssFiles = getAdminProjectFileMap('css', store);
  const jsFiles = getAdminProjectFileMap('js', store);
  return {
    htmlFiles: Object.fromEntries(Object.entries(htmlFiles || {}).map(([name, code]) => [name, getShortCodeSample(code, 9000)])),
    cssFiles: Object.fromEntries(Object.entries(cssFiles || {}).map(([name, code]) => [name, getShortCodeSample(code, 9000)])),
    jsFiles: Object.fromEntries(Object.entries(jsFiles || {}).map(([name, code]) => [name, getShortCodeSample(code, 9000)])),
    activeHtmlPage: getAdminProjectActiveFileName('html'),
    activeCssFile: getAdminProjectActiveFileName('css'),
    activeJsFile: getAdminProjectActiveFileName('js')
  };
}

function collectAdminProjectOutputSummary() {
  const summary = {
    visibleText: '',
    title: '',
    headings: [],
    links: [],
    buttons: [],
    images: [],
    elementCounts: {},
    note: 'Output summary is collected from the rendered preview iframe when available.'
  };
  try {
    const doc = adminProjectViewerFrame?.contentDocument || adminProjectViewerFrame?.contentWindow?.document || null;
    if (!doc) {
      summary.note = 'Preview document was not available. Judge mainly from code.';
      return summary;
    }
    summary.title = String(doc.title || '').trim().slice(0, 240);
    summary.visibleText = String(doc.body?.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 2500);
    summary.headings = Array.from(doc.querySelectorAll('h1,h2,h3,h4,h5,h6')).map(node => ({ tag: node.tagName.toLowerCase(), text: String(node.innerText || '').trim().slice(0, 180) })).filter(item => item.text).slice(0, 12);
    summary.links = Array.from(doc.querySelectorAll('a[href]')).map(node => ({ text: String(node.innerText || '').trim().slice(0, 160), href: String(node.getAttribute('href') || '').trim().slice(0, 180) })).slice(0, 12);
    summary.buttons = Array.from(doc.querySelectorAll('button,input[type="button"],input[type="submit"]')).map(node => String(node.innerText || node.value || '').trim().slice(0, 160)).filter(Boolean).slice(0, 12);
    summary.images = Array.from(doc.querySelectorAll('img')).map(node => ({ src: String(node.getAttribute('src') || '').trim().slice(0, 160), alt: String(node.getAttribute('alt') || '').trim().slice(0, 160) })).slice(0, 12);
    ['header','nav','main','section','article','aside','footer','ul','ol','li','table','form','input','img','a','button'].forEach(tag => {
      summary.elementCounts[tag] = doc.querySelectorAll(tag).length;
    });
  } catch (error) {
    summary.note = `Could not read preview output: ${error?.message || 'unknown iframe error'}. Judge mainly from code.`;
  }
  return summary;
}

function buildAdminAiRubricPrompt(context) {
  const style = aiRubricSettings.reviewStyle || 'strict';
  return `You are an experienced Grade 8 ICT/web coding teacher. Grade the student's project using ONLY the teacher rubric, the student code, and the rendered output summary below.\n\nIMPORTANT RULES:\n- Be consistent and evidence-based.\n- Do not reward code that is not present or output that cannot be verified.\n- If output summary is limited, use the code as evidence and mention the limitation.\n- Score each criterion from 0 up to its max points only.\n- A criterion that satisfies every explicit Excellent-level requirement must receive the Excellent score for that row.
- Do a contradiction audit: evidence, level, score, and improvement must agree.
- Total score must equal the sum of criterion scores.\n- Use the rubric descriptions as the main basis.\n- Review all provided HTML/CSS/JavaScript files and verify HTML-CSS selector connections; do not focus on one example or a fixed list of tags.\n- Give constructive feedback that a beginner can understand.\n- Do not give a complete replacement code solution.\n- Return ONLY valid JSON. No markdown.\n- Use this review style: ${style}.\n\nRequired JSON schema:\n{\n  "summary": "one short teacher summary",\n  "totalScore": 0,\n  "possibleScore": 0,\n  "percent": 0,\n  "confidence": "high|medium|low",\n  "criteria": [\n    {"name":"criterion name", "max":0, "score":0, "level":"Excellent|Good|Fair|Needs Improvement", "evidence":"specific evidence from code/output", "improvement":"specific improvement"}\n  ],\n  "studentFeedback": "short feedback for the student",\n  "teacherNotes": ["short note for teacher"],\n  "warnings": ["limitations or uncertain items"]\n}\n\nPROJECT CONTEXT JSON:\n${JSON.stringify(context, null, 2)}`;
}

function extractJsonObjectFromText(text) {
  const raw = String(text || '').trim();
  if (!raw) throw new Error('Empty Gemini response.');
  try { return JSON.parse(raw); } catch (error) {}
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) {
    try { return JSON.parse(fenced[1]); } catch (error) {}
  }
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(raw.slice(start, end + 1));
  throw new Error('Gemini did not return valid JSON.');
}

function normalizeAdminAiRubricReview(raw, context) {
  const rubricCriteria = Array.isArray(context?.activity?.criteria) ? context.activity.criteria : [];
  const rawCriteria = Array.isArray(raw?.criteria) ? raw.criteria : [];
  const criteria = rubricCriteria.map((criterion, index) => {
    const max = Math.max(0, Number(getCriterionPossiblePoints(criterion) || criterion.points || 0));
    const match = rawCriteria.find(item => String(item.name || '').trim().toLowerCase() === String(criterion.title || '').trim().toLowerCase()) || rawCriteria[index] || {};
    const score = clamp(Number(match.score ?? match.earned ?? 0) || 0, 0, max);
    return {
      name: criterion.title || match.name || `Criterion ${index + 1}`,
      max,
      score: Math.round(score * 10) / 10,
      level: match.level || progressToLevelKey(max ? score / max : 0),
      evidence: String(match.evidence || 'Evidence was not clearly provided by Gemini.').slice(0, 700),
      improvement: String(match.improvement || 'Review the rubric and improve this part.').slice(0, 700)
    };
  });
  const possibleScore = criteria.reduce((sum, item) => sum + item.max, 0);
  const totalScore = Math.round(criteria.reduce((sum, item) => sum + item.score, 0) * 10) / 10;
  const percent = possibleScore ? Math.round((totalScore / possibleScore) * 100) : 0;
  return {
    summary: String(raw?.summary || 'Smart review completed.').slice(0, 700),
    totalScore,
    possibleScore,
    percent,
    confidence: ['high', 'medium', 'low'].includes(String(raw?.confidence || '').toLowerCase()) ? String(raw.confidence).toLowerCase() : 'medium',
    criteria,
    studentFeedback: String(raw?.studentFeedback || raw?.feedback || 'Good effort. Review the criterion notes and improve one item at a time.').slice(0, 1800),
    teacherNotes: Array.isArray(raw?.teacherNotes) ? raw.teacherNotes.map(item => String(item).slice(0, 400)).slice(0, 8) : [],
    warnings: Array.isArray(raw?.warnings) ? raw.warnings.map(item => String(item).slice(0, 400)).slice(0, 8) : [],
    reviewedAt: new Date(),
    activityId: context?.activity?.id || adminProjectViewerState.activityKey || 'scratch',
    activityTitle: context?.activity?.title || getAdminProjectActivityLabel(adminProjectViewerState.activityKey),
    model: getGeminiModelName(aiRubricSettings.model)
  };
}

async function callGeminiAdminAiRubricReview(context) {
  const settings = saveAiRubricSettingsLocal(getAiRubricSettingsFromControls());
  if (!settings.enabled || !settings.apiKey) throw new Error('Smart Review is not enabled or API key is missing.');
  const prompt = buildAdminAiRubricPrompt(context);
  if (adminAiRubricController) adminAiRubricController.abort();
  adminAiRubricController = new AbortController();
  const timeout = window.setTimeout(() => adminAiRubricController.abort(), 45000);
  try {
    const response = await fetchGeminiGenerateContent(settings, {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        maxOutputTokens: 4096
      }
    }, { signal: adminAiRubricController.signal });
    window.clearTimeout(timeout);
    const data = await response.json();
    const text = data?.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('\n') || '';
    return normalizeAdminAiRubricReview(extractJsonObjectFromText(text), context);
  } finally {
    window.clearTimeout(timeout);
  }
}

function renderAdminAiRubricLoading() {
  if (!adminAiReviewOutput) return;
  adminAiReviewOutput.innerHTML = `
    <div class="admin-ai-loading">
      <span class="admin-ai-spinner" aria-hidden="true"></span>
      <div><strong>Reviewing the rubric, code, and output...</strong><p class="muted-text">This is teacher-triggered only. Please wait.</p></div>
    </div>`;
}

function renderAdminAiRubricReview(review) {
  if (!adminAiReviewOutput) return;
  const safe = review || adminLatestAiReview;
  if (!safe) {
    resetAdminAiReviewPanel();
    return;
  }
  adminAiReviewOutput.innerHTML = `
    <div class="admin-ai-score-card">
      <div class="admin-ai-score-head">
        <div>
          <p class="section-kicker">${escapeHTML(safe.confidence || 'medium')} confidence · ${escapeHTML(safe.model || '')}</p>
          <h3>${escapeHTML(safe.summary || 'Smart review completed.')}</h3>
          <p class="muted-text">${escapeHTML(safe.activityTitle || 'Activity rubric')}</p>
        </div>
        <div class="admin-ai-score-number">${escapeHTML(formatPoints(safe.totalScore))}<small> / ${escapeHTML(formatPoints(safe.possibleScore))}</small><div><small>${Number(safe.percent || 0)}%</small></div></div>
      </div>
      <div class="admin-ai-feedback-block">
        <h4>Student Feedback</h4>
        <p>${escapeHTML(safe.studentFeedback || '')}</p>
      </div>
      ${safe.teacherNotes?.length ? `<div class="admin-ai-feedback-block"><h4>Teacher Notes</h4><ul>${safe.teacherNotes.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul></div>` : ''}
      ${safe.warnings?.length ? `<div class="admin-ai-feedback-block"><h4>Warnings / Limits</h4><ul class="admin-ai-warning-list">${safe.warnings.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul></div>` : ''}
      <div class="admin-ai-criteria-list">
        ${safe.criteria.map(item => `
          <div class="admin-ai-criterion">
            <div class="admin-ai-criterion-top"><strong>${escapeHTML(item.name)}</strong><span class="admin-ai-criterion-score">${escapeHTML(formatPoints(item.score))}/${escapeHTML(formatPoints(item.max))}</span></div>
            <p><strong>Evidence:</strong> ${escapeHTML(item.evidence || '')}</p>
            <p><strong>Improve:</strong> ${escapeHTML(item.improvement || '')}</p>
          </div>`).join('')}
      </div>
    </div>`;
  if (adminSaveAiReviewBtn) adminSaveAiReviewBtn.disabled = false;
  if (adminUseAiFeedbackBtn) adminUseAiFeedbackBtn.disabled = false;
  if (adminApplyAiScoreBtn) adminApplyAiScoreBtn.disabled = false;
}

function formatAdminAiReviewAsComment(review = adminLatestAiReview) {
  if (!review) return '';
  const lines = [
    `Smart Rubric Review: ${formatPoints(review.totalScore)}/${formatPoints(review.possibleScore)} (${review.percent}%)`,
    '',
    review.studentFeedback || '',
    '',
    'Criterion notes:'
  ];
  (review.criteria || []).forEach(item => {
    lines.push(`- ${item.name}: ${formatPoints(item.score)}/${formatPoints(item.max)}. ${item.improvement || item.evidence || ''}`);
  });
  if (review.warnings?.length) {
    lines.push('', 'Review notes:', ...review.warnings.map(item => `- ${item}`));
  }
  return lines.join('\n').trim();
}

async function runAdminAiRubricReview() {
  const project = adminProjectViewerState.project;
  const student = adminProjectViewerState.student;
  if (!project?.id || !student?.uid) {
    appAlert('Open a student project first.', { title: 'Smart Rubric Review' });
    return;
  }
  const settings = saveAiRubricSettingsLocal(getAiRubricSettingsFromControls());
  if (!settings.enabled || !settings.apiKey) {
    appAlert('Turn ON Smart Review and save a Gemini API key in Admin → Assistance first.', { title: 'Smart Rubric Review' });
    return;
  }
  try {
    if (adminRunAiRubricReviewBtn) adminRunAiRubricReviewBtn.disabled = true;
    if (adminSaveAiReviewBtn) adminSaveAiReviewBtn.disabled = true;
    if (adminUseAiFeedbackBtn) adminUseAiFeedbackBtn.disabled = true;
    setAdminAiReviewStatus('Reviewing...', 'running');
    renderAdminAiRubricLoading();
    runAdminProjectViewerPreview(getAdminProjectActiveFileName('html'));
    await new Promise(resolve => window.setTimeout(resolve, 650));
    const activityForReview = getAdminProjectRubricForAi();
    const context = {
      app: 'ICT 8 Connect',
      student: { name: student.name || '', studentId: student.studentId || '', section: student.section || '' },
      project: { name: project.name || '', id: project.id || '', activityKey: adminProjectViewerState.activityKey || '', updatedAt: formatStudentDate(project.updatedAt) },
      activity: {
        id: activityForReview.id,
        title: activityForReview.title,
        description: activityForReview.description,
        passingScore: activityForReview.passingScore,
        criteria: activityForReview.criteria.map(item => ({
          title: item.title,
          points: getCriterionPossiblePoints(item),
          rule: item.rule || 'smart_rubric',
          target: item.target || '',
          rubricText: getCriterionRubricText(item)
        }))
      },
      code: getAdminProjectAllCodeForAi(),
      output: collectAdminProjectOutputSummary()
    };
    const review = await callGeminiAdminAiRubricReview(context);
    adminLatestAiReview = review;
    renderAdminAiRubricReview(review);
    setAdminAiReviewStatus('Review ready', 'ready');
    setStatus('Smart rubric review ready');
  } catch (error) {
    console.error('Smart rubric review failed.', error);
    setAdminAiReviewStatus('Review failed', 'error');
    if (adminAiReviewOutput) {
      adminAiReviewOutput.innerHTML = `<div class="admin-ai-error"><strong>Smart review failed.</strong><p>${escapeHTML(error?.message || 'Check API key, model, internet connection, and quota.')}</p></div>`;
    }
  } finally {
    syncAiRubricSettingsControls(aiRubricSettings);
    if (adminRunAiRubricReviewBtn) adminRunAiRubricReviewBtn.disabled = !(aiRubricSettings.enabled && aiRubricSettings.apiKey);
  }
}

function useAdminAiFeedbackAsComment() {
  if (!adminLatestAiReview || !adminProjectTeacherComment) return;
  adminProjectTeacherComment.value = formatAdminAiReviewAsComment(adminLatestAiReview);
  setAdminProjectCommentStatus('Smart feedback inserted · not saved yet', 'saving');
  adminProjectTeacherComment.focus({ preventScroll: true });
}


function buildLastResultFromAdminAiReview(review = adminLatestAiReview) {
  if (!review) return null;
  const activityForReview = getAdminProjectRubricForAi();
  return {
    score: Number(review.totalScore || 0),
    possible: Number(review.possibleScore || 0),
    percent: Number(review.percent || 0),
    passed: Number(review.percent || 0) >= Number(activityForReview.passingScore || 75),
    feedback: review.studentFeedback || review.summary || 'Smart rubric review completed.',
    aiAssisted: true,
    reviewedByAi: true,
    activityTitle: review.activityTitle || activityForReview.title || getAdminProjectActivityLabel(adminProjectViewerState.activityKey),
    results: (review.criteria || []).map(item => ({
      title: item.name,
      levelKey: Number(item.max || 0) ? progressToLevelKey(Number(item.score || 0) / Number(item.max || 1)) : 'needsImprovement',
      levelLabel: item.level || '',
      earned: Number(item.score || 0),
      points: Number(item.max || 0),
      evidence: item.evidence || '',
      improvement: item.improvement || '',
      rule: 'ai_rubric_review',
      target: ''
    }))
  };
}

async function applyAdminAiReviewAsScore() {
  const project = adminProjectViewerState.project;
  const student = adminProjectViewerState.student;
  const result = buildLastResultFromAdminAiReview(adminLatestAiReview);
  if (!result || !project?.id || !student?.uid) return;
  const confirmed = await appConfirm(`Apply smart score ${formatPoints(result.score)}/${formatPoints(result.possible)} as this project score? You can still edit/save teacher comments separately.`, {
    title: 'Apply Smart Score',
    confirmText: 'Apply Score'
  });
  if (!confirmed) return;
  try {
    if (adminApplyAiScoreBtn) adminApplyAiScoreBtn.disabled = true;
    setAdminAiReviewStatus('Applying score...', 'running');
    const { setDoc, serverTimestamp } = firebaseSync.modules;
    await setDoc(getStudentProjectDocRef(student.uid, project.id), {
      lastResult: result,
      aiScoreAppliedAt: serverTimestamp(),
      aiScoreAppliedBy: firebaseSync.auth?.currentUser?.email || firebaseSync.currentUser?.email || 'teacher'
    }, { merge: true });
    project.lastResult = result;
    setAdminAiReviewStatus('Score applied', 'ready');
    setStatus('Smart score applied');
  } catch (error) {
    console.error('Could not apply smart score.', error);
    setAdminAiReviewStatus('Apply failed', 'error');
    appAlert(error?.message || 'Could not apply smart score. Check teacher login and Firestore rules.', { title: 'Apply Smart Score' });
  } finally {
    if (adminApplyAiScoreBtn) adminApplyAiScoreBtn.disabled = false;
  }
}

async function saveAdminAiRubricReview() {
  const project = adminProjectViewerState.project;
  const student = adminProjectViewerState.student;
  if (!adminLatestAiReview || !project?.id || !student?.uid) return;
  try {
    if (adminSaveAiReviewBtn) adminSaveAiReviewBtn.disabled = true;
    setAdminAiReviewStatus('Saving...', 'running');
    const { setDoc, serverTimestamp } = firebaseSync.modules;
    const key = getAdminProjectCommentKey();
    const teacherEmail = firebaseSync.auth?.currentUser?.email || firebaseSync.currentUser?.email || 'teacher';
    const saveRecord = {
      ...adminLatestAiReview,
      reviewedAt: serverTimestamp(),
      reviewedBy: teacherEmail,
      activityKey: key
    };
    await setDoc(getStudentProjectDocRef(student.uid, project.id), {
      aiRubricReviews: { [key]: saveRecord },
      aiRubricReviewUpdatedAt: serverTimestamp(),
      aiRubricReviewUpdatedBy: teacherEmail
    }, { merge: true });
    project.aiRubricReviews = {
      ...(project.aiRubricReviews && typeof project.aiRubricReviews === 'object' ? project.aiRubricReviews : {}),
      [key]: { ...adminLatestAiReview, reviewedAt: new Date(), reviewedBy: teacherEmail, activityKey: key }
    };
    setAdminAiReviewStatus('Saved', 'ready');
    setStatus('Smart review saved');
  } catch (error) {
    console.error('Could not save Smart Review.', error);
    setAdminAiReviewStatus('Save failed', 'error');
    appAlert(error?.message || 'Could not save smart review. Check teacher login and Firestore rules.', { title: 'Smart Review Save' });
  } finally {
    if (adminSaveAiReviewBtn) adminSaveAiReviewBtn.disabled = false;
  }
}



function getStudentProjectCommentKey(project = appSession.currentProject || {}) {
  return selectedActivityId || project.selectedActivityId || 'scratch';
}

function getProjectCommentRecordForStudent(project = appSession.currentProject || {}, key = getStudentProjectCommentKey(project)) {
  const comments = project?.teacherComments && typeof project.teacherComments === 'object' ? project.teacherComments : {};
  const record = comments[key] || comments.scratch || null;
  if (record && typeof record === 'object') return record;
  if (typeof record === 'string') return { text: record };
  if (typeof project?.teacherComment === 'string' && project.teacherComment.trim()) return { text: project.teacherComment };

  // If the teacher commented on another activity/file, show the newest available
  // comment rather than hiding all feedback from the student.
  const records = Object.values(comments)
    .map(item => (typeof item === 'string' ? { text: item } : item))
    .filter(item => item && typeof item === 'object' && String(item.text || '').trim());
  if (!records.length) return { text: '' };
  records.sort((a, b) => {
    const aTime = timestampToDate(a.updatedAt)?.getTime() || 0;
    const bTime = timestampToDate(b.updatedAt)?.getTime() || 0;
    return bTime - aTime;
  });
  return records[0] || { text: '' };
}

function renderStudentTeacherComment(project = appSession.currentProject || {}) {
  if (!studentTeacherCommentPanel || !studentTeacherCommentContent) return;
  const isStudentProject = Boolean(appSession.mode === 'student' && appSession.currentProjectId && project);
  studentTeacherCommentPanel.classList.toggle('hidden', !isStudentProject);
  if (!isStudentProject) return;

  const key = getStudentProjectCommentKey(project);
  const record = getProjectCommentRecordForStudent(project, key);
  const text = String(record?.text || '').trim();
  const updatedAt = timestampToDate(record?.updatedAt);
  const activityLabel = record?.activityTitle || (key === 'scratch' ? 'Practice project' : getActivityById(key)?.title || 'Project activity');
  const savedText = updatedAt ? `Saved ${formatStudentDate(updatedAt)}` : (text ? 'Teacher comment saved' : 'No teacher comment yet.');

  if (studentTeacherCommentStatus) {
    studentTeacherCommentStatus.textContent = text
      ? `${activityLabel} · ${savedText}`
      : 'No teacher comment yet.';
  }

  if (!text) {
    studentTeacherCommentContent.classList.add('empty-teacher-comment');
    studentTeacherCommentContent.innerHTML = `
      <div class="teacher-comment-empty-icon">💬</div>
      <h3>No teacher feedback yet</h3>
      <p>Your teacher’s saved project comment will appear here. You can view it, but you cannot edit it.</p>`;
    return;
  }

  studentTeacherCommentContent.classList.remove('empty-teacher-comment');
  studentTeacherCommentContent.innerHTML = `
    <span class="teacher-comment-pill">💬 Teacher comment</span>
    <p class="teacher-comment-text">${escapeHTML(text)}</p>
    <small class="teacher-comment-meta">${escapeHTML(activityLabel)}${updatedAt ? ` · ${escapeHTML(formatStudentDate(updatedAt))}` : ''}${record?.updatedBy ? ` · From ${escapeHTML(record.updatedBy)}` : ''}</small>`;
}

async function refreshStudentTeacherComment({ silent = false } = {}) {
  if (!appSession.student?.uid || !appSession.currentProjectId) {
    renderStudentTeacherComment();
    return null;
  }
  try {
    if (refreshStudentTeacherCommentBtn) refreshStudentTeacherCommentBtn.disabled = true;
    if (studentTeacherCommentStatus && !silent) studentTeacherCommentStatus.textContent = 'Checking teacher feedback...';
    const { getDoc } = firebaseSync.modules;
    const snapshot = await withTimeout(
      getDoc(getStudentProjectDocRef(appSession.student.uid, appSession.currentProjectId)),
      APP_NETWORK_TIMEOUT_MS,
      'Loading teacher feedback is taking too long. Please check the internet connection, then try again.'
    );
    if (!snapshotExists(snapshot)) return null;
    const updatedProject = { id: appSession.currentProjectId, ...snapshotData(snapshot) };
    appSession.currentProject = {
      ...(appSession.currentProject || {}),
      ...updatedProject,
      id: appSession.currentProjectId
    };
    const index = appSession.projects.findIndex(project => project.id === appSession.currentProjectId);
    if (index >= 0) appSession.projects[index] = { ...appSession.projects[index], ...appSession.currentProject };
    renderStudentTeacherComment(appSession.currentProject);
    if (!silent) setStatus('Teacher feedback refreshed');
    return appSession.currentProject;
  } catch (error) {
    console.warn('Could not refresh teacher feedback', error);
    renderStudentTeacherComment(appSession.currentProject);
    if (!silent) appAlert(error?.message || 'Could not refresh teacher feedback. Try again.', { title: 'Teacher Feedback' });
    return null;
  } finally {
    if (refreshStudentTeacherCommentBtn) refreshStudentTeacherCommentBtn.disabled = false;
  }
}

async function saveAdminProjectTeacherComment({ clear = false } = {}) {
  const project = adminProjectViewerState.project;
  const student = adminProjectViewerState.student;
  if (!project?.id || !student?.uid) {
    appAlert('Open a student project first before saving a comment.', { title: 'Teacher Comment' });
    return;
  }
  const key = getAdminProjectCommentKey();
  const text = clear ? '' : String(adminProjectTeacherComment?.value || '').trim();
  try {
    if (adminProjectSaveCommentBtn) adminProjectSaveCommentBtn.disabled = true;
    if (adminProjectClearCommentBtn) adminProjectClearCommentBtn.disabled = true;
    setAdminProjectCommentStatus(clear ? 'Clearing...' : 'Saving...', 'saving');
    const { setDoc, serverTimestamp } = firebaseSync.modules;
    const teacherEmail = firebaseSync.auth?.currentUser?.email || firebaseSync.currentUser?.email || 'teacher';
    const commentRecord = {
      text,
      activityKey: key,
      activityTitle: getAdminProjectActivityLabel(key),
      updatedBy: teacherEmail,
      updatedAt: serverTimestamp()
    };
    await setDoc(getStudentProjectDocRef(student.uid, project.id), {
      teacherComments: { [key]: commentRecord },
      teacherCommentUpdatedAt: serverTimestamp(),
      teacherCommentUpdatedBy: teacherEmail
    }, { merge: true });

    const localRecord = {
      ...commentRecord,
      updatedAt: new Date()
    };
    project.teacherComments = {
      ...(project.teacherComments && typeof project.teacherComments === 'object' ? project.teacherComments : {}),
      [key]: localRecord
    };
    project.teacherCommentUpdatedAt = localRecord.updatedAt;
    project.teacherCommentUpdatedBy = teacherEmail;
    if (adminProjectTeacherComment) adminProjectTeacherComment.value = text;
    setAdminProjectCommentStatus(text ? 'Comment saved' : 'Comment cleared', 'saved');
    setStatus(text ? 'Teacher comment saved' : 'Teacher comment cleared');
  } catch (error) {
    console.error('Could not save teacher comment', error);
    setAdminProjectCommentStatus('Save failed', 'error');
    appAlert(error?.message || 'Could not save the teacher comment. Check the internet connection and try again.', { title: 'Teacher Comment' });
  } finally {
    if (adminProjectSaveCommentBtn) adminProjectSaveCommentBtn.disabled = false;
    if (adminProjectClearCommentBtn) adminProjectClearCommentBtn.disabled = false;
  }
}

function renderAdminProjectViewer() {
  const project = adminProjectViewerState.project;
  const student = adminProjectViewerState.student;
  if (!project) return;
  if (adminProjectViewerTitle) adminProjectViewerTitle.textContent = project.name || 'Untitled Project';
  if (adminProjectViewerSubtitle) {
    const owner = student ? `${student.name || 'Student'} · ${student.studentId || ''}` : 'Student project';
    adminProjectViewerSubtitle.textContent = `${owner} · ${project.activityTitle || 'Practice project'} · Updated ${formatStudentDate(project.updatedAt)}`;
  }
  populateAdminProjectViewerActivitySelect();
  populateAdminProjectViewerFileSelect();
  updateAdminProjectViewerCode();
  renderAdminProjectTeacherComment();
  renderSavedAdminAiReviewForCurrentProject();
  runAdminProjectViewerPreview(getAdminProjectActiveFileName('html'));
}

async function openAdminProjectViewer(projectId) {
  const student = adminProjectViewerState.student;
  if (!student || !projectId) return;
  let project = (adminProjectViewerState.projects || []).find(item => item.id === projectId) || null;
  if (!project || !project.codeByActivity) {
    try {
      const { getDoc } = firebaseSync.modules;
      const snapshot = await getDoc(getStudentProjectDocRef(student.uid, projectId));
      if (snapshotExists(snapshot)) project = { id: projectId, ...snapshotData(snapshot) };
    } catch (error) {
      console.error('Could not fetch project for viewer', error);
    }
  }
  if (!project) {
    appAlert('This project could not be opened. Check the internet connection and try again.', { title: 'Project unavailable' });
    return;
  }
  adminProjectViewerState.project = project;
  adminProjectViewerState.codeByActivity = normalizeProjectCodeByActivity(project.codeByActivity || {});
  adminProjectViewerState.activityKey = project.selectedActivityId && adminProjectViewerState.codeByActivity[project.selectedActivityId]
    ? project.selectedActivityId
    : Object.keys(adminProjectViewerState.codeByActivity)[0] || 'scratch';
  adminProjectViewerState.language = 'html';
  adminProjectViewerOverlay?.classList.remove('hidden');
  document.body.classList.add('student-auth-open');
  renderAdminProjectViewer();
}

function closeAdminProjectViewer() {
  closeAdminProjectFullscreen();
  adminProjectViewerOverlay?.classList.add('hidden');
  if (adminProjectViewerFrame) adminProjectViewerFrame.srcdoc = '';
  document.body.classList.toggle('student-auth-open', Boolean(adminStudentProjectsOverlay && !adminStudentProjectsOverlay.classList.contains('hidden')));
}

async function showAdminStudentProjects(uid) {
  const student = adminStudentsCache.find(item => item.uid === uid);
  if (!student) return;
  adminStudentProjectsTitle.textContent = `${student.name}'s Projects`;
  adminStudentProjectsSubtitle.textContent = `${student.studentId} · ${student.section}`;
  adminStudentProjectsList.innerHTML = '<div class="dashboard-status">Loading projects...</div>';
  adminStudentProjectsOverlay.classList.remove('hidden');
  document.body.classList.add('student-auth-open');
  try {
    const { getDocs } = firebaseSync.modules;
    const snapshot = await getDocs(getStudentProjectsCollectionRef(uid));
    const projects = (snapshot.docs || []).map(docSnapshot => ({ id: docSnapshot.id, ...snapshotData(docSnapshot) }))
      .sort((a, b) => (timestampToDate(b.updatedAt)?.getTime() || 0) - (timestampToDate(a.updatedAt)?.getTime() || 0));
    if (!projects.length) {
      adminStudentProjectsList.innerHTML = '<div class="empty-projects-card"><h3>No projects yet</h3><p>This student has logged in but has not created a project.</p></div>';
      return;
    }
    adminProjectViewerState.student = student;
    adminProjectViewerState.projects = projects;
    adminStudentProjectsList.innerHTML = projects.map(project => {
      const result = project.lastResult;
      return `
        <article class="admin-project-row" data-admin-project-id="${escapeAttribute(project.id)}">
          <div><strong>${escapeHTML(project.name || 'Untitled Project')}</strong><small>${escapeHTML(project.activityTitle || 'Practice project')} · Updated ${escapeHTML(formatStudentDate(project.updatedAt))}</small></div>
          <span>${getProjectStatusLabel(getProjectStatus(project))}</span>
          <span>${Number(project.runCount || 0)} run${Number(project.runCount || 0) === 1 ? '' : 's'}</span>
          <strong>${result ? `${formatPoints(result.score || 0)}/${formatPoints(result.possible || 0)} · ${Number(result.percent || 0)}%` : 'Not scored'}</strong>
          <button class="primary-btn admin-project-view-btn" type="button" data-admin-project-action="view" data-admin-project-id="${escapeAttribute(project.id)}">View / Run</button>
        </article>`;
    }).join('');
  } catch (error) {
    console.error('Could not load student projects for admin', error);
    adminStudentProjectsList.innerHTML = '<div class="empty-projects-card"><h3>Could not load projects</h3><p>Check the internet connection and Firestore rules.</p></div>';
  }
}

function closeAdminStudentProjects() {
  adminStudentProjectsOverlay?.classList.add('hidden');
  adminProjectViewerOverlay?.classList.add('hidden');
  if (adminProjectViewerFrame) adminProjectViewerFrame.srcdoc = '';
  document.body.classList.remove('student-auth-open');
}

const selfClosingTagNames = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
  'meta', 'param', 'source', 'track', 'wbr'
]);

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function applyEditorZoom(value) {
  editorFontSize = clamp(Number(value) || BASE_EDITOR_FONT_SIZE, MIN_EDITOR_FONT_SIZE, MAX_EDITOR_FONT_SIZE);
  document.documentElement.style.setProperty('--editor-font-size', `${editorFontSize}px`);
  if (zoomLevel) {
    zoomLevel.textContent = `${Math.round((editorFontSize / BASE_EDITOR_FONT_SIZE) * 100)}%`;
  }
  saveJSON(STORAGE_KEYS.editorZoom, editorFontSize);
  fitEditorToContent();
  updateTagMatching();
  syncEditorScroll();
}

function changeEditorZoom(delta) {
  applyEditorZoom(editorFontSize + delta);
  setStatus(`Editor zoom ${Math.round((editorFontSize / BASE_EDITOR_FONT_SIZE) * 100)}%`);
}

function resetEditorZoom() {
  applyEditorZoom(BASE_EDITOR_FONT_SIZE);
  setStatus('Editor zoom reset');
}

function syncEditorScroll() {
  lineNumbers.scrollTop = editor.scrollTop;
  if (codeMatchLayer) {
    codeMatchLayer.scrollTop = editor.scrollTop;
    codeMatchLayer.scrollLeft = editor.scrollLeft;
  }
}

function syncCodeHighlightLayerGeometry() {
  if (!editor || !codeMatchLayer) return;

  const computed = window.getComputedStyle(editor);
  const mirroredProps = [
    'boxSizing',
    'fontFamily',
    'fontSize',
    'fontWeight',
    'fontStyle',
    'fontVariant',
    'fontStretch',
    'lineHeight',
    'letterSpacing',
    'textTransform',
    'textIndent',
    'textAlign',
    'tabSize',
    'whiteSpace',
    'overflowWrap',
    'wordBreak',
    'paddingTop',
    'paddingRight',
    'paddingBottom',
    'paddingLeft',
    'borderTopWidth',
    'borderRightWidth',
    'borderBottomWidth',
    'borderLeftWidth'
  ];

  mirroredProps.forEach(prop => {
    try { codeMatchLayer.style[prop] = computed[prop]; } catch (_) {}
  });

  // Keep the visual syntax layer exactly on top of the editable textarea.
  // This prevents the old cursor-drift issue after zoom, resize, fullscreen,
  // or phone/desktop layout switches.
  codeMatchLayer.style.width = `${editor.offsetWidth}px`;
  codeMatchLayer.style.height = `${editor.offsetHeight}px`;
  codeMatchLayer.style.minHeight = computed.minHeight;
  codeMatchLayer.style.maxHeight = computed.maxHeight;
}

function isPhoneNativeEditorScrollMode() {
  const root = document.documentElement;
  const body = document.body;
  const narrowPhoneLayout = Boolean(window.matchMedia?.('(max-width: 820px)')?.matches);
  const coarsePhoneTouch = Boolean(window.matchMedia?.('(hover: none) and (pointer: coarse)')?.matches);
  const phoneLikeEditor = root?.dataset?.deviceMode === 'phone' || narrowPhoneLayout || coarsePhoneTouch;
  return phoneLikeEditor
    && body?.classList?.contains('mobile-editor-normal')
    && !body?.classList?.contains('editor-fullscreen-active')
    && !body?.classList?.contains('preview-fullscreen-active');
}

function clearEditorAutoHeightStyles() {
  editor.style.height = '';
  lineNumbers.style.height = '';
  if (codeMatchLayer) codeMatchLayer.style.height = '';
  if (editorStack) editorStack.style.height = '';
  if (editorWrap) {
    editorWrap.style.height = '';
    editorWrap.style.minHeight = '';
  }
}

function fitEditorToContent() {
  if (!editor || !lineNumbers) return;

  // Phone normal editor uses the textarea's native inertial scrolling.
  // Do not keep growing the textarea height, because that makes touch scrolling
  // inside the editor feel stuck/laggy and forces students to scroll outside it.
  if (isPhoneNativeEditorScrollMode()) {
    clearEditorAutoHeightStyles();
    syncCodeHighlightLayerGeometry();
    syncEditorScroll();
    return;
  }

  // In full editor mode, CSS controls the editor height so the full screen stays stable.
  if (document.body.classList.contains('editor-fullscreen-active')) {
    clearEditorAutoHeightStyles();
    syncCodeHighlightLayerGeometry();
    syncEditorScroll();
    return;
  }

  const minHeight = Math.max(560, Math.round(window.innerHeight * 0.72));
  editor.style.height = 'auto';
  const targetHeight = Math.max(minHeight, editor.scrollHeight + 4);
  const finalHeight = `${targetHeight}px`;

  editor.style.height = finalHeight;
  lineNumbers.style.height = finalHeight;
  if (codeMatchLayer) codeMatchLayer.style.height = finalHeight;
  if (editorStack) editorStack.style.height = finalHeight;
  if (editorWrap) editorWrap.style.minHeight = finalHeight;

  syncCodeHighlightLayerGeometry();
  syncEditorScroll();
}

function getLineNumberAt(text, index) {
  return text.slice(0, index).split('\n').length;
}


function preserveNewLinesAsSpaces(value) {
  return String(value || '').replace(/[^\n\r]/g, ' ');
}

function maskIgnoredHTMLSections(text) {
  let output = String(text || '');
  output = output.replace(/<!--[\s\S]*?-->/g, match => preserveNewLinesAsSpaces(match));

  const rawTextPattern = /<(script|style|textarea|template)\b[^>]*>[\s\S]*?<\/\1\s*>/gi;
  output = output.replace(rawTextPattern, full => {
    const open = full.match(/^<(script|style|textarea|template)\b[^>]*>/i)?.[0] || '';
    const closeMatch = full.match(/<\/(script|style|textarea|template)\s*>\s*$/i);
    const close = closeMatch ? closeMatch[0] : '';
    const middleStart = open.length;
    const middleEnd = full.length - close.length;
    return open + preserveNewLinesAsSpaces(full.slice(middleStart, middleEnd)) + close;
  });

  return output;
}

function parseHTMLTagToken(text, start) {
  let index = start + 1;
  let quote = '';

  while (index < text.length) {
    const char = text[index];
    if (quote) {
      if (char === quote) quote = '';
    } else if (char === '"' || char === "'") {
      quote = char;
    } else if (char === '>') {
      const raw = text.slice(start, index + 1);
      if (/^<!--/.test(raw) || /^<!DOCTYPE\s+html\s*>/i.test(raw)) {
        return { raw, end: index + 1, skip: true };
      }
      const nameMatch = raw.match(/^<\s*\/?\s*([A-Za-z][A-Za-z0-9:-]*)\b/);
      if (!nameMatch) return { raw, end: index + 1, skip: true };
      const name = nameMatch[1].toLowerCase();
      const closing = /^<\s*\//.test(raw);
      const explicitSelfClosing = /\/\s*>$/.test(raw);
      const selfClosing = explicitSelfClosing || selfClosingTagNames.has(name);
      return { raw, end: index + 1, name, closing, selfClosing, skip: false };
    }
    index += 1;
  }

  return null;
}

function parseHtmlTags(text) {
  const original = String(text || '');
  const safeText = maskIgnoredHTMLSections(original);
  const tags = [];

  for (let index = 0; index < safeText.length; index += 1) {
    if (safeText[index] !== '<') continue;
    const token = parseHTMLTagToken(safeText, index);
    if (!token) continue;
    if (!token.skip && token.name) {
      tags.push({
        name: token.name,
        raw: original.slice(index, token.end),
        start: index,
        end: token.end,
        closing: token.closing,
        selfClosing: token.selfClosing,
        pairIndex: null,
        unmatchedReason: ''
      });
    }
    index = Math.max(index, token.end - 1);
  }

  const stack = [];
  tags.forEach((tag, index) => {
    if (tag.selfClosing) return;

    if (!tag.closing) {
      stack.push(index);
      return;
    }

    let matchedStackIndex = -1;
    for (let i = stack.length - 1; i >= 0; i -= 1) {
      if (tags[stack[i]].name === tag.name) {
        matchedStackIndex = i;
        break;
      }
    }

    if (matchedStackIndex === -1) {
      tag.unmatchedReason = 'missing-opening';
      return;
    }

    const openingIndex = stack[matchedStackIndex];
    tags[openingIndex].pairIndex = index;
    tag.pairIndex = openingIndex;

    for (let i = stack.length - 1; i > matchedStackIndex; i -= 1) {
      const interrupted = tags[stack[i]];
      if (!interrupted.unmatchedReason) interrupted.unmatchedReason = 'possible-missing-closing';
    }
    stack.splice(matchedStackIndex, stack.length - matchedStackIndex);
  });

  stack.forEach(openingIndex => {
    if (!tags[openingIndex].unmatchedReason) tags[openingIndex].unmatchedReason = 'missing-closing';
  });

  return tags;
}

function getTagAtCursor(tags, cursor) {
  return tags.find(tag => cursor >= tag.start && cursor <= tag.end)
    || tags.find(tag => cursor > tag.start - 2 && cursor < tag.end + 2)
    || null;
}

function createSyntaxToken(start, end, className, priority = 1) {
  return Number.isFinite(start) && Number.isFinite(end) && end > start
    ? { start, end, className, priority }
    : null;
}

function addSyntaxToken(tokens, start, end, className, priority = 1) {
  const token = createSyntaxToken(start, end, className, priority);
  if (token) tokens.push(token);
}

function getHTMLSyntaxTokens(text) {
  const tokens = [];
  const tagPattern = /<!--([\s\S]*?)-->|<!DOCTYPE\s+html\s*>|<\/?[A-Za-z][A-Za-z0-9:-]*(?:\s[^<>]*?)?>/gi;
  let match;

  while ((match = tagPattern.exec(text)) !== null) {
    const full = match[0];
    const offset = match.index;

    if (full.startsWith('<!--')) {
      addSyntaxToken(tokens, offset, offset + full.length, 'syn-comment', 8);
      continue;
    }

    if (/^<!DOCTYPE/i.test(full)) {
      addSyntaxToken(tokens, offset, offset + full.length, 'syn-doctype', 8);
      continue;
    }

    addSyntaxToken(tokens, offset, offset + 1, 'syn-html-bracket', 7);
    if (full.endsWith('>')) addSyntaxToken(tokens, offset + full.length - 1, offset + full.length, 'syn-html-bracket', 7);

    const nameMatch = full.match(/^<\s*\/?\s*([A-Za-z][A-Za-z0-9:-]*)/);
    if (!nameMatch) continue;

    const name = nameMatch[1];
    const nameStartLocal = full.indexOf(name);
    const nameEndLocal = nameStartLocal + name.length;
    addSyntaxToken(tokens, offset + nameStartLocal, offset + nameEndLocal, 'syn-html-tag', 9);

    if (/^<\s*\//.test(full)) {
      const slashLocal = full.indexOf('/');
      if (slashLocal >= 0) addSyntaxToken(tokens, offset + slashLocal, offset + slashLocal + 1, 'syn-html-bracket', 7);
      continue;
    }

    const attrPartStart = nameEndLocal;
    const attrPartEnd = Math.max(attrPartStart, full.length - (full.endsWith('/>') ? 2 : 1));
    const attrText = full.slice(attrPartStart, attrPartEnd);
    const attrPattern = /([A-Za-z_:][A-Za-z0-9_:.-]*)(\s*=\s*)?("[^"]*"|'[^']*'|[^\s"'=<>`]+)?/g;
    let attrMatch;

    while ((attrMatch = attrPattern.exec(attrText)) !== null) {
      const attrName = attrMatch[1];
      if (!attrName || attrName === name) continue;
      const attrNameStart = offset + attrPartStart + attrMatch.index;
      addSyntaxToken(tokens, attrNameStart, attrNameStart + attrName.length, 'syn-html-attr', 9);

      if (attrMatch[2]) {
        const equalsStart = attrNameStart + attrName.length;
        addSyntaxToken(tokens, equalsStart, equalsStart + attrMatch[2].length, 'syn-html-equals', 6);
      }

      if (attrMatch[3]) {
        const valueStart = attrNameStart + attrName.length + (attrMatch[2]?.length || 0);
        addSyntaxToken(tokens, valueStart, valueStart + attrMatch[3].length, 'syn-string', 10);
      }
    }
  }

  return tokens;
}

function getCSSSyntaxTokens(text) {
  const tokens = [];

  for (const match of text.matchAll(/\/\*[\s\S]*?\*\//g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-comment', 10);
  }

  for (const match of text.matchAll(/("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-string', 10);
  }

  for (const match of text.matchAll(/(^|[{};\n])\s*([^{};:\n][^{};\n]*?)\s*(?=\{)/g)) {
    const selector = match[2];
    const selectorStart = match.index + match[0].indexOf(selector);
    addSyntaxToken(tokens, selectorStart, selectorStart + selector.length, 'syn-css-selector', 6);
  }

  for (const match of text.matchAll(/([a-zA-Z-]+)(\s*:)/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[1].length, 'syn-css-property', 8);
    addSyntaxToken(tokens, match.index + match[1].length, match.index + match[0].length, 'syn-punctuation', 5);
  }

  for (const match of text.matchAll(/#[0-9a-fA-F]{3,8}\b|\b\d+(?:\.\d+)?(?:px|rem|em|%|vh|vw|s|ms)?\b/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-number', 7);
  }

  for (const match of text.matchAll(/[{}();,]/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-punctuation', 4);
  }

  return tokens;
}

function getJSSyntaxTokens(text) {
  const tokens = [];
  const keywordPattern = /\b(const|let|var|function|return|if|else|for|while|do|switch|case|break|continue|class|new|this|try|catch|finally|throw|true|false|null|undefined|document|window)\b/g;

  for (const match of text.matchAll(/\/\/[^\r\n]*|\/\*[\s\S]*?\*\//g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-comment', 10);
  }

  for (const match of text.matchAll(/`(?:\\.|[^`\\])*`|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-string', 10);
  }

  for (const match of text.matchAll(keywordPattern)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-js-keyword', 7);
  }

  for (const match of text.matchAll(/\b\d+(?:\.\d+)?\b/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-number', 6);
  }

  for (const match of text.matchAll(/\b([A-Za-z_$][\w$]*)(\s*)(?=\()/g)) {
    const name = match[1];
    if (!['if', 'for', 'while', 'switch', 'catch', 'function'].includes(name)) {
      addSyntaxToken(tokens, match.index, match.index + name.length, 'syn-js-function', 8);
    }
  }

  for (const match of text.matchAll(/[{}()[\].,;:+\-*/%=<>!&|?]/g)) {
    addSyntaxToken(tokens, match.index, match.index + match[0].length, 'syn-punctuation', 3);
  }

  return tokens;
}

function getSyntaxTokens(text) {
  if (activeLanguage === 'html') return getHTMLSyntaxTokens(text);
  if (activeLanguage === 'css') return getCSSSyntaxTokens(text);
  if (activeLanguage === 'js') return getJSSyntaxTokens(text);
  return [];
}

function getBestTokenForSegment(tokens, start, end) {
  return tokens
    .filter(token => start >= token.start && end <= token.end)
    .sort((a, b) => b.priority - a.priority)[0] || null;
}

function getMatchClassForSegment(spans, start, end) {
  const matches = (spans || []).filter(span => start >= span.start && end <= span.end);
  if (!matches.length) return '';

  // CSS Jump uses a tiny selector-word span inside the bigger HTML tag-match span.
  // Prefer it over normal opening/closing tag highlights so Ctrl-hover only
  // underlines class/id names, not the whole element pair.
  const cssJumpMatch = matches.find(span => String(span.className || '').includes('css-jump-hover'));
  if (cssJumpMatch) return `tag-match ${cssJumpMatch.className}`;

  const smallest = matches.sort((a, b) => (a.end - a.start) - (b.end - b.start))[0];
  return smallest ? `tag-match ${smallest.className}` : '';
}

function renderCodeMatchLayer(spans = []) {
  if (!codeMatchLayer) return;
  if (MCS_NATIVE_TEXT_EDITOR_MODE) {
    codeMatchLayer.textContent = '';
    syncEditorScroll();
    return;
  }

  syncCodeHighlightLayerGeometry();
  const text = editor.value || '';
  const syntaxTokens = getSyntaxTokens(text);
  const combinedSpans = [
    ...(Array.isArray(spans) ? spans : []),
    ...(cssJumpHoverInfo && activeLanguage === 'html' ? [{
      start: cssJumpHoverInfo.start,
      end: cssJumpHoverInfo.end,
      className: 'css-jump-hover'
    }] : [])
  ];
  const sortedMatches = combinedSpans
    .filter(span => Number.isFinite(span.start) && Number.isFinite(span.end) && span.end > span.start)
    .sort((a, b) => a.start - b.start);

  const boundaries = new Set([0, text.length]);
  syntaxTokens.forEach(token => {
    boundaries.add(token.start);
    boundaries.add(token.end);
  });
  sortedMatches.forEach(span => {
    boundaries.add(span.start);
    boundaries.add(span.end);
  });

  const points = [...boundaries]
    .filter(value => value >= 0 && value <= text.length)
    .sort((a, b) => a - b);

  let output = '';
  for (let i = 0; i < points.length - 1; i += 1) {
    const start = points[i];
    const end = points[i + 1];
    if (end <= start) continue;

    const chunk = text.slice(start, end);
    const token = getBestTokenForSegment(syntaxTokens, start, end);
    const matchClass = getMatchClassForSegment(sortedMatches, start, end);
    const className = [token?.className || '', matchClass].filter(Boolean).join(' ');

    output += className
      ? `<span class="${escapeAttribute(className)}">${escapeHTML(chunk)}</span>`
      : escapeHTML(chunk);
  }

  codeMatchLayer.innerHTML = (output || '&nbsp;') + '\n';
  syncEditorScroll();
}

function resetTagMatchInfo() {
  if (!tagMatchInfo) return;
  tagMatchInfo.className = 'tag-match-info';
  tagMatchInfo.textContent = '';
}

function updateTagMatching() {
  if (!tagMatchInfo || !codeMatchLayer) return;
  if (MCS_NATIVE_TEXT_EDITOR_MODE) {
    activeTagMatches = [];
    codeMatchLayer.textContent = '';
    resetTagMatchInfo();
    return;
  }

  if (activeLanguage !== 'html') {
    activeTagMatches = [];
    renderCodeMatchLayer([]);
    resetTagMatchInfo();
    return;
  }

  const text = editor.value;
  const tags = parseHtmlTags(text);
  const selectedTag = getTagAtCursor(tags, editor.selectionStart);

  if (!selectedTag) {
    activeTagMatches = [];
    renderCodeMatchLayer([]);
    resetTagMatchInfo();
    return;
  }

  if (selectedTag.selfClosing) {
    activeTagMatches = [{ start: selectedTag.start, end: selectedTag.end, className: 'tag-match-self' }];
    renderCodeMatchLayer(activeTagMatches);
    tagMatchInfo.className = 'tag-match-info good';
    tagMatchInfo.textContent = `Self-closing tag: <${selectedTag.name}> does not need a closing tag.`;
    return;
  }

  if (selectedTag.pairIndex !== null && tags[selectedTag.pairIndex]) {
    const pair = tags[selectedTag.pairIndex];
    activeTagMatches = [selectedTag, pair]
      .sort((a, b) => a.start - b.start)
      .map(tag => ({ start: tag.start, end: tag.end, className: 'tag-match-pair' }));
    renderCodeMatchLayer(activeTagMatches);
    tagMatchInfo.className = 'tag-match-info good';
    const openTag = selectedTag.closing ? pair : selectedTag;
    const closeTag = selectedTag.closing ? selectedTag : pair;
    tagMatchInfo.textContent = `Matched: <${selectedTag.name}> opens on line ${getLineNumberAt(text, openTag.start)} and closes on line ${getLineNumberAt(text, closeTag.start)}.`;
    return;
  }

  activeTagMatches = [{ start: selectedTag.start, end: selectedTag.end, className: 'tag-match-missing' }];
  renderCodeMatchLayer(activeTagMatches);
  tagMatchInfo.className = 'tag-match-info error';
  tagMatchInfo.textContent = selectedTag.closing
    ? `This </${selectedTag.name}> closing tag has no matching opening tag.`
    : `This <${selectedTag.name}> opening tag needs a matching </${selectedTag.name}> closing tag.`;
}

function applyTheme(theme) {
  const safeTheme = theme === 'dark' ? 'dark' : 'light';
  document.documentElement.dataset.theme = safeTheme;
  if (themeToggle) themeToggle.textContent = safeTheme === 'dark' ? '☀️ Light' : '🌙 Dark';
  if (entryThemeToggle) {
    entryThemeToggle.classList.toggle('is-dark', safeTheme === 'dark');
    entryThemeToggle.setAttribute('aria-pressed', String(safeTheme === 'dark'));
  }
  if (entryThemeLabel) entryThemeLabel.textContent = safeTheme === 'dark' ? 'Dark Mode' : 'Light Mode';
  saveJSON(STORAGE_KEYS.theme, safeTheme);
}


function getEditorHistoryKey(language = activeLanguage) {
  const filePart = ['html', 'css', 'js'].includes(language) ? `:${getActiveLanguageFileName(language)}` : '';
  return `${activity?.id || 'no-activity'}:${language}${filePart}`;
}

function createEditorState(value = editor.value, start = editor.selectionStart || 0, end = editor.selectionEnd || start) {
  return { value, start, end };
}

function statesHaveSameText(a, b) {
  return Boolean(a && b && a.value === b.value);
}

function ensureEditorHistory(language = activeLanguage, value = codeStore[language] || '') {
  const key = getEditorHistoryKey(language);
  if (!editorHistoryByKey[key]) {
    editorHistoryByKey[key] = {
      undo: [{ value, start: 0, end: 0 }],
      redo: []
    };
  }
  return editorHistoryByKey[key];
}

function resetEditorHistory(language = activeLanguage, value = codeStore[language] || '') {
  const key = getEditorHistoryKey(language);
  editorHistoryByKey[key] = {
    undo: [{ value, start: 0, end: 0 }],
    redo: []
  };
}

function resetAllLanguageHistoryForCurrentActivity() {
  ['html', 'css', 'js'].forEach(language => resetEditorHistory(language, codeStore[language] || ''));
}

function commitEditorHistory() {
  if (isRestoringEditorHistory) return;
  const history = ensureEditorHistory();
  const state = createEditorState();
  const last = history.undo[history.undo.length - 1];

  if (!statesHaveSameText(last, state)) {
    history.undo.push(state);
    if (history.undo.length > EDITOR_HISTORY_LIMIT) history.undo.shift();
    history.redo = [];
  } else if (last) {
    last.start = state.start;
    last.end = state.end;
  }
}

function restoreEditorState(state, statusText = '') {
  if (!state) return;
  isRestoringEditorHistory = true;
  editor.value = state.value;
  const safeStart = Math.min(state.start ?? state.value.length, state.value.length);
  const safeEnd = Math.min(state.end ?? safeStart, state.value.length);
  editor.setSelectionRange(safeStart, safeEnd);
  saveActiveEditor();
  updateLineNumbers();
  hideSuggestions();
  updateTagMatching();
  syncEditorScroll();
  isRestoringEditorHistory = false;
  if (statusText) setStatus(statusText);
}

function customUndo() {
  const history = ensureEditorHistory();
  const current = createEditorState();
  const last = history.undo[history.undo.length - 1];

  if (!statesHaveSameText(last, current)) {
    history.undo.push(current);
  }

  if (history.undo.length <= 1) {
    setStatus('Nothing to undo');
    return;
  }

  const popped = history.undo.pop();
  history.redo.push(popped);
  restoreEditorState(history.undo[history.undo.length - 1], 'Undo');
}

function customRedo() {
  const history = ensureEditorHistory();
  if (!history.redo.length) {
    setStatus('Nothing to redo');
    return;
  }

  const next = history.redo.pop();
  history.undo.push(next);
  restoreEditorState(next, 'Redo');
}

function applyProgrammaticEditorChange(nextValue, cursorStart = 0, cursorEnd = cursorStart, statusText = '') {
  editor.value = nextValue;
  editor.focus();
  const safeStart = Math.min(cursorStart, nextValue.length);
  const safeEnd = Math.min(cursorEnd, nextValue.length);
  editor.setSelectionRange(safeStart, safeEnd);
  saveActiveEditor();
  updateLineNumbers();
  updateTagMatching();
  commitEditorHistory();
  if (statusText) setStatus(statusText);
}


function loadActiveEditor() {
  syncActiveLanguageFileFromStore(activeLanguage);
  editor.value = getLanguageFileContent(activeLanguage, getActiveLanguageFileName(activeLanguage));
  ensureEditorHistory(activeLanguage, editor.value);
  editorInfo.textContent = activeLanguage === 'html'
    ? `HTML page: ${getActiveHtmlPageName()}. Add more pages for website activities, then connect them using links like <a href="about.html">.`
    : activeLanguage === 'css'
      ? `CSS file: ${getActiveLanguageFileName('css')}. You can add more CSS files if an activity needs a larger website.`
      : `JavaScript file: ${getActiveLanguageFileName('js')}. You can add more JS files if an activity needs separate scripts.`;
  renderHTMLPageManager();
  updateLineNumbers();
  hideSuggestions();
  renderStructureAlert();
  fitEditorToContent();
  updateTagMatching();
}


let editorHelperRefreshTimer = 0;
function scheduleEditorHelperRefresh(delay = 260) {
  window.clearTimeout(editorHelperRefreshTimer);
  editorHelperRefreshTimer = window.setTimeout(() => {
    if (!errorCheckerPanel || errorCheckerPanel.classList.contains('hidden')) return;
    try { renderErrorChecker(); } catch (error) { console.warn('Code Helper refresh skipped', error); }
  }, Math.max(80, Number(delay) || 260));
}

function saveActiveEditor() {
  setLanguageFileContent(activeLanguage, getActiveLanguageFileName(activeLanguage), editor.value);
  saveCodeFileNames();
  saveCodeStoreForCurrentActivity();

  renderHTMLPageManager();
  renderStructureAlert();
  fitEditorToContent();
  updateTagMatching();
  scheduleEditorHelperRefresh();
}

function updateLineNumbers() {
  const lines = editor.value.split('\n').length || 1;
  lineNumbers.textContent = Array.from({ length: lines }, (_, index) => index + 1).join('\n');
  fitEditorToContent();
}


