function getSuggestionContext() {
  const cursor = editor.selectionStart;
  const textBeforeCursor = editor.value.slice(0, cursor);

  if (activeLanguage === 'html') {
    const tagMatch = textBeforeCursor.match(/<([A-Za-z0-9!\- ]*)$/);
    if (tagMatch) {
      return {
        word: tagMatch[1].trimStart(),
        start: cursor - tagMatch[0].length,
        mode: 'html-tag'
      };
    }
  }

  if (activeLanguage === 'css') {
    const currentLine = textBeforeCursor.split(/\r?\n/).pop() || '';
    const valueMatch = currentLine.match(/([a-z-]+)\s*:\s*([^;{}]*)$/i);
    if (valueMatch) {
      const rawValue = valueMatch[2] || '';
      const typedValueMatch = rawValue.match(/[^\s]*$/);
      const typedValue = typedValueMatch ? typedValueMatch[0] : '';
      return {
        word: typedValue,
        start: cursor - typedValue.length,
        mode: 'css-value',
        property: valueMatch[1].toLowerCase()
      };
    }
  }

  const wordMatch = textBeforeCursor.match(/[A-Za-z0-9_.:-]+$/);
  if (wordMatch) {
    return {
      word: wordMatch[0],
      start: cursor - wordMatch[0].length,
      mode: 'word'
    };
  }

  return { word: '', start: cursor, mode: 'word' };
}

function scheduleSuggestionHide(delay = 4200) {
  window.clearTimeout(suggestionHideTimer);
  suggestionHideTimer = window.setTimeout(() => {
    hideSuggestions();
  }, delay);
}

function isPhoneUiViewportForSuggestions() {
  const phoneMode = document.documentElement?.dataset?.deviceMode === 'phone';
  const narrowViewport = Boolean(window.matchMedia && window.matchMedia('(max-width: 820px)').matches);
  return phoneMode || narrowViewport;
}

function showSuggestions(event) {
  if (isPhoneUiViewportForSuggestions() && document.body.classList.contains('mobile-suggestions-off')) {
    hideSuggestions();
    return;
  }
  if (!isStudentAssistanceFeatureEnabled('codeSuggestions')) {
    hideSuggestions();
    return;
  }

  const isRealTyping = !event || event.inputType?.startsWith('insert') || event.inputType === 'historyUndo' || event.inputType === 'historyRedo';

  if (!isRealTyping || editor.selectionStart !== editor.selectionEnd) {
    hideSuggestions();
    return;
  }

  const context = getSuggestionContext();
  currentWord = context.word.trim();
  currentSuggestionStart = context.start;

  // Do not open the menu just because the cursor is inside the editor.
  // The student must type at least one useful character first.
  if (currentWord.length < 1) {
    hideSuggestions();
    return;
  }

  // For HTML tags, avoid showing the list after typing only "<".
  // It appears when the student starts typing the tag name, like <h or <bo.
  if (context.mode === 'html-tag' && !/[A-Za-z!]/.test(currentWord)) {
    hideSuggestions();
    return;
  }

  lastSuggestionInputAt = Date.now();

  const activeSuggestions = (context.mode === 'css-value'
    ? getCSSValueSuggestionsForProperty(context.property)
    : suggestionsByLanguage[activeLanguage]
  ).map(item => ({
    ...item,
    languageType: context.mode === 'css-value' ? 'VALUE' : activeLanguage.toUpperCase()
  }));

  const query = currentWord.toLowerCase();
  currentMatches = activeSuggestions
    .filter(item => {
      const label = item.label.toLowerCase();
      const insertText = String(item.insert || '').toLowerCase();
      return label.startsWith(query) || label.includes(query) || insertText.includes(query);
    })
    .slice(0, context.mode === 'css-value' ? 8 : 6);

  if (!currentMatches.length) {
    hideSuggestions();
    return;
  }

  activeSuggestionIndex = 0;
  suggestionBox.innerHTML = `
    <div class="suggestion-mini-header">
      <span>Suggestions</span>
      <button class="suggestion-close" type="button" aria-label="Hide suggestions">×</button>
    </div>
    ${currentMatches.map((item, index) => {
      const chip = getSuggestionChip(item);
      return `
        <div class="suggestion-item ${index === 0 ? 'active' : ''} ${item.hasClosing ? 'has-closing' : ''}" data-index="${index}" role="option">
          <div>
            <div class="suggestion-label">${escapeHTML(item.label)}</div>
            <div class="suggestion-desc">${escapeHTML(item.desc)}</div>
          </div>
          <span class="suggestion-type ${chip.className}">${escapeHTML(chip.text)}</span>
        </div>
      `;
    }).join('')}
  `;

  suggestionBox.classList.remove('hidden');
  document.body.classList.add('suggestions-open');
  scheduleSuggestionHide();
}

function getSuggestionChip(item) {
  if (item.hasClosing) return { text: 'closing', className: 'closing' };
  if (item.selfClosing) return { text: 'self', className: 'self-closing' };
  if (item.type === 'template') return { text: 'template', className: 'template' };
  return { text: item.languageType || activeLanguage.toUpperCase(), className: '' };
}

function hideSuggestions() {
  window.clearTimeout(suggestionHideTimer);
  suggestionBox.classList.add('hidden');
  document.body.classList.remove('suggestions-open');
  suggestionBox.innerHTML = '';
  currentMatches = [];
}

function moveActiveSuggestion(direction) {
  if (!currentMatches.length) return;
  activeSuggestionIndex = (activeSuggestionIndex + direction + currentMatches.length) % currentMatches.length;
  [...suggestionBox.querySelectorAll('.suggestion-item')].forEach((item, index) => {
    item.classList.toggle('active', index === activeSuggestionIndex);
  });
}

function applySuggestion(index = activeSuggestionIndex) {
  const selected = currentMatches[index];
  if (!selected) return;

  const cursor = editor.selectionStart;
  const before = editor.value.slice(0, currentSuggestionStart);
  const after = editor.value.slice(cursor);
  const rawInsert = selected.insert;
  const markerIndex = rawInsert.indexOf('|');
  const insertText = rawInsert.replace('|', '');

  const nextValue = before + insertText + after;
  const newCursorPosition = markerIndex >= 0
    ? before.length + markerIndex
    : before.length + insertText.length;

  applyProgrammaticEditorChange(
    nextValue,
    newCursorPosition,
    newCursorPosition,
    selected.hasClosing ? `Inserted ${selected.label} with closing tag` : `Inserted ${selected.label}`
  );
  hideSuggestions();
}

function getHTMLStructureReport() {
  const html = codeStore.html || '';
  const checks = [
    { key: 'doctype', label: '<!DOCTYPE html>', passed: /<!doctype\s+html\s*>/i.test(html) },
    { key: 'htmlOpen', label: '<html>', passed: /<html(\s|>)/i.test(html) },
    { key: 'htmlClose', label: '</html>', passed: /<\/html\s*>/i.test(html) },
    { key: 'headOpen', label: '<head>', passed: /<head(\s|>)/i.test(html) },
    { key: 'headClose', label: '</head>', passed: /<\/head\s*>/i.test(html) },
    { key: 'title', label: '<title>', passed: /<title(\s|>)[\s\S]*?<\/title\s*>/i.test(html) },
    { key: 'bodyOpen', label: '<body>', passed: /<body(\s|>)/i.test(html) },
    { key: 'bodyClose', label: '</body>', passed: /<\/body\s*>/i.test(html) }
  ];

  return {
    checks,
    passed: checks.every(item => item.passed),
    missing: checks.filter(item => !item.passed)
  };
}

function renderStructureAlert() {
  if (!structureAlert) return;

  if (activeLanguage !== 'html') {
    structureAlert.classList.add('hidden');
    return;
  }

  const report = getHTMLStructureReport();
  structureAlert.classList.remove('hidden', 'good', 'warning');
  structureAlert.classList.add(report.passed ? 'good' : 'warning');

  const message = report.passed
    ? 'Complete HTML structure detected. Good job!'
    : 'Whole HTML structure required. Add the missing parts below.';

  structureAlert.innerHTML = `
    <div class="structure-message">
      <strong>${message}</strong>
      <span>HTML-only output still works after clicking Run Code.</span>
    </div>
    <div class="structure-list">
      ${report.checks.map(item => `
        <span class="structure-chip ${item.passed ? 'pass' : 'missing'}">${item.passed ? '✓' : '!'} ${escapeHTML(item.label)}</span>
      `).join('')}
    </div>
  `;
}

function isCompleteHTMLStructure() {
  return getHTMLStructureReport().passed;
}


function getHTMLSourceQualityReport() {
  const html = codeStore.html || '';
  const lower = html.toLowerCase();
  const structure = getHTMLStructureReport();
  const findIndex = pattern => {
    const match = pattern.exec(lower);
    return match ? match.index : -1;
  };

  const doctypeIndex = findIndex(/<!doctype\s+html\s*>/i);
  const htmlOpenIndex = findIndex(/<html\b/i);
  const headOpenIndex = findIndex(/<head\b/i);
  const headCloseIndex = findIndex(/<\/head\s*>/i);
  const titleIndex = findIndex(/<title\b/i);
  const bodyOpenIndex = findIndex(/<body\b/i);
  const bodyCloseIndex = findIndex(/<\/body\s*>/i);
  const htmlCloseIndex = findIndex(/<\/html\s*>/i);

  const bodyMatch = html.match(/<body\b[^>]*>([\s\S]*?)<\/body\s*>/i);
  const bodyContent = bodyMatch ? bodyMatch[1] : '';
  const visibleBodyText = bodyContent
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const betweenHeadAndBody = headCloseIndex >= 0
    ? html.slice(headCloseIndex + (html.match(/<\/head\s*>/i)?.[0]?.length || 7), bodyOpenIndex >= 0 ? bodyOpenIndex : (bodyCloseIndex >= 0 ? bodyCloseIndex : html.length))
    : '';
  const headContent = headOpenIndex >= 0 && headCloseIndex > headOpenIndex ? html.slice(headOpenIndex, headCloseIndex) : '';
  const visibleTagsInHead = /<(h[1-6]|p|img|a|button|ul|ol|li|div|section|main|header|footer|nav)\b/i.test(headContent);
  const visibleTagsOutsideBody = /<(h[1-6]|p|img|a|button|ul|ol|li|div|section|main|header|footer|nav)\b/i.test(betweenHeadAndBody);
  const textOutsideBody = betweenHeadAndBody
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const tagErrors = getDetailedHTMLTagIssues(html || '').filter(issue => issue.severity === 'error');

  const orderChecks = [];
  if (doctypeIndex >= 0 && htmlOpenIndex >= 0) orderChecks.push(doctypeIndex <= htmlOpenIndex);
  if (htmlOpenIndex >= 0 && headOpenIndex >= 0) orderChecks.push(htmlOpenIndex <= headOpenIndex);
  if (headOpenIndex >= 0 && headCloseIndex >= 0) orderChecks.push(headOpenIndex < headCloseIndex);
  if (titleIndex >= 0 && headOpenIndex >= 0 && headCloseIndex >= 0) orderChecks.push(titleIndex > headOpenIndex && titleIndex < headCloseIndex);
  if (headCloseIndex >= 0 && bodyOpenIndex >= 0) orderChecks.push(headCloseIndex < bodyOpenIndex);
  if (bodyOpenIndex >= 0 && bodyCloseIndex >= 0) orderChecks.push(bodyOpenIndex < bodyCloseIndex);
  if (bodyCloseIndex >= 0 && htmlCloseIndex >= 0) orderChecks.push(bodyCloseIndex < htmlCloseIndex);

  const orderProgress = orderChecks.length ? orderChecks.filter(Boolean).length / orderChecks.length : 0;
  const requiredProgress = structure.checks.filter(item => item.passed).length / Math.max(1, structure.checks.length);
  const bodyProgress = bodyOpenIndex >= 0 && bodyCloseIndex >= 0
    ? (visibleBodyText.length >= 10 ? 1 : visibleBodyText.length ? 0.7 : 0.35)
    : 0;
  const placementProgress = (visibleTagsInHead || visibleTagsOutsideBody || (textOutsideBody && bodyOpenIndex < 0)) ? 0.25 : 1;
  const balanceProgress = getBalancedTagProgress(html);

  let progress = weightedProgress([
    { value: requiredProgress, weight: 2.2 },
    { value: orderProgress, weight: 1.4 },
    { value: bodyProgress, weight: 2.4 },
    { value: placementProgress, weight: 1.8 },
    { value: balanceProgress, weight: 1.4 }
  ]);

  // Critical source mistakes should not still receive a strong score just because the browser renders something.
  if (bodyOpenIndex < 0 || bodyCloseIndex < 0) progress = Math.min(progress, 0.58);
  if (headCloseIndex >= 0 && bodyOpenIndex < 0 && (visibleTagsOutsideBody || textOutsideBody)) progress = Math.min(progress, 0.48);
  if (visibleTagsInHead) progress = Math.min(progress, 0.55);
  if (tagErrors.length) progress = Math.min(progress, 0.62);

  const issues = [];
  if (bodyOpenIndex < 0) issues.push('Missing opening <body> tag. Visible content should be inside <body>...</body>.');
  if (bodyCloseIndex < 0) issues.push('Missing closing </body> tag.');
  if (visibleTagsOutsideBody || (textOutsideBody && bodyOpenIndex < 0)) issues.push('Some visible page content is outside the body section.');
  if (visibleTagsInHead) issues.push('Visible content tags should not be placed inside the head section.');
  if (orderProgress < 1) issues.push('Some main HTML sections are not in the correct order.');
  if (tagErrors.length) issues.push('Some HTML tags are not properly paired.');

  return {
    progress: clamp01(progress),
    issues,
    hasBodyOpen: bodyOpenIndex >= 0,
    hasBodyClose: bodyCloseIndex >= 0,
    hasVisibleBodyContent: visibleBodyText.length > 0,
    visibleBodyTextLength: visibleBodyText.length,
    visibleTagsOutsideBody,
    visibleTagsInHead,
    orderProgress,
    requiredProgress,
    placementProgress,
    bodyProgress,
    tagErrors
  };
}

function getStrictHTMLStructureProgress() {
  return getHTMLSourceQualityReport().progress;
}

function getCriterionIntent(criterion) {
  const normalized = normalizeCriterion(criterion);
  const title = String(normalized.title || '').toLowerCase();
  const excellent = String(normalized.levels?.excellent?.description || '').toLowerCase();
  const good = String(normalized.levels?.good?.description || '').toLowerCase();
  const fair = String(normalized.levels?.fair?.description || '').toLowerCase();
  const needs = String(normalized.levels?.needsImprovement?.description || '').toLowerCase();
  const text = `${title} ${excellent} ${good} ${fair} ${needs}`.replace(/<[^>]+>/g, ' ');

  // Treat CSS as required only when the rubric clearly asks for stylesheet-based styling.
  // Attribute names such as width/height on an <img> are HTML requirements, not CSS requirements.
  const explicitCss = includesAnyText(text, [
    /\bcss\b/, /stylesheet/, /css propert/, /css selector/, /style sheet/,
    /visual design/, /visual appeal/, /responsive design/, /media quer/, /flexbox|\bflex layout\b/, /css grid/,
    /background-color/, /font-family/, /font-size/, /border-radius/, /box-shadow/,
    /(?:use|uses|using|apply|applies|add|adds|include|includes|required?)\s+(?:meaningful\s+)?(?:css|styling|styles)/
  ]);

  const explicitJs = includesAnyText(text, [
    /javascript|\bjs\b|script/, /event listener/, /onclick/, /interactive|interaction/, /function/, /dom/, /button action/, /textcontent|innerhtml|classlist/
  ]);

  const structure = includesAnyText(text, [
    /html structure/, /document structure/, /complete structure/, /required html tags/, /doctype/, /<html|&lt;html/, /<head|&lt;head/, /<body|&lt;body/, /<title|&lt;title/, /proper structure|correct structure/
  ]);

  const content = includesAnyText(text, [
    /content/, /organization|organized/, /complete details?/, /required details?/, /visible text/, /readable/, /easy to read/, /paragraph/, /heading/, /webpage content/
  ]);

  const htmlElements = includesAnyText(text, [
    /formatting elements?/, /html elements?/, /required elements?/, /heading/, /paragraph/, /image|picture|photo|img/, /link|anchor|hyperlink/, /list|bullet|numbered/, /button/, /table/, /form|input/
  ]);

  const semantic = includesAnyText(text, [/semantic/, /\bheader\b|\bfooter\b|\bnav\b|\bmain\b|\bsection\b|\barticle\b|\baside\b/]);

  return { text, title, explicitCss, explicitJs, structure, content, htmlElements, semantic };
}

function getLocalCriterionEvidence(criterion, progress) {
  const intent = getCriterionIntent(criterion);
  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const sourceQuality = getHTMLSourceQualityReport();
  const outputText = getOutputText().trim();
  const cssProperties = countMatches(css, /[a-z-]+\s*:/gi);
  const issues = [];
  const evidence = [];
  const requirementAudit = buildRubricRequirementAudit(criterion);

  if (requirementAudit.checks.length) {
    const passedDetails = requirementAudit.passed.slice(0, 5).map(item => item.evidence || `${item.label} passed.`).filter(Boolean);
    const missingDetails = requirementAudit.missing.slice(0, 4).map(item => item.fix || `${item.label} is missing.`).filter(Boolean);
    return {
      evidence: passedDetails.length
        ? passedDetails.join(' ')
        : 'No required rubric evidence was verified in the submitted code.',
      improvement: missingDetails.length
        ? missingDetails.join(' ')
        : 'All explicitly detected requirements for this criterion are satisfied.'
    };
  }

  // Only apply global HTML structure penalties to criteria that actually ask for HTML/source structure.
  // Content and element criteria may mention a specific element without requiring full document structure.
  if (intent.structure || intent.semantic) {
    if (sourceQuality.issues.length) issues.push(...sourceQuality.issues.slice(0, 2));
    const report = getHTMLStructureReport();
    const missing = report.missing.map(item => item.label);
    if (!missing.length && sourceQuality.progress >= 0.9) evidence.push('The required document sections are present and in the correct order.');
    if (missing.length) issues.push(`Missing or misplaced required structure: ${missing.slice(0, 3).join(', ')}.`);
  }

  if (intent.content) {
    if (outputText.length >= 60) evidence.push('The output has clear visible content.');
    else if (outputText.length >= 15) evidence.push('The output has visible text, but it still needs more detail.');
    else if (outputText.length >= 3) issues.push('The output has very little visible text.');
    else issues.push('The rendered output has little or no visible text.');

    if (intent.structure && !sourceQuality.hasVisibleBodyContent) {
      issues.push('Visible content is not properly placed inside the body section.');
    }
  }

  if (intent.htmlElements) {
    const elementEvidence = [];
    const missingElements = [];
    const text = intent.text;
    const hasElement = (name, regex, previewSelector) => Boolean(regex.test(html) || queryPreview(previewSelector));

    if (/heading|\bh[1-6]\b/.test(text)) (hasElement('heading', /<h[1-6](\s|>|\/)/i, 'h1, h2, h3, h4, h5, h6') ? elementEvidence : missingElements).push('heading');
    if (/paragraph|\bp\s*tag|\bp\b/.test(text)) (hasElement('paragraph', /<p(\s|>|\/)/i, 'p') ? elementEvidence : missingElements).push('paragraph');
    if (/image|picture|photo|\bimg\b/.test(text)) (hasElement('image', /<img(\s|>|\/)/i, 'img') ? elementEvidence : missingElements).push('image');
    if (/link|anchor|hyperlink|\ba\s*tag/.test(text)) (hasElement('link', /<a(\s|>|\/)/i, 'a') ? elementEvidence : missingElements).push('link');
    if (/list|bullet|numbered|\bul\b|\bol\b|\bli\b/.test(text)) (hasElement('list', /<(ul|ol)(\s|>|\/)/i, 'ul, ol') ? elementEvidence : missingElements).push('list');
    if (/button/.test(text)) (hasElement('button', /<button(\s|>|\/)/i, 'button') ? elementEvidence : missingElements).push('button');

    if (elementEvidence.length) evidence.push(`Detected required element evidence: ${elementEvidence.slice(0, 4).join(', ')}.`);
    if (missingElements.length && !/as required/.test(text)) issues.push(`Missing expected element evidence: ${missingElements.slice(0, 4).join(', ')}.`);
    if (!elementEvidence.length && !missingElements.length && /formatting|elements?/.test(text)) {
      evidence.push('Basic HTML elements are present in the page.');
    }
  }

  if (intent.semantic) {
    const count = countSemanticHTMLTags(html);
    if (count >= 2) evidence.push(`Detected ${count} semantic HTML elements.`);
    else issues.push('Add more semantic HTML elements required by this rubric item.');
  }

  if (intent.explicitCss) {
    if (css.trim()) evidence.push(`CSS is present with ${cssProperties} detected propert${cssProperties === 1 ? 'y' : 'ies'}.`);
    else issues.push('This rubric item asks for styling/design, but no CSS styling was found.');
    if (css.trim() && cssProperties > 0 && cssProperties < 3) issues.push('The styling is still limited; add more meaningful CSS properties.');
  }

  if (intent.explicitJs) {
    if (js.trim() || /onclick\s*=/i.test(html)) evidence.push('A script or inline event was detected.');
    else issues.push('This rubric item asks for interactivity or JavaScript, but no related script was detected.');
  }

  if (!evidence.length) {
    if (progress >= 0.9) evidence.push('The work strongly matches the wording of this rubric item.');
    else if (progress >= 0.65) evidence.push('The work partially matches the wording of this rubric item.');
    else evidence.push('Only limited evidence was found for this rubric item.');
  }

  let improvement = '';
  if (issues.length) improvement = issues[0];
  else if (progress < 0.9) improvement = 'Add more evidence that directly matches this criterion description.';
  else improvement = 'All detected requirements for this criterion are satisfied.';

  return {
    evidence: evidence.slice(0, 2).join(' '),
    improvement
  };
}


function hasBalancedHTMLTags(html) {
  const issues = getDetailedHTMLTagIssues(html || '');
  return !issues.some(issue => issue.severity === 'error');
}


function createStyleBlock(cssText = '') {
  const css = String(cssText || '').trim();
  if (!css) return '';
  const safeCSS = css.replace(/<\/style>/gi, '');
  return `<style>\n${safeCSS}\n</style>`;
}

function createScriptBlock(jsText = '') {
  const js = String(jsText || '').trim();
  if (!js) return '';
  const safeJS = JSON.stringify(js).replace(/<\//g, '<\\/');

  return `<script>
(function () {
  function showStudentError(error) {
    document.body.dataset.runtimeError = error.message || String(error);
    var pre = document.createElement('pre');
    pre.textContent = 'JavaScript Error: ' + (error.message || String(error));
    pre.style.background = '#fee2e2';
    pre.style.color = '#991b1b';
    pre.style.padding = '16px';
    pre.style.borderRadius = '12px';
    pre.style.whiteSpace = 'pre-wrap';
    pre.style.fontFamily = 'Consolas, Monaco, monospace';
    document.body.appendChild(pre);
    try {
      parent.postMessage({ type: 'mcs-preview-runtime', level: 'error', message: error.message || String(error) }, '*');
    } catch (postError) {}
  }

  try {
    new Function(${safeJS})();
  } catch (error) {
    showStudentError(error);
  }
})();
<\/script>`;
}

function getReferencedCodeFiles(html, language) {
  const refs = language === 'css' ? getExternalCSSReferences(html) : getExternalJSReferences(html);
  const files = getLanguageFileMap(language);
  const matches = [];
  refs.forEach(ref => {
    const base = cleanLanguageFileName(getBaseFileNameFromReference(ref), language);
    if (base && Object.prototype.hasOwnProperty.call(files, base)) {
      matches.push({ name: base, content: files[base] || '' });
    }
  });
  return matches;
}

function getCSSBlocksForPreview(html) {
  const refs = getExternalCSSReferences(html);
  const matched = getReferencedCodeFiles(html, 'css').filter(item => String(item.content || '').trim());
  if (refs.length) return matched.map(item => createStyleBlock(item.content)).join('\n');
  const activeCss = getLanguageFileContent('css', getActiveLanguageFileName('css'));
  return activeCss.trim() ? createStyleBlock(activeCss) : '';
}

function getJSBlocksForPreview(html) {
  const refs = getExternalJSReferences(html);
  const matched = getReferencedCodeFiles(html, 'js').filter(item => String(item.content || '').trim());
  if (refs.length) return matched.map(item => createScriptBlock(item.content)).join('\n');
  const activeJs = getLanguageFileContent('js', getActiveLanguageFileName('js'));
  return activeJs.trim() ? createScriptBlock(activeJs) : '';
}

function shouldApplyCSSForPreview(html) {
  return Boolean(getCSSBlocksForPreview(html));
}

function shouldApplyJSForPreview(html) {
  return Boolean(getJSBlocksForPreview(html));
}

function injectAssetsIntoHTML(html, styleBlock, scriptBlock) {
  let output = html || '';

  if (styleBlock) {
    if (/<\/head\s*>/i.test(output)) {
      output = output.replace(/<\/head\s*>/i, `${styleBlock}\n</head>`);
    } else {
      output = `${styleBlock}\n${output}`;
    }
  }

  if (scriptBlock) {
    if (/<\/body\s*>/i.test(output)) {
      output = output.replace(/<\/body\s*>/i, `${scriptBlock}\n</body>`);
    } else {
      output = `${output}\n${scriptBlock}`;
    }
  }

  return output;
}


function shouldOpenExternalLinksInsidePreview() {
  const settings = normalizeAssistanceSettings(studentAssistanceSettings);
  return settings.externalLinksSamePreview !== false;
}

function createPreviewNavigationBlock(currentPageName = getActiveHtmlPageName()) {
  const safePage = JSON.stringify(currentPageName);
  const externalLinksInsidePreview = shouldOpenExternalLinksInsidePreview();
  const safeExternalLinksInsidePreview = JSON.stringify(externalLinksInsidePreview);
  return `<script>
(function () {
  var currentPage = ${safePage};
  var externalLinksInsidePreview = ${safeExternalLinksInsidePreview};

  function isExternalWebLink(href) {
    return /^https?:\/\//i.test(String(href || '').trim());
  }

  function isInternalPage(href) {
    if (!href || /^(https?:|mailto:|tel:|javascript:|data:|blob:|#)/i.test(href)) return false;
    var clean = href.split('#')[0].split('?')[0];
    var name = clean.split('/').pop();
    return /\.html?$/i.test(name);
  }

  function prepareExternalLinks(root) {
    var links = (root || document).querySelectorAll ? (root || document).querySelectorAll('a[href]') : [];
    Array.prototype.forEach.call(links, function (link) {
      var href = link.getAttribute('href') || '';
      if (!isExternalWebLink(href)) return;
      if (externalLinksInsidePreview) {
        link.setAttribute('target', '_self');
        link.removeAttribute('rel');
        return;
      }
      link.setAttribute('target', '_blank');
      var rel = (link.getAttribute('rel') || '').toLowerCase();
      if (rel.indexOf('noopener') === -1 || rel.indexOf('noreferrer') === -1) {
        link.setAttribute('rel', 'noopener noreferrer');
      }
    });
  }

  prepareExternalLinks(document);

  try {
    var observer = new MutationObserver(function () { prepareExternalLinks(document); });
    observer.observe(document.documentElement || document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['href'] });
  } catch (error) {}

  document.addEventListener('click', function (event) {
    var link = event.target && event.target.closest ? event.target.closest('a[href]') : null;
    if (!link) return;
    var href = link.getAttribute('href') || '';

    if (isExternalWebLink(href)) {
      if (externalLinksInsidePreview) {
        event.preventDefault();
        try { window.location.href = href; } catch (error) { link.setAttribute('target', '_self'); }
        return;
      }
      link.setAttribute('target', '_blank');
      link.setAttribute('rel', 'noopener noreferrer');
      return;
    }

    if (!isInternalPage(href)) return;
    event.preventDefault();
    parent.postMessage({ type: 'mcs-preview-navigate', href: href, from: currentPage }, '*');
  }, true);
})();
<\/script>`;
}


function createPreviewRuntimeReporterBlock() {
  return `<script>
(function () {
  function send(level, message) {
    try {
      var clean = String(message || '').replace(/\s+/g, ' ').slice(0, 500);
      if (!clean) return;
      if (document.body && level !== 'log') document.body.dataset.runtimeError = clean;
      parent.postMessage({ type: 'mcs-preview-runtime', level: level, message: clean }, '*');
    } catch (error) {}
  }
  window.addEventListener('error', function (event) {
    send('error', event.message || (event.error && event.error.message) || 'JavaScript error');
  });
  window.addEventListener('unhandledrejection', function (event) {
    var reason = event.reason;
    send('unhandledrejection', reason && reason.message ? reason.message : reason);
  });
  ['error', 'warn'].forEach(function (method) {
    var original = console[method];
    console[method] = function () {
      var message = Array.prototype.slice.call(arguments).map(function (item) {
        if (item && item.message) return item.message;
        if (typeof item === 'object') {
          try { return JSON.stringify(item); } catch (error) { return String(item); }
        }
        return String(item);
      }).join(' ');
      send(method === 'error' ? 'error' : 'warning', message);
      if (original) original.apply(console, arguments);
    };
  });
})();
<\/script>`;
}


function injectRuntimeReporterEarly(html, reporterBlock) {
  let output = html || '';
  if (!reporterBlock) return output;
  if (/<head\b[^>]*>/i.test(output)) {
    return output.replace(/<head\b[^>]*>/i, match => `${match}\n${reporterBlock}`);
  }
  if (/<html\b[^>]*>/i.test(output)) {
    return output.replace(/<html\b[^>]*>/i, match => `${match}\n${reporterBlock}`);
  }
  if (/<!doctype\s+html\s*>/i.test(output)) {
    return output.replace(/<!doctype\s+html\s*>/i, match => `${match}\n${reporterBlock}`);
  }
  return `${reporterBlock}\n${output}`;
}

function hasCompletePreviewDocumentShell(html = '') {
  const source = String(html || '');
  return /<html\b[^>]*>/i.test(source)
    && /<\/html\s*>/i.test(source)
    && /<head\b[^>]*>/i.test(source)
    && /<\/head\s*>/i.test(source)
    && /<body\b[^>]*>/i.test(source)
    && /<\/body\s*>/i.test(source);
}

function shouldIncludePreviewNavigationBlock(html = '') {
  return /<a\b[^>]*\bhref\s*=/i.test(String(html || ''));
}


function stripAppPreviewHelperLeak(html = '') {
  let output = String(html || '');

  // Some older preview builds injected app helper code into the iframe. If a
  // malformed document or cached preview turns that helper into plain text, it
  // can appear in Output Preview even though the student never typed it. Remove
  // only our known helper snippets; do not touch normal student code.
  const knownHelperMarkers = [
    'mcs-preview-navigate',
    'mcs-preview-runtime',
    'externalLinksInsidePreview',
    'isExternalWebLink(href)',
    'prepareExternalLinks(document)',
    'MutationObserver(function () { prepareExternalLinks(document); })'
  ];

  if (!knownHelperMarkers.some(marker => output.includes(marker))) return output;

  // Remove complete script blocks that contain only our preview helper code.
  output = output.replace(/<script\b[^>]*>[\s\S]*?(?:mcs-preview-navigate|externalLinksInsidePreview|mcs-preview-runtime)[\s\S]*?<\/script\s*>/gi, '');

  // Remove raw helper text if it leaked without visible <script> tags.
  output = output.replace(/\(function\s*\(\)\s*\{[\s\S]{0,9000}?(?:mcs-preview-navigate|externalLinksInsidePreview)[\s\S]{0,4000}?\}\)\s*\(\)\s*;?/gi, '');
  output = output.replace(/\(function\s*\(\)\s*\{[\s\S]{0,9000}?(?:mcs-preview-runtime)[\s\S]{0,4000}?\}\)\s*\(\)\s*;?/gi, '');

  return output;
}

function attachPreviewLinkHandlers() {
  if (!previewFrame) return;
  let doc = null;
  try {
    doc = previewFrame.contentDocument || previewFrame.contentWindow?.document || null;
  } catch (error) {
    doc = null;
  }
  if (!doc || doc.__mcsParentPreviewLinksReady) return;
  doc.__mcsParentPreviewLinksReady = true;

  const updateExternalLinks = () => {
    const openInside = shouldOpenExternalLinksInsidePreview();
    const links = doc.querySelectorAll ? doc.querySelectorAll('a[href]') : [];
    Array.prototype.forEach.call(links, link => {
      const href = link.getAttribute('href') || '';
      if (!/^https?:\/\//i.test(String(href || '').trim())) return;
      if (openInside) {
        link.setAttribute('target', '_self');
        link.removeAttribute('rel');
      } else {
        link.setAttribute('target', '_blank');
        link.setAttribute('rel', 'noopener noreferrer');
      }
    });
  };

  updateExternalLinks();
  try {
    const observer = new MutationObserver(updateExternalLinks);
    observer.observe(doc.documentElement || doc.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['href'] });
  } catch (error) {}

  doc.addEventListener('click', event => {
    const link = event.target && event.target.closest ? event.target.closest('a[href]') : null;
    if (!link) return;
    const href = link.getAttribute('href') || '';
    const trimmed = String(href || '').trim();
    if (!trimmed || /^(mailto:|tel:|javascript:|data:|blob:|#)/i.test(trimmed)) return;
    if (/^https?:\/\//i.test(trimmed)) {
      if (shouldOpenExternalLinksInsidePreview()) {
        event.preventDefault();
        try { previewFrame.contentWindow.location.href = trimmed; } catch (error) {}
      }
      return;
    }
    const clean = trimmed.split('#')[0].split('?')[0];
    const fileName = clean.split('/').pop();
    if (!/\.html?$/i.test(fileName)) return;
    event.preventDefault();
    navigatePreviewToPage(trimmed);
  }, true);
}

function buildFullCode(pageName = getActiveHtmlPageName()) {
  const safePageName = normalizeHtmlPageName(pageName);
  const rawHtml = getHTMLPageContent(safePageName) || '';
  const html = stripAppPreviewHelperLeak(rawHtml);
  const styleBlock = getCSSBlocksForPreview(html);
  const scriptBlock = getJSBlocksForPreview(html);
  // App navigation helpers are attached from the parent iframe load handler.
  // Keeping them out of srcdoc prevents helper JS from ever becoming visible
  // text in Output Preview when a student's HTML is incomplete or cached.
  const navigationBlock = '';
  const runtimeReporterBlock = createPreviewRuntimeReporterBlock();
  const bodyScriptBlock = [scriptBlock, navigationBlock].filter(Boolean).join('\n');
  const looksLikeFullDocument = /<!doctype/i.test(html) || /<html(\s|>)/i.test(html) || /<head(\s|>)/i.test(html) || /<body(\s|>)/i.test(html);
  const hasCompleteDocumentShell = hasCompletePreviewDocumentShell(html);

  if (looksLikeFullDocument && hasCompleteDocumentShell) {
    return injectAssetsIntoHTML(injectRuntimeReporterEarly(html, runtimeReporterBlock), styleBlock, bodyScriptBlock);
  }

  if (looksLikeFullDocument && !hasCompleteDocumentShell) {
    return injectAssetsIntoHTML(html, styleBlock, '');
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  ${runtimeReporterBlock}
  ${styleBlock}
</head>
<body>
${html}
${bodyScriptBlock}
</body>
</html>`;
}

function getCollapsedTopbarHeight(topbar) {
  if (!topbar) return 0;
  const brandHeight = topbar.querySelector('.brand-block')?.getBoundingClientRect().height || 0;
  const actionsHeight = topbar.querySelector('.top-actions')?.getBoundingClientRect().height || 0;
  const styles = window.getComputedStyle(topbar);
  const paddingY = (parseFloat(styles.paddingTop) || 0) + (parseFloat(styles.paddingBottom) || 0);
  const borderY = (parseFloat(styles.borderTopWidth) || 0) + (parseFloat(styles.borderBottomWidth) || 0);
  return Math.ceil(Math.max(brandHeight, actionsHeight, 42) + paddingY + borderY);
}

function getTopbarSafeOffset(options = {}) {
  const topbar = document.querySelector('.topbar');
  if (!topbar) return options.tight ? 8 : 14;

  const isPhone = document.documentElement.dataset.deviceMode === 'phone' || window.innerWidth <= 760;
  if (isPhone) {
    const rect = topbar.getBoundingClientRect();
    const visible = rect.bottom > 0 && rect.top < window.innerHeight;
    return Math.ceil((visible ? Math.max(0, rect.bottom) : 0) + (options.tight ? 6 : 10));
  }

  let topbarHeight = topbar.getBoundingClientRect().height || 0;
  const isDesktop = window.matchMedia?.('(min-width: 821px)').matches ?? window.innerWidth >= 821;
  const accountStripCanSlide = isDesktop && (
    document.body.classList.contains('student-session-active') ||
    document.body.classList.contains('guest-session-active')
  );

  // The account strip is hidden until hover on desktop. Do not include its
  // expanded height while aligning Output Preview; otherwise Run stops too low.
  if (options.preferCollapsedHeader && accountStripCanSlide) {
    const collapsedHeight = getCollapsedTopbarHeight(topbar);
    if (collapsedHeight > 0) topbarHeight = Math.min(topbarHeight, collapsedHeight);
  }

  return Math.ceil(topbarHeight + (options.tight ? 6 : 12));
}

function getViewportSafeTop(options = {}) {
  if (options.outputTopLock) return 0;
  const topbar = document.querySelector('.topbar');
  const margin = options.tight ? 6 : 10;
  if (!topbar) return margin;

  const isPhone = document.documentElement.dataset.deviceMode === 'phone' || window.innerWidth <= 760;
  const rect = topbar.getBoundingClientRect();
  const isVisible = rect.bottom > 0 && rect.top < window.innerHeight;
  if (!isVisible) return margin;

  if (isPhone) return Math.ceil(Math.max(0, rect.bottom) + margin);

  const isDesktop = window.matchMedia?.('(min-width: 821px)').matches ?? window.innerWidth >= 821;
  const accountStripCanSlide = isDesktop && (
    document.body.classList.contains('student-session-active') ||
    document.body.classList.contains('guest-session-active')
  );

  if (options.preferCollapsedHeader && accountStripCanSlide) {
    return Math.ceil(Math.max(0, rect.top) + getCollapsedTopbarHeight(topbar) + margin);
  }

  return Math.ceil(Math.max(0, rect.bottom) + margin);
}

let outputPreviewScrollTimer = 0;
let outputPreviewScrollRaf = 0;
let outputPreviewAnimationFrame = 0;
let outputPreviewLastTarget = -1;

function getElementDocumentTop(element) {
  const rect = element.getBoundingClientRect();
  return Math.max(0, window.scrollY + rect.top);
}

function getMaxWindowScrollTop() {
  const doc = document.documentElement;
  const body = document.body;
  return Math.max(0, Math.max(
    doc?.scrollHeight || 0,
    body?.scrollHeight || 0
  ) - window.innerHeight);
}

function getOutputPreviewTargetScrollTop(element, options = {}) {
  const safeTop = getViewportSafeTop(options);
  const rawTarget = Math.round(getElementDocumentTop(element) - safeTop);
  return Math.max(0, Math.min(getMaxWindowScrollTop(), rawTarget));
}

function cancelOutputPreviewScroll() {
  window.clearTimeout(outputPreviewScrollTimer);
  if (outputPreviewScrollRaf) window.cancelAnimationFrame(outputPreviewScrollRaf);
  if (outputPreviewAnimationFrame) window.cancelAnimationFrame(outputPreviewAnimationFrame);
  outputPreviewScrollTimer = 0;
  outputPreviewScrollRaf = 0;
  outputPreviewAnimationFrame = 0;
}

function animateWindowScrollTo(targetTop, options = {}) {
  const startTop = Math.round(window.scrollY || document.documentElement.scrollTop || 0);
  const distance = targetTop - startTop;
  const prefersReducedMotion = Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches);
  const duration = prefersReducedMotion || options.instant ? 0 : Number(options.duration || 220);

  if (Math.abs(distance) < 3 || duration <= 0) {
    window.scrollTo(0, targetTop);
    return;
  }

  const start = performance.now();
  const easeOutCubic = t => 1 - Math.pow(1 - t, 3);
  const step = now => {
    const progress = Math.min(1, (now - start) / duration);
    const nextTop = Math.round(startTop + (distance * easeOutCubic(progress)));
    window.scrollTo(0, nextTop);
    if (progress < 1) {
      outputPreviewAnimationFrame = window.requestAnimationFrame(step);
    } else {
      outputPreviewAnimationFrame = 0;
      window.scrollTo(0, targetTop);
    }
  };
  outputPreviewAnimationFrame = window.requestAnimationFrame(step);
}

function alignElementToViewportTop(element, options = {}) {
  if (!element) return;
  const targetTop = getOutputPreviewTargetScrollTop(element, options);
  const currentTop = Math.round(window.scrollY || document.documentElement.scrollTop || 0);
  if (Math.abs(targetTop - currentTop) < 3) return;
  outputPreviewLastTarget = targetTop;
  animateWindowScrollTo(targetTop, options);
}

function scrollElementIntoSafeView(element, delay = 0, options = {}) {
  if (!element) return;
  cancelOutputPreviewScroll();

  const runScroll = () => {
    outputPreviewScrollRaf = window.requestAnimationFrame(() => {
      outputPreviewScrollRaf = 0;
      alignElementToViewportTop(element, options);
    });
  };

  if (delay > 0) outputPreviewScrollTimer = window.setTimeout(runScroll, delay);
  else runScroll();
}

function scrollToOutput() {
  // Fast premium-feel scroll: one short custom animation, exact top alignment,
  // no repeated correction timers that make phones feel laggy.
  scrollElementIntoSafeView(previewPanel, 0, {
    tight: true,
    preferCollapsedHeader: true,
    outputTopLock: true,
    duration: 220
  });
}

function playBookPageTransition(direction = 'to-preview') {
  window.clearTimeout(bookTransitionTimer);
  document.body.classList.remove(
    'book-page-transitioning',
    'book-to-preview',
    'book-to-editor',
    'book-preview-revealing',
    'book-preview-leaving',
    'book-editor-revealing'
  );

  // Force a reflow so the animation always restarts, even after repeated Run/Back clicks.
  void document.body.offsetWidth;
  document.body.classList.add(
    'book-page-transitioning',
    direction === 'to-editor' ? 'book-to-editor' : 'book-to-preview'
  );

  bookTransitionTimer = window.setTimeout(() => {
    document.body.classList.remove(
      'book-page-transitioning',
      'book-to-preview',
      'book-to-editor',
      'book-preview-revealing',
      'book-preview-leaving',
      'book-editor-revealing'
    );
    fullscreenPageTransitionBusy = false;
  }, FULLSCREEN_PAGE_TRANSITION_MS + 180);
}


function removeFullscreenBookTransitionLayer() {
  const layer = document.getElementById('fullscreenBookTransitionLayer');
  if (layer) layer.remove();
}

function ensureFullscreenBookTransitionLayer(direction = 'to-preview', label = '') {
  if (!editorPanel) return null;
  removeFullscreenBookTransitionLayer();
  const layer = document.createElement('div');
  layer.id = 'fullscreenBookTransitionLayer';
  layer.className = `fullscreen-book-transition-layer ${direction === 'to-editor' ? 'to-editor' : 'to-preview'}`;
  layer.setAttribute('aria-hidden', 'true');
  layer.innerHTML = `
    <div class="fullscreen-book-vignette"></div>
    <div class="fullscreen-book-stage">
      <div class="fullscreen-book-fixed-page"></div>
      <div class="fullscreen-book-turn-page">
        <span class="fullscreen-book-spine"></span>
        <span class="fullscreen-book-highlight"></span>
      </div>
      <div class="fullscreen-book-edge"></div>
    </div>
    <div class="fullscreen-book-caption">${escapeHTML(label)}</div>
  `;
  editorPanel.appendChild(layer);
  return layer;
}

function clearFullscreenBookStateClasses() {
  document.body.classList.remove(
    'book-page-transitioning',
    'book-to-preview',
    'book-to-editor',
    'book-preview-revealing',
    'book-preview-leaving',
    'book-editor-revealing'
  );
}

function runSmoothFullscreenBookTransition({ direction = 'to-preview', label = '', onSwap = null, onDone = null } = {}) {
  window.clearTimeout(bookTransitionTimer);
  window.clearTimeout(previewCloseToEditorTimer);
  clearFullscreenBookStateClasses();

  const layer = ensureFullscreenBookTransitionLayer(direction, label);
  if (!layer) {
    if (typeof onSwap === 'function') onSwap();
    if (typeof onDone === 'function') onDone();
    fullscreenPageTransitionBusy = false;
    return;
  }

  // Force layout once so the animation starts cleanly every time.
  void layer.offsetWidth;
  document.body.classList.add('fullscreen-book-transition-active');
  layer.classList.add('is-running');

  const swapDelay = direction === 'to-editor' ? 560 : 540;
  const doneDelay = 1240;

  const swapTimer = window.setTimeout(() => {
    layer.classList.add('has-swapped');
    try {
      if (typeof onSwap === 'function') onSwap();
    } catch (error) {
      console.error('Book transition swap failed', error);
    }
  }, swapDelay);

  bookTransitionTimer = window.setTimeout(() => {
    window.clearTimeout(swapTimer);
    layer.classList.add('is-done');
    window.setTimeout(() => {
      removeFullscreenBookTransitionLayer();
      document.body.classList.remove('fullscreen-book-transition-active');
      clearFullscreenBookStateClasses();
      try {
        if (typeof onDone === 'function') onDone();
      } catch (error) {
        console.error('Book transition completion failed', error);
      }
      fullscreenPageTransitionBusy = false;
    }, 90);
  }, doneDelay);
}

function movePreviewPanelIntoEditorFullscreen() {
  if (!previewPanel || !editorPanel) return false;

  if (!previewMovedIntoEditor) {
    previewOriginalParent = previewPanel.parentElement;
    previewOriginalNextSibling = previewPanel.nextSibling;
    editorPanel.appendChild(previewPanel);
    previewMovedIntoEditor = true;
  }

  document.body.classList.add('preview-inside-editor-fullscreen');
  return true;
}

function restorePreviewPanelFromEditorFullscreen() {
  if (previewMovedIntoEditor && previewOriginalParent) {
    if (previewOriginalNextSibling && previewOriginalNextSibling.parentElement === previewOriginalParent) {
      previewOriginalParent.insertBefore(previewPanel, previewOriginalNextSibling);
    } else {
      previewOriginalParent.appendChild(previewPanel);
    }
  }

  previewMovedIntoEditor = false;
  previewOriginalParent = null;
  previewOriginalNextSibling = null;
  document.body.classList.remove('preview-inside-editor-fullscreen', 'preview-closing-to-editor');
}

function openOutputPreviewAfterFullEditor() {
  if (fullscreenPageTransitionBusy) return;
  fullscreenPageTransitionBusy = true;
  returnToFullEditorAfterPreview = true;
  hideSuggestions();
  closeCodeHelperPanel();

  runSmoothFullscreenBookTransition({
    direction: 'to-preview',
    label: 'Opening Output Preview',
    onSwap: () => {
      movePreviewPanelIntoEditorFullscreen();
      enterFullPreview({ fromFullEditor: true, nativeFullscreen: false, keepEditorFullscreen: true });
      document.body.classList.add('book-preview-revealing');
    },
    onDone: () => {
      document.body.classList.remove('book-preview-revealing');
      ensureBackToEditorPreviewBtn()?.focus({ preventScroll: true });
    }
  });
}

function runCode(showMessage = true, options = {}) {
  const wasFullEditor = document.body.classList.contains('editor-fullscreen-active');
  saveActiveEditor();
  const pageName = normalizeHtmlPageName(options.pageName || getActiveHtmlPageName());
  latestPreviewRuntimeError = '';
  latestPreviewConsoleMessage = '';
  previewRenderToken += 1;
  setPreviewLoading(true, { token: previewRenderToken, pageName });
  previewFrame.srcdoc = buildFullCode(pageName);
  previewFrame.dataset.currentPage = pageName;
  window.setTimeout(renderErrorChecker, 180);

  if (showMessage) {
    setStatus(wasFullEditor ? 'Output full preview' : `Output: ${pageName}`);
    if (options.trackRun !== false) markStudentProjectRun();
  }

  if (typeof window.__MCS_SUPER_STUDIO_AFTER_RUN__ === 'function') {
    try {
      window.__MCS_SUPER_STUDIO_AFTER_RUN__({ pageName, showMessage, options });
    } catch (error) {
      console.warn('Super Studio run hook skipped.', error);
    }
  }

  if (options.scroll !== false && showMessage) {
    if (wasFullEditor) {
      openOutputPreviewAfterFullEditor();
      return;
    }
    scrollToOutput();
  }
}

function getPreviewDocument() {
  try {
    return previewFrame.contentDocument || previewFrame.contentWindow.document;
  } catch (error) {
    return null;
  }
}

function getOutputText() {
  const doc = getPreviewDocument();
  return (doc?.body?.innerText || doc?.body?.textContent || '').toLowerCase();
}

function queryPreview(selector) {
  const doc = getPreviewDocument();
  try {
    return doc ? doc.querySelector(selector) : null;
  } catch (error) {
    return null;
  }
}

function navigatePreviewToPage(rawHref) {
  const target = normalizeInternalHtmlReference(rawHref);
  if (!target) return false;
  const pages = getHTMLPages();
  if (!hasOwnFile(pages, target)) {
    renderErrorChecker();
    setStatus('Missing page');
    appAlert(`${target} does not exist yet. Add this page in Pages, or change the link href.`, { title: 'Missing linked page' });
    return false;
  }
  latestPreviewRuntimeError = '';
  latestPreviewConsoleMessage = '';
  previewRenderToken += 1;
  setPreviewLoading(true, { token: previewRenderToken, pageName: target });
  previewFrame.srcdoc = buildFullCode(target);
  previewFrame.dataset.currentPage = target;
  setStatus(`Preview: ${target}`);
  return true;
}

window.addEventListener('message', event => {
  const data = event.data || {};
  if (!data) return;
  if (data.type === 'mcs-preview-navigate') {
    navigatePreviewToPage(data.href);
    return;
  }
  if (data.type === 'mcs-preview-runtime') {
    handlePreviewRuntimeIssue(data);
  }
});

function getBodyInnerHTML(html) {
  const match = String(html || '').match(/<body\b[^>]*>([\s\S]*?)<\/body\s*>/i);
  return match ? match[1] : String(html || '');
}

function stripHTMLTags(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function getDetailedHTMLTagIssues(html) {
  const source = String(html || '');
  const tags = parseHtmlTags(source);
  const structureReport = getHTMLStructureReport();
  const structureIsComplete = structureReport.passed;
  const protectedStructureTags = new Set(['html', 'head', 'body', 'title']);
  const optionalEndTags = new Set(['li', 'p', 'dt', 'dd', 'option', 'optgroup', 'tr', 'td', 'th', 'thead', 'tbody', 'tfoot', 'colgroup']);

  return tags
    .filter(tag => !tag.selfClosing && tag.pairIndex === null)
    .filter(tag => !(structureIsComplete && protectedStructureTags.has(tag.name)))
    .slice(0, 8)
    .map(tag => {
      const optional = optionalEndTags.has(tag.name);
      const reason = tag.unmatchedReason || (tag.closing ? 'missing-opening' : 'missing-closing');
      return {
        name: tag.name,
        line: getLineNumberAt(source, tag.start),
        closing: tag.closing,
        reason,
        severity: optional ? 'warning' : 'warning',
        confidence: optional ? 'low' : 'medium'
      };
    });
}

function hasBalancedCurlyBraces(value) {
  const text = String(value || '').replace(/(['"`])(?:\\.|(?!\1)[\s\S])*\1/g, '');
  let count = 0;
  for (const char of text) {
    if (char === '{') count += 1;
    if (char === '}') count -= 1;
    if (count < 0) return false;
  }
  return count === 0;
}

function getJavaScriptSyntaxError(js) {
  const code = String(js || '').trim();
  if (!code) return '';
  try {
    new Function(code);
    return '';
  } catch (error) {
    return error.message || String(error);
  }
}

function getRuntimeErrorMessage() {
  const doc = getPreviewDocument();
  return latestPreviewRuntimeError || doc?.body?.dataset?.runtimeError || '';
}

function createCheckerItem(type, title, detail, fix = '') {
  return { type, title, detail, fix };
}



function getSmartHTMLQualityIssues(html = '') {
  const issues = [];
  const lines = String(html || '').split('\n');
  const pushIssue = (index, issue, fix) => {
    issues.push({ line: index + 1, issue, fix });
  };

  lines.forEach((line, index) => {
    if (!line.trim() || /^\s*<!--/.test(line)) return;

    const spacedTag = line.match(/<\s+(\/?)\s*([a-zA-Z][\w:-]*)([^<>]*?)>/);
    if (spacedTag) {
      const tag = spacedTag[2].toLowerCase();
      const fixedTag = getClosestSmartHtmlTagName(tag) || tag;
      pushIssue(index, `Extra space inside <${tag}> tag`, `Change ${spacedTag[0]} to ${createFixedHtmlTagText(spacedTag[1], fixedTag, spacedTag[3])}.`);
      return;
    }

    const spacedClose = line.match(/<\s*\/\s+([a-zA-Z][\w:-]*)([^<>]*?)>/);
    if (spacedClose) {
      const tag = spacedClose[1].toLowerCase();
      const fixedTag = getClosestSmartHtmlTagName(tag) || tag;
      pushIssue(index, `Extra space inside closing tag </${tag}>`, `Change ${spacedClose[0]} to ${createFixedHtmlTagText('/', fixedTag, spacedClose[2])}.`);
      return;
    }

    const mismatch = line.match(/<\s*([a-zA-Z][\w:-]*)\b[^>]*>[\s\S]*?<\s*\/\s*([a-zA-Z][\w:-]*)\s*>/);
    if (mismatch) {
      const openTag = mismatch[1].toLowerCase();
      const closeTag = mismatch[2].toLowerCase();
      if (openTag !== closeTag && !SMART_INLINE_VOID_HTML_TAGS.has(openTag)) {
        pushIssue(index, `Opening <${openTag}> does not match closing </${closeTag}>`, `Change the closing tag to </${openTag}>.`);
        return;
      }
    }

    const tagPattern = /<\/?\s*([a-zA-Z][\w:-]*)/g;
    let match;
    while ((match = tagPattern.exec(line)) !== null) {
      const typed = match[1].toLowerCase();
      if (isSmartKnownHtmlTag(typed)) continue;
      const fixed = getClosestSmartHtmlTagName(typed);
      if (fixed && fixed !== typed) {
        pushIssue(index, `Possible misspelled HTML tag <${typed}>`, `Change <${typed}> to <${fixed}>.`);
        return;
      }
    }

    const unfinished = line.match(/<\s*(\/?)\s*([a-zA-Z][\w:-]*)(\s[^<>]*)?$/);
    if (unfinished && !line.includes('>', unfinished.index)) {
      const tag = unfinished[2].toLowerCase();
      const fixedTag = getClosestSmartHtmlTagName(tag) || tag;
      pushIssue(index, `Unfinished <${unfinished[1] || ''}${tag}> tag`, `Complete it as ${createFixedHtmlTagText(unfinished[1], fixedTag, unfinished[3] || '')}.`);
    }
  });

  return issues.slice(0, 6);
}




function getSmartHtmlAttributeMap(attrsText = '') {
  const attrs = {};
  const pattern = /([A-Za-z_:][\w:.-]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s"'=<>`]+))?/g;
  let match;
  while ((match = pattern.exec(String(attrsText || ''))) !== null) {
    const name = String(match[1] || '').toLowerCase();
    if (!name) continue;
    let value = match[2] || '';
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    attrs[name] = String(value || '').trim();
  }
  return attrs;
}

function getSmartHtmlContextCheckerItems(html = '') {
  const source = String(html || '');
  const items = [];
  const ids = new Map();
  const bodyStart = source.search(/<\s*body\b/i);
  const bodyEnd = source.search(/<\s*\/\s*body\s*>/i);
  const insideBody = index => bodyStart >= 0 && index > bodyStart && (bodyEnd < 0 || index < bodyEnd);
  let validStylesheetLinkCount = 0;
  let linkGuidanceShown = false;

  const tagPattern = /<\s*([a-zA-Z][\w:-]*)([^<>]*?)>/g;
  let match;
  while ((match = tagPattern.exec(source)) !== null) {
    const tagName = match[1].toLowerCase();
    const attrs = getSmartHtmlAttributeMap(match[2] || '');
    const line = getLineNumberAt(source, match.index);

    if (attrs.id) {
      if (!ids.has(attrs.id)) ids.set(attrs.id, []);
      ids.get(attrs.id).push(line);
    }

    if (tagName === 'link') {
      const rel = String(attrs.rel || '').toLowerCase();
      const href = attrs.href || '';
      if (!href) {
        items.push(createCheckerItem('warning', 'Link tag missing href', `Line ${line}: <link> is valid HTML, but it needs href="..." to point to a CSS file or resource.`, 'For CSS, use <link rel="stylesheet" href="style.css">. For clickable text, use <a href="...">Text</a>.'));
      } else if (/stylesheet/i.test(rel)) {
        validStylesheetLinkCount += 1;
      } else if (!linkGuidanceShown) {
        items.push(createCheckerItem('tip', '<link> is valid HTML', `Line ${line}: <link> is not an error. It connects external resources. If the goal is a clickable page link, use <a href="${href}">Text</a> instead.`, 'Keep <link> for CSS/resources. Use <a> for clickable links in the webpage body.'));
        linkGuidanceShown = true;
      }
      if (insideBody(match.index) && /stylesheet/i.test(rel)) {
        items.push(createCheckerItem('tip', 'Stylesheet link works best in head', `Line ${line}: Your stylesheet <link> is valid, but beginners should usually place it inside <head>.`, 'Move <link rel="stylesheet" href="style.css"> above </head> when possible.'));
      }
    }

    if (tagName === 'a' && !attrs.href) {
      items.push(createCheckerItem('warning', 'Clickable link missing href', `Line ${line}: <a> creates a clickable link, but it needs href="...".`, 'Example: <a href="https://example.com">Visit site</a>'));
    }

    if (tagName === 'img') {
      if (!attrs.src) {
        items.push(createCheckerItem('error', 'Image tag missing src', `Line ${line}: <img> is valid, but it needs src="..." so the browser knows which image to show.`, 'Example: <img src="photo.jpg" alt="Description">'));
      } else if (!attrs.alt) {
        items.push(createCheckerItem('tip', 'Image can be more accessible', `Line ${line}: Add alt="..." so readers know what the image means.`, 'Example: <img src="photo.jpg" alt="My school project">'));
      }
    }
  }

  ids.forEach((lines, id) => {
    if (lines.length > 1) {
      items.push(createCheckerItem('warning', 'Duplicate id found', `id="${id}" appears on lines ${lines.slice(0, 4).join(', ')}. IDs should be unique on a page.`, `Use class="${id}" for repeated styling, or give each element a different id.`));
    }
  });

  const listPattern = /<\s*(ul|ol)\b[^>]*>([\s\S]*?)<\s*\/\s*\1\s*>/gi;
  let listMatch;
  while ((listMatch = listPattern.exec(source)) !== null) {
    if (!/<\s*li\b/i.test(listMatch[2])) {
      items.push(createCheckerItem('warning', 'List has no list items', `Line ${getLineNumberAt(source, listMatch.index)}: <${listMatch[1].toLowerCase()}> should usually contain <li> items.`, `Add <li>Item</li> inside the <${listMatch[1].toLowerCase()}> list.`));
    }
  }

  if (validStylesheetLinkCount) {
    items.push(createCheckerItem('pass', 'Stylesheet link tag is valid', `<link rel="stylesheet" href="..."> is recognized correctly. It will not be treated as a <li> mistake.`));
  }

  return items.slice(0, 8);
}

function getFilenameReferenceCheckerItems() {
  const html = codeStore.html || '';
  const cssFiles = getLanguageFileMap('css');
  const jsFiles = getLanguageFileMap('js');
  const cssNames = Object.keys(cssFiles);
  const jsNames = Object.keys(jsFiles);
  const items = [];
  const cssReferences = getExternalCSSReferences(html);
  const jsReferences = getExternalJSReferences(html);
  const cssMissing = cssReferences
    .map(ref => cleanLanguageFileName(getBaseFileNameFromReference(ref), 'css'))
    .filter(name => name && !Object.prototype.hasOwnProperty.call(cssFiles, name));
  const jsMissing = jsReferences
    .map(ref => cleanLanguageFileName(getBaseFileNameFromReference(ref), 'js'))
    .filter(name => name && !Object.prototype.hasOwnProperty.call(jsFiles, name));
  const cssMatched = cssReferences
    .map(ref => cleanLanguageFileName(getBaseFileNameFromReference(ref), 'css'))
    .filter(name => name && Object.prototype.hasOwnProperty.call(cssFiles, name));
  const jsMatched = jsReferences
    .map(ref => cleanLanguageFileName(getBaseFileNameFromReference(ref), 'js'))
    .filter(name => name && Object.prototype.hasOwnProperty.call(jsFiles, name));

  if (cssReferences.length && cssMissing.length) {
    items.push(createCheckerItem(
      'error',
      'CSS file link mismatch',
      `HTML links to missing CSS file${cssMissing.length === 1 ? '' : 's'}: ${cssMissing.join(', ')}. Existing CSS files: ${cssNames.join(', ') || 'none'}.`,
      'Add that CSS file in Tabs/Pages, rename your CSS file, or change the HTML href.'
    ));
  } else if (cssMatched.length) {
    items.push(createCheckerItem('pass', 'CSS file link matches', `HTML correctly links to ${[...new Set(cssMatched)].join(', ')}.`));
  }

  if (jsReferences.length && jsMissing.length) {
    items.push(createCheckerItem(
      'error',
      'JavaScript file link mismatch',
      `HTML links to missing JavaScript file${jsMissing.length === 1 ? '' : 's'}: ${jsMissing.join(', ')}. Existing JS files: ${jsNames.join(', ') || 'none'}.`,
      'Add that JS file in Tabs/Pages, rename your JS file, or change the HTML src.'
    ));
  } else if (jsMatched.length) {
    items.push(createCheckerItem('pass', 'JavaScript file link matches', `HTML correctly links to ${[...new Set(jsMatched)].join(', ')}.`));
  }

  if (cssReferences.length && cssMatched.some(name => !String(cssFiles[name] || '').trim())) {
    items.push(createCheckerItem('warning', 'Linked CSS file is blank', 'One linked CSS file exists but has no CSS code yet.', 'Open that CSS file in Tabs/Pages and add CSS code.'));
  }

  if (jsReferences.length && jsMatched.some(name => !String(jsFiles[name] || '').trim())) {
    items.push(createCheckerItem('warning', 'Linked JavaScript file is blank', 'One linked JavaScript file exists but has no JavaScript code yet.', 'Open that JS file in Tabs/Pages and add JavaScript code.'));
  }

  return items;
}

function getErrorCheckerItems() {
  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const items = [];
  const structureReport = getHTMLStructureReport();
  const bodyInner = getBodyInnerHTML(html);
  const bodyText = stripHTMLTags(bodyInner);
  const tagIssues = getDetailedHTMLTagIssues(html);
  const smartHtmlIssues = getSmartHTMLQualityIssues(html);
  const jsSyntaxError = getJavaScriptSyntaxError(js);
  const runtimeError = getRuntimeErrorMessage();

  if (structureReport.passed) {
    items.push(createCheckerItem('pass', 'Complete HTML structure', 'DOCTYPE, html, head, title, and body are detected.'));
  } else {
    items.push(createCheckerItem(
      'error',
      'Missing HTML structure',
      `Missing: ${structureReport.missing.map(item => item.label).join(', ') || 'required structure'}.`,
      'Use the complete HTML starter structure before adding content.'
    ));
  }

  if (/<title\b[^>]*>\s*<\/title\s*>/i.test(html)) {
    items.push(createCheckerItem('warning', 'Empty title tag', 'Your <title> exists but has no title text.', 'Type a short page title inside <title>.'));
  } else if (/<title\b[^>]*>[\s\S]+?<\/title\s*>/i.test(html)) {
    items.push(createCheckerItem('pass', 'Title tag has content', 'The browser tab title is not empty.'));
  }

  if (bodyText.length >= 3) {
    items.push(createCheckerItem('pass', 'Body has visible content', 'Your webpage has readable text/content inside the body.'));
  } else {
    items.push(createCheckerItem('warning', 'Body looks empty', 'The body section has little or no visible text.', 'Add a heading, paragraph, image, button, or other visible content inside <body>.'));
  }

  items.push(...getSmartHtmlContextCheckerItems(html));

  if (smartHtmlIssues.length) {
    const details = smartHtmlIssues.map(item => `Line ${item.line}: ${item.issue}`).join('; ');
    const fixes = smartHtmlIssues.map(item => `Line ${item.line}: ${item.fix}`).join(' ');
    items.push(createCheckerItem(
      'error',
      'Smart HTML correction needed',
      details,
      fixes || 'Use Smart Hint on the red/problem line to apply the correction.'
    ));
  }

  if (!tagIssues.length && !smartHtmlIssues.length) {
    items.push(createCheckerItem('pass', 'HTML tags look balanced', 'No confirmed missing opening/closing tag was detected.'));
  } else if (tagIssues.length) {
    const details = tagIssues.map(issue => {
      return issue.closing
        ? `Possible issue: </${issue.name}> on line ${issue.line} may not have a matching opening tag`
        : `Possible issue: <${issue.name}> on line ${issue.line} may need </${issue.name}>`;
    }).join('; ');
    items.push(createCheckerItem(
      'warning',
      'Possible tag closing issue',
      details,
      'Review the highlighted line, but do not worry if the page output is correct. This checker now treats uncertain tag matches as warnings, not automatic errors.'
    ));
  }

  if (css.trim()) {
    if (hasBalancedCurlyBraces(css)) {
      items.push(createCheckerItem('pass', 'CSS braces look okay', 'Opening and closing curly braces are balanced.'));
    } else {
      items.push(createCheckerItem('error', 'CSS brace problem', 'One or more CSS { } braces are missing or extra.', 'Check each selector and make sure every { has a matching }.'));
    }

    if (!/[a-z-]+\s*:\s*[^;{}]+;?/i.test(css)) {
      items.push(createCheckerItem('warning', 'CSS may be incomplete', 'CSS has text but no clear property/value pair was detected.', 'Example: color: blue; or background: lightyellow;'));
    }
  } else {
    items.push(createCheckerItem('tip', 'CSS is blank', 'This is okay if the activity does not require design.'));
  }

  if (js.trim()) {
    if (jsSyntaxError) {
      items.push(createCheckerItem('error', 'JavaScript syntax error', jsSyntaxError, 'Check missing parentheses, quotes, braces, or semicolons.'));
    } else {
      items.push(createCheckerItem('pass', 'JavaScript syntax looks okay', 'No basic JavaScript syntax error was detected.'));
    }

    if (runtimeError) {
      items.push(createCheckerItem('error', 'JavaScript runtime error', runtimeError, 'Run again after checking element IDs, variable names, and event code.'));
    }
  } else {
    items.push(createCheckerItem('tip', 'JavaScript is blank', 'This is okay if the activity does not require interactivity.'));
  }

  items.push(...getFilenameReferenceCheckerItems());

  const pageNames = getHTMLPageNames();
  if (pageNames.length > 1) {
    items.push(createCheckerItem('pass', 'Multi-page website mode', `${pageNames.length} HTML pages found: ${pageNames.join(', ')}.`));
  }

  const missingPageLinks = getMissingInternalPageReferences();
  if (missingPageLinks.length) {
    const details = missingPageLinks.slice(0, 6).map(item => `${item.from} links to missing ${item.to}`).join('; ');
    items.push(createCheckerItem('error', 'Broken page links', details, 'Add the missing page in Pages or change the href to an existing .html file.'));
  } else if (pageNames.length > 1) {
    items.push(createCheckerItem('pass', 'Page links look valid', 'Internal .html links point to existing pages.'));
  }

  const pageStructureProblems = getPageStructureProblems();
  if (pageStructureProblems.length) {
    const details = pageStructureProblems.slice(0, 5).map(item => `${item.pageName} missing ${item.missing.join(', ')}`).join('; ');
    items.push(createCheckerItem('warning', 'Some pages need complete HTML structure', details, 'Open each page from Pages and complete its HTML structure.'));
  }

  return items;
}


function getAICodeCheckerEndpoint() {
  return String(window.MCS_AI_CHECKER_ENDPOINT || window.MCS_AI_CODE_CHECK_ENDPOINT || '').trim();
}

function isAICodeCheckerEnabled() {
  return window.MCS_AI_CHECKER_ENABLED !== false;
}

function buildAICodeCheckerPayload(items = getErrorCheckerItems()) {
  const snapshot = getSmartProjectCodeSnapshot();
  return {
    app: 'ICT 8 Connect',
    task: 'teacher-code-helper-check',
    level: 'Grade 8 beginner web development',
    checkerItems: items.map(item => ({
      type: item.type,
      title: item.title,
      detail: item.detail,
      fix: item.fix || ''
    })),
    outputText: getOutputText().slice(0, 4000),
    activeFile: {
      language: activeLanguage,
      name: getActiveLanguageFileName(activeLanguage)
    },
    files: {
      html: snapshot.htmlFiles,
      css: snapshot.cssFiles,
      js: snapshot.jsFiles
    },
    code: {
      html: getShortCodeSample(codeStore.html, 9000),
      css: getShortCodeSample(codeStore.css, 7000),
      js: getShortCodeSample(codeStore.js, 7000)
    },
    instruction: [
      'Act like a helpful Grade 8 ICT teacher and code debugging assistant.',
      'Analyze the full HTML, CSS, and JavaScript together, not only the current line.',
      'Find exact beginner mistakes: misspelled tags/attributes/properties/functions, wrong closing tags, missing dots, wrong id/class selectors, onclick function mismatches, broken links, missing linked files, and runtime causes.',
      'For every confirmed issue, explain why it is wrong and give the exact corrected code snippet, but do not rewrite the whole project.',
      'Be careful with false positives. If the output can still work, mark it as a warning or improvement, not an error.',
      'Return JSON only with keys: summary, confirmedErrors, falsePositiveWarnings, suggestions, exactFixes, crossFileFindings, improvements, nextSteps.',
      'exactFixes should be an array of objects: {file,line,issue,why,before,after}. Keep snippets short and beginner-friendly.'
    ].join(' ')
  };
}

function smartArrayFromAny(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map(item => {
      if (typeof item === 'string') return item.trim();
      if (item && typeof item === 'object') {
        return [item.file, item.line ? `Line ${item.line}` : '', item.issue || item.title || item.detail || item.message || item.suggestion]
          .filter(Boolean)
          .join(' - ')
          .trim();
      }
      return '';
    })
    .filter(Boolean)
    .slice(0, 8);
}

function normalizeSmartExactFixes(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map(item => {
      if (typeof item === 'string') {
        return { file: '', line: '', issue: item, why: '', before: '', after: '' };
      }
      if (!item || typeof item !== 'object') return null;
      return {
        file: String(item.file || item.filename || '').trim(),
        line: item.line || item.lineNumber || '',
        issue: String(item.issue || item.title || item.detail || '').trim(),
        why: String(item.why || item.explanation || item.reason || '').trim(),
        before: String(item.before || item.oldCode || item.current || '').trim(),
        after: String(item.after || item.fixedCode || item.corrected || item.replacement || '').trim()
      };
    })
    .filter(item => item && (item.issue || item.after || item.why))
    .slice(0, 6);
}

function normalizeAICodeCheckResponse(data) {
  const source = data?.check || data?.review || data || {};
  return {
    summary: String(source.summary || source.message || 'Advanced check completed.'),
    confirmedErrors: smartArrayFromAny(source.confirmedErrors),
    falsePositiveWarnings: smartArrayFromAny(source.falsePositiveWarnings),
    suggestions: smartArrayFromAny(source.suggestions),
    exactFixes: normalizeSmartExactFixes(source.exactFixes || source.fixes || source.corrections),
    crossFileFindings: smartArrayFromAny(source.crossFileFindings || source.crossFileIssues || source.connections),
    improvements: smartArrayFromAny(source.improvements || source.recommendations),
    nextSteps: smartArrayFromAny(source.nextSteps || source.actions)
  };
}

function getSmartProjectCodeSnapshot() {
  const mapToArray = (language, limit) => {
    const files = getLanguageFileMap(language);
    return Object.entries(files || {}).map(([name, content]) => ({
      name,
      content: getShortCodeSample(String(content || ''), limit)
    }));
  };
  return {
    htmlFiles: mapToArray('html', 9000),
    cssFiles: mapToArray('css', 7000),
    jsFiles: mapToArray('js', 7000)
  };
}

function getSmartLineText(text = '', lineNumber = 1) {
  return String(text || '').split('\n')[Math.max(0, Number(lineNumber || 1) - 1)] || '';
}

function addSmartExactFix(list, data = {}) {
  if (!data.issue && !data.after) return;
  if (list.length >= 8) return;
  list.push({
    file: String(data.file || '').trim(),
    line: data.line || '',
    issue: String(data.issue || '').trim(),
    why: String(data.why || '').trim(),
    before: String(data.before || '').trim(),
    after: String(data.after || '').trim()
  });
}

function addSmartUniqueString(list, value, limit = 8) {
  const text = String(value || '').trim();
  if (!text || list.includes(text) || list.length >= limit) return;
  list.push(text);
}

const SMART_PROJECT_HTML_ATTR_FIXES = {
  clss: 'class', clas: 'class', calss: 'class', cls: 'class', classs: 'class',
  ids: 'id', iid: 'id', idd: 'id',
  herf: 'href', hre: 'href', hreff: 'href', ref: 'href',
  scr: 'src', sr: 'src', source: 'src',
  onclik: 'onclick', onlick: 'onclick', oncilck: 'onclick', click: 'onclick',
  stlye: 'style', sytle: 'style', styl: 'style',
  atl: 'alt', lat: 'alt', altt: 'alt',
  palceholder: 'placeholder', placehoder: 'placeholder',
  typ: 'type', tipe: 'type', valu: 'value', valeu: 'value',
  targt: 'target', traget: 'target', rels: 'rel', namee: 'name', form: 'for'
};

const SMART_PROJECT_COMMON_HTML_ATTRS = new Set([
  'accept', 'accept-charset', 'accesskey', 'action', 'allow', 'alt', 'async', 'autocomplete', 'autofocus',
  'autoplay', 'charset', 'checked', 'cite', 'class', 'cols', 'colspan', 'content', 'contenteditable',
  'controls', 'coords', 'data', 'datetime', 'defer', 'dir', 'disabled', 'download', 'draggable', 'enctype',
  'for', 'form', 'height', 'hidden', 'href', 'hreflang', 'id', 'lang', 'list', 'loop', 'max', 'maxlength',
  'media', 'method', 'min', 'multiple', 'muted', 'name', 'pattern', 'placeholder', 'poster', 'preload',
  'readonly', 'rel', 'required', 'reversed', 'role', 'rows', 'rowspan', 'selected', 'shape', 'size', 'span',
  'spellcheck', 'src', 'srcset', 'start', 'step', 'style', 'tabindex', 'target', 'title', 'type', 'value',
  'width', 'wrap',
  // Event attributes supported for beginner projects. Other on* attributes are accepted separately.
  'onclick', 'onchange', 'oninput', 'onsubmit', 'onmouseover', 'onmouseout', 'onkeydown', 'onkeyup',
  // Common ARIA labels are accepted, while any aria-* and data-* are accepted by prefix checks.
  'aria-label', 'aria-hidden', 'aria-expanded', 'aria-controls'
]);

function getClosestSmartHtmlAttributeName(name = '') {
  return getClosestSmartInlineValue(name, SMART_PROJECT_COMMON_HTML_ATTRS, SMART_PROJECT_HTML_ATTR_FIXES, { maxDistance: String(name || '').length <= 4 ? 1 : 2 });
}

function getSmartProjectHtmlFacts(snapshot) {
  const ids = new Set();
  const classes = new Set();
  const tags = new Set();
  const onclickCalls = [];
  const links = [];
  (snapshot.htmlFiles || []).forEach(file => {
    const html = String(file.content || '');
    const tagPattern = /<\s*([a-zA-Z][\w:-]*)([^<>]*)>/g;
    let tagMatch;
    while ((tagMatch = tagPattern.exec(html)) !== null) {
      const tagName = tagMatch[1].toLowerCase();
      const attrsText = tagMatch[2] || '';
      tags.add(tagName);
      const line = getLineNumberAt(html, tagMatch.index);
      const idMatch = attrsText.match(/\bid\s*=\s*(["'])(.*?)\1/i);
      if (idMatch?.[2]) ids.add(idMatch[2].trim());
      const classMatch = attrsText.match(/\bclass\s*=\s*(["'])(.*?)\1/i);
      if (classMatch?.[2]) classMatch[2].split(/\s+/).filter(Boolean).forEach(cls => classes.add(cls));
      const hrefMatch = attrsText.match(/\bhref\s*=\s*(["'])(.*?)\1/i);
      if (hrefMatch?.[2]) links.push({ file: file.name, line, value: hrefMatch[2].trim() });
      const eventPattern = /\bon\w+\s*=\s*(["'])\s*([A-Za-z_$][\w$]*)\s*\(/gi;
      let eventMatch;
      while ((eventMatch = eventPattern.exec(attrsText)) !== null) {
        onclickCalls.push({ file: file.name, line, name: eventMatch[2], before: eventMatch[0] });
      }
    }
  });
  return { ids, classes, tags, onclickCalls, links };
}

function getSmartProjectJsFacts(snapshot) {
  const functions = new Set();
  const idRefs = [];
  const classRefs = [];
  (snapshot.jsFiles || []).forEach(file => {
    const js = String(file.content || '');
    const functionPattern = /\bfunction\s+([A-Za-z_$][\w$]*)\s*\(|\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:function\s*\(|(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>)/g;
    let fnMatch;
    while ((fnMatch = functionPattern.exec(js)) !== null) functions.add(fnMatch[1] || fnMatch[2]);

    const getIdPattern = /\bgetElementById\s*\(\s*(["'])(.*?)\1\s*\)/g;
    let idMatch;
    while ((idMatch = getIdPattern.exec(js)) !== null) {
      idRefs.push({ file: file.name, line: getLineNumberAt(js, idMatch.index), value: idMatch[2], before: idMatch[0], kind: 'getElementById' });
    }

    const selectorPattern = /\bquerySelector(?:All)?\s*\(\s*(["'])([.#])([^"']+)\1\s*\)/g;
    let selectorMatch;
    while ((selectorMatch = selectorPattern.exec(js)) !== null) {
      const list = selectorMatch[2] === '#' ? idRefs : classRefs;
      list.push({
        file: file.name,
        line: getLineNumberAt(js, selectorMatch.index),
        value: selectorMatch[3].trim(),
        before: selectorMatch[0],
        kind: selectorMatch[2] === '#' ? 'querySelector id' : 'querySelector class'
      });
    }
  });
  return { functions, idRefs, classRefs };
}

function findClosestSmartName(value = '', choices = []) {
  const clean = String(value || '').trim();
  if (!clean) return '';
  let best = '';
  let bestDistance = Infinity;
  for (const choice of choices || []) {
    const distance = getSmartInlineEditDistance(clean, String(choice || ''));
    if (distance < bestDistance) {
      best = String(choice || '');
      bestDistance = distance;
    }
  }
  const maxDistance = clean.length <= 4 ? 1 : 2;
  return best && bestDistance <= maxDistance ? best : '';
}

function analyzeSmartHtmlFiles(snapshot, review) {
  (snapshot.htmlFiles || []).forEach(file => {
    const html = String(file.content || '');
    const lines = html.split('\n');
    lines.forEach((lineText, index) => {
      const line = index + 1;
      const spacedTag = lineText.match(/<\s+(\/?)\s*([a-zA-Z][\w:-]*)([^<>]*?)>/);
      if (spacedTag) {
        const fixedTag = getClosestSmartHtmlTagName(spacedTag[2]) || spacedTag[2].toLowerCase();
        addSmartExactFix(review.exactFixes, {
          file: file.name,
          line,
          issue: 'May extra space after < in an HTML tag.',
          why: 'Browsers may not read a tag correctly when the tag name is separated from the < symbol.',
          before: spacedTag[0],
          after: createFixedHtmlTagText(spacedTag[1], fixedTag, spacedTag[3])
        });
      }

      const spacedClose = lineText.match(/<\s*\/\s+([a-zA-Z][\w:-]*)([^<>]*?)>/);
      if (spacedClose) {
        const fixedTag = getClosestSmartHtmlTagName(spacedClose[1]) || spacedClose[1].toLowerCase();
        addSmartExactFix(review.exactFixes, {
          file: file.name,
          line,
          issue: 'May extra space inside a closing tag.',
          why: 'A closing tag should be written like </tag>, without a space after /.',
          before: spacedClose[0],
          after: createFixedHtmlTagText('/', fixedTag, spacedClose[2])
        });
      }

      const tagPattern = /<\/?\s*([a-zA-Z][\w:-]*)\b/g;
      let tagMatch;
      while ((tagMatch = tagPattern.exec(lineText)) !== null) {
        const typed = tagMatch[1].toLowerCase();
        if (isSmartKnownHtmlTag(typed)) continue;
        const fixed = getClosestSmartHtmlTagName(typed);
        if (fixed && fixed !== typed) {
          addSmartExactFix(review.exactFixes, {
            file: file.name,
            line,
            issue: `Possible misspelled HTML tag <${typed}>.`,
            why: `HTML has a <${fixed}> tag, but <${typed}> is not a common beginner tag.`,
            before: `<${typed}>`,
            after: `<${fixed}>`
          });
        }
      }

      const tagWithAttrs = lineText.match(/<\s*([a-zA-Z][\w:-]*)([^<>]*)>/);
      if (tagWithAttrs?.[2]) {
        const attrs = tagWithAttrs[2];
        const attrPattern = /\s([^\s=\/<>]+)(\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?/g;
        let attrMatch;
        while ((attrMatch = attrPattern.exec(attrs)) !== null) {
          const attrName = attrMatch[1].toLowerCase();
          if (!attrName || attrName.startsWith('data-') || attrName.startsWith('aria-') || attrName.startsWith('on')) continue;
          if (SMART_PROJECT_COMMON_HTML_ATTRS.has(attrName)) continue;
          const fixedAttr = getClosestSmartHtmlAttributeName(attrName);
          if (fixedAttr && fixedAttr !== attrName) {
            addSmartExactFix(review.exactFixes, {
              file: file.name,
              line,
              issue: `Possible misspelled HTML attribute ${attrName}.`,
              why: `The browser needs the correct attribute name ${fixedAttr} to connect styling, links, images, or actions.`,
              before: attrMatch[0].trim(),
              after: `${fixedAttr}${attrMatch[2] || ''}`.trim()
            });
          }
        }
      }

      if (/<\s*img\b/i.test(lineText) && !/\balt\s*=/i.test(lineText)) {
        addSmartUniqueString(review.improvements, `${file.name} line ${line}: Add alt="..." to the image so the page is more accessible.`);
      }
    });
  });
}

function analyzeSmartCssFiles(snapshot, htmlFacts, review) {
  (snapshot.cssFiles || []).forEach(file => {
    const css = String(file.content || '');
    const lines = css.split('\n');
    lines.forEach((lineText, index) => {
      const line = index + 1;
      const propertyMatch = lineText.match(/^\s*([a-zA-Z][\w\s-]*)\s*:\s*([^;{}]+);?/);
      if (propertyMatch) {
        const typed = propertyMatch[1].trim().toLowerCase();
        const fixed = getClosestSmartCssPropertyName(typed);
        if (fixed && fixed !== typed) {
          const before = propertyMatch[0].trim();
          const after = before.replace(propertyMatch[1], fixed);
          addSmartExactFix(review.exactFixes, {
            file: file.name,
            line,
            issue: `Possible misspelled CSS property ${typed}.`,
            why: `CSS will ignore properties it does not understand. Use ${fixed}.`,
            before,
            after
          });
        }
        if (!/;\s*$/.test(lineText.trim()) && !/[{}]/.test(lineText)) {
          addSmartUniqueString(review.suggestions, `${file.name} line ${line}: Add ; at the end of the CSS declaration for cleaner code.`);
        }
      } else if (/^\s*[a-zA-Z][\w\s-]+\s+[^:{};]+;?\s*$/.test(lineText) && !/[{}]/.test(lineText)) {
        addSmartExactFix(review.exactFixes, {
          file: file.name,
          line,
          issue: 'This CSS line may be missing a colon.',
          why: 'CSS properties use property: value; format.',
          before: lineText.trim(),
          after: lineText.trim().replace(/^(\s*[a-zA-Z][\w\s-]+)\s+(.+)$/, '$1: $2')
        });
      }
    });

    const selectorPattern = /(^|[}\n,])\s*([#.])([A-Za-z_][\w-]*)\s*(?=[,{])/g;
    let selectorMatch;
    while ((selectorMatch = selectorPattern.exec(css)) !== null) {
      const symbol = selectorMatch[2];
      const name = selectorMatch[3];
      const line = getLineNumberAt(css, selectorMatch.index);
      if (symbol === '.' && !htmlFacts.classes.has(name)) {
        const closest = findClosestSmartName(name, [...htmlFacts.classes]);
        addSmartUniqueString(review.crossFileFindings, closest
          ? `${file.name} line ${line}: CSS uses .${name}, but HTML has class="${closest}". Change the selector to .${closest} or change the HTML class.`
          : `${file.name} line ${line}: CSS selector .${name} does not match any class currently found in the HTML.`);
      }
      if (symbol === '#' && !htmlFacts.ids.has(name)) {
        const closest = findClosestSmartName(name, [...htmlFacts.ids]);
        addSmartUniqueString(review.crossFileFindings, closest
          ? `${file.name} line ${line}: CSS uses #${name}, but HTML has id="${closest}". Change the selector to #${closest} or change the HTML id.`
          : `${file.name} line ${line}: CSS selector #${name} does not match any id currently found in the HTML.`);
      }
    }
  });
}

function analyzeSmartJsConnections(snapshot, htmlFacts, review) {
  const jsFacts = getSmartProjectJsFacts(snapshot);
  htmlFacts.onclickCalls.forEach(call => {
    if (jsFacts.functions.has(call.name)) return;
    const closest = findClosestSmartName(call.name, [...jsFacts.functions]);
    if (closest) {
      addSmartExactFix(review.exactFixes, {
        file: call.file,
        line: call.line,
        issue: `HTML calls ${call.name}(), but JavaScript has ${closest}().`,
        why: 'The onclick function name must match the JavaScript function name exactly.',
        before: `${call.name}()`,
        after: `${closest}()`
      });
    } else {
      addSmartUniqueString(review.confirmedErrors, `${call.file} line ${call.line}: HTML calls ${call.name}(), but no JavaScript function with that name was found.`);
      addSmartUniqueString(review.nextSteps, `Create function ${call.name}() in JavaScript or correct the onclick name in the HTML.`);
    }
  });

  jsFacts.idRefs.forEach(ref => {
    if (htmlFacts.ids.has(ref.value)) return;
    const closest = findClosestSmartName(ref.value, [...htmlFacts.ids]);
    if (closest) {
      addSmartExactFix(review.exactFixes, {
        file: ref.file,
        line: ref.line,
        issue: `JavaScript looks for id "${ref.value}", but HTML has id "${closest}".`,
        why: 'getElementById and # selectors must match the exact id in HTML.',
        before: ref.value,
        after: closest
      });
    } else {
      addSmartUniqueString(review.crossFileFindings, `${ref.file} line ${ref.line}: JavaScript references id "${ref.value}", but that id is not found in the HTML.`);
    }
  });

  jsFacts.classRefs.forEach(ref => {
    if (htmlFacts.classes.has(ref.value)) return;
    const closest = findClosestSmartName(ref.value, [...htmlFacts.classes]);
    addSmartUniqueString(review.crossFileFindings, closest
      ? `${ref.file} line ${ref.line}: JavaScript uses .${ref.value}, but HTML has class="${closest}".`
      : `${ref.file} line ${ref.line}: JavaScript references class "${ref.value}", but that class is not found in the HTML.`);
  });
}

function getLocalSmartTeacherReview(items = getErrorCheckerItems()) {
  const snapshot = getSmartProjectCodeSnapshot();
  const htmlFacts = getSmartProjectHtmlFacts(snapshot);
  const errors = items.filter(item => item.type === 'error');
  const warnings = items.filter(item => item.type === 'warning');
  const possibleTagWarnings = warnings.filter(item => /tag/i.test(item.title));
  const review = {
    summary: '',
    confirmedErrors: errors.map(item => `${item.title}: ${item.detail}`).slice(0, 6),
    falsePositiveWarnings: possibleTagWarnings.map(item => `${item.title}: ${item.detail}`).slice(0, 4),
    suggestions: warnings
      .filter(item => !/tag/i.test(item.title))
      .map(item => item.fix || item.detail)
      .filter(Boolean)
      .slice(0, 6),
    exactFixes: [],
    crossFileFindings: [],
    improvements: [],
    nextSteps: []
  };

  analyzeSmartHtmlFiles(snapshot, review);
  analyzeSmartCssFiles(snapshot, htmlFacts, review);
  analyzeSmartJsConnections(snapshot, htmlFacts, review);

  if (!review.nextSteps.length) {
    if (review.exactFixes.length) addSmartUniqueString(review.nextSteps, 'Apply the exact fixes one at a time, then click Run Code again.');
    else if (review.crossFileFindings.length) addSmartUniqueString(review.nextSteps, 'Check if the HTML names, CSS selectors, and JavaScript references match exactly.');
    else addSmartUniqueString(review.nextSteps, 'Run the code and compare the output with the activity instructions.');
  }

  const totalIssues = errors.length + review.exactFixes.length + review.crossFileFindings.length;
  review.summary = totalIssues
    ? `${totalIssues} issue${totalIssues === 1 ? '' : 's'} found. Smart Helper checked HTML, CSS, JavaScript, and connections between files.`
    : warnings.length
      ? `No confirmed coding errors found. ${warnings.length} warning${warnings.length === 1 ? '' : 's'} may still need review.`
      : 'No confirmed errors found. The project looks okay based on the smart local teacher check.';

  return review;
}

function getLocalSmartCheckerReview(items = getErrorCheckerItems()) {
  return getLocalSmartTeacherReview(items);
}

function renderSmartExactFixList(fixes = []) {
  return fixes.map(fix => `
    <li class="advanced-checker-fix-item">
      <strong>${escapeHTML([fix.file, fix.line ? `Line ${fix.line}` : ''].filter(Boolean).join(' · ') || 'Suggested fix')}</strong>
      <span>${escapeHTML(fix.issue || 'Use this correction.')}</span>
      ${fix.why ? `<small>${escapeHTML(fix.why)}</small>` : ''}
      ${fix.before || fix.after ? `
        <div class="advanced-checker-code-pair">
          ${fix.before ? `<code><b>Now:</b> ${escapeHTML(fix.before)}</code>` : ''}
          ${fix.after ? `<code><b>Use:</b> ${escapeHTML(fix.after)}</code>` : ''}
        </div>
      ` : ''}
    </li>
  `).join('');
}

function renderAdvancedCheckerReview(review, options = {}) {
  if (!errorCheckerContent) return;
  const safe = normalizeAICodeCheckResponse(review);
  const existing = errorCheckerContent.querySelector('.advanced-checker-card');
  if (existing) existing.remove();

  const card = document.createElement('div');
  card.className = `advanced-checker-card ${options.loading ? 'loading' : ''}`;
  card.innerHTML = options.loading ? `
    <div class="advanced-checker-head">
      <strong>Smart teacher helper is checking...</strong>
      <span>Reading the HTML, CSS, JavaScript, output, and file connections.</span>
    </div>
  ` : `
    <div class="advanced-checker-head">
      <strong>${escapeHTML(options.remote ? 'Smart teacher helper' : 'Smart teacher helper')}</strong>
      <span>${escapeHTML(safe.summary)}</span>
    </div>
    ${safe.exactFixes.length ? `
      <div class="advanced-checker-block fix">
        <h4>Exact code fixes</h4>
        <ul class="advanced-checker-fix-list">${renderSmartExactFixList(safe.exactFixes)}</ul>
      </div>
    ` : ''}
    ${safe.confirmedErrors.length ? `
      <div class="advanced-checker-block error">
        <h4>Confirmed issues</h4>
        <ul>${safe.confirmedErrors.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
    ${safe.crossFileFindings.length ? `
      <div class="advanced-checker-block warning">
        <h4>HTML/CSS/JavaScript connections</h4>
        <ul>${safe.crossFileFindings.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
    ${safe.falsePositiveWarnings.length ? `
      <div class="advanced-checker-block warning">
        <h4>Review only / possible false alarm</h4>
        <ul>${safe.falsePositiveWarnings.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
    ${safe.suggestions.length ? `
      <div class="advanced-checker-block tip">
        <h4>Suggestions</h4>
        <ul>${safe.suggestions.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
    ${safe.improvements.length ? `
      <div class="advanced-checker-block tip">
        <h4>Improve your code</h4>
        <ul>${safe.improvements.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
    ${safe.nextSteps.length ? `
      <div class="advanced-checker-block tip">
        <h4>Next steps</h4>
        <ul>${safe.nextSteps.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
      </div>
    ` : ''}
  `;

  errorCheckerContent.prepend(card);
}

async function requestAdvancedErrorCheck() {
  saveActiveEditor();
  runCode(false, { scroll: false });
  const items = getErrorCheckerItems();
  renderErrorChecker();

  if (!isAICodeCheckerEnabled()) {
    renderAdvancedCheckerReview(getLocalSmartCheckerReview(items));
    setStatus('Smart checked');
    return;
  }

  const endpoint = getAICodeCheckerEndpoint();
  if (!endpoint) {
    renderAdvancedCheckerReview(getLocalSmartCheckerReview(items));
    setStatus('Smart checked');
    return;
  }

  renderAdvancedCheckerReview(getLocalSmartCheckerReview(items), { loading: true, remote: true });
  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(buildAICodeCheckerPayload(items))
    });
    if (!response.ok) throw new Error(`Checker endpoint returned ${response.status}`);
    const data = await response.json();
    renderAdvancedCheckerReview(normalizeAICodeCheckResponse(data), { remote: true });
    setStatus('Advanced checked');
  } catch (error) {
    console.warn('Advanced checker failed; using smart local review.', error);
    const fallback = getLocalSmartCheckerReview(items);
    fallback.summary = `${fallback.summary} Advanced verification was unavailable, so the smart local checker was used.`;
    renderAdvancedCheckerReview(fallback);
    setStatus('Smart checked');
  }
}

function renderErrorChecker() {
  if (!errorCheckerContent) return;
  const items = getErrorCheckerItems();
  const errorCount = items.filter(item => item.type === 'error').length;
  const warningCount = items.filter(item => item.type === 'warning').length;
  const passCount = items.filter(item => item.type === 'pass').length;

  const summaryClass = errorCount ? 'error' : warningCount ? 'warning' : 'pass';
  const summaryText = errorCount
    ? `${errorCount} error${errorCount > 1 ? 's' : ''} found`
    : warningCount
      ? `${warningCount} warning${warningCount > 1 ? 's' : ''} found`
      : 'No major errors found';

  errorCheckerContent.innerHTML = `
    ${renderCssFinderCardHtml()}
    <div class="checker-summary ${summaryClass}">
      <div>
        <strong>${escapeHTML(summaryText)}</strong>
        <span>${passCount} passed checks · ${warningCount} warning${warningCount === 1 ? '' : 's'} · ${errorCount} error${errorCount === 1 ? '' : 's'}</span>
      </div>
    </div>
    <div class="checker-list">
      ${items.map(item => `
        <article class="checker-item ${escapeAttribute(item.type)}">
          <span class="checker-icon">${item.type === 'pass' ? '✓' : item.type === 'error' ? '!' : item.type === 'warning' ? '⚠' : 'i'}</span>
          <div>
            <h3>${escapeHTML(item.title)}</h3>
            <p>${escapeHTML(item.detail)}</p>
            ${item.fix ? `<small>Fix: ${escapeHTML(item.fix)}</small>` : ''}
          </div>
        </article>
      `).join('')}
    </div>
  `;
}



function openCodeHelperPanel() {
  if (!errorCheckerPanel) return;
  if (!isStudentAssistanceFeatureEnabled('codeHelper')) {
    setStatus('Code Helper is disabled by the teacher');
    return;
  }
  saveActiveEditor();
  renderErrorChecker();
  errorCheckerPanel.classList.remove('hidden');
  errorCheckerPanel.setAttribute('aria-hidden', 'false');
  document.body.classList.add('code-helper-open');
  setStatus('Code Helper opened');
  window.setTimeout(() => refreshErrorCheckerBtn?.focus({ preventScroll: true }), 0);
}

function closeCodeHelperPanel() {
  if (!errorCheckerPanel) return;
  errorCheckerPanel.classList.add('hidden');
  errorCheckerPanel.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('code-helper-open');
  codeHelperFloatingBtn?.focus({ preventScroll: true });
}

function toggleCodeHelperPanel() {
  if (!errorCheckerPanel) return;
  if (!isStudentAssistanceFeatureEnabled('codeHelper')) {
    setStatus('Code Helper is disabled by the teacher');
    return;
  }
  if (errorCheckerPanel.classList.contains('hidden')) {
    openCodeHelperPanel();
  } else {
    closeCodeHelperPanel();
  }
}


let deferredInstallPrompt = null;

function isAppInstalledMode() {
  return window.matchMedia?.('(display-mode: standalone)')?.matches || window.navigator.standalone === true;
}

function updateInstallButtonVisibility() {
  if (!installAppBtn) return;
  const shouldShow = !isAppInstalledMode();
  installAppBtn.classList.toggle('hidden', !shouldShow);
}

function registerPWAServiceWorker() {
  if (!('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./service-worker.js').catch(error => {
      console.warn('Service worker registration failed', error);
    });
  });
}

async function handleInstallAppClick() {
  if (deferredInstallPrompt) {
    deferredInstallPrompt.prompt();
    try {
      await deferredInstallPrompt.userChoice;
    } catch (error) {
      console.warn('Install prompt closed', error);
    }
    deferredInstallPrompt = null;
    updateInstallButtonVisibility();
    return;
  }

  const isiOS = /iphone|ipad|ipod/i.test(window.navigator.userAgent || '');
  const message = isiOS
    ? 'To install on iPhone/iPad: tap Share, then choose Add to Home Screen.'
    : 'To install on Android/Chrome: open the browser menu, then choose Install app or Add to Home screen.';
  appAlert(message, { title: 'Install on phone' });
}

function setupPWAInstallPrompt() {
  updateInstallButtonVisibility();

  window.addEventListener('beforeinstallprompt', event => {
    event.preventDefault();
    deferredInstallPrompt = event;
    updateInstallButtonVisibility();
  });

  window.addEventListener('appinstalled', () => {
    deferredInstallPrompt = null;
    updateInstallButtonVisibility();
    setStatus('Installed');
  });

  installAppBtn?.addEventListener('click', handleInstallAppClick);
}

function countSemanticHTMLTags(html) {
  const matches = String(html || '').match(/<(header|nav|main|section|article|aside|footer)\b/gi) || [];
  return new Set(matches.map(item => item.replace(/[<\s]/g, '').toLowerCase())).size;
}

function hasSemanticHTMLTags(html) {
  return countSemanticHTMLTags(html) >= 2;
}

function getSemanticTagProgress(html) {
  return Math.min(1, countSemanticHTMLTags(html) / 2);
}

function checkCriterion(criterion) {
  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const htmlLower = html.toLowerCase();
  const cssLower = css.toLowerCase();
  const jsLower = js.toLowerCase();
  const outputLower = getOutputText();
  const target = (criterion.target || '').trim().toLowerCase();
  const combinedLength = [html, css, js].join('').replace(/\s/g, '').length;
  const previewDoc = getPreviewDocument();
  const hasRuntimeError = Boolean(previewDoc?.body?.dataset?.runtimeError);

  switch (criterion.rule) {
    case 'smart_rubric':
      return getSmartCriterionProgress(criterion) >= 0.65;
    case 'html_contains':
      return target ? htmlLower.includes(target) : false;
    case 'css_contains':
      return target ? cssLower.includes(target) : false;
    case 'js_contains':
      return target ? jsLower.includes(target) : false;
    case 'output_contains':
      return target ? outputLower.includes(target) : false;
    case 'full_html_structure':
      return isCompleteHTMLStructure();
    case 'has_semantic_tags':
      return hasSemanticHTMLTags(html);
    case 'balanced_html_tags':
      return hasBalancedHTMLTags(html);
    case 'output_has_visible_text':
      return outputLower.trim().length >= 3;
    case 'has_heading':
      return /<h[1-6](\s|>|\/)/i.test(html) || Boolean(queryPreview('h1, h2, h3, h4, h5, h6'));
    case 'has_paragraph':
      return /<p(\s|>|\/)/i.test(html) || Boolean(queryPreview('p'));
    case 'has_button':
      return /<button(\s|>|\/)/i.test(html) || Boolean(queryPreview('button'));
    case 'has_link':
      return /<a(\s|>|\/)/i.test(html) || Boolean(queryPreview('a'));
    case 'has_button_or_link':
      return /<(button|a)(\s|>|\/)/i.test(html) || Boolean(queryPreview('button, a'));
    case 'has_image':
      return /<img(\s|>|\/)/i.test(html) || Boolean(queryPreview('img'));
    case 'has_list':
      return /<(ul|ol)(\s|>|\/)/i.test(html) || Boolean(queryPreview('ul, ol'));
    case 'uses_css_property': {
      if (target) return cssLower.includes(target);
      const usefulProperties = /(color|background|background-color|padding|margin|border|border-radius|font-size|font-family|font-weight|line-height|display|box-shadow|text-align|width|max-width|min-height|height|gap|grid-template-columns|justify-content|align-items|position|transition|transform|opacity|object-fit|overflow)\s*:/i;
      return usefulProperties.test(css);
    }
    case 'uses_event_listener':
      return /addEventListener\s*\(/i.test(js) || /onclick\s*=/i.test(html);
    case 'js_changes_page':
      return /(textContent|innerHTML|innerText|classList|style\.|setAttribute|appendChild|createElement)/i.test(js);
    case 'no_runtime_error':
      return !hasRuntimeError;
    case 'minimum_effort':
      return combinedLength >= 120;
    default:
      return false;
  }
}

function getHTMLStructureProgress() {
  return getStrictHTMLStructureProgress();
}

function getBalancedTagProgress(html) {
  if (hasBalancedHTMLTags(html)) return 1;
  const tags = (html.match(/<\/?\s*([a-zA-Z][a-zA-Z0-9-]*|!DOCTYPE)\b[^>]*>/g) || []).length;
  if (tags <= 2) return 0.15;

  const voidTags = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr', '!doctype']);
  const openTags = {};
  const closeTags = {};
  const tagRegex = /<\/?\s*([a-zA-Z][a-zA-Z0-9-]*|!DOCTYPE)\b[^>]*>/g;
  let match;

  while ((match = tagRegex.exec(html)) !== null) {
    const fullTag = match[0];
    const tagName = match[1].toLowerCase();
    if (voidTags.has(tagName) || fullTag.endsWith('/>') || fullTag.startsWith('<!--')) continue;
    if (/^<\//.test(fullTag)) {
      closeTags[tagName] = (closeTags[tagName] || 0) + 1;
    } else {
      openTags[tagName] = (openTags[tagName] || 0) + 1;
    }
  }

  const names = new Set([...Object.keys(openTags), ...Object.keys(closeTags)]);
  if (!names.size) return 0;
  let matched = 0;
  let total = 0;
  names.forEach(name => {
    matched += Math.min(openTags[name] || 0, closeTags[name] || 0);
    total += Math.max(openTags[name] || 0, closeTags[name] || 0);
  });
  return total ? Math.max(0.1, matched / total) : 0;
}


function clamp01(value) {
  if (!Number.isFinite(Number(value))) return 0;
  return Math.max(0, Math.min(1, Number(value)));
}

function averageProgress(values) {
  const clean = values.filter(value => Number.isFinite(Number(value)));
  if (!clean.length) return 0;
  return clamp01(clean.reduce((sum, value) => sum + Number(value), 0) / clean.length);
}

function weightedProgress(items) {
  const clean = items.filter(item => Number.isFinite(Number(item.value)) && Number(item.weight) > 0);
  const totalWeight = clean.reduce((sum, item) => sum + Number(item.weight), 0);
  if (!totalWeight) return 0;
  return clamp01(clean.reduce((sum, item) => sum + Number(item.value) * Number(item.weight), 0) / totalWeight);
}

function getCriterionRubricText(criterion) {
  const normalized = normalizeCriterion(criterion);
  const descriptions = rubricLevels
    .map(level => normalized.levels?.[level.key]?.description || '')
    .join(' ');
  return `${normalized.title || ''} ${descriptions || ''}`.trim();
}

function includesAnyText(text, patterns) {
  return patterns.some(pattern => typeof pattern === 'string' ? text.includes(pattern) : pattern.test(text));
}

function countMatches(text, pattern) {
  return (String(text || '').match(pattern) || []).length;
}


function getScorableStudentCodeText() {
  return [codeStore.html || '', codeStore.css || '', codeStore.js || '']
    .join('\n')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|\n)\s*\/\/.*(?=\n|$)/g, '\n')
    .replace(/\s+/g, '')
    .trim();
}

function isSubmissionEmptyForScoring() {
  return getScorableStudentCodeText().length === 0;
}

function getCodeBasicsProgress() {
  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const combinedLength = [html, css, js].join('').replace(/\s/g, '').length;
  const previewDoc = getPreviewDocument();
  const hasRuntimeError = Boolean(previewDoc?.body?.dataset?.runtimeError);
  const bodyTextLength = getOutputText().trim().length;
  const sourceQuality = getHTMLSourceQualityReport();
  const visibleTextBase = bodyTextLength >= 80 ? 1 : bodyTextLength >= 40 ? 0.85 : bodyTextLength >= 15 ? 0.6 : bodyTextLength >= 3 ? 0.35 : 0;
  const visibleText = sourceQuality.hasBodyOpen && sourceQuality.hasVisibleBodyContent
    ? visibleTextBase
    : Math.min(visibleTextBase, sourceQuality.hasBodyOpen ? 0.55 : 0.42);

  return {
    htmlStructure: sourceQuality.progress,
    balancedTags: getBalancedTagProgress(html),
    semanticTags: getSemanticTagProgress(html),
    visibleText,
    rawVisibleText: visibleTextBase,
    sourceQuality: sourceQuality.progress,
    bodyPlacement: sourceQuality.placementProgress,
    bodyContent: sourceQuality.bodyProgress,
    effort: Math.min(1, combinedLength / 180),
    noRuntimeError: hasRuntimeError ? 0 : 1
  };
}

function getTagAttributeValue(tagSource, attributeName) {
  const escaped = String(attributeName || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = String(tagSource || '').match(new RegExp(`\\b${escaped}\\s*=\\s*(?:["']([^"']*)["']|([^\\s>]+))`, 'i'));
  return match ? String(match[1] ?? match[2] ?? '').trim() : '';
}

function getFirstOpeningTag(html, tagName) {
  const match = String(html || '').match(new RegExp(`<${tagName}\\b[^>]*>`, 'i'));
  return match ? match[0] : '';
}


function parseStudentHTMLForRubric(html = codeStore.html || '') {
  try {
    return new DOMParser().parseFromString(String(html || ''), 'text/html');
  } catch (error) {
    return null;
  }
}

function isMeaningfulRubricText(value = '', minimum = 3) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (text.length < minimum) return false;
  return !/^(image|img|photo|picture|link|click here|text|none|n\/a|test|sample)$/i.test(text);
}


function getAllStudentCodeForRubric(language = 'html') {
  try {
    const files = getLanguageFileMap(language);
    if (files && typeof files === 'object') return Object.values(files).map(value => String(value || '')).join('\n\n');
  } catch (error) {}
  if (language === 'html') return String(codeStore.html || '');
  if (language === 'css') return String(codeStore.css || '');
  if (language === 'js') return String(codeStore.js || '');
  return '';
}

function parseRubricCssRules(cssText = '') {
  const css = String(cssText || '').replace(/\/\*[\s\S]*?\*\//g, ' ');
  const rules = [];
  const blockPattern = /([^{}]+)\{([^{}]*)\}/g;
  let match;
  while ((match = blockPattern.exec(css)) !== null) {
    const selectorText = String(match[1] || '').trim();
    if (!selectorText || selectorText.startsWith('@')) continue;
    const declarations = {};
    String(match[2] || '').split(';').forEach(part => {
      const colon = part.indexOf(':');
      if (colon < 1) return;
      const property = part.slice(0, colon).trim().toLowerCase();
      const value = part.slice(colon + 1).trim();
      if (property) declarations[property] = value;
    });
    selectorText.split(',').map(item => item.trim()).filter(Boolean).forEach(selector => rules.push({ selector, declarations }));
  }
  return rules;
}

function rubricSelectorMatchesDocument(doc, selector = '') {
  if (!doc || !selector) return false;
  try { return Boolean(doc.querySelector(selector)); } catch (error) {
    const simple = String(selector).match(/([#.])([A-Za-z_][\w-]*)/);
    if (!simple) return false;
    return simple[1] === '#' ? Boolean(doc.getElementById(simple[2])) : Boolean(doc.querySelector(`.${simple[2]}`));
  }
}

function enhanceUniversalRubricAudit({ criterion, requirementText, rubricText, html, doc, checks, add }) {
  const allHtml = getAllStudentCodeForRubric('html') || html;
  const allCss = [getAllStudentCodeForRubric('css'), ...Array.from(doc?.querySelectorAll('style') || []).map(node => node.textContent || '')].join('\n');
  const cssRules = parseRubricCssRules(allCss);
  const lower = String(requirementText || '').toLowerCase();
  const tagAliases = {
    navigation: 'nav', navbar: 'nav', header: 'header', footer: 'footer', main: 'main', section: 'section', article: 'article', aside: 'aside',
    table: 'table', form: 'form', button: 'button', textarea: 'textarea', select: 'select', iframe: 'iframe', audio: 'audio', video: 'video', canvas: 'canvas'
  };
  const standardTags = new Set(['html','head','body','title','meta','link','style','script','header','nav','main','section','article','aside','footer','h1','h2','h3','h4','h5','h6','p','div','span','strong','b','em','i','u','small','mark','sub','sup','blockquote','pre','code','br','hr','ul','ol','li','dl','dt','dd','a','img','picture','source','audio','video','track','iframe','table','caption','thead','tbody','tfoot','tr','th','td','colgroup','col','form','label','input','textarea','select','option','button','fieldset','legend','details','summary','figure','figcaption','canvas']);

  // Any literal HTML tags named by the selected rubric are checked, not just a fixed sample set.
  const literalTags = new Set();
  for (const match of String(requirementText || '').matchAll(/<\/?\s*([a-z][\w-]*)\b/gi)) literalTags.add(match[1].toLowerCase());
  Object.entries(tagAliases).forEach(([word, tag]) => { if (new RegExp(`\\b${word}\\b`, 'i').test(lower)) literalTags.add(tag); });
  standardTags.forEach(tag => {
    if (new RegExp(`(?:\\b${tag}\\s+(?:tag|element)s?\\b|\\buse\\s+(?:an?\\s+)?${tag}\\b)`, 'i').test(lower)) literalTags.add(tag);
  });
  literalTags.forEach(tag => {
    if (['img','a','ul','ol','li','br','hr','html','head','body','title'].includes(tag)) return;
    const count = doc ? doc.querySelectorAll(tag).length : (allHtml.match(new RegExp(`<${tag}\\b`, 'gi')) || []).length;
    add(`universal-tag-${tag}`, `<${tag}> element`, count > 0, `${count} <${tag}> element(s) detected.`, `Add the required <${tag}> element.`);
  });

  // Common structural relationships.
  if (/semantic(?: html| elements?| tags?)|semantic structure/.test(lower)) {
    const semantic = ['header','nav','main','section','article','aside','footer'];
    const present = semantic.filter(tag => doc?.querySelector(tag));
    add('universal-semantic', 'Semantic HTML structure', present.length >= 2, present.length ? `Semantic elements detected: ${present.join(', ')}.` : '', 'Use the semantic elements specifically requested by the rubric.');
  }
  if (/table/.test(lower)) {
    if (/header cells?|<th|table headings?/.test(lower)) add('universal-th', 'Table header cells', Boolean(doc?.querySelector('table th')), 'Table header cells were detected.', 'Add <th> cells for the required table headings.');
    if (/rows?/.test(lower)) {
      const requested = lower.match(/(?:at least|minimum of|with)\s+(\d+)\s+(?:table\s+)?rows?/);
      const count = doc?.querySelectorAll('table tr').length || 0;
      if (requested) add('universal-table-rows', `At least ${requested[1]} table rows`, count >= Number(requested[1]), `${count} table row(s) detected.`, `Add enough <tr> rows to reach ${requested[1]}.`);
    }
  }
  if (/form|input field|form field/.test(lower)) {
    if (/label/.test(lower)) add('universal-label', 'Form labels', Boolean(doc?.querySelector('label')), `${doc?.querySelectorAll('label').length || 0} label(s) detected.`, 'Add labels for the required form controls.');
    const typeMatches = [...lower.matchAll(/(?:input(?:\s+type)?|type)\s*[=:]?\s*["']?(text|email|password|number|date|radio|checkbox|submit)/g)].map(m => m[1]);
    [...new Set(typeMatches)].forEach(type => add(`universal-input-${type}`, `Input type ${type}`, Boolean(doc?.querySelector(`input[type="${type}"]`)), `input[type="${type}"] was detected.`, `Add the required input type="${type}".`));
    if (/required fields?|required attribute/.test(lower)) add('universal-required', 'Required form fields', Boolean(doc?.querySelector('input[required],select[required],textarea[required]')), 'A required form control was detected.', 'Add the required attribute to the specified form controls.');
  }

  // Generic attribute checks when the rubric explicitly names an attribute.
  const attrNames = ['id','class','src','href','alt','title','target','width','height','placeholder','required','type','name','value','controls','autoplay','loop','poster','colspan','rowspan','action','method','for','role','tabindex'];
  attrNames.forEach(attr => {
    if (!new RegExp(`(?:\\b${attr}\\s+attribute\\b|\\battribute\\s+${attr}\\b|\\bwith\\s+(?:an?\\s+)?${attr}\\b)`, 'i').test(lower)) return;
    if (['src','href','alt','target','width','height'].includes(attr) && (/image|link|anchor|youtube/.test(lower))) return;
    const node = doc?.querySelector(`[${attr}]`);
    add(`universal-attr-${attr}`, `${attr} attribute`, Boolean(node), node ? `${attr}="${String(node.getAttribute(attr) || '').slice(0,100)}" detected.` : '', `Add the explicitly required ${attr} attribute.`);
  });

  const hasAnyCss = Boolean(allCss.trim() || /\sstyle\s*=/.test(allHtml));
  const cssExplicit = /\bcss\b|stylesheet|style(?:d|ing)?|visual design|layout|responsive|media quer|flexbox|css grid|grid layout|selector|pseudo-class|animation|transition/.test(lower);
  if (!cssExplicit) return;

  add('universal-css-present', 'CSS implementation', hasAnyCss, hasAnyCss ? 'CSS code was detected in the project.' : '', 'Add CSS because this selected criterion explicitly requires styling.', 1.15);

  const cssRequirements = [
    ['display','display'],['color','color'],['background-color','background-color'],['background','background'],['font-family','font-family'],['font-size','font-size'],['font-weight','font-weight'],['text-align','text-align'],['line-height','line-height'],
    ['margin','margin'],['padding','padding'],['gap','gap'],['width','width'],['height','height'],['max-width','max-width'],['min-height','min-height'],['border','border'],['border-radius','border-radius'],['box-shadow','box-shadow'],
    ['position','position'],['top','top'],['right','right'],['bottom','bottom'],['left','left'],['overflow','overflow'],['opacity','opacity'],['transform','transform'],['transition','transition'],['animation','animation'],
    ['justify-content','justify-content'],['align-items','align-items'],['flex-direction','flex-direction'],['flex-wrap','flex-wrap'],['grid-template-columns','grid-template-columns'],['grid-template-rows','grid-template-rows']
  ];
  cssRequirements.forEach(([phrase, property]) => {
    if (!new RegExp(`\\b${phrase.replace('-', '[- ]')}\\b`, 'i').test(lower)) return;
    // width/height may be HTML attributes; only grade as CSS here because CSS was explicitly requested.
    const matches = cssRules.filter(rule => Object.prototype.hasOwnProperty.call(rule.declarations, property));
    add(`universal-css-${property}`, `CSS ${property}`, matches.length > 0, matches.length ? `${property} is used in selector “${matches[0].selector}”.` : '', `Add the required ${property}: value; declaration.`);
  });

  if (/flexbox|display\s*:\s*flex|\bflex layout\b|\buse flex\b/.test(lower)) {
    const flexRules = cssRules.filter(rule => /\bflex\b/i.test(rule.declarations.display || ''));
    add('universal-flex', 'Flexbox layout', flexRules.length > 0, flexRules.length ? `display: flex is used by “${flexRules[0].selector}”.` : '', 'Apply display: flex to the element named by the rubric.');
    if (flexRules.length) add('universal-flex-connected', 'Flexbox selector matches HTML', flexRules.some(rule => rubricSelectorMatchesDocument(doc, rule.selector)), 'A Flexbox selector matches an element in the HTML.', 'Make sure the Flexbox selector matches an actual HTML element.');
  }
  if (/css grid|grid layout|display\s*:\s*grid|\buse grid\b/.test(lower)) {
    const gridRules = cssRules.filter(rule => /\b(?:grid|inline-grid)\b/i.test(rule.declarations.display || ''));
    add('universal-grid', 'CSS Grid layout', gridRules.length > 0, gridRules.length ? `display: grid is used by “${gridRules[0].selector}”.` : '', 'Apply display: grid to the element named by the rubric.');
    if (gridRules.length) add('universal-grid-connected', 'Grid selector matches HTML', gridRules.some(rule => rubricSelectorMatchesDocument(doc, rule.selector)), 'A Grid selector matches an element in the HTML.', 'Make sure the Grid selector matches an actual HTML element.');
  }
  if (/responsive|media quer|mobile view|small screen/.test(lower)) add('universal-media-query', 'Responsive media query', /@media\b/i.test(allCss), '@media rule detected.', 'Add the responsive @media rule required by the rubric.');
  if (/hover|pseudo-class/.test(lower)) add('universal-hover', 'CSS pseudo-class', /:[a-z-]+(?:\([^)]*\))?\s*\{/i.test(allCss), 'A CSS pseudo-class selector was detected.', 'Add the requested pseudo-class such as :hover or :focus.');
  if (/transition/.test(lower)) add('universal-transition', 'CSS transition', /\btransition(?:-[a-z-]+)?\s*:/i.test(allCss), 'A transition declaration was detected.', 'Add the required CSS transition.');
  if (/animation|keyframes/.test(lower)) {
    add('universal-keyframes', 'CSS keyframes', /@keyframes\s+[\w-]+/i.test(allCss), '@keyframes rule detected.', 'Define the required @keyframes animation.');
    add('universal-animation-use', 'Animation applied', /\banimation(?:-name)?\s*:/i.test(allCss), 'An animation declaration was detected.', 'Apply the animation to the intended selector.');
  }

  // Explicit class/id names in the rubric must exist in both HTML and CSS when styling is requested.
  const classNames = [...String(requirementText || '').matchAll(/(?:class(?:name)?\s*[=:]?\s*["']?|\.)([A-Za-z_][\w-]{1,})/gi)].map(m => m[1]);
  const idNames = [...String(requirementText || '').matchAll(/(?:id\s*[=:]?\s*["']?|#)([A-Za-z_][\w-]{1,})/gi)].map(m => m[1]);
  [...new Set(classNames)].forEach(name => {
    const inHtml = Boolean(doc?.querySelector(`.${CSS.escape(name)}`));
    const inCss = cssRules.some(rule => new RegExp(`\\.${name}(?![\\w-])`).test(rule.selector));
    add(`universal-class-html-${name}`, `HTML class .${name}`, inHtml, inHtml ? `class="${name}" is used in HTML.` : '', `Add class="${name}" to the intended HTML element.`);
    add(`universal-class-css-${name}`, `CSS selector .${name}`, inCss, inCss ? `.${name} has a CSS rule.` : '', `Add a .${name} CSS rule.`);
  });
  [...new Set(idNames)].forEach(name => {
    const inHtml = Boolean(doc?.getElementById(name));
    const inCss = cssRules.some(rule => new RegExp(`#${name}(?![\\w-])`).test(rule.selector));
    add(`universal-id-html-${name}`, `HTML id #${name}`, inHtml, inHtml ? `id="${name}" is used in HTML.` : '', `Add id="${name}" to the intended HTML element.`);
    add(`universal-id-css-${name}`, `CSS selector #${name}`, inCss, inCss ? `#${name} has a CSS rule.` : '', `Add a #${name} CSS rule.`);
  });
}

function buildRubricRequirementAudit(criterion) {
  const normalized = normalizeCriterion(criterion);
  const rubricText = getCriterionRubricText(normalized);
  const text = rubricText.toLowerCase().replace(/<[^>]+>/g, ' ');
  const excellentText = String(normalized.levels?.excellent?.description || '').toLowerCase().replace(/<[^>]+>/g, ' ');
  const requirementText = `${normalized.title || ''} ${excellentText || text}`.toLowerCase();
  const html = codeStore.html || '';
  const doc = parseStudentHTMLForRubric(html);
  const bodyText = String(doc?.body?.innerText || getOutputText() || '').replace(/\s+/g, ' ').trim();
  const checks = [];
  const add = (id, label, passed, evidence, fix, weight = 1) => checks.push({ id, label, passed: Boolean(passed), evidence, fix, weight });
  const has = selector => Boolean(doc?.querySelector(selector));
  const count = selector => doc ? doc.querySelectorAll(selector).length : 0;
  const sourceHas = regex => regex.test(html);

  const asks = (...patterns) => patterns.some(pattern => pattern.test(requirementText));
  const asksAnyRubric = (...patterns) => patterns.some(pattern => pattern.test(text));

  if (asks(/doctype/, /complete html structure/, /document structure/, /html structure/)) {
    add('doctype', 'DOCTYPE declaration', /^\s*<!doctype\s+html[^>]*>/i.test(html), 'DOCTYPE is present.', 'Add <!DOCTYPE html> at the beginning.');
    add('html', '<html> element', /<html\b/i.test(html) && /<\/html\s*>/i.test(html), 'Opening and closing <html> tags are present.', 'Add complete <html>...</html> tags.');
    add('head', '<head> element', /<head\b/i.test(html) && /<\/head\s*>/i.test(html), 'Opening and closing <head> tags are present.', 'Add complete <head>...</head> tags.');
    add('title', '<title> element', has('title') && isMeaningfulRubricText(doc?.title || ''), `Page title: “${String(doc?.title || '').trim()}”.`, 'Add a meaningful <title> inside <head>.');
    add('body', '<body> element', /<body\b/i.test(html) && /<\/body\s*>/i.test(html), 'Opening and closing <body> tags are present.', 'Place visible page content inside complete <body>...</body> tags.');
  }

  if (asks(/heading/, /<h1/, /main title/)) add('heading', 'Required heading', has('h1,h2,h3,h4,h5,h6'), 'A heading element is present.', 'Add the heading requested by the rubric.');
  if (asks(/paragraph/, /<p\b/)) add('paragraph', 'Paragraph content', has('p'), `${count('p')} paragraph element(s) detected.`, 'Add the required paragraph content.');
  if (asks(/line break/, /<br\b/, /\bbr tag\b/)) add('br', '<br> line break', sourceHas(/<br\s*\/?\s*>/i), '<br> is present.', 'Add the required <br> line break.');
  if (asks(/horizontal rule/, /<hr\b/, /\bhr tag\b/)) add('hr', '<hr> separator', sourceHas(/<hr\s*\/?\s*>/i), '<hr> is present.', 'Add the required <hr> separator.');

  if (asks(/unordered list/, /bullet(?:ed)? list/, /<ul\b/) || /\bul\b/.test(requirementText)) {
    add('ul', 'Unordered list', has('ul'), `${count('ul')} unordered list(s) detected.`, 'Add the required <ul> unordered list.');
  }
  if (asks(/ordered list/, /numbered list/, /<ol\b/) || /\bol\b/.test(requirementText)) {
    add('ol', 'Ordered list', has('ol'), `${count('ol')} ordered list(s) detected.`, 'Add the required <ol> ordered list.');
  }
  const requestedItemsMatch = requirementText.match(/(?:at least|minimum of|with)\s+(\d+)\s+(?:list\s+)?items?/i);
  if (requestedItemsMatch) {
    const minimum = Number(requestedItemsMatch[1]) || 1;
    add('li-count', `At least ${minimum} list items`, count('li') >= minimum, `${count('li')} list item(s) detected.`, `Add enough <li> items to reach at least ${minimum}.`);
  } else if (asks(/list items?/, /<li\b/)) {
    add('li', 'List items', count('li') > 0, `${count('li')} list item(s) detected.`, 'Add the required <li> list items.');
  }

  if (asks(/image/, /picture/, /photo/, /<img\b/, /\bimg tag\b/)) {
    const images = Array.from(doc?.querySelectorAll('img') || []);
    const validSrc = images.find(img => String(img.getAttribute('src') || '').trim());
    const withWidth = images.find(img => String(img.getAttribute('width') || '').trim());
    const withHeight = images.find(img => String(img.getAttribute('height') || '').trim());
    const withAlt = images.find(img => isMeaningfulRubricText(img.getAttribute('alt') || '', 4));
    add('img', 'Image element', images.length > 0, `${images.length} <img> element(s) detected.`, 'Add the required <img> element.');
    if (asks(/\bsrc\b/, /image source/)) add('img-src', 'Image src', validSrc, validSrc ? `Image src is “${validSrc.getAttribute('src')}”.` : '', 'Add a non-empty src attribute to the image.');
    if (asks(/\bwidth\b/)) add('img-width', 'Image width', withWidth, withWidth ? `Image width is ${withWidth.getAttribute('width')}.` : '', 'Add the required width attribute to the image.');
    if (asks(/\bheight\b/)) add('img-height', 'Image height', withHeight, withHeight ? `Image height is ${withHeight.getAttribute('height')}.` : '', 'Add the required height attribute to the image.');
    if (asks(/\balt\b/, /alternative text/, /meaningful alt/, /descriptive alt/)) add('img-alt', 'Meaningful image alt text', withAlt, withAlt ? `Image alt text is “${withAlt.getAttribute('alt')}”.` : '', 'Add meaningful, descriptive alt text to the image.');
  }

  if (asks(/link/, /anchor/, /hyperlink/, /youtube/, /<a\b/, /\ba tag\b/)) {
    const links = Array.from(doc?.querySelectorAll('a') || []);
    const withHref = links.find(link => String(link.getAttribute('href') || '').trim() && !/^#?$/.test(String(link.getAttribute('href') || '').trim()));
    const blank = links.find(link => String(link.getAttribute('target') || '').toLowerCase() === '_blank');
    const youtube = links.find(link => /(?:youtube\.com|youtu\.be)/i.test(String(link.getAttribute('href') || '')));
    add('link', 'Anchor link', links.length > 0, `${links.length} <a> link(s) detected.`, 'Add the required <a> link.');
    if (asks(/\bhref\b/, /working link/, /youtube link/)) add('href', 'Non-empty href', withHref, withHref ? `Link href is “${withHref.getAttribute('href')}”.` : '', 'Add a valid, non-empty href attribute.');
    if (asks(/target/, /new tab/, /_blank/)) add('target', 'Open in new tab', blank, 'target="_blank" is present.', 'Add target="_blank" to the required link.');
    // A rubric saying “YouTube link” requires a YouTube URL only when it explicitly says URL/link to YouTube, not merely a favorite-video section title.
    if (/(youtube\s+(?:url|link)|link\s+to\s+(?:a\s+)?youtube)/.test(requirementText)) add('youtube-url', 'YouTube URL', youtube, youtube ? `YouTube URL detected: “${youtube.getAttribute('href')}”.` : '', 'Use a valid youtube.com or youtu.be URL.');
  }

  const sentenceRequirement = requirementText.match(/(?:at least|minimum of|write|include|contains?)\s+(\d+)\s+(?:complete\s+)?sentences?/i);
  if (sentenceRequirement) {
    const minimum = Number(sentenceRequirement[1]) || 1;
    const sentenceCount = (bodyText.match(/[.!?](?=\s|$)/g) || []).length;
    add('sentences', `At least ${minimum} sentences`, sentenceCount >= minimum, `${sentenceCount} sentence ending(s) detected in visible content.`, `Write at least ${minimum} complete sentences.`);
  }

  const keywordMap = [
    ['name', /\bname\b/, /\bname\s*:/i],
    ['birthday', /birthday|birth date|date of birth/, /(?:birthday|birth date|date of birth)\s*:/i],
    ['introduction', /introduction|introduce yourself/, /introduction\s*:/i],
    ['hobbies', /hobbies|hobby/, /hobbies?|my hobbies/i],
    ['favorites', /favorite things?|favourites?/, /favo(?:u)?rite/i],
    ['idol', /idol|favorite person|favourite person/, /idol|favorite person|favourite person/i]
  ];
  keywordMap.forEach(([id, rubricPattern, outputPattern]) => {
    if (rubricPattern.test(requirementText)) add(`content-${id}`, `${id.charAt(0).toUpperCase()}${id.slice(1)} content`, outputPattern.test(bodyText), `Visible ${id} content was detected.`, `Add the required ${id} information.`);
  });

  if (asksAnyRubric(/css/, /stylesheet/, /visual design/, /styling/) && getCriterionIntent(normalized).explicitCss) {
    add('css', 'Required CSS styling', Boolean(String(codeStore.css || '').trim() || /style\s*=|<style\b/i.test(html)), 'CSS styling was detected.', 'Add the CSS styling explicitly required by this criterion.', 1.2);
  }
  if (asksAnyRubric(/javascript/, /\bjs\b/, /interactive/, /event listener/) && getCriterionIntent(normalized).explicitJs) {
    add('js', 'Required JavaScript', Boolean(String(codeStore.js || '').trim() || /onclick\s*=|<script\b/i.test(html)), 'JavaScript or an inline event was detected.', 'Add the JavaScript/interactivity explicitly required by this criterion.', 1.2);
  }

  enhanceUniversalRubricAudit({ criterion: normalized, requirementText, rubricText: text, html, doc, checks, add });

  const unique = [];
  const seen = new Set();
  checks.forEach(check => { if (!seen.has(check.id)) { seen.add(check.id); unique.push(check); } });
  const totalWeight = unique.reduce((sum, check) => sum + check.weight, 0);
  const passedWeight = unique.reduce((sum, check) => sum + (check.passed ? check.weight : 0), 0);
  return {
    checks: unique,
    progress: totalWeight ? clamp01(passedWeight / totalWeight) : null,
    passed: unique.filter(item => item.passed),
    missing: unique.filter(item => !item.passed)
  };
}

function getHTMLContentSmartProgress(text) {
  const html = codeStore.html || '';
  const outputText = getOutputText();
  const sourceQuality = getHTMLSourceQualityReport();
  const elementChecks = [];

  const sourceHas = selectorRegex => selectorRegex.test(html) && sourceQuality.hasBodyOpen && !sourceQuality.visibleTagsInHead;
  if (includesAnyText(text, [/heading|title heading|\bh[1-6]\b/])) elementChecks.push(sourceHas(/<h[1-6](\s|>|\/)/i) || Boolean(queryPreview('h1, h2, h3, h4, h5, h6')) && sourceQuality.hasBodyOpen ? 1 : 0);
  if (includesAnyText(text, [/paragraph|\bp\s*tag|\bp\b/])) elementChecks.push(sourceHas(/<p(\s|>|\/)/i) || Boolean(queryPreview('p')) && sourceQuality.hasBodyOpen ? 1 : 0);

  if (includesAnyText(text, [/image|picture|photo|\bimg\b/])) {
    const imgTag = getFirstOpeningTag(html, 'img');
    elementChecks.push(imgTag ? 1 : 0);
    if (/\bsrc\b/.test(text)) elementChecks.push(getTagAttributeValue(imgTag, 'src') ? 1 : 0);
    if (/\bwidth\b/.test(text)) elementChecks.push(getTagAttributeValue(imgTag, 'width') ? 1 : 0);
    if (/\bheight\b/.test(text)) elementChecks.push(getTagAttributeValue(imgTag, 'height') ? 1 : 0);
    if (/\balt\b|alternative text|meaningful alt/.test(text)) {
      const alt = getTagAttributeValue(imgTag, 'alt');
      elementChecks.push(alt && alt.length >= 3 ? 1 : alt ? 0.6 : 0);
    }
  }

  if (includesAnyText(text, [/link|anchor|hyperlink|\ba\s*tag|youtube/])) {
    const linkTag = getFirstOpeningTag(html, 'a');
    elementChecks.push(linkTag ? 1 : 0);
    if (/\bhref\b|working link|youtube link/.test(text)) elementChecks.push(getTagAttributeValue(linkTag, 'href') ? 1 : 0);
    if (/target|new tab|_blank/.test(text)) elementChecks.push(getTagAttributeValue(linkTag, 'target').toLowerCase() === '_blank' ? 1 : 0);
  }

  if (includesAnyText(text, [/button|clickable/])) elementChecks.push(sourceHas(/<button(\s|>|\/)/i) || Boolean(queryPreview('button')) && sourceQuality.hasBodyOpen ? 1 : 0);

  if (includesAnyText(text, [/list|bullet|numbered|\bul\b|\bol\b|\bli\b/])) {
    const needsUl = /both[^.]{0,40}(?:<ul|\bul\b)|(?:<ul|\bul\b)[^.]{0,40}and[^.]{0,20}(?:<ol|\bol\b)/.test(text);
    const needsOl = /both[^.]{0,40}(?:<ol|\bol\b)|(?:<ol|\bol\b)[^.]{0,40}and[^.]{0,20}(?:<ul|\bul\b)/.test(text);
    if (needsUl || needsOl) {
      elementChecks.push(sourceHas(/<ul(\s|>|\/)/i) ? 1 : 0);
      elementChecks.push(sourceHas(/<ol(\s|>|\/)/i) ? 1 : 0);
    } else {
      elementChecks.push(sourceHas(/<(ul|ol)(\s|>|\/)/i) || Boolean(queryPreview('ul, ol')) && sourceQuality.hasBodyOpen ? 1 : 0);
    }
  }

  if (/\b<br\b|line break/.test(text)) elementChecks.push(/<br\s*\/?>/i.test(html) ? 1 : 0);
  if (/\b<hr\b|horizontal rule/.test(text)) elementChecks.push(/<hr\s*\/?>/i.test(html) ? 1 : 0);

  if (!elementChecks.length) {
    elementChecks.push(outputText.trim().length >= 15 ? 1 : outputText.trim().length >= 3 ? 0.5 : 0);
  }

  let progress = averageProgress(elementChecks);
  if (!sourceQuality.hasBodyOpen || sourceQuality.visibleTagsOutsideBody || sourceQuality.visibleTagsInHead) progress = Math.min(progress, 0.62);
  if (!sourceQuality.hasVisibleBodyContent) progress = Math.min(progress, 0.55);
  return progress;
}

function getCSSSmartProgress(text) {
  const css = codeStore.css || '';
  const cssTrimmed = css.trim();
  if (!cssTrimmed) return 0;

  const propertyCount = countMatches(css, /[a-z-]+\s*:/gi);
  const visualCount = countMatches(css, /\b(color|background|font-size|font-family|font-weight|text-align|border|border-radius|box-shadow)\s*:/gi);
  const spacingCount = countMatches(css, /\b(padding|margin|gap|line-height)\s*:/gi);
  const layoutCount = countMatches(css, /\b(display|grid-template-columns|justify-content|align-items|flex|width|max-width|height)\s*:/gi);

  const hasSelector = /[.#]?[a-zA-Z][\w-]*\s*\{[^}]+\}/.test(css);
  const hasRequiredProperty = (() => {
    const propertyMatch = text.match(/\b(background-color|border-radius|font-family|font-size|text-align|box-shadow|grid-template-columns|justify-content|align-items|background|padding|margin|border|display|color|width|height|gap)\b/);
    return propertyMatch ? new RegExp(`\\b${propertyMatch[1]}\\s*:`, 'i').test(css) : 1;
  })();

  return weightedProgress([
    { value: hasSelector ? 1 : 0.4, weight: 1 },
    { value: Math.min(1, propertyCount / 6), weight: 2 },
    { value: Math.min(1, visualCount / 3), weight: 1.5 },
    { value: Math.min(1, spacingCount / 2), weight: 1 },
    { value: Math.min(1, layoutCount / 2), weight: includesAnyText(text, [/layout|organized|presentation|design/]) ? 1.2 : 0.5 },
    { value: hasRequiredProperty ? 1 : 0, weight: 1 }
  ]);
}

function getDesignPresentationSmartProgress(text) {
  const basics = getCodeBasicsProgress();
  return weightedProgress([
    { value: getCSSSmartProgress(text), weight: 3 },
    { value: basics.visibleText, weight: 1.5 },
    { value: getHTMLContentSmartProgress(text), weight: 1 },
    { value: basics.balancedTags, weight: 0.7 }
  ]);
}

function getJavaScriptSmartProgress(text) {
  const js = codeStore.js || '';
  const html = codeStore.html || '';
  if (!js.trim() && !/onclick\s*=/i.test(html)) return 0;

  const hasEvent = /addEventListener\s*\(/i.test(js) || /onclick\s*=/i.test(html);
  const changesPage = /(textContent|innerHTML|innerText|classList|style\.|setAttribute|appendChild|createElement)/i.test(js);
  const hasFunction = /function\s+|=>/.test(js);
  const noError = getCodeBasicsProgress().noRuntimeError;

  if (includesAnyText(text, [/event listener|onclick|interaction|interactive|click event|button action/])) {
    return weightedProgress([
      { value: hasEvent ? 1 : 0, weight: 2 },
      { value: changesPage ? 1 : 0.5, weight: 1 },
      { value: noError, weight: 1 }
    ]);
  }

  return weightedProgress([
    { value: hasFunction ? 1 : 0.5, weight: 1 },
    { value: hasEvent ? 1 : 0, weight: 1 },
    { value: changesPage ? 1 : 0, weight: 1 },
    { value: noError, weight: 1 }
  ]);
}

function getInstructionSmartProgress(text) {
  const basics = getCodeBasicsProgress();
  const wantsCss = includesAnyText(text, [/\bcss\b|stylesheet|\bstyl(e|ing|ed)\b|visual design|visual appeal|presentation|layout|responsive|media quer|flexbox|\bflex\b|grid|color|background|font|border|margin|padding|gap|box-shadow|width|height|align|justify/]);
  const wantsJs = includesAnyText(text, [/javascript|script|event|interactive|button action|onclick/]);
  const wantsSemantic = includesAnyText(text, [/semantic|header|nav|main|section|article|aside|footer/]);

  const items = [
    { value: basics.htmlStructure, weight: 2.5 },
    { value: basics.balancedTags, weight: 1.5 },
    { value: basics.bodyPlacement, weight: 1.4 },
    { value: basics.visibleText, weight: 1.5 },
    { value: basics.effort, weight: 1 },
    { value: basics.noRuntimeError, weight: 1 }
  ];

  if (wantsCss) items.push({ value: getCSSSmartProgress(text), weight: 1.5 });
  if (wantsJs) items.push({ value: getJavaScriptSmartProgress(text), weight: 1.5 });
  if (wantsSemantic) items.push({ value: basics.semanticTags, weight: 1.5 });

  return weightedProgress(items);
}

function getSmartCriterionProgress(criterion) {
  const rubricText = getCriterionRubricText(criterion);
  const text = rubricText.toLowerCase();
  if (!text.trim()) return null;

  const requirementAudit = buildRubricRequirementAudit(criterion);
  if (requirementAudit.progress !== null && requirementAudit.checks.length) {
    return requirementAudit.progress;
  }

  const intent = getCriterionIntent(criterion);
  const basics = getCodeBasicsProgress();
  const wantsFollowing = includesAnyText(text, [/following instructions|requirements?|completed accurately|met expectations|instructions not followed|exceeded expectations/]);
  const wantsSemantic = intent.semantic;
  const wantsCompleteStructure = intent.structure;
  const wantsBalanced = includesAnyText(text, [/closing tag|closed tag|properly closed|balanced? tag|incomplete or inconsistent|missing many tags|disorganized/]);
  const wantsCSS = intent.explicitCss;
  const wantsJS = intent.explicitJs;
  const wantsOutput = intent.content;
  const wantsFormattingElements = intent.htmlElements;

  // Specific requirements first. Do not invent CSS/JS requirements unless the rubric explicitly asks for them.
  if (wantsSemantic && wantsCompleteStructure) {
    return weightedProgress([
      { value: basics.htmlStructure, weight: 2 },
      { value: basics.semanticTags, weight: 2 },
      { value: basics.balancedTags, weight: 1 },
      { value: basics.visibleText, weight: 0.7 }
    ]);
  }

  if (wantsSemantic) {
    return weightedProgress([
      { value: basics.semanticTags, weight: 2 },
      { value: basics.htmlStructure, weight: 1 },
      { value: basics.balancedTags, weight: 1 }
    ]);
  }

  if (wantsCompleteStructure) {
    return weightedProgress([
      { value: basics.htmlStructure, weight: 3 },
      { value: basics.balancedTags, weight: 1 },
      { value: basics.visibleText, weight: 0.35 }
    ]);
  }

  if (wantsBalanced) {
    return weightedProgress([
      { value: basics.balancedTags, weight: 2 },
      { value: basics.htmlStructure, weight: 0.8 },
      { value: basics.visibleText, weight: 0.4 }
    ]);
  }

  if (wantsJS) return getJavaScriptSmartProgress(text);

  if (wantsCSS) {
    return getCSSSmartProgress(text);
  }

  if (wantsFormattingElements) {
    return weightedProgress([
      { value: getHTMLContentSmartProgress(text), weight: 2.4 },
      { value: basics.balancedTags, weight: 1 },
      { value: basics.visibleText, weight: 0.8 },
      { value: wantsCompleteStructure ? basics.htmlStructure : 1, weight: wantsCompleteStructure ? 1.2 : 0.2 }
    ]);
  }

  if (wantsOutput) {
    return weightedProgress([
      { value: basics.visibleText, weight: 2 },
      { value: getHTMLContentSmartProgress(text), weight: 1 },
      { value: basics.balancedTags, weight: 0.5 }
    ]);
  }

  if (wantsFollowing) return getInstructionSmartProgress(text);

  // For broad/unrecognized rubric rows, judge only general completeness and visible output.
  // Do not assume CSS, JavaScript, or specific requirements that the rubric did not mention.
  if (criterion.rule === 'smart_rubric') {
    return weightedProgress([
      { value: basics.visibleText, weight: 2 },
      { value: basics.balancedTags, weight: 1 },
      { value: basics.effort, weight: 1 },
      { value: basics.noRuntimeError, weight: 1 }
    ]);
  }

  return null;
}


function getCriterionProgress(criterion) {
  const smartProgress = getSmartCriterionProgress(criterion);
  if (smartProgress !== null) return clamp01(smartProgress);

  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const htmlLower = html.toLowerCase();
  const cssLower = css.toLowerCase();
  const jsLower = js.toLowerCase();
  const outputLower = getOutputText();
  const target = (criterion.target || '').trim().toLowerCase();
  const combinedLength = [html, css, js].join('').replace(/\s/g, '').length;

  if (checkCriterion(criterion)) return 1;

  switch (criterion.rule) {
    case 'full_html_structure':
      return getHTMLStructureProgress();
    case 'has_semantic_tags':
      return getSemanticTagProgress(html);
    case 'balanced_html_tags':
      return getBalancedTagProgress(html);
    case 'output_has_visible_text': {
      const length = outputLower.trim().length;
      if (length >= 20) return 1;
      if (length >= 10) return 0.75;
      if (length >= 3) return 0.5;
      return 0;
    }
    case 'minimum_effort':
      return Math.min(1, combinedLength / 120);
    case 'uses_css_property': {
      if (!css.trim()) return 0;
      const properties = (css.match(/[a-z-]+\s*:/gi) || []).length;
      return Math.min(0.85, properties / 4);
    }
    case 'uses_event_listener':
      return js.trim() || /<button(\s|>|\/)/i.test(html) ? 0.5 : 0;
    case 'js_changes_page':
      return js.trim() ? 0.5 : 0;
    case 'html_contains':
      return target && htmlLower.includes(target.split(/\s+/)[0] || target) ? 0.5 : 0;
    case 'css_contains':
      return target && cssLower.includes(target.split(/\s+/)[0] || target) ? 0.5 : 0;
    case 'js_contains':
      return target && jsLower.includes(target.split(/\s+/)[0] || target) ? 0.5 : 0;
    case 'output_contains':
      return target && outputLower.includes(target.split(/\s+/)[0] || target) ? 0.5 : 0;
    case 'no_runtime_error':
      return 0;
    default:
      return 0;
  }
}

function progressToLevelKey(progress) {
  if (progress >= 0.9) return 'excellent';
  if (progress >= 0.65) return 'good';
  if (progress >= 0.35) return 'fair';
  return 'needsImprovement';
}

function gradeCriterion(criterion) {
  const normalizedCriterion = normalizeCriterion(criterion);
  const emptySubmission = isSubmissionEmptyForScoring();
  const progress = emptySubmission ? 0 : getCriterionProgress(normalizedCriterion);
  const levelKey = emptySubmission ? 'needsImprovement' : progressToLevelKey(progress);
  const level = getCriterionLevel(normalizedCriterion, levelKey);
  const possible = getCriterionPossiblePoints(normalizedCriterion);
  const localJudgement = emptySubmission
    ? {
        evidence: 'No student code was submitted yet.',
        improvement: 'Start by adding the required HTML/content for this activity, then run Result again.'
      }
    : getLocalCriterionEvidence(normalizedCriterion, progress);

  return {
    ...normalizedCriterion,
    progress,
    levelKey,
    levelLabel: level.label || rubricLevels.find(item => item.key === levelKey)?.label || levelKey,
    levelDescription: level.description || '',
    evidence: localJudgement.evidence,
    improvement: localJudgement.improvement,
    passed: levelKey === 'excellent' || levelKey === 'good',
    earned: Math.max(0, Number(level.points) || 0),
    points: possible
  };
}


function getResultRecordingMeta(result = null) {
  const safeResult = result || {};
  const cachedStudent = getLastStudentProfile?.() || {};
  const liveStudent = appSession.student || appSession.lastStudentProfile || cachedStudent || {};
  const preferLiveStudent = Boolean(appSession.mode === 'student' && (appSession.student || appSession.lastStudentProfile));
  const currentActivity = activity || (safeResult.activityId ? getActivityById(safeResult.activityId) : null);
  const studentName = String(
    (preferLiveStudent ? (liveStudent.name || liveStudent.studentName || liveStudent.fullName) : '')
    || safeResult.studentName
    || safeResult.recordMeta?.studentName
    || liveStudent.name
    || liveStudent.studentName
    || liveStudent.fullName
    || (appSession.mode === 'guest' ? 'Guest / Practice Mode' : 'Not signed in')
  ).trim();
  const studentId = String(
    (preferLiveStudent ? (liveStudent.studentId || liveStudent.studentIdNormalized || liveStudent.id) : '')
    || safeResult.studentId
    || safeResult.recordMeta?.studentId
    || liveStudent.studentId
    || liveStudent.studentIdNormalized
    || liveStudent.id
    || ''
  ).trim();
  const section = String(
    (preferLiveStudent ? (liveStudent.section || liveStudent.gradeSection) : '')
    || safeResult.section
    || safeResult.recordMeta?.section
    || liveStudent.section
    || liveStudent.gradeSection
    || ''
  ).trim();
  const activityTitle = String(
    currentActivity?.title
    || safeResult.activityTitle
    || safeResult.recordMeta?.activityTitle
    || 'No activity selected'
  ).trim();
  const activityId = String(
    currentActivity?.id
    || safeResult.activityId
    || safeResult.recordMeta?.activityId
    || ''
  ).trim();
  const projectName = String(
    appSession.currentProject?.name
    || safeResult.projectName
    || safeResult.recordMeta?.projectName
    || ''
  ).trim();
  const checkedAt = safeResult.checkedAt || safeResult.recordMeta?.checkedAt || new Date().toISOString();

  return {
    studentName: studentName || 'Not signed in',
    studentId,
    section,
    activityTitle: activityTitle || 'No activity selected',
    activityId,
    projectName,
    checkedAt
  };
}


function attachCurrentResultRecordingMeta(result = null) {
  if (!result || typeof result !== 'object') return result;
  const recordMeta = getResultRecordingMeta(result);
  result.activityId = recordMeta.activityId;
  result.activityTitle = recordMeta.activityTitle;
  result.studentId = recordMeta.studentId;
  result.studentName = recordMeta.studentName;
  result.section = recordMeta.section;
  result.projectName = recordMeta.projectName;
  result.checkedAt = result.checkedAt || recordMeta.checkedAt;
  result.recordMeta = { ...(result.recordMeta || {}), ...recordMeta, checkedAt: result.checkedAt };
  return result;
}

function buildResultRecordingHeader(result = null) {
  const meta = getResultRecordingMeta(result);
  const detailItems = [
    meta.studentId ? `<span><strong>ID:</strong> ${escapeHTML(meta.studentId)}</span>` : '',
    meta.section ? `<span><strong>Section:</strong> ${escapeHTML(meta.section)}</span>` : '',
    meta.projectName ? `<span><strong>Project:</strong> ${escapeHTML(meta.projectName)}</span>` : '',
    meta.checkedAt ? `<span><strong>Checked:</strong> ${escapeHTML(formatStudentDate(meta.checkedAt, 'Just now'))}</span>` : ''
  ].filter(Boolean).join('');

  return `
    <div class="result-record-header" aria-label="Student result recording details">
      <div class="result-record-main">
        <span class="result-record-label">Result & Feedback</span>
        <h3>${escapeHTML(meta.studentName)}</h3>
        <p><strong>Activity/Rubric:</strong> ${escapeHTML(meta.activityTitle)}</p>
      </div>
      ${detailItems ? `<div class="result-record-details">${detailItems}</div>` : ''}
    </div>
  `;
}

function gradeActivity() {
  if (!activity) return null;
  saveActiveEditor();
  const results = activity.criteria.map(gradeCriterion);

  const score = results.reduce((sum, item) => sum + item.earned, 0);
  const possible = results.reduce((sum, item) => sum + item.points, 0);
  const percent = possible > 0 ? Math.round((score / possible) * 100) : 0;

  const recordMeta = getResultRecordingMeta();

  return {
    score,
    possible,
    percent,
    passed: percent >= activity.passingScore,
    results,
    feedback: generateFeedback(score, possible, percent, results),
    activityId: recordMeta.activityId,
    activityTitle: recordMeta.activityTitle,
    studentId: recordMeta.studentId,
    studentName: recordMeta.studentName,
    section: recordMeta.section,
    projectName: recordMeta.projectName,
    checkedAt: recordMeta.checkedAt,
    recordMeta
  };
}

function formatPoints(value) {
  const number = Number(value) || 0;
  return Number.isInteger(number) ? String(number) : number.toFixed(1).replace(/\.0$/, '');
}

function generateFeedback(score, possible, percent, results) {
  if (isSubmissionEmptyForScoring()) {
    return `No code was submitted yet. Add your HTML/content first, then run Result again. Score: ${formatPoints(score)}/${formatPoints(possible)}.`;
  }

  const missingItems = results.filter(item => item.levelKey === 'needsImprovement' || item.levelKey === 'fair');
  const achievedItems = results.filter(item => item.levelKey === 'excellent' || item.levelKey === 'good');
  const sourceQuality = getHTMLSourceQualityReport();

  let opening = '';
  if (percent >= 90) {
    opening = 'Excellent work! Your work strongly matches the selected rubric.';
  } else if (percent >= 75) {
    opening = 'Good work. The local rubric judge found some areas to polish based on the selected criteria.';
  } else if (percent >= 60) {
    opening = 'You are getting there. Some rubric requirements still need improvement.';
  } else {
    opening = 'Keep practicing. Focus on the criteria with the lowest scores first.';
  }

  const shouldMentionStructure = results.some(item => getCriterionIntent(item).structure || getCriterionIntent(item).semantic);
  const structureWarning = shouldMentionStructure && sourceQuality.issues.length
    ? `Main issue: ${sourceQuality.issues[0]}`
    : '';
  const strengths = achievedItems.length
    ? `Strengths: ${achievedItems.slice(0, 2).map(item => `${item.title} (${item.levelLabel})`).join(', ')}.`
    : 'No strong rubric area was detected yet.';
  const nextSteps = missingItems.length
    ? `Next: ${missingItems.slice(0, 3).map(item => item.improvement || `${item.title} needs improvement`).join(' ')}`
    : 'Next: review the rubric descriptions and make small improvements before submitting.';

  return [opening, structureWarning, strengths, nextSteps, `Score: ${formatPoints(score)}/${formatPoints(possible)}.`].filter(Boolean).join(' ');
}



function getAIReviewEndpoint() {
  return String(window.MCS_AI_FEEDBACK_ENDPOINT || '').trim();
}

function isAIReviewEnabled() {
  return window.MCS_AI_FEEDBACK_ENABLED !== false;
}

function getAIReviewTimeoutMs() {
  const value = Number(window.MCS_AI_FEEDBACK_TIMEOUT_MS);
  return Number.isFinite(value) && value > 3000 ? value : 25000;
}

function getShortCodeSample(value, maxLength = 6000) {
  const text = String(value || '');
  return text.length > maxLength ? `${text.slice(0, maxLength)}\n/* ...code shortened for rubric review... */` : text;
}

function buildAIReviewPayload(result) {
  const currentResult = result || lastRubricResult || gradeActivity();
  const checkerItems = getErrorCheckerItems().map(item => ({
    type: item.type,
    title: item.title,
    detail: item.detail,
    fix: item.fix || ''
  }));

  return {
    app: 'ICT 8 Connect',
    activity: activity ? {
      id: activity.id,
      title: activity.title,
      description: activity.description,
      passingScore: activity.passingScore,
      criteria: activity.criteria.map(item => ({
        title: item.title,
        points: getCriterionPossiblePoints(item),
        rule: item.rule,
        target: item.target || '',
        levels: item.levels || {}
      }))
    } : null,
    rubricResult: currentResult ? {
      score: currentResult.score,
      possible: currentResult.possible,
      percent: currentResult.percent,
      passed: currentResult.passed,
      feedback: currentResult.feedback,
      criteria: currentResult.results.map(item => ({
        title: item.title,
        levelKey: item.levelKey,
        levelLabel: item.levelLabel,
        earned: item.earned,
        points: item.points,
        rule: item.rule,
        target: item.target || '',
        progress: item.progress
      }))
    } : null,
    checkerItems,
    outputText: getOutputText().slice(0, 4000),
    code: {
      html: getShortCodeSample(codeStore.html),
      css: getShortCodeSample(codeStore.css),
      js: getShortCodeSample(codeStore.js)
    },
    instruction: 'Act as a Grade 8 ICT teacher. Use the teacher rubric as the main basis for scoring. Interpret the rubric level descriptions, inspect the code and output, then provide fair beginner-friendly scoring feedback. Do not mention AI. Do not give a complete replacement answer or full code. Return strengths, improvements, next steps, and an adjusted score only when the rubric result clearly mismatches the submitted work.'
  };
}

function getCheckerProblemsForAI() {
  return getErrorCheckerItems().filter(item => item.type === 'error' || item.type === 'warning');
}

function generateLocalAIReview(result) {
  const safeResult = result || lastRubricResult || gradeActivity();
  const problems = getCheckerProblemsForAI();
  const missingCriteria = safeResult?.results?.filter(item => item.levelKey === 'needsImprovement' || item.levelKey === 'fair') || [];
  const strongCriteria = safeResult?.results?.filter(item => item.levelKey === 'excellent' || item.levelKey === 'good') || [];
  const html = codeStore.html || '';
  const css = codeStore.css || '';
  const js = codeStore.js || '';
  const suggestions = [];

  if (!isCompleteHTMLStructure()) suggestions.push('Complete the full HTML structure first: doctype, html, head, title, and body.');
  if (!/<body[\s\S]*?>[\s\S]*?<\/body>/i.test(html)) suggestions.push('Put visible content inside the body section.');
  if (css.trim() && !/(color|background|padding|margin|font-size|display|border|border-radius)\s*:/i.test(css)) suggestions.push('Use simple CSS properties such as color, background, padding, margin, or font-size to improve design.');
  if (js.trim() && !/(addEventListener|onclick|textContent|innerHTML|classList|style\.)/i.test(js)) suggestions.push('For JavaScript activities, make sure your script changes something visible on the page.');

  problems.slice(0, 3).forEach(item => suggestions.push(`${item.title}: ${item.fix || item.detail}`));
  missingCriteria.slice(0, 3).forEach(item => suggestions.push(`Improve rubric item: ${item.title}. Current level: ${item.levelLabel}.`));

  const strengths = strongCriteria.length
    ? strongCriteria.slice(0, 3).map(item => item.title)
    : ['You started the page and can improve it step by step.'];

  const scoreLine = safeResult
    ? `${formatPoints(safeResult.score)}/${formatPoints(safeResult.possible)} (${safeResult.percent}%)`
    : 'No rubric result yet';

  return {
    mode: 'Rubric Review',
    officialScore: scoreLine,
    suggestedScore: safeResult ? safeResult.score : null,
    summary: safeResult
      ? safeResult.percent >= 90
        ? 'Strong work. The project meets most requirements and is ready for polishing.'
        : safeResult.percent >= 75
          ? 'Good work. The page is working, but a few details can still be improved.'
          : safeResult.percent >= 60
            ? 'Almost there. Focus on the missing rubric items and the error checker hints.'
            : 'Needs more improvement. Start with the basic HTML structure and visible page content.'
      : 'Click Result first so the app can compare your work with the selected rubric.',
    strengths,
    improvements: suggestions.length ? suggestions.slice(0, 6) : ['No major issue was detected. Improve design, spacing, readability, and creativity.'],
    nextSteps: [
      'Run the code again after every fix.',
      'Check the Error Checker before clicking Result.',
      'Make small improvements instead of changing everything at once.'
    ],
    teacherNote: ''
  };
}

function normalizeAIReviewResponse(data, fallbackResult) {
  if (!data) return generateLocalAIReview(fallbackResult);
  if (typeof data === 'string') {
    return {
      mode: 'Rubric Review',
      officialScore: fallbackResult ? `${formatPoints(fallbackResult.score)}/${formatPoints(fallbackResult.possible)} (${fallbackResult.percent}%)` : 'No rubric result yet',
      summary: data,
      strengths: [],
      improvements: [],
      nextSteps: [],
      teacherNote: ''
    };
  }

  return {
    mode: data.mode || data.source || 'Rubric Review',
    officialScore: data.officialScore || (fallbackResult ? `${formatPoints(fallbackResult.score)}/${formatPoints(fallbackResult.possible)} (${fallbackResult.percent}%)` : 'No rubric result yet'),
    suggestedScore: data.suggestedScore ?? data.score ?? null,
    summary: data.summary || data.feedback || data.message || 'Review completed.',
    strengths: Array.isArray(data.strengths) ? data.strengths : [],
    improvements: Array.isArray(data.improvements) ? data.improvements : Array.isArray(data.nextFixes) ? data.nextFixes : [],
    nextSteps: Array.isArray(data.nextSteps) ? data.nextSteps : [],
    teacherNote: data.teacherNote || data.note || ''
  };
}

function renderAIReview(review, options = {}) {
  if (!aiReviewContent) return;
  const safeReview = normalizeAIReviewResponse(review, lastRubricResult);
  const isLoading = options.loading === true;

  aiReviewContent.classList.remove('empty-ai-review');
  aiReviewContent.innerHTML = isLoading ? `
    <div class="ai-loading-box">
      <div class="ai-spinner" aria-hidden="true"></div>
      <div>
        <h3>Reviewing your work...</h3>
        <p>Please wait. The app is checking the rubric, code, output, and error checker hints.</p>
      </div>
    </div>
  ` : `
    <div class="ai-review-card">
      <div class="ai-review-main">
        <div>
          <p class="section-kicker">${escapeHTML(safeReview.mode || 'Rubric Review')}</p>
          <h3>${escapeHTML(safeReview.summary || 'Review completed.')}</h3>
          <p class="muted-text">Rubric score: <strong>${escapeHTML(safeReview.officialScore || 'Not available')}</strong>${safeReview.suggestedScore !== null && safeReview.suggestedScore !== undefined ? ` · Suggested score: <strong>${escapeHTML(formatPoints(safeReview.suggestedScore))}</strong>` : ''}</p>
        </div>
        <span class="ai-badge">Rubric</span>
      </div>

      <div class="ai-review-grid">
        <div class="ai-review-block good">
          <h4>Strengths</h4>
          <ul>${(safeReview.strengths?.length ? safeReview.strengths : ['Your work has been checked against the activity rubric.']).map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
        </div>
        <div class="ai-review-block improve">
          <h4>Improve Next</h4>
          <ul>${(safeReview.improvements?.length ? safeReview.improvements : ['Polish spacing, readability, color, and content clarity.']).map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
        </div>
        <div class="ai-review-block steps">
          <h4>Next Steps</h4>
          <ul>${(safeReview.nextSteps?.length ? safeReview.nextSteps : ['Fix one issue, run again, then check the result.']).map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
        </div>
      </div>

      ${safeReview.teacherNote ? `<div class="ai-note"><strong>Note:</strong> ${escapeHTML(safeReview.teacherNote)}</div>` : ''}
    </div>
  `;
  updatePhoneResultFeedbackPopup('feedback');
}

function resetAIReviewPanel() {
  if (!aiReviewContent) return;
  aiReviewContent.classList.add('empty-ai-review');
  aiReviewContent.innerHTML = `
    <div class="ai-empty-icon">✨</div>
    <h3>No detailed feedback yet</h3>
    <p>Click <strong>Result</strong> first, then use <strong>Review Feedback</strong> for clearer rubric notes.</p>
    <p class="ai-small-note">This feedback follows the teacher rubric and checker results.</p>
  `;
}


const phoneResultFeedbackPopupState = {
  overlay: null,
  body: null,
  title: null,
  closeBtn: null,
  activeType: null
};

function normalizeButtonActionOptions(options = {}) {
  if (!options || typeof options !== 'object') return {};
  if (typeof options.preventDefault === 'function' || options.currentTarget || options.target) return {};
  return options;
}

function isPhoneResultFeedbackView() {
  return document.documentElement?.dataset?.deviceMode === 'phone' ||
    Boolean(window.matchMedia && window.matchMedia('(max-width: 820px)').matches);
}

function shouldUsePhoneResultFeedbackPopup(options = {}) {
  const safeOptions = normalizeButtonActionOptions(options);
  if (!isPhoneResultFeedbackView()) return false;
  if (safeOptions.fromPreview) return false;
  if (safeOptions.suppressPhonePopup) return false;
  if (document.body.classList.contains('preview-fullscreen-active')) return false;
  if (document.body.classList.contains('preview-inside-editor-fullscreen')) return false;
  return true;
}

function ensurePhoneResultFeedbackPopup() {
  if (phoneResultFeedbackPopupState.overlay) return phoneResultFeedbackPopupState.overlay;

  const overlay = document.createElement('div');
  overlay.id = 'phoneResultFeedbackPopup';
  overlay.className = 'phone-result-feedback-popup hidden';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-labelledby', 'phoneResultFeedbackTitle');
  overlay.innerHTML = `
    <div class="phone-result-feedback-card" role="document">
      <div class="phone-result-feedback-head">
        <div>
          <p class="section-kicker">Activity Check</p>
          <h2 id="phoneResultFeedbackTitle">Result</h2>
        </div>
        <button id="phoneResultFeedbackClose" class="icon-btn phone-result-feedback-close" type="button" aria-label="Close popup">×</button>
      </div>
      <div id="phoneResultFeedbackBody" class="phone-result-feedback-body"></div>
    </div>
  `;

  document.body.appendChild(overlay);
  phoneResultFeedbackPopupState.overlay = overlay;
  phoneResultFeedbackPopupState.title = overlay.querySelector('#phoneResultFeedbackTitle');
  phoneResultFeedbackPopupState.body = overlay.querySelector('#phoneResultFeedbackBody');
  phoneResultFeedbackPopupState.closeBtn = overlay.querySelector('#phoneResultFeedbackClose');

  phoneResultFeedbackPopupState.closeBtn?.addEventListener('click', closePhoneResultFeedbackPopup);
  overlay.addEventListener('click', event => {
    if (event.target === overlay) event.stopPropagation();
  });

  if (!document.body.dataset.phoneResultFeedbackEscapeBound) {
    document.body.dataset.phoneResultFeedbackEscapeBound = 'true';
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape' && phoneResultFeedbackPopupState.overlay && !phoneResultFeedbackPopupState.overlay.classList.contains('hidden')) {
        closePhoneResultFeedbackPopup();
      }
    });
  }

  return overlay;
}

function getPhoneResultFeedbackSource(type) {
  return type === 'feedback' ? aiReviewContent : resultContent;
}

function refreshPhoneResultFeedbackPopup(type = phoneResultFeedbackPopupState.activeType) {
  const overlay = phoneResultFeedbackPopupState.overlay;
  const body = phoneResultFeedbackPopupState.body;
  if (!overlay || !body || !type) return;

  const source = getPhoneResultFeedbackSource(type);
  const title = type === 'feedback' ? 'Feedback' : 'Result';
  phoneResultFeedbackPopupState.activeType = type;
  if (phoneResultFeedbackPopupState.title) phoneResultFeedbackPopupState.title.textContent = title;
  overlay.dataset.popupType = type;
  body.className = `phone-result-feedback-body ${type === 'feedback' ? 'phone-feedback-body' : 'phone-result-body'}`;
  body.innerHTML = source?.innerHTML || '<div class="empty-projects-card"><h3>Nothing to show yet</h3><p>Run the check first.</p></div>';
}

function openPhoneResultFeedbackPopup(type) {
  const overlay = ensurePhoneResultFeedbackPopup();
  phoneResultFeedbackPopupState.activeType = type;
  refreshPhoneResultFeedbackPopup(type);
  overlay.classList.remove('hidden');
  document.body.classList.add('phone-result-feedback-open');
  window.setTimeout(() => phoneResultFeedbackPopupState.closeBtn?.focus(), 30);
}

function updatePhoneResultFeedbackPopup(type) {
  const overlay = phoneResultFeedbackPopupState.overlay;
  if (!overlay || overlay.classList.contains('hidden')) return;
  if (phoneResultFeedbackPopupState.activeType !== type) return;
  refreshPhoneResultFeedbackPopup(type);
}

function closePhoneResultFeedbackPopup() {
  const overlay = phoneResultFeedbackPopupState.overlay;
  if (!overlay) return;
  overlay.classList.add('hidden');
  document.body.classList.remove('phone-result-feedback-open');
  phoneResultFeedbackPopupState.activeType = null;
}


function collectStudentOutputSummaryForAi() {
  const summary = {
    visibleText: getOutputText().slice(0, 2500),
    title: '',
    headings: [],
    links: [],
    buttons: [],
    images: [],
    elementCounts: {},
    note: 'Output summary is collected from the live preview when available.'
  };
  try {
    const doc = getPreviewDocument();
    if (!doc) {
      summary.note = 'Preview document was not available. Judge mainly from code and checker results.';
      return summary;
    }
    summary.title = String(doc.title || '').trim().slice(0, 240);
    summary.visibleText = String(doc.body?.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 2500);
    summary.headings = Array.from(doc.querySelectorAll('h1,h2,h3,h4,h5,h6')).map(node => ({ tag: node.tagName.toLowerCase(), text: String(node.innerText || '').trim().slice(0, 180) })).filter(item => item.text).slice(0, 12);
    summary.links = Array.from(doc.querySelectorAll('a[href]')).map(node => ({ text: String(node.innerText || '').trim().slice(0, 160), href: String(node.getAttribute('href') || '').trim().slice(0, 180) })).slice(0, 20);
    summary.buttons = Array.from(doc.querySelectorAll('button,input[type="button"],input[type="submit"]')).map(node => String(node.innerText || node.value || '').trim().slice(0, 160)).filter(Boolean).slice(0, 12);
    summary.images = Array.from(doc.querySelectorAll('img')).map(node => ({ src: String(node.getAttribute('src') || '').trim().slice(0, 160), alt: String(node.getAttribute('alt') || '').trim().slice(0, 160) })).slice(0, 20);
    ['header','nav','main','section','article','aside','footer','ul','ol','li','table','form','input','img','a','button'].forEach(tag => {
      summary.elementCounts[tag] = doc.querySelectorAll(tag).length;
    });
  } catch (error) {
    summary.note = `Could not read preview output: ${error?.message || 'unknown iframe error'}. Judge mainly from code.`;
  }
  return summary;
}

function buildStudentAiRubricScoringPrompt(localResult = null) {
  const rubricCriteria = activity?.criteria?.map(item => ({
    title: item.title,
    max: getCriterionPossiblePoints(item),
    levels: item.levels || {}
  })) || [];
  const context = {
    app: 'ICT 8 Connect',
    mode: 'student_result_scoring',
    activity: activity ? {
      title: activity.title,
      description: activity.description,
      passingScore: activity.passingScore,
      criteria: rubricCriteria
    } : null,
    localFallbackScore: localResult ? {
      score: localResult.score,
      possible: localResult.possible,
      percent: localResult.percent,
      feedback: localResult.feedback
    } : null,
    checkerItems: getErrorCheckerItems().map(item => ({
      type: item.type,
      title: item.title,
      detail: item.detail,
      fix: item.fix || ''
    })).slice(0, 8),
    outputSummary: collectStudentOutputSummaryForAi(),
    code: {
      html: getShortCodeSample(codeStore.html, 2600),
      css: getShortCodeSample(codeStore.css, 2600),
      js: getShortCodeSample(codeStore.js, 1800)
    }
  };
  const style = aiRubricSettings.reviewStyle || 'balanced';
  return `You are a consistent Grade 8 ICT/web coding teacher. Score this student's work using ONLY the teacher rubric, student code, rendered output summary, and checker items.

IMPORTANT:
- The rubric builder has no auto-check rules. You must interpret the criteria and level descriptions.
- Compare the actual code/output to EACH explicit requirement in the selected criterion, especially the Excellent-level description.
- Evaluate the complete project across all HTML and CSS files, not only the active file or familiar sample tags.
- Understand arbitrary valid HTML elements, attributes, nesting, forms, tables, media, semantic structure, and accessibility only when requested by the rubric.
- For CSS, verify actual selectors, declarations, Flexbox, Grid, responsive media queries, pseudo-classes, transitions, animations, and whether selectors match real HTML elements.
- Treat HTML attributes such as img width and height as HTML evidence; never invent a CSS requirement unless the rubric explicitly says CSS/styling/stylesheet.
- Inspect all matching elements, not only the first image or link.
- Give points based on quoted/specific evidence, not generic encouragement.
- Do not reward missing code or output that cannot be verified.
- If a visual judgment is limited by the text summary, mention it briefly.
- Score each criterion from 0 up to its max points only.
- A criterion that satisfies every explicit Excellent-level requirement must receive the Excellent score for that row.
- Do a contradiction audit: evidence, level, score, and improvement must agree.
- Total score must equal the sum of criterion scores.
- Do not give full replacement code.
- Return ONLY valid JSON. No markdown.
- Review style: ${style}.

Required JSON schema:
{
  "summary": "one short teacher summary",
  "totalScore": 0,
  "possibleScore": 0,
  "percent": 0,
  "confidence": "high|medium|low",
  "criteria": [
    {"name":"criterion name", "max":0, "score":0, "level":"Excellent|Good|Fair|Needs Improvement", "evidence":"specific evidence from code/output", "improvement":"specific improvement"}
  ],
  "studentFeedback": "short student-friendly feedback",
  "teacherNotes": ["short consistency note"],
  "warnings": ["limitations or uncertain items"]
}

CONTEXT JSON:
${JSON.stringify(context, null, 2)}`;
}

function normalizeLevelKeyFromAi(level, score, max) {
  const text = String(level || '').toLowerCase();
  if (text.includes('excellent')) return 'excellent';
  if (text.includes('good')) return 'good';
  if (text.includes('fair') || text.includes('satisfactory')) return 'fair';
  if (text.includes('needs') || text.includes('improvement')) return 'needsImprovement';
  return progressToLevelKey(max ? Number(score || 0) / max : 0);
}

function buildResultFromAiRubricReview(raw, localResult = null) {
  const rubricCriteria = Array.isArray(activity?.criteria) ? activity.criteria : [];
  const rawCriteria = Array.isArray(raw?.criteria) ? raw.criteria : [];
  const results = rubricCriteria.map((criterion, index) => {
    const normalized = normalizeCriterion({ ...criterion, rule: 'smart_rubric', target: '' });
    const max = Math.max(0, Number(getCriterionPossiblePoints(normalized) || normalized.points || 0));
    const ai = rawCriteria.find(item => String(item.name || '').trim().toLowerCase() === String(normalized.title || '').trim().toLowerCase()) || rawCriteria[index] || {};
    const earned = Math.round(clamp(Number(ai.score ?? ai.earned ?? 0) || 0, 0, max) * 10) / 10;
    const levelKey = normalizeLevelKeyFromAi(ai.level, earned, max);
    const level = getCriterionLevel(normalized, levelKey);
    const evidence = String(ai.evidence || '').trim();
    const improvement = String(ai.improvement || '').trim();
    const levelDescription = [evidence, improvement ? `Improve: ${improvement}` : ''].filter(Boolean).join(' ')
      || level.description
      || 'Gemini compared this criterion with the submitted code/output.';
    return {
      ...normalized,
      progress: max ? clamp01(earned / max) : 0,
      levelKey,
      levelLabel: ai.level || level.label || rubricLevels.find(item => item.key === levelKey)?.label || levelKey,
      levelDescription,
      passed: levelKey === 'excellent' || levelKey === 'good',
      earned,
      points: max,
      rule: 'smart_rubric',
      target: '',
      evidence,
      improvement
    };
  });
  const possible = results.reduce((sum, item) => sum + item.points, 0);
  const score = Math.round(results.reduce((sum, item) => sum + item.earned, 0) * 10) / 10;
  const percent = possible ? Math.round((score / possible) * 100) : 0;
  const feedback = String(raw?.studentFeedback || raw?.summary || generateFeedback(score, possible, percent, results)).slice(0, 1800);
  const recordMeta = getResultRecordingMeta(localResult);
  return {
    source: 'gemini',
    score,
    possible,
    percent,
    passed: activity ? percent >= activity.passingScore : false,
    results,
    feedback,
    activityId: recordMeta.activityId,
    activityTitle: recordMeta.activityTitle,
    studentId: recordMeta.studentId,
    studentName: recordMeta.studentName,
    section: recordMeta.section,
    projectName: recordMeta.projectName,
    checkedAt: recordMeta.checkedAt,
    recordMeta,
    aiSummary: String(raw?.summary || '').slice(0, 700),
    aiConfidence: String(raw?.confidence || 'medium').toLowerCase(),
    aiWarnings: Array.isArray(raw?.warnings) ? raw.warnings.map(item => String(item).slice(0, 400)).slice(0, 6) : [],
    aiTeacherNotes: Array.isArray(raw?.teacherNotes) ? raw.teacherNotes.map(item => String(item).slice(0, 400)).slice(0, 6) : [],
    localFallbackScore: localResult ? { score: localResult.score, possible: localResult.possible, percent: localResult.percent } : null
  };
}

async function callGeminiStudentRubricScoring(localResult = null, { signal } = {}) {
  const settings = getCurrentAiRubricSettings();
  if (!shouldUseGeminiForResultFeedback(settings)) throw new Error('Smart Result Feedback is not enabled or API key is missing.');
  const raw = await callGeminiJson(settings, buildStudentAiRubricScoringPrompt(localResult), {
    signal,
    maxOutputTokens: 1536,
    temperature: 0
  });
  return buildResultFromAiRubricReview(raw, localResult);
}


function quickHashText(value = '') {
  const text = String(value || '');
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function buildSmartResultCacheKey() {
  const rubricKey = activity ? {
    id: activity.id,
    title: activity.title,
    criteria: (activity.criteria || []).map(item => ({
      title: item.title,
      points: getCriterionPossiblePoints(item),
      levels: item.levels || {}
    }))
  } : null;
  const settingsKey = {
    model: getGeminiModelName(aiRubricSettings.model),
    style: aiRubricSettings.reviewStyle || 'balanced'
  };
  return quickHashText(JSON.stringify({
    rubricKey,
    settingsKey,
    html: codeStore.html || '',
    css: codeStore.css || '',
    js: codeStore.js || ''
  }));
}

function getSmartReviewCooldownSeconds() {
  const remaining = Math.ceil((smartResultCooldownUntil - Date.now()) / 1000);
  return Math.max(0, remaining);
}

function extractRetryDelaySeconds(error) {
  const detailText = [error?.message, error?.geminiDetail?.message, error?.geminiDetail?.raw].filter(Boolean).join(' ');
  const retryMatch = String(detailText || '').match(/retry\s+in\s+([0-9]+(?:\.[0-9]+)?)s/i);
  if (retryMatch) return Math.ceil(Number(retryMatch[1]) || 30);
  const quotaMatch = String(detailText || '').match(/quota|rate\s*limit|429/i);
  return quotaMatch ? 60 : 0;
}

function applySmartReviewCooldown(error) {
  const status = Number(error?.status || error?.geminiDetail?.status || 0);
  const delaySeconds = status === 429 ? Math.max(30, extractRetryDelaySeconds(error) || 60) : 0;
  if (!delaySeconds) return 0;
  smartResultCooldownUntil = Date.now() + (delaySeconds * 1000) + 2000;
  smartResultCooldownReason = 'review-limit';
  return delaySeconds;
}

function makeFastLocalResult(localResult, status = 'pending', detail = '') {
  const isPending = status === 'pending';
  return {
    ...localResult,
    source: isPending ? 'local-pending' : 'local-fallback',
    smartReviewStatus: status,
    smartReviewDetail: detail || '',
    // Keep the student feedback clean. Technical service errors belong in the small system note, not in the feedback paragraph.
    feedback: localResult.feedback
  };
}

async function runSmartResultInBackground(localResult, requestId, cacheKey) {
  try {
    if (smartResultMemoryCache.has(cacheKey)) {
      const cached = smartResultMemoryCache.get(cacheKey);
      if (requestId !== smartResultRequestId) return;
      lastRubricResult = cached;
      renderResult(cached);
      saveCurrentStudentProject({ result: cached, immediate: true, reason: 'smart-result-cache' });
      saveSubmissionToCloud(cached);
      setStatus(`Smart score ${formatPoints(cached.score)}/${formatPoints(cached.possible)}`);
      return;
    }

    if (aiReviewController) aiReviewController.abort();
    aiReviewController = new AbortController();
    const timeout = window.setTimeout(() => aiReviewController.abort(), 35000);
    const smartResult = await callGeminiStudentRubricScoring(localResult, { signal: aiReviewController.signal });
    window.clearTimeout(timeout);
    if (requestId !== smartResultRequestId) return;
    smartResultMemoryCache.set(cacheKey, smartResult);
    if (smartResultMemoryCache.size > 12) {
      const firstKey = smartResultMemoryCache.keys().next().value;
      smartResultMemoryCache.delete(firstKey);
    }
    lastRubricResult = smartResult;
    renderResult(smartResult);
    saveCurrentStudentProject({ result: smartResult, immediate: true, reason: 'smart-result' });
    saveSubmissionToCloud(smartResult);
    setStatus(`Smart score ${formatPoints(smartResult.score)}/${formatPoints(smartResult.possible)}`);
  } catch (error) {
    console.warn('Smart result scoring failed; keeping fast local result.', error);
    if (requestId !== smartResultRequestId) return;
    const cooldownSeconds = applySmartReviewCooldown(error);
    const fallbackStatus = cooldownSeconds ? 'cooldown' : 'fallback';
    const fallbackResult = makeFastLocalResult(localResult, fallbackStatus, cooldownSeconds ? String(cooldownSeconds) : '');
    lastRubricResult = fallbackResult;
    renderResult(fallbackResult);
    saveCurrentStudentProject({ result: fallbackResult, immediate: true, reason: cooldownSeconds ? 'result-limit-fallback' : 'result-fallback' });
    saveSubmissionToCloud(fallbackResult);
    setStatus(cooldownSeconds ? `Quick score kept. Smart review paused for about ${cooldownSeconds}s.` : `Score ${formatPoints(fallbackResult.score)}/${formatPoints(fallbackResult.possible)}`);
  }
}

function renderResultLoading(message = 'Smart Review is comparing your code and output with the rubric...') {
  if (!resultContent) return;
  resultContent.classList.remove('empty-state');
  resultContent.innerHTML = `
    <div class="ai-loading-box">
      <div class="ai-spinner" aria-hidden="true"></div>
      <div>
        <h3>${escapeHTML(message)}</h3>
        <p>Please wait. The score will be based on the rubric criteria, your code, and your visible output.</p>
      </div>
    </div>
  `;
}

function buildGeminiStudentRubricFeedbackPrompt(result) {
  const payload = buildAIReviewPayload(result);
  const style = aiRubricSettings.reviewStyle || 'balanced';
  return `You are a careful Grade 8 ICT teacher reviewing a student's HTML/CSS/JavaScript project.

Use the teacher rubric as the main scoring basis. Compare the rubric, code, checker warnings, and visible output text. Be fair and consistent. Do not invent output that is not shown. If a visual judgment is limited because you only have a text summary, mention that limitation briefly. Do not provide a complete replacement code solution.

Return ONLY valid JSON. No markdown.

Required JSON schema:
{
  "mode": "Smart Rubric Feedback",
  "officialScore": "rubric score text",
  "suggestedScore": 0,
  "summary": "one short teacher-like summary",
  "strengths": ["specific strength"],
  "improvements": ["specific improvement"],
  "nextSteps": ["student-friendly next step"],
  "teacherNote": "short note explaining score consistency or limitations"
}

Scoring rules:
- Use the existing rubric score as a baseline.
- Change suggestedScore only if code/output evidence clearly shows the local checker over-scored or under-scored the work.
- Never exceed the possible score.
- Focus on rubric evidence, not generic encouragement.
- Review style: ${style}.

CONTEXT JSON:
${JSON.stringify(payload, null, 2)}`;
}

function normalizeGeminiStudentReview(raw, fallbackResult) {
  const fallback = normalizeAIReviewResponse(raw, fallbackResult);
  const maxScore = Number(fallbackResult?.possible || 0) || null;
  if (maxScore !== null && fallback.suggestedScore !== null && fallback.suggestedScore !== undefined) {
    fallback.suggestedScore = Math.round(clamp(Number(fallback.suggestedScore) || 0, 0, maxScore) * 10) / 10;
  }
  fallback.mode = fallback.mode || 'Smart Rubric Feedback';
  fallback.teacherNote = fallback.teacherNote || 'Smart feedback is a suggested review only. Teacher rubric settings remain the official basis.';
  return fallback;
}

async function callGeminiStudentRubricFeedback(result, { signal } = {}) {
  const settings = getCurrentAiRubricSettings();
  if (!shouldUseGeminiForResultFeedback(settings)) throw new Error('Smart Result Feedback is not enabled or API key is missing.');
  const prompt = buildGeminiStudentRubricFeedbackPrompt(result);
  const raw = await callGeminiJson(settings, prompt, { signal, maxOutputTokens: 3072, temperature: 0 });
  return normalizeGeminiStudentReview(raw, result);
}

async function requestAIReview(options = {}) {
  // Unified feedback flow: the Result button is now the only student-facing scorer.
  // Any old Feedback buttons simply run Result & Feedback again.
  return showResult({ ...normalizeButtonActionOptions(options), scroll: true });
}

function renderResult(result) {
  result = attachCurrentResultRecordingMeta(result);
  const pillClass = result.percent >= activity.passingScore
    ? ''
    : result.percent >= 60
      ? 'almost'
      : 'needs-work';
  const pillText = result.percent >= activity.passingScore ? 'Passed' : result.percent >= 60 ? 'Almost' : 'Needs Work';
  const isSmart = result.source === 'gemini';
  const isPendingSmart = result.source === 'local-pending';
  const isFallbackSmart = result.source === 'local-fallback';
  const strengths = isSmart
    ? result.results.filter(item => item.passed).slice(0, 4).map(item => `${item.title}: ${item.evidence || item.levelDescription || 'Meets the rubric level.'}`)
    : result.results.filter(item => item.passed).slice(0, 3).map(item => `${item.title}: ${item.levelDescription || 'Meets the rubric level.'}`);
  const improvements = result.results
    .filter(item => !item.passed || item.improvement)
    .slice(0, 4)
    .map(item => `${item.title}: ${item.improvement || item.levelDescription || 'Improve this criterion.'}`);
  const confidenceLine = isSmart
    ? `<p class="muted-text smart-result-note">Smart review compared the rubric, code, checker hints, and visible output summary. Confidence: ${escapeHTML(result.aiConfidence || 'medium')}.</p>`
    : isPendingSmart
      ? `<p class="muted-text smart-result-note smart-result-pending">Quick result is shown now. Smart review is checking in the background and will update this score automatically.</p>`
      : isFallbackSmart
        ? result.smartReviewStatus === 'cooldown'
          ? `<p class="muted-text smart-result-note">Local rubric judge was used while Smart Review is temporarily paused to avoid the request limit. Try again in about ${escapeHTML(String(getSmartReviewCooldownSeconds() || result.smartReviewDetail || 30))}s.</p>`
          : `<p class="muted-text smart-result-note">Local rubric judge was used. It checked structure, content placement, output, and rubric descriptions without showing technical errors.</p>`
        : `<p class="muted-text smart-result-note">Local rubric judge was used. It checked the code and output against the selected rubric.</p>`;
  const warnings = isSmart && Array.isArray(result.aiWarnings) && result.aiWarnings.length
    ? `<div class="result-warning-note"><strong>Review note:</strong> ${escapeHTML(result.aiWarnings.join(' '))}</div>`
    : '';

  const recordHeader = buildResultRecordingHeader(result);

  resultContent.classList.remove('empty-state');
  resultContent.innerHTML = `
    <div class="score-card smart-result-card ${isSmart ? 'gemini-scored' : 'local-scored'}">
      ${recordHeader}
      <div class="score-main">
        <div>
          <p class="section-kicker">${isSmart ? 'Smart Rubric Score' : isPendingSmart ? 'Quick Rubric Preview' : 'Rubric Score'}</p>
          <div class="score-number">${formatPoints(result.score)}<small> / ${formatPoints(result.possible)}</small></div>
          <p class="muted-text">${result.percent}% · Passing score: ${activity.passingScore}%</p>
          ${confidenceLine}
        </div>
        <span class="score-pill ${pillClass}">${pillText}</span>
      </div>

      <div class="feedback-box smart-feedback-box">
        <strong>Feedback:</strong> ${escapeHTML(result.feedback)}
      </div>
      ${warnings}

      <div class="result-insight-grid" aria-label="Result feedback highlights">
        <div class="result-insight-card good">
          <h4>Strengths</h4>
          <ul>${(strengths.length ? strengths : ['Your work has been checked against the selected rubric.']).map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
        </div>
        <div class="result-insight-card improve">
          <h4>Improve Next</h4>
          <ul>${(improvements.length ? improvements : ['No major rubric issue was detected. Continue polishing readability and design.']).map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul>
        </div>
      </div>

      <ul class="rubric-list" aria-label="Rubric breakdown">
        ${result.results.map(item => `
          <li class="rubric-item scale-result-item ${escapeAttribute(item.levelKey)}">
            <span class="rubric-check ${item.passed ? '' : 'fail'}">${item.passed ? '✓' : '!'}</span>
            <div>
              <p class="rubric-title">${escapeHTML(item.title)}</p>
              <div class="rubric-rule"><strong>${escapeHTML(item.levelLabel)}</strong> · ${escapeHTML(item.levelDescription || 'No level description set.')}</div>
              ${item.evidence ? `<div class="rubric-evidence"><strong>Evidence:</strong> ${escapeHTML(item.evidence)}</div>` : ''}
              ${item.improvement ? `<div class="rubric-improvement"><strong>Improve:</strong> ${escapeHTML(item.improvement)}</div>` : ''}
            </div>
            <span class="rubric-points">${formatPoints(item.earned)}/${formatPoints(item.points)}</span>
          </li>
        `).join('')}
      </ul>
    </div>
  `;
  updatePhoneResultFeedbackPopup('result');
}
function renderNoActivityResult() {
  lastRubricResult = null;
  resetAIReviewPanel();
  resultContent.classList.add('empty-state');
  resultContent.innerHTML = `
    <div class="empty-icon">!</div>
    <h3>No activity selected yet</h3>
    <p>Please choose an activity first. After you select one, Result and Feedback will check your current code automatically.</p>
  `;
  if (!isPhoneResultFeedbackView()) scrollElementIntoSafeView(resultPanel);
}

async function showResult(options = {}) {
  const safeOptions = normalizeButtonActionOptions(options);
  if (!activity) {
    showActivityRequiredWarning();
    setStatus('Choose activity first');
    return;
  }

  runCode(false, { scroll: false });
  const wantsGemini = shouldUseGeminiForResultFeedback(getCurrentAiRubricSettings());
  const cooldownSecondsBeforeRun = getSmartReviewCooldownSeconds();
  const useGemini = wantsGemini && cooldownSecondsBeforeRun <= 0;
  setStatus(useGemini ? 'Preparing quick result...' : wantsGemini ? `Quick result only. Smart review can retry in about ${cooldownSecondsBeforeRun}s.` : 'Checking rubric...');
  if (resultContent) {
    resultContent.classList.remove('empty-state');
    resultContent.innerHTML = `
      <div class="score-card smart-result-card local-scored result-loading-card">
        ${buildResultRecordingHeader()}
        <div class="score-main">
          <div>
            <p class="section-kicker">Result & Feedback</p>
            <div class="score-number"><small>Checking...</small></div>
            <p class="muted-text">Please wait while the selected rubric checks the current code.</p>
          </div>
          <span class="score-pill almost">Checking</span>
        </div>
      </div>
    `;
  }

  try {
    await new Promise(resolve => window.setTimeout(resolve, 120));
    const localResult = gradeActivity();
    if (!localResult) {
      renderNoActivityResult();
      setStatus('No rubric result generated');
      return;
    }

    const requestId = ++smartResultRequestId;

    if (wantsGemini && !useGemini) {
      const cooldownResult = makeFastLocalResult(localResult, 'cooldown', String(cooldownSecondsBeforeRun || getSmartReviewCooldownSeconds() || 30));
      lastRubricResult = cooldownResult;
      renderResult(cooldownResult);
      resetAIReviewPanel();
      saveCurrentStudentProject({ result: cooldownResult, immediate: true, reason: 'result-cooldown' });
      saveSubmissionToCloud(cooldownResult);
      setStatus(`Quick score shown. Smart review can retry in about ${getSmartReviewCooldownSeconds()}s.`);
      if (shouldUsePhoneResultFeedbackPopup(safeOptions)) {
        openPhoneResultFeedbackPopup('result');
      } else {
        scrollElementIntoSafeView(resultPanel);
      }
      return;
    }

    if (useGemini) {
      const cacheKey = buildSmartResultCacheKey();
      const cachedResult = smartResultMemoryCache.get(cacheKey);
      const fastResult = cachedResult || makeFastLocalResult(localResult, 'pending');
      lastRubricResult = fastResult;
      renderResult(fastResult);
      resetAIReviewPanel();
      setStatus(cachedResult ? `Smart score ${formatPoints(cachedResult.score)}/${formatPoints(cachedResult.possible)}` : 'Quick result shown. Smart Review is still checking...');
      if (shouldUsePhoneResultFeedbackPopup(safeOptions)) {
        openPhoneResultFeedbackPopup('result');
      } else {
        scrollElementIntoSafeView(resultPanel);
      }
      if (!cachedResult) {
        window.setTimeout(() => runSmartResultInBackground(localResult, requestId, cacheKey), 30);
      } else {
        saveCurrentStudentProject({ result: cachedResult, immediate: true, reason: 'smart-result-cache' });
        saveSubmissionToCloud(cachedResult);
      }
      return;
    }

    lastRubricResult = localResult;
    renderResult(localResult);
    resetAIReviewPanel();
    saveCurrentStudentProject({ result: localResult, immediate: true, reason: 'result' });
    saveSubmissionToCloud(localResult);
    setStatus(`Score ${formatPoints(localResult.score)}/${formatPoints(localResult.possible)}`);
    if (shouldUsePhoneResultFeedbackPopup(safeOptions)) {
      openPhoneResultFeedbackPopup('result');
    } else {
      scrollElementIntoSafeView(resultPanel);
    }
  } catch (error) {
    console.error('Result check failed', error);
    if (resultContent) {
      resultContent.classList.remove('empty-state');
      resultContent.innerHTML = `
        <div class="score-card smart-result-card result-error-card">
          ${buildResultRecordingHeader(lastRubricResult)}
          <div class="score-main">
            <div>
              <p class="section-kicker">Result Check</p>
              <div class="score-number"><small>Try Again</small></div>
              <p class="muted-text">The click worked, but the checker hit a temporary problem. Your code is still saved locally.</p>
            </div>
            <span class="score-pill needs-work">Retry</span>
          </div>
          <div class="feedback-box smart-feedback-box"><strong>What happened:</strong> ${escapeHTML(error?.message || 'Could not check the result. Please click Result again or refresh only if needed.')}</div>
        </div>
      `;
      if (!isPhoneResultFeedbackView()) scrollElementIntoSafeView(resultPanel);
    }
    setStatus('Result failed · try again');
  }
}

function getRuleLabel(rule) {
  return ruleOptions.find(option => option.value === rule)?.label || rule;
}

function resetResultPanel() {
  lastRubricResult = null;
  resetAIReviewPanel();
  resultContent.classList.add('empty-state');
  resultContent.innerHTML = `
    <div class="empty-icon">✓</div>
    <h3>No result yet</h3>
    <p>Choose an activity first, then click <strong>Result</strong> when you are ready to check your score.</p>
  `;
}

function showResultReadyAfterActivitySelection(message = 'Activity and rubric are ready. Click the Result button when you are ready to check your score.') {
  if (!resultContent) return;
  resultContent.classList.add('empty-state');
  resultContent.innerHTML = `
    <div class="empty-icon">✓</div>
    <h3>Ready to check</h3>
    <p>${escapeHTML(message)}</p>
    <p class="muted-text small-note">Use the button inside the Activity/Rubric popup or the Result button in the header. No score is computed until you click.</p>
  `;
}

function setActivityModalResultPromptVisible(isVisible) {
  activityResultPrompt?.classList.toggle('hidden', !isVisible);
  activityRubricResultPrompt?.classList.toggle('hidden', !isVisible);
  if (activityModalResultBtn) {
    activityModalResultBtn.disabled = !isVisible;
    activityModalResultBtn.setAttribute('aria-disabled', String(!isVisible));
  }
  if (activityRubricResultBtn) {
    activityRubricResultBtn.disabled = !isVisible;
    activityRubricResultBtn.setAttribute('aria-disabled', String(!isVisible));
  }
}

function handleActivityModalResultClick() {
  if (!activity) {
    showActivityRequiredWarning();
    return;
  }
  closeActivityRubricModal();
  closeActivityCard();
  window.setTimeout(() => showResult({ source: 'activity-modal-button' }), 80);
}


function updateActivityButtonState() {
  if (!stepActivityBtn) return;
  const hasActivity = Boolean(activity);
  stepActivityBtn.classList.toggle('activity-selected', hasActivity);
  stepActivityBtn.classList.toggle('activity-empty', !hasActivity);
  if (!stepActivityBtn.classList.contains('needs-attention')) {
    stepActivityBtn.classList.toggle('needs-attention', !hasActivity && activityWarning && !activityWarning.classList.contains('hidden'));
  }
  stepActivityBtn.innerHTML = hasActivity ? '✅ Activity Set' : '📌 Choose Activity';
  stepActivityBtn.title = hasActivity ? `Selected activity: ${activity.title}` : 'Choose an activity before checking Result';
  stepActivityBtn.setAttribute('aria-label', hasActivity ? `Activity selected: ${activity.title}` : 'Choose activity');
}

function getActivityRubricHTML(sourceActivity) {
  if (!sourceActivity || !Array.isArray(sourceActivity.criteria) || !sourceActivity.criteria.length) {
    return '<div class="empty-projects-card"><h3>No rubric yet</h3><p>Your teacher has not added rubric criteria for this activity.</p></div>';
  }
  const rows = sourceActivity.criteria.map((criterion, index) => {
    const normalized = normalizeCriterion(criterion);
    const levelCells = rubricLevels.map(level => {
      const levelData = getCriterionLevel(normalized, level.key);
      const description = levelData.description || defaultLevelDescriptions[level.key] || 'No description set.';
      const points = Number(levelData.points);
      return `
        <td>
          <strong>${Number.isFinite(points) ? `${formatPoints(points)} pts` : '—'}</strong>
          <span>${escapeHTML(description)}</span>
        </td>
      `;
    }).join('');
    return `
      <tr>
        <th scope="row"><span>${index + 1}</span>${escapeHTML(normalized.title)}</th>
        ${levelCells}
      </tr>
    `;
  }).join('');
  return `
    <table class="student-rubric-table">
      <thead>
        <tr>
          <th>Criteria</th>
          ${rubricLevels.map(level => `<th>${escapeHTML(level.label)}</th>`).join('')}
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

function openActivityRubricModal() {
  if (!activity) {
    showActivityRequiredWarning();
    return;
  }
  if (!activityRubricOverlay || !activityRubricTable) return;
  const possible = activity.criteria.reduce((sum, criterion) => sum + getCriterionPossiblePoints(criterion), 0);
  if (activityRubricTitle) activityRubricTitle.textContent = activity.title || 'Activity Rubric';
  if (activityRubricMeta) activityRubricMeta.textContent = `Rubric Total: ${formatPoints(possible)} pts • ${activity.criteria.length} rubric item${activity.criteria.length === 1 ? '' : 's'} • This is the full teacher rubric, not a scored result yet.`;
  activityRubricTable.innerHTML = getActivityRubricHTML(activity);
  activityRubricOverlay.classList.remove('hidden');
  document.body.classList.add('activity-rubric-open');
  window.setTimeout(() => closeActivityRubricBtn?.focus(), 30);
}

function closeActivityRubricModal() {
  activityRubricOverlay?.classList.add('hidden');
  document.body.classList.remove('activity-rubric-open');
}

function renderActivitySelector() {
  if (!activitySelect) return;
  const placeholder = `<option value="" ${activity ? '' : 'selected'}>Select an activity first...</option>`;
  const options = activities.map((item) => `
    <option value="${escapeAttribute(item.id)}" ${activity && item.id === activity.id ? 'selected' : ''}>${escapeHTML(item.title)}</option>
  `).join('');
  activitySelect.innerHTML = placeholder + options;
}

function renderAdminActivitySelect() {
  if (!adminActivitySelect) return;

  if (!activities.length) {
    adminActivitySelect.innerHTML = '<option value="">No saved activities yet</option>';
    adminActivitySelect.value = '';
    return;
  }

  adminActivitySelect.innerHTML = activities.map((item) => `
    <option value="${escapeAttribute(item.id)}" ${item.id === adminEditingActivityId ? 'selected' : ''}>${escapeHTML(item.title)}</option>
  `).join('');
}

function renderActivitySummary() {
  if (!activity) {
    activityTitle.textContent = 'No activity selected yet';
    activityDescription.textContent = 'Choose an activity first. Run Code still works, but score and feedback need a selected activity/rubric.';
    totalPoints.textContent = '0';
    criteriaCount.textContent = '0';
    activityCriteriaStat?.classList.add('disabled');
    setActivityModalResultPromptVisible(false);
    renderActivitySelector();
    updateActivityButtonState();
    renderStudentTeacherComment();
    return;
  }

  const possible = activity.criteria.reduce((sum, criterion) => sum + getCriterionPossiblePoints(criterion), 0);
  activityTitle.textContent = activity.title;
  activityDescription.textContent = activity.description;
  totalPoints.textContent = formatPoints(possible);
  criteriaCount.textContent = activity.criteria.length;
  activityCriteriaStat?.classList.remove('disabled');
  setActivityModalResultPromptVisible(true);
  renderActivitySelector();
  updateActivityButtonState();
  clearActivityRequiredWarning();
  renderStudentTeacherComment();
}

function selectActivity(activityId, options = {}) {
  const shouldPreserveEditorCode = options.preserveEditorCode !== false;
  const editorSnapshot = shouldPreserveEditorCode ? cloneCurrentEditorCodeStore({ skipSave: options.skipSave }) : null;
  const hasEditorContent = shouldPreserveEditorCode && codeStoreHasVisibleContent(editorSnapshot);

  if (!activityId) {
    window.clearTimeout(autoResultAfterActivityTimer);
    if (!shouldPreserveEditorCode && !options.skipSave) saveActiveEditor();
    activity = null;
    selectedActivityId = '';
    saveJSON(STORAGE_KEYS.selectedActivityId, '');
    if (hasEditorContent) {
      keepEditorCodeForActivityKey('scratch', editorSnapshot);
    } else {
      codeStore = codeByActivity.scratch ? getCodeStoreForActivity('scratch') : normalizeCodeStore(starterCode);
    }
    renderActivitySummary();
    setActivityModalResultPromptVisible(false);
    loadActiveEditor();
    resetResultPanel();
    runCode(false, { scroll: false });
    return;
  }

  const nextActivity = getActivityById(activityId);
  if (!nextActivity) return;

  if (!shouldPreserveEditorCode && !options.skipSave) {
    saveActiveEditor();
  }

  activity = nextActivity;
  selectedActivityId = nextActivity.id;
  adminEditingActivityId = nextActivity.id;
  saveJSON(STORAGE_KEYS.selectedActivityId, selectedActivityId);

  if (hasEditorContent) {
    keepEditorCodeForActivityKey(nextActivity.id, editorSnapshot);
  } else {
    codeStore = getCodeStoreForActivity(nextActivity.id);
  }

  if (!options.keepLanguage) {
    activeLanguage = 'html';
    tabButtons.forEach(tab => tab.classList.toggle('active', tab.dataset.language === activeLanguage));
  }

  renderActivitySummary();
  setActivityModalResultPromptVisible(true);
  loadActiveEditor();
  resetResultPanel();
  runCode(false, { scroll: false });
  if (options.showResultPrompt !== false) {
    showResultReadyAfterActivitySelection('Activity rubric loaded. Click the button inside this popup or Result when you are ready to check your current HTML, CSS, and JavaScript.');
  }
  setStatus(`Loaded: ${nextActivity.title}. Click Result when ready.`);
}

async function resetCurrentActivityCode() {
  if (!activity) {
    showActivityRequiredWarning();
    return;
  }

  if (!await appConfirm(`Reset your code for "${activity.title}"?`, { title: 'Reset activity code', danger: true })) return;
  codeStore = normalizeCodeStore(starterCode);
  codeByActivity[activity.id] = codeStore;
  saveCodeByActivity();
  resetAllLanguageHistoryForCurrentActivity();
  loadActiveEditor();
  resetResultPanel();
  runCode();
  setStatus('Activity code reset');
}

function setPreviewLayout(layout) {
  const safeLayout = ['split', 'stacked', 'preview-focus'].includes(layout) ? layout : 'split';
  workspace.dataset.layout = safeLayout;
  layoutButtons.forEach(button => button.classList.toggle('active', button.dataset.layout === safeLayout));
  saveJSON(STORAGE_KEYS.layout, safeLayout);
  setStatus(safeLayout === 'preview-focus' ? 'Big preview layout' : `${safeLayout[0].toUpperCase()}${safeLayout.slice(1)} layout`);
}

function setDesktopPreviewMode(enabled) {
  // The monitor simulation is intentionally available on phones only.
  if (!isLikelyPhoneViewport()) {
    applyPreviewDeviceMode();
    return;
  }

  const isEnabled = Boolean(enabled);
  previewPanel?.classList.toggle('mobile-desktop-preview', isEnabled);
  if (desktopPreviewBtn) {
    desktopPreviewBtn.classList.toggle('active', isEnabled);
    desktopPreviewBtn.setAttribute('aria-pressed', String(isEnabled));
    const isPhoneView = document.documentElement.dataset.deviceMode === 'phone' || window.innerWidth <= 760;
    desktopPreviewBtn.textContent = isPhoneView ? (isEnabled ? 'Phone' : 'Monitor') : (isEnabled ? 'Phone View' : 'Desktop Monitor');
    desktopPreviewBtn.dataset.mobileLabel = isEnabled ? '📱 Phone' : '🖥️ Monitor';
    desktopPreviewBtn.setAttribute('aria-label', isEnabled ? 'Return to phone preview' : 'Open desktop monitor preview');
    desktopPreviewBtn.title = isEnabled
      ? 'Return the preview to normal phone width'
      : 'Show the output inside a scaled desktop monitor view';
  }
  window.setTimeout(updateDesktopMonitorPreviewSizing, 0);
  setStatus(isEnabled ? 'Desktop monitor preview' : 'Phone preview');
}

function toggleDesktopPreviewMode() {
  setDesktopPreviewMode(!previewPanel?.classList.contains('mobile-desktop-preview'));
}

function ensureBackToEditorPreviewBtn() {
  let button = document.getElementById('backToEditorPreviewBtn');
  if (!button) {
    button = document.createElement('button');
    button.id = 'backToEditorPreviewBtn';
    button.type = 'button';
    button.className = 'layout-btn strong back-editor-preview-btn hidden';
    button.textContent = '↩ Back to Editor';
    button.title = 'Return to Full Editor';
    const actions = previewPanel?.querySelector('.preview-actions');
    if (actions && exitPreviewBtn) {
      actions.insertBefore(button, exitPreviewBtn);
    } else if (actions) {
      actions.appendChild(button);
    }
    button.addEventListener('click', backToEditorFromPreview);
  }
  return button;
}

function ensurePreviewResultBtn() {
  let button = document.getElementById('resultFromPreviewBtn');
  if (!button) {
    button = document.createElement('button');
    button.id = 'resultFromPreviewBtn';
    button.type = 'button';
    button.className = 'layout-btn strong preview-result-btn';
    button.textContent = '✓ Result';
    button.title = 'Check result from Output Preview';
    const actions = previewPanel?.querySelector('.preview-actions');
    const backButton = document.getElementById('backToEditorPreviewBtn');
    if (actions && exitPreviewBtn) {
      actions.insertBefore(button, exitPreviewBtn);
    } else if (actions && backButton?.nextSibling) {
      actions.insertBefore(button, backButton.nextSibling);
    } else if (actions) {
      actions.appendChild(button);
    }
    button.addEventListener('click', showResultFromPreview);
  }
  return button;
}

function ensurePreviewControlsToggle() {
  let button = document.getElementById('previewControlsToggle');
  const actions = previewPanel?.querySelector('.preview-actions');
  if (!button) {
    button = document.createElement('button');
    button.id = 'previewControlsToggle';
    button.type = 'button';
    button.className = 'layout-btn preview-controls-toggle hidden';
    button.textContent = '🖥️';
    button.title = 'Show output controls';
    button.setAttribute('aria-label', 'Show output controls');
    button.setAttribute('aria-expanded', 'false');
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      const controls = previewPanel?.querySelector('.preview-actions');
      const isOpen = controls?.classList.toggle('output-menu-open');
      button.setAttribute('aria-expanded', String(Boolean(isOpen)));
      button.title = isOpen ? 'Hide output controls' : 'Show output controls';
      button.setAttribute('aria-label', isOpen ? 'Hide output controls' : 'Show output controls');
    });
  }
  if (actions && button.parentElement !== actions) {
    actions.insertBefore(button, actions.firstChild);
  }
  return button;
}

function setPreviewControlsMenu(open) {
  const actions = previewPanel?.querySelector('.preview-actions');
  const toggle = document.getElementById('previewControlsToggle');
  actions?.classList.toggle('output-menu-open', Boolean(open));
  if (toggle) {
    toggle.setAttribute('aria-expanded', String(Boolean(open)));
    toggle.title = open ? 'Hide output controls' : 'Show output controls';
    toggle.setAttribute('aria-label', open ? 'Hide output controls' : 'Show output controls');
  }
}

function showResultFromPreview() {
  hideSuggestions();
  const wasPreviewFullscreen = document.body.classList.contains('preview-fullscreen-active');
  const wasInsideFullEditor = previewMovedIntoEditor ||
    document.body.classList.contains('preview-inside-editor-fullscreen') ||
    document.body.classList.contains('editor-fullscreen-active');

  if (wasPreviewFullscreen) {
    exitFullPreview({ keepReturnFlag: false, silent: true, keepNative: true });
    if (wasInsideFullEditor || document.body.classList.contains('editor-fullscreen-active')) {
      exitFullEditor({ silent: true, skipFocus: true });
    }
    window.setTimeout(() => {
      showResult({ fromPreview: true });
    }, 180);
    return;
  }

  showResult({ fromPreview: true });
}


function setPreviewTransitionClass() {
  window.clearTimeout(previewTransitionTimer);
  document.body.classList.add('preview-transitioning');
  previewTransitionTimer = window.setTimeout(() => {
    document.body.classList.remove('preview-transitioning');
  }, 360);
}

function enterFullPreview(options = {}) {
  const fromFullEditor = Boolean(options.fromFullEditor || returnToFullEditorAfterPreview);
  const insideEditorFullscreen = Boolean(
    fromFullEditor &&
    options.keepEditorFullscreen !== false &&
    document.body.classList.contains('editor-fullscreen-active') &&
    movePreviewPanelIntoEditorFullscreen()
  );
  const wantsNativeFullscreen = options.nativeFullscreen !== false && !insideEditorFullscreen;

  returnToFullEditorAfterPreview = fromFullEditor;
  const backButton = ensureBackToEditorPreviewBtn();
  const previewResultButton = ensurePreviewResultBtn();
  const previewControlsToggle = ensurePreviewControlsToggle();
  backButton?.classList.toggle('hidden', !fromFullEditor);
  previewResultButton?.classList.toggle('hidden', !fromFullEditor);
  previewControlsToggle?.classList.toggle('hidden', !fromFullEditor);
  setPreviewControlsMenu(false);

  document.body.classList.add('preview-fullscreen-active');
  document.body.classList.toggle('preview-has-back-editor', fromFullEditor);
  document.body.classList.toggle('preview-inside-editor-fullscreen', insideEditorFullscreen);
  document.body.classList.remove('preview-closing-to-editor');

  // When the preview is shown inside the full editor, hide editor-only floating controls.
  // The preview must show only its own Back/Exit controls so it does not look like
  // the editor buttons are part of the student's output.
  if (insideEditorFullscreen) {
    hideSuggestions();
    closeCodeHelperPanel();
    ensureFullscreenActionBar()?.classList.add('hidden');
  }

  if (!insideEditorFullscreen) {
    setPreviewTransitionClass();
  }

  fullPreviewBtn?.classList.add('hidden');
  exitPreviewBtn?.classList.remove('hidden');
  window.setTimeout(updateDesktopMonitorPreviewSizing, 0);

  if (wantsNativeFullscreen && previewPanel?.requestFullscreen && document.fullscreenElement !== previewPanel) {
    previewPanel.requestFullscreen().catch(() => {
      // If the browser blocks native fullscreen, the CSS fullscreen fallback remains active.
    });
  }

  setStatus(fromFullEditor ? 'Output preview' : 'Full preview');
}

function exitFullPreview(options = {}) {
  // The Exit button in a preview that came from Full Editor must close the whole
  // fullscreen flow, not return to the editor fullscreen. Back to Editor already
  // handles that separate behavior.
  const safeOptions = options && typeof options === 'object' && !('target' in options) ? options : {};
  const isInsideEditorFullscreen = previewMovedIntoEditor || document.body.classList.contains('preview-inside-editor-fullscreen');
  const shouldCloseEditorFullscreen = Boolean(safeOptions.closeEditorFullscreen && isInsideEditorFullscreen);
  const shouldExitNativePreview = document.fullscreenElement === previewPanel &&
    !safeOptions.keepNative &&
    !safeOptions.fromNative &&
    document.exitFullscreen;
  const shouldExitNativeEditor = shouldCloseEditorFullscreen &&
    document.fullscreenElement === editorPanel &&
    !safeOptions.keepNative &&
    !safeOptions.fromNative &&
    document.exitFullscreen;

  document.body.classList.remove(
    'preview-fullscreen-active',
    'preview-has-back-editor',
    'preview-closing-to-editor',
    'preview-inside-editor-fullscreen',
    'book-preview-revealing',
    'book-preview-leaving'
  );

  if (!isInsideEditorFullscreen) {
    setPreviewTransitionClass();
  }

  fullPreviewBtn?.classList.remove('hidden');
  exitPreviewBtn?.classList.add('hidden');
  ensureBackToEditorPreviewBtn()?.classList.add('hidden');
  if (isInsideEditorFullscreen) ensurePreviewResultBtn()?.classList.add('hidden');
  else ensurePreviewResultBtn()?.classList.remove('hidden');
  ensurePreviewControlsToggle()?.classList.add('hidden');
  setPreviewControlsMenu(false);

  if (isInsideEditorFullscreen) {
    restorePreviewPanelFromEditorFullscreen();
  }

  if (shouldCloseEditorFullscreen) {
    document.body.classList.remove('editor-fullscreen-active');
    document.getElementById('fullscreenEditorActions')?.classList.add('hidden');
    document.getElementById('exitEditorStickyBtn')?.classList.add('hidden');
    document.getElementById('fullscreenRunBtn')?.classList.add('hidden');
    document.getElementById('fullscreenResultBtn')?.classList.add('hidden');
    fullEditorBtn?.classList.remove('hidden');
    exitEditorBtn?.classList.add('hidden');
    hideSuggestions();
    closeCodeHelperPanel();
  }

  if (shouldExitNativePreview || shouldExitNativeEditor) {
    document.exitFullscreen().catch(() => {});
  }

  if (!safeOptions.keepReturnFlag) {
    returnToFullEditorAfterPreview = false;
  }
  if (!safeOptions.silent) {
    setStatus(shouldCloseEditorFullscreen ? 'Fullscreen closed' : 'Preview restored');
  }

  window.setTimeout(updateDesktopMonitorPreviewSizing, 0);
  fitEditorToContent();
}

function backToEditorFromPreview() {
  if (fullscreenPageTransitionBusy) return;
  const isInsideEditorFullscreen = previewMovedIntoEditor || document.body.classList.contains('preview-inside-editor-fullscreen');

  if (isInsideEditorFullscreen) {
    fullscreenPageTransitionBusy = true;
    hideSuggestions();
    closeCodeHelperPanel();
    document.body.classList.add('preview-closing-to-editor');

    runSmoothFullscreenBookTransition({
      direction: 'to-editor',
      label: 'Back to Editor',
      onSwap: () => {
        restoreEditorFullscreenAfterPreview();
        document.body.classList.add('book-editor-revealing');
        scheduleFullEditorControlsRestore();
        setStatus('Back to editor');
      },
      onDone: () => {
        document.body.classList.remove('book-editor-revealing', 'preview-closing-to-editor');
        editor?.focus({ preventScroll: true });
      }
    });
    return;
  }

  // Normal native-preview fallback: switch it back to the editor while this click has user activation.
  if (document.fullscreenElement === previewPanel && editorPanel?.requestFullscreen) {
    editorPanel.requestFullscreen().catch(() => {});
  }

  exitFullPreview({ keepReturnFlag: true, silent: true, keepNative: true });
  window.setTimeout(() => {
    enterFullEditor();
    restoreEditorFullscreenAfterPreview();
    scheduleFullEditorControlsRestore();
    returnToFullEditorAfterPreview = false;
    fullscreenPageTransitionBusy = false;
    setStatus('Back to editor');
  }, 180);
}


function ensureFullscreenActionBar() {
  if (!editorPanel) return null;
  let actions = document.getElementById('fullscreenEditorActions');
  if (!actions) {
    actions = document.createElement('div');
    actions.id = 'fullscreenEditorActions';
    actions.className = 'fullscreen-editor-actions hidden';
    actions.setAttribute('aria-label', 'Full editor actions');
    editorPanel.insertBefore(actions, editorPanel.firstChild);
  }

  const buttonSpecs = [
    {
      id: 'fullscreenRunBtn',
      className: 'primary-btn fullscreen-run-btn',
      text: '▶ Run',
      title: 'Run: Ctrl + Enter',
      onClick: handleFullscreenRunClick
    },
    {
      id: 'fullscreenAutoRunBtn',
      className: 'ghost-btn fullscreen-auto-run-btn',
      text: autoRunEnabled ? '⚡ Auto On' : '⚡ Auto Off',
      title: 'Auto update preview after typing',
      onClick: toggleAutoRun
    },
    {
      id: 'fullscreenResultBtn',
      className: 'success-btn fullscreen-result-btn',
      text: '✓ Result',
      title: 'Check result: Ctrl + Shift + Enter',
      onClick: handleFullscreenResultClick
    },
    {
      id: 'exitEditorStickyBtn',
      className: 'fullscreen-exit-btn',
      text: 'Exit Full',
      title: 'Exit full editor: Esc',
      onClick: exitFullEditor
    }
  ];

  buttonSpecs.forEach(spec => {
    let button = document.getElementById(spec.id);
    if (!button) {
      button = document.createElement('button');
      button.id = spec.id;
      button.type = 'button';
      actions.appendChild(button);
    }
    if (button.parentElement !== actions) actions.appendChild(button);
    button.className = spec.className;
    button.textContent = spec.text;
    button.title = spec.title;
    button.classList.remove('hidden');
    if (!button.dataset.fullscreenActionBound) {
      button.addEventListener('click', spec.onClick);
      button.dataset.fullscreenActionBound = 'true';
    }
  });

  updateAutoRunButtons();
  return actions;
}

function forceFullEditorControlsVisible() {
  const previewActive = document.body.classList.contains('preview-fullscreen-active') ||
    document.body.classList.contains('preview-inside-editor-fullscreen') ||
    previewMovedIntoEditor;

  if (!document.body.classList.contains('editor-fullscreen-active') || previewActive) {
    return;
  }

  const actions = ensureFullscreenActionBar();
  if (actions) {
    actions.classList.remove('hidden');
    actions.removeAttribute('aria-hidden');
  }

  [
    document.getElementById('fullscreenRunBtn'),
    document.getElementById('fullscreenResultBtn'),
    document.getElementById('exitEditorStickyBtn')
  ].forEach(button => {
    if (!button) return;
    button.classList.remove('hidden');
    button.removeAttribute('aria-hidden');
    button.disabled = false;
  });

  if (codeHelperFloatingBtn) {
    codeHelperFloatingBtn.classList.remove('hidden');
    codeHelperFloatingBtn.removeAttribute('aria-hidden');
    codeHelperFloatingBtn.disabled = false;
  }

  if (fullEditorBtn) fullEditorBtn.classList.add('hidden');
  if (exitEditorBtn) exitEditorBtn.classList.add('hidden');
}

function restoreEditorFullscreenAfterPreview() {
  window.clearTimeout(previewCloseToEditorTimer);
  document.body.classList.remove(
    'preview-fullscreen-active',
    'preview-has-back-editor',
    'preview-inside-editor-fullscreen',
    'preview-closing-to-editor'
  );

  if (previewMovedIntoEditor) {
    restorePreviewPanelFromEditorFullscreen();
  }

  document.body.classList.add('editor-fullscreen-active');
  returnToFullEditorAfterPreview = false;
  fullPreviewBtn?.classList.remove('hidden');
  exitPreviewBtn?.classList.add('hidden');
  ensureBackToEditorPreviewBtn()?.classList.add('hidden');
  ensurePreviewResultBtn()?.classList.add('hidden');
  ensurePreviewControlsToggle()?.classList.add('hidden');
  setPreviewControlsMenu(false);
  forceFullEditorControlsVisible();
  fitEditorToContent();
}

function scheduleFullEditorControlsRestore() {
  [0, 60, 180, 420].forEach(delay => {
    window.setTimeout(forceFullEditorControlsVisible, delay);
  });
}


function enterFullEditor() {
  if (document.body.classList.contains('preview-fullscreen-active')) {
    exitFullPreview();
  }

  document.body.classList.add('editor-fullscreen-active');
  syncSmartInlineHintHost();
  fullEditorBtn?.classList.add('hidden');
  exitEditorBtn?.classList.remove('hidden');
  const fullscreenActions = ensureFullscreenActionBar();
  fullscreenActions?.classList.remove('hidden');
  document.getElementById('exitEditorStickyBtn')?.classList.remove('hidden');
  document.getElementById('fullscreenRunBtn')?.classList.remove('hidden');
  document.getElementById('fullscreenResultBtn')?.classList.remove('hidden');
  ensurePreviewResultBtn()?.classList.add('hidden');
  hideSuggestions();

  const isSmallScreen = window.matchMedia('(max-width: 820px)').matches;
  if (!isSmallScreen && editorPanel?.requestFullscreen && !document.fullscreenElement) {
    editorPanel.requestFullscreen().catch(() => {
      // Browser may block fullscreen from some shortcuts; CSS fullscreen still works.
    });
  }

  forceFullEditorControlsVisible();
  scheduleFullEditorControlsRestore();
  setStatus('Full editor mode');
  fitEditorToContent();
  window.setTimeout(() => editor.focus(), 80);
}

function exitFullEditor(options = {}) {
  if (previewMovedIntoEditor || document.body.classList.contains('preview-inside-editor-fullscreen')) {
    exitFullPreview({ silent: true, keepNative: true });
  }
  document.body.classList.remove('editor-fullscreen-active');
  syncSmartInlineHintHost();
  fullEditorBtn?.classList.remove('hidden');
  exitEditorBtn?.classList.add('hidden');
  document.getElementById('fullscreenEditorActions')?.classList.add('hidden');
  document.getElementById('exitEditorStickyBtn')?.classList.add('hidden');
  document.getElementById('fullscreenRunBtn')?.classList.add('hidden');
  document.getElementById('fullscreenResultBtn')?.classList.add('hidden');
  if (!document.body.classList.contains('preview-fullscreen-active')) ensurePreviewResultBtn()?.classList.remove('hidden');
  hideSuggestions();

  if (!options.fromNative && document.fullscreenElement && document.exitFullscreen) {
    document.exitFullscreen().catch(() => {});
  }

  if (!options.silent) {
    setStatus('Editor restored');
  }
  fitEditorToContent();
  if (!options.skipFocus) {
    window.setTimeout(() => editor.focus(), 80);
  }
}



/* =========================================================
   Lesson Viewer + free Google Drive Lesson Manager
   PDF files stay in the teacher's Google Drive. Firestore stores
   only the small lesson list inside the existing root document.
   ========================================================= */
const LESSON_TERMS = Object.freeze({
  term1: 'Term 1',
  term2: 'Term 2',
  term3: 'Term 3'
});
const LESSON_GOOGLE_DRIVE_SCOPE = 'https://www.googleapis.com/auth/drive.file';
const LESSON_GOOGLE_API_BASE = 'https://www.googleapis.com/drive/v3';
const LESSON_GOOGLE_UPLOAD_BASE = 'https://www.googleapis.com/upload/drive/v3';
const lessonLibraryState = {
  lessons: [],
  loaded: false,
  loading: false,
  activeTerm: 'term1',
  sourceMode: 'upload',
  editingId: '',
  returnView: 'dashboard',
  driveAccessToken: '',
  driveTokenExpiresAt: 0,
  driveTokenClient: null,
  pdfLoadTimer: null,
  pdfControlsTimer: null,
  pdfFrameTimer: null,
  renderTimer: null,
  currentPdfRequestId: 0,
  currentLessonId: '',
  currentLessonOpenedAt: 0
};

function lessonTermLabel(term = 'term1') {
  return LESSON_TERMS[term] || LESSON_TERMS.term1;
}

function lessonTimestampMs(value) {
  if (!value) return 0;
  if (typeof value?.toDate === 'function') return value.toDate().getTime();
  if (typeof value?.seconds === 'number') return value.seconds * 1000;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isFinite(date.getTime()) ? date.getTime() : 0;
}

function lessonIsoDate(value = Date.now()) {
  const ms = lessonTimestampMs(value) || Date.now();
  return new Date(ms).toISOString();
}

function extractGoogleDriveFileId(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const patterns = [
    /\/file\/d\/([a-zA-Z0-9_-]+)/i,
    /[?&]id=([a-zA-Z0-9_-]+)/i,
    /\/d\/([a-zA-Z0-9_-]+)/i
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) return match[1];
  }
  return '';
}

function buildGoogleDriveLessonUrls(fileId = '') {
  const id = String(fileId || '').trim();
  if (!id) return { previewUrl: '', openUrl: '', downloadUrl: '' };
  return {
    previewUrl: `https://drive.google.com/file/d/${encodeURIComponent(id)}/preview`,
    openUrl: `https://drive.google.com/file/d/${encodeURIComponent(id)}/view`,
    downloadUrl: `https://drive.google.com/uc?export=download&id=${encodeURIComponent(id)}`
  };
}

function normalizeLessonSourceUrl(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return { fileId: '', previewUrl: '', openUrl: '', downloadUrl: '', source: 'link' };
  let parsed = null;
  try {
    parsed = new URL(raw, window.location.href);
  } catch (_) {
    throw new Error('Enter a complete public PDF or Google Drive link.');
  }
  if (!/^https?:$/i.test(parsed.protocol)) throw new Error('Only secure web links can be used for lessons.');
  const fileId = extractGoogleDriveFileId(raw);
  if (fileId) return { fileId, ...buildGoogleDriveLessonUrls(fileId), source: 'drive-link' };
  return { fileId: '', previewUrl: parsed.href, openUrl: parsed.href, downloadUrl: parsed.href, source: 'external-link' };
}

function normalizeLesson(raw = {}, index = 0) {
  const term = Object.prototype.hasOwnProperty.call(LESSON_TERMS, raw.term) ? raw.term : 'term1';
  const fileId = String(raw.fileId || extractGoogleDriveFileId(raw.previewUrl || raw.openUrl || raw.url || '') || '').trim();
  const driveUrls = buildGoogleDriveLessonUrls(fileId);
  const previewUrl = String(raw.previewUrl || raw.url || driveUrls.previewUrl || '').trim();
  const openUrl = String(raw.openUrl || driveUrls.openUrl || previewUrl).trim();
  const downloadUrl = String(raw.downloadUrl || driveUrls.downloadUrl || openUrl).trim();
  const order = Math.max(1, Math.min(999, Number.parseInt(raw.order, 10) || index + 1));
  return {
    id: String(raw.id || `lesson-${Date.now()}-${index}`).replace(/[^a-zA-Z0-9_-]/g, '-'),
    title: String(raw.title || 'Untitled Lesson').trim().slice(0, 120),
    description: String(raw.description || '').trim().slice(0, 300),
    term,
    order,
    fileId,
    fileName: String(raw.fileName || '').trim().slice(0, 180),
    fileSize: Math.max(0, Number(raw.fileSize || 0)),
    previewUrl,
    openUrl,
    downloadUrl,
    source: String(raw.source || (fileId ? 'google-drive' : 'external-link')),
    uploadedAt: lessonIsoDate(raw.uploadedAt || raw.createdAt || Date.now()),
    updatedAt: lessonIsoDate(raw.updatedAt || raw.uploadedAt || raw.createdAt || Date.now())
  };
}

function sortLessonsForDisplay(items = [], mode = 'order-asc') {
  const lessons = [...items];
  if (mode === 'title-asc') return lessons.sort((a, b) => a.title.localeCompare(b.title, undefined, { sensitivity: 'base' }));
  if (mode === 'newest') return lessons.sort((a, b) => lessonTimestampMs(b.updatedAt) - lessonTimestampMs(a.updatedAt));
  if (mode === 'oldest') return lessons.sort((a, b) => lessonTimestampMs(a.updatedAt) - lessonTimestampMs(b.updatedAt));
  return lessons.sort((a, b) => a.order - b.order || a.title.localeCompare(b.title, undefined, { sensitivity: 'base' }));
}

function saveLessonLibraryCache() {
  saveJSON(STORAGE_KEYS.lessonLibrary, {
    savedAt: Date.now(),
    lessons: lessonLibraryState.lessons.map((lesson, index) => normalizeLesson(lesson, index))
  });
}

function loadLessonLibraryCache() {
  const cached = loadJSON(STORAGE_KEYS.lessonLibrary, null);
  const list = Array.isArray(cached?.lessons) ? cached.lessons : [];
  return list.map((lesson, index) => normalizeLesson(lesson, index));
}

function formatLessonFileSize(bytes = 0) {
  const size = Number(bytes || 0);
  if (!size) return '';
  if (size < 1024 * 1024) return `${Math.max(1, Math.round(size / 1024))} KB`;
  return `${(size / (1024 * 1024)).toFixed(size >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
}

function setLessonLibraryStatus(message = '', type = '') {
  if (!lessonLibraryStatus) return;
  lessonLibraryStatus.textContent = message;
  lessonLibraryStatus.dataset.type = type;
}

function setLessonAdminStatus(message = '', type = '') {
  if (!lessonAdminStatus) return;
  lessonAdminStatus.textContent = message;
  lessonAdminStatus.dataset.type = type;
}

function setLessonDriveStatus(message = '', type = '') {
  if (!lessonDriveStatus) return;
  lessonDriveStatus.textContent = message;
  lessonDriveStatus.dataset.type = type;
}

function runLessonIdleTask(callback, delay = 60) {
  if (typeof callback !== 'function') return 0;
  if (typeof window.requestIdleCallback === 'function') {
    return window.requestIdleCallback(callback, { timeout: Math.max(120, delay + 120) });
  }
  return window.setTimeout(callback, delay);
}

function cancelLessonIdleTask(id = 0) {
  if (!id) return;
  if (typeof window.cancelIdleCallback === 'function') window.cancelIdleCallback(id);
  else window.clearTimeout(id);
}

function scheduleStudentLessonLibraryRender(delay = 80) {
  window.clearTimeout(lessonLibraryState.renderTimer);
  lessonLibraryState.renderTimer = window.setTimeout(() => {
    lessonLibraryState.renderTimer = null;
    renderStudentLessonLibrary();
  }, Math.max(0, delay));
}

function handleLessonPdfFrameLoad() {
  window.clearTimeout(lessonLibraryState.pdfLoadTimer);
  lessonPdfLoading?.classList.add('hidden');
}

function bindLessonPdfFrameLoadHandler() {
  lessonPdfFrame?.removeEventListener('load', handleLessonPdfFrameLoad);
  lessonPdfFrame?.addEventListener('load', handleLessonPdfFrameLoad);
}

function resetLessonPdfFrame(options = {}) {
  cancelLessonIdleTask(lessonLibraryState.pdfFrameTimer);
  lessonLibraryState.pdfFrameTimer = null;
  lessonLibraryState.currentPdfRequestId += 1;
  if (!lessonPdfFrame) return;
  try {
    lessonPdfFrame.dataset.lessonSrc = '';
    lessonPdfFrame.removeAttribute('src');
    lessonPdfFrame.src = 'about:blank';
  } catch (error) {
    console.warn('Could not reset lesson PDF frame.', error);
  }
  if (options.hard && lessonPdfFrame.parentNode) {
    const freshFrame = lessonPdfFrame.cloneNode(false);
    freshFrame.removeAttribute('src');
    freshFrame.dataset.lessonSrc = '';
    lessonPdfFrame.replaceWith(freshFrame);
    lessonPdfFrame = freshFrame;
    bindLessonPdfFrameLoadHandler();
  }
}

function loadLessonPdfFrame(url = '') {
  const pdfUrl = String(url || '').trim();
  if (!pdfUrl || !lessonPdfFrame) return;
  resetLessonPdfFrame();
  const requestId = lessonLibraryState.currentPdfRequestId;
  lessonPdfLoading?.classList.remove('hidden', 'lesson-pdf-load-warning');
  requestAnimationFrame(() => {
    lessonLibraryState.pdfFrameTimer = runLessonIdleTask(() => {
      if (requestId !== lessonLibraryState.currentPdfRequestId) return;
      if (!lessonPdfFrame || !lessonPdfOverlay || lessonPdfOverlay.classList.contains('hidden')) return;
      lessonPdfFrame.dataset.lessonSrc = pdfUrl;
      lessonPdfFrame.src = pdfUrl;
    }, 40);
  });
}


function getLessonReaderKey() {
  const student = appSession.student || appSession.lastStudentProfile || null;
  const raw = student?.uid || student?.studentIdNormalized || student?.studentId || student?.id || (appSession.mode === 'guest' ? 'guest' : 'local');
  return String(raw || 'local').replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 80) || 'local';
}

function loadLessonProgressRoot() {
  const value = loadJSON(STORAGE_KEYS.lessonProgress, {});
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function loadLessonProgressMap() {
  const root = loadLessonProgressRoot();
  const readerKey = getLessonReaderKey();
  const map = root[readerKey];
  return map && typeof map === 'object' && !Array.isArray(map) ? map : {};
}

function saveLessonProgressMap(progressMap = {}) {
  const root = loadLessonProgressRoot();
  root[getLessonReaderKey()] = progressMap;
  saveJSON(STORAGE_KEYS.lessonProgress, root);
}

function normalizeLessonProgress(record = {}) {
  const progress = record && typeof record === 'object' ? record : {};
  const startedAt = lessonTimestampMs(progress.startedAt) || 0;
  const lastOpenedAt = lessonTimestampMs(progress.lastOpenedAt) || 0;
  const completedAt = lessonTimestampMs(progress.completedAt) || 0;
  const totalSeconds = Math.max(0, Number(progress.totalSeconds || 0));
  const openCount = Math.max(0, Number.parseInt(progress.openCount || 0, 10));
  const percent = completedAt ? 100 : (lastOpenedAt ? Math.max(15, Math.min(60, 15 + Math.min(45, openCount * 10))) : 0);
  return {
    startedAt,
    lastOpenedAt,
    completedAt,
    totalSeconds,
    openCount,
    percent,
    status: completedAt ? 'completed' : (lastOpenedAt ? 'in-progress' : 'not-started')
  };
}

function getLessonProgress(lessonId = '') {
  const map = loadLessonProgressMap();
  return normalizeLessonProgress(map[String(lessonId || '')] || {});
}

function updateLessonProgress(lessonId = '', patch = {}) {
  const id = String(lessonId || '').trim();
  if (!id) return normalizeLessonProgress({});
  const map = loadLessonProgressMap();
  const current = normalizeLessonProgress(map[id] || {});
  const next = {
    ...current,
    ...patch,
    startedAt: patch.startedAt || current.startedAt || Date.now(),
    lastOpenedAt: patch.lastOpenedAt || current.lastOpenedAt || Date.now()
  };
  if (patch.completedAt) next.percent = 100;
  map[id] = next;
  saveLessonProgressMap(map);
  return normalizeLessonProgress(next);
}

function formatLessonRelativeTime(value = 0) {
  const ms = lessonTimestampMs(value);
  if (!ms) return '';
  const diff = Math.max(0, Date.now() - ms);
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (diff < minute) return 'just now';
  if (diff < hour) return `${Math.max(1, Math.round(diff / minute))} min ago`;
  if (diff < day) return `${Math.max(1, Math.round(diff / hour))} hr ago`;
  if (diff < 7 * day) return `${Math.max(1, Math.round(diff / day))} day${Math.round(diff / day) === 1 ? '' : 's'} ago`;
  return new Date(ms).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function getLessonProgressLabel(lessonId = '') {
  const progress = getLessonProgress(lessonId);
  if (progress.completedAt) return { status: 'completed', label: 'Completed', detail: '100% read', percent: 100 };
  if (progress.lastOpenedAt) return {
    status: 'in-progress',
    label: 'Continue',
    detail: `Opened ${formatLessonRelativeTime(progress.lastOpenedAt) || 'recently'}`,
    percent: progress.percent
  };
  return { status: 'not-started', label: 'Not started', detail: 'Ready to read', percent: 0 };
}

function getLatestLessonProgressItem() {
  const map = loadLessonProgressMap();
  const ids = new Set(lessonLibraryState.lessons.map(lesson => lesson.id));
  const records = Object.entries(map)
    .filter(([lessonId]) => ids.has(lessonId))
    .map(([lessonId, record]) => ({ lessonId, progress: normalizeLessonProgress(record) }))
    .filter(item => item.progress.lastOpenedAt || item.progress.completedAt)
    .sort((a, b) => Math.max(b.progress.lastOpenedAt, b.progress.completedAt) - Math.max(a.progress.lastOpenedAt, a.progress.completedAt));
  const active = records.find(item => !item.progress.completedAt) || records[0] || null;
  if (!active) return null;
  const lesson = lessonLibraryState.lessons.find(item => item.id === active.lessonId);
  return lesson ? { lesson, progress: active.progress } : null;
}

function renderLessonContinueReading() {
  if (!lessonContinueCard) return;
  const latest = getLatestLessonProgressItem();
  if (!latest) {
    lessonContinueCard.classList.add('hidden');
    if (lessonContinueBtn) lessonContinueBtn.dataset.lessonContinue = '';
    return;
  }
  const { lesson, progress } = latest;
  const completed = Boolean(progress.completedAt);
  lessonContinueCard.classList.remove('hidden');
  if (lessonContinueTitle) lessonContinueTitle.textContent = lesson.title;
  if (lessonContinueMeta) {
    const when = formatLessonRelativeTime(progress.lastOpenedAt || progress.completedAt) || 'recently';
    lessonContinueMeta.textContent = `${lessonTermLabel(lesson.term)} · Lesson ${lesson.order} · ${completed ? 'Completed' : 'Last opened'} ${when}`;
  }
  if (lessonContinueProgressBar) lessonContinueProgressBar.style.width = `${completed ? 100 : progress.percent}%`;
  if (lessonContinueBtn) {
    lessonContinueBtn.dataset.lessonContinue = lesson.id;
    lessonContinueBtn.textContent = completed ? 'Review Again' : 'Continue';
  }
}

function syncLessonPdfProgressUi(lessonId = lessonLibraryState.currentLessonId) {
  const id = String(lessonId || '').trim();
  const progress = getLessonProgress(id);
  const label = getLessonProgressLabel(id);
  if (lessonPdfProgressText) {
    lessonPdfProgressText.textContent = progress.completedAt
      ? `Completed · ${formatLessonRelativeTime(progress.completedAt) || 'saved locally'}`
      : (progress.lastOpenedAt ? `In progress · Last opened ${formatLessonRelativeTime(progress.lastOpenedAt) || 'recently'}` : 'Not started yet');
    lessonPdfProgressText.dataset.status = label.status;
  }
  if (lessonPdfMarkDoneBtn) {
    lessonPdfMarkDoneBtn.textContent = progress.completedAt ? '✓ Done' : '✓ Mark Done';
    lessonPdfMarkDoneBtn.disabled = Boolean(progress.completedAt);
  }
}

function finishCurrentLessonReadingSession() {
  const id = lessonLibraryState.currentLessonId;
  if (!id || !lessonLibraryState.currentLessonOpenedAt) return;
  const elapsed = Math.max(0, Math.round((Date.now() - lessonLibraryState.currentLessonOpenedAt) / 1000));
  const current = getLessonProgress(id);
  updateLessonProgress(id, {
    totalSeconds: Math.max(0, Number(current.totalSeconds || 0)) + elapsed,
    lastOpenedAt: Date.now()
  });
  lessonLibraryState.currentLessonOpenedAt = 0;
  renderStudentLessonLibrary();
  renderLessonContinueReading();
}

function getLessonFilteredForStudent() {
  const term = lessonLibraryState.activeTerm;
  const search = String(lessonLibrarySearch?.value || '').trim().toLowerCase();
  const mode = lessonLibrarySort?.value || 'order-asc';
  const matches = lessonLibraryState.lessons.filter(lesson => {
    if (lesson.term !== term) return false;
    if (!search) return true;
    return `${lesson.title} ${lesson.description} ${lesson.fileName}`.toLowerCase().includes(search);
  });
  return sortLessonsForDisplay(matches, mode);
}

function renderLessonTermCounts() {
  Object.keys(LESSON_TERMS).forEach(term => {
    const count = lessonLibraryState.lessons.filter(lesson => lesson.term === term).length;
    document.querySelectorAll(`[data-term-count="${term}"]`).forEach(element => { element.textContent = String(count); });
  });
  if (lessonLibraryTotalCount) lessonLibraryTotalCount.textContent = String(lessonLibraryState.lessons.length);
}

function renderStudentLessonLibrary() {
  if (!lessonLibraryGrid) return;
  renderLessonTermCounts();
  renderLessonContinueReading();
  lessonTermTabs?.querySelectorAll('[data-lesson-term]').forEach(button => {
    const active = button.dataset.lessonTerm === lessonLibraryState.activeTerm;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  const lessons = getLessonFilteredForStudent();
  const search = String(lessonLibrarySearch?.value || '').trim();
  if (!lessons.length) {
    const hasTermLessons = lessonLibraryState.lessons.some(lesson => lesson.term === lessonLibraryState.activeTerm);
    lessonLibraryGrid.innerHTML = `
      <div class="lesson-library-empty">
        <span aria-hidden="true">${search ? '🔎' : '📖'}</span>
        <h3>${search ? 'No matching lesson' : `No ${escapeHTML(lessonTermLabel(lessonLibraryState.activeTerm))} lessons yet`}</h3>
        <p>${search ? 'Try another title or topic.' : 'Your teacher can publish PDF lessons from the Admin Lesson Manager.'}</p>
      </div>`;
    setLessonLibraryStatus(hasTermLessons && search ? 'No lesson matches your search.' : 'Choose another term or check again later.', hasTermLessons ? '' : 'empty');
    return;
  }
  lessonLibraryGrid.innerHTML = lessons.map(lesson => {
    const size = formatLessonFileSize(lesson.fileSize);
    const date = lessonTimestampMs(lesson.updatedAt) ? new Date(lesson.updatedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '';
    const progress = getLessonProgressLabel(lesson.id);
    return `
      <article class="lesson-library-card" data-lesson-id="${escapeAttribute(lesson.id)}" data-progress-status="${escapeAttribute(progress.status)}">
        <button class="lesson-card-open" type="button" data-lesson-open="${escapeAttribute(lesson.id)}" aria-label="Open ${escapeAttribute(lesson.title)}">
          <div class="lesson-card-cover">
            <span class="lesson-card-number">${escapeHTML(String(lesson.order).padStart(2, '0'))}</span>
            <span class="lesson-card-pdf">PDF</span>
            <span class="lesson-card-book" aria-hidden="true">📘</span>
          </div>
          <div class="lesson-card-content">
            <span class="lesson-card-term">${escapeHTML(lessonTermLabel(lesson.term))} · Lesson ${escapeHTML(String(lesson.order))}</span>
            <h3>${escapeHTML(lesson.title)}</h3>
            <p>${escapeHTML(lesson.description || 'Open this PDF lesson to read and review the topic.')}</p>
            <div class="lesson-card-meta">
              <span>${size || 'PDF lesson'}</span>
              <span>${date || 'Ready to view'}</span>
            </div>
            <div class="lesson-card-progress" data-status="${escapeAttribute(progress.status)}">
              <div class="lesson-progress-track" aria-hidden="true"><span style="width:${Math.max(0, Math.min(100, progress.percent))}%"></span></div>
              <span>${escapeHTML(progress.label)} · ${escapeHTML(progress.detail)}</span>
            </div>
            <span class="lesson-card-cta">${progress.status === 'in-progress' ? 'Continue lesson' : (progress.status === 'completed' ? 'Review lesson' : 'Read lesson')} <b aria-hidden="true">→</b></span>
          </div>
        </button>
      </article>`;
  }).join('');
  setLessonLibraryStatus(`${lessons.length} lesson${lessons.length === 1 ? '' : 's'} in ${lessonTermLabel(lessonLibraryState.activeTerm)}.`, 'success');
}

async function loadLessonLibrary(options = {}) {
  if (lessonLibraryState.loading) return lessonLibraryState.lessons;
  if (lessonLibraryState.loaded && !options.force) {
    renderStudentLessonLibrary();
    renderAdminLessonList();
    return lessonLibraryState.lessons;
  }
  lessonLibraryState.loading = true;
  setLessonLibraryStatus('Loading lessons...', 'loading');
  if (lessonAdminListStatus) lessonAdminListStatus.textContent = 'Loading lessons...';
  if (!options.force && !lessonLibraryState.loaded) {
    const cached = loadLessonLibraryCache();
    if (cached.length) {
      lessonLibraryState.lessons = cached;
      lessonLibraryState.loaded = true;
      renderStudentLessonLibrary();
      renderAdminLessonList();
      setLessonLibraryStatus('Showing saved lessons · refreshing in background...', 'warning');
    }
  }
  try {
    const ready = await initFirebaseSync();
    if (!ready) throw new Error(firebaseSync.lastError || 'Could not connect to Firebase.');
    const rootDoc = await withTimeout(readCloudActivitiesDocument(options), APP_NETWORK_TIMEOUT_MS, 'Lesson list took too long to load. Check the connection and try again.');
    const data = rootDoc.exists ? rootDoc.data : {};
    lessonLibraryState.lessons = (Array.isArray(data.lessons) ? data.lessons : []).map((lesson, index) => normalizeLesson(lesson, index));
    lessonLibraryState.loaded = true;
    saveLessonLibraryCache();
    renderStudentLessonLibrary();
    renderAdminLessonList();
    return lessonLibraryState.lessons;
  } catch (error) {
    console.warn('Could not load lesson library.', error);
    const cached = loadLessonLibraryCache();
    if (cached.length) {
      lessonLibraryState.lessons = cached;
      lessonLibraryState.loaded = true;
      renderStudentLessonLibrary();
      renderAdminLessonList();
      setLessonLibraryStatus(`Offline lesson list · ${cached.length} saved item${cached.length === 1 ? '' : 's'}. Reconnect to open PDFs.`, 'warning');
      return cached;
    }
    lessonLibraryState.lessons = [];
    renderStudentLessonLibrary();
    renderAdminLessonList();
    setLessonLibraryStatus(error?.message || 'Could not load lessons.', 'error');
    return [];
  } finally {
    lessonLibraryState.loading = false;
  }
}

async function saveLessonLibraryToCloud() {
  if (!isTeacherAuthenticated()) throw new Error('Log in as teacher before publishing lessons.');
  const ready = await initFirebaseSync();
  if (!ready) throw new Error(firebaseSync.lastError || 'Firebase is not ready.');
  const { setDoc, serverTimestamp } = firebaseSync.modules;
  const lessons = lessonLibraryState.lessons.map((lesson, index) => normalizeLesson(lesson, index));
  await withTimeout(setDoc(getCloudActivitiesDocRef(), {
    lessons,
    lessonLibraryUpdatedAt: serverTimestamp()
  }, { merge: true }), APP_NETWORK_TIMEOUT_MS, 'Publishing lessons took too long. Check the connection and try again.');
  clearSelectiveFirestoreCache('rootDocument:');
  lessonLibraryState.lessons = lessons;
  lessonLibraryState.loaded = true;
  saveLessonLibraryCache();
  renderStudentLessonLibrary();
  renderAdminLessonList();
  return true;
}

async function openLessonLibrary(origin = 'dashboard') {
  const openedFromEntry = origin === 'entry';
  if (!appSession.student && appSession.mode !== 'guest') {
    if (!openedFromEntry) {
      openStudentLogin();
      return;
    }
    appSession.mode = 'guest';
  }
  lessonLibraryState.returnView = openedFromEntry ? 'entry' : (origin === 'editor' ? 'editor' : 'dashboard');
  closeStudentAccountMenu();
  closeLessonPdfViewer();
  hideEntryGate();
  studentDashboard?.classList.add('hidden');
  document.body.classList.remove('student-dashboard-active');
  document.body.classList.add('lesson-viewer-active');
  lessonViewerScreen?.classList.remove('hidden');
  queueStudentPresenceUpdate({ currentView: 'lesson_library', activityGroup: 'Lesson Viewer', activityLabel: 'Browsing lessons' }, { force: true });
  await loadLessonLibrary({ force: !lessonLibraryState.loaded });
  window.setTimeout(() => lessonLibrarySearch?.focus({ preventScroll: true }), 60);
}

function closeLessonLibrary() {
  closeLessonPdfViewer();
  lessonViewerScreen?.classList.add('hidden');
  document.body.classList.remove('lesson-viewer-active');
  if (lessonLibraryState.returnView === 'entry') {
    if (appSession.mode === 'guest' && !appSession.currentProjectId) {
      appSession.mode = 'entry';
      updateAppHeaderForSession();
    }
    showEntryGate();
  } else if (lessonLibraryState.returnView === 'dashboard' && appSession.student) {
    showStudentDashboard();
  } else if (appSession.currentProjectId) {
    queueStudentPresenceUpdate({
      currentView: 'editor',
      activityGroup: 'Coding',
      activityLabel: `Coding: ${appSession.currentProject?.name || 'Project'}`,
      projectId: appSession.currentProjectId,
      projectName: appSession.currentProject?.name || 'Project'
    }, { force: true });
  }
}

function openLessonPdfViewer(lessonId = '') {
  finishCurrentLessonReadingSession();
  const lesson = lessonLibraryState.lessons.find(item => item.id === lessonId);
  if (!lesson || !lesson.previewUrl) {
    appAlert('This lesson has no valid PDF link yet.', { title: 'Lesson unavailable', danger: true });
    return;
  }
  const currentProgress = getLessonProgress(lesson.id);
  updateLessonProgress(lesson.id, {
    startedAt: currentProgress.startedAt || Date.now(),
    lastOpenedAt: Date.now(),
    openCount: Math.max(0, Number(currentProgress.openCount || 0)) + 1
  });
  lessonLibraryState.currentLessonId = lesson.id;
  lessonLibraryState.currentLessonOpenedAt = Date.now();
  queueStudentPresenceUpdate({
    currentView: 'lesson_pdf',
    activityGroup: 'Reading Lesson',
    activityLabel: `Reading: ${lesson.title}`,
    lessonId: lesson.id,
    lessonTitle: lesson.title
  }, { force: true });
  renderStudentLessonLibrary();
  if (lessonPdfTerm) lessonPdfTerm.textContent = `${lessonTermLabel(lesson.term)} · Lesson ${lesson.order}`;
  if (lessonPdfTitle) lessonPdfTitle.textContent = lesson.title;
  if (lessonPdfDescription) lessonPdfDescription.textContent = lesson.description || lesson.fileName || 'PDF lesson';
  if (lessonPdfOpenBtn) lessonPdfOpenBtn.href = lesson.openUrl || lesson.previewUrl;
  if (lessonPdfDownloadBtn) {
    lessonPdfDownloadBtn.href = lesson.downloadUrl || lesson.openUrl || lesson.previewUrl;
    lessonPdfDownloadBtn.classList.toggle('hidden', !(lesson.downloadUrl || lesson.openUrl));
  }
  syncLessonPdfProgressUi(lesson.id);
  lessonPdfLoading?.classList.remove('hidden', 'lesson-pdf-load-warning');
  if (lessonPdfLoading) lessonPdfLoading.innerHTML = '<span class="lesson-loading-spinner" aria-hidden="true"></span><strong>Opening PDF lesson...</strong><small>Large files may take a moment on slower connections.</small>';
  lessonPdfOverlay?.classList.remove('hidden');
  document.body.classList.add('lesson-pdf-open');
  window.clearTimeout(lessonLibraryState.pdfLoadTimer);
  loadLessonPdfFrame(lesson.previewUrl);
  lessonLibraryState.pdfLoadTimer = window.setTimeout(() => {
    if (!lessonPdfLoading || lessonPdfLoading.classList.contains('hidden')) return;
    lessonPdfLoading.classList.add('lesson-pdf-load-warning');
    lessonPdfLoading.innerHTML = '<span aria-hidden="true">⏳</span><strong>The PDF is still loading.</strong><small>Check your connection or use the Open button above.</small>';
  }, 12000);
}

function getLessonPdfFullscreenElement() {
  return document.fullscreenElement || document.webkitFullscreenElement || null;
}

function isLessonPdfFullscreen() {
  return getLessonPdfFullscreenElement() === lessonPdfCard;
}

function isDesktopLessonPdfFullscreen() {
  return isLessonPdfFullscreen() && Boolean(window.matchMedia?.('(hover: hover) and (pointer: fine)').matches);
}

function clearLessonPdfControlsTimer() {
  window.clearTimeout(lessonLibraryState.pdfControlsTimer);
  lessonLibraryState.pdfControlsTimer = null;
}

function hideLessonPdfFullscreenControls() {
  clearLessonPdfControlsTimer();
  if (!isDesktopLessonPdfFullscreen() || !lessonPdfCard) return;
  if (lessonPdfHeader?.contains(document.activeElement)) {
    lessonLibraryState.pdfControlsTimer = window.setTimeout(hideLessonPdfFullscreenControls, 1200);
    return;
  }
  lessonPdfCard.classList.add('lesson-controls-hidden');
}

function showLessonPdfFullscreenControls(options = {}) {
  clearLessonPdfControlsTimer();
  lessonPdfCard?.classList.remove('lesson-controls-hidden');
  if (!isDesktopLessonPdfFullscreen() || options.keepVisible) return;
  lessonLibraryState.pdfControlsTimer = window.setTimeout(hideLessonPdfFullscreenControls, 2500);
}

function syncLessonPdfFullscreenUi() {
  const active = isLessonPdfFullscreen();
  lessonPdfCard?.classList.toggle('lesson-native-fullscreen', active);
  if (lessonPdfFullscreenBtn) lessonPdfFullscreenBtn.textContent = active ? '⛶ Exit Fullscreen' : '⛶ Fullscreen';
  if (active) showLessonPdfFullscreenControls();
  else {
    clearLessonPdfControlsTimer();
    lessonPdfCard?.classList.remove('lesson-controls-hidden');
  }
}

function closeLessonPdfViewer() {
  finishCurrentLessonReadingSession();
  lessonLibraryState.currentLessonId = '';
  window.clearTimeout(lessonLibraryState.pdfLoadTimer);
  clearLessonPdfControlsTimer();
  lessonPdfOverlay?.classList.add('hidden');
  document.body.classList.remove('lesson-pdf-open');
  lessonPdfCard?.classList.remove('lesson-controls-hidden', 'lesson-native-fullscreen');
  resetLessonPdfFrame({ hard: true });
  if (!lessonViewerScreen?.classList.contains('hidden')) {
    queueStudentPresenceUpdate({ currentView: 'lesson_library', activityGroup: 'Lesson Viewer', activityLabel: 'Browsing lessons' }, { force: true });
  }
  if (isLessonPdfFullscreen()) {
    const exitFullscreen = document.exitFullscreen || document.webkitExitFullscreen;
    if (exitFullscreen) Promise.resolve(exitFullscreen.call(document)).catch(() => {});
  }
}

async function toggleLessonPdfFullscreen() {
  try {
    if (isLessonPdfFullscreen()) {
      const exitFullscreen = document.exitFullscreen || document.webkitExitFullscreen;
      if (exitFullscreen) await exitFullscreen.call(document);
      return;
    }
    const requestFullscreen = lessonPdfCard?.requestFullscreen || lessonPdfCard?.webkitRequestFullscreen;
    if (requestFullscreen) await requestFullscreen.call(lessonPdfCard);
  } catch (error) {
    console.warn('Lesson fullscreen unavailable.', error);
  }
}

function updateLessonDriveSetupUI() {
  const clientId = String(window.MCS_GOOGLE_DRIVE_CLIENT_ID || '').trim();
  const connected = Boolean(lessonLibraryState.driveAccessToken && lessonLibraryState.driveTokenExpiresAt > Date.now() + 30000);
  lessonDriveSetupNotice?.classList.toggle('drive-ready', Boolean(clientId));
  lessonDriveSetupNotice?.classList.toggle('drive-connected', connected);
  if (lessonDriveSetupText) {
    lessonDriveSetupText.textContent = clientId
      ? 'Direct upload is configured. Connect your Google Drive when you are ready to upload or replace a PDF.'
      : 'Add a free Google OAuth Client ID in firebase-config.js to enable direct PDF upload. You can already use Paste PDF/Drive Link below.';
  }
  if (lessonDriveConnectBtn) {
    lessonDriveConnectBtn.disabled = !clientId;
    lessonDriveConnectBtn.textContent = connected ? 'Drive Connected ✓' : (clientId ? 'Connect Google Drive' : 'Setup Required');
  }
  if (!clientId) setLessonDriveStatus('Direct upload needs the one-time free Google Drive setup. Paste-link publishing is ready now.', 'warning');
  else if (connected) setLessonDriveStatus('Google Drive connected for this browser tab. PDF uploads are ready.', 'success');
}

function loadGoogleIdentityServices() {
  if (window.google?.accounts?.oauth2) return Promise.resolve(true);
  if (loadGoogleIdentityServices.promise) return loadGoogleIdentityServices.promise;
  loadGoogleIdentityServices.promise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-mcs-google-identity]');
    if (existing) {
      existing.addEventListener('load', () => resolve(true), { once: true });
      existing.addEventListener('error', () => reject(new Error('Google login library could not load.')), { once: true });
      return;
    }
    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;
    script.dataset.mcsGoogleIdentity = '1';
    script.onload = () => resolve(true);
    script.onerror = () => reject(new Error('Google login library could not load. Check the connection.'));
    document.head.appendChild(script);
  });
  return loadGoogleIdentityServices.promise;
}

async function connectLessonGoogleDrive(options = {}) {
  const clientId = String(window.MCS_GOOGLE_DRIVE_CLIENT_ID || '').trim();
  if (!clientId) throw new Error('Google Drive direct upload is not configured yet. Follow GOOGLE_DRIVE_LESSON_SETUP.md or use Paste PDF/Drive Link.');
  if (!isTeacherAuthenticated()) throw new Error('Log in as teacher before connecting Google Drive.');
  if (lessonLibraryState.driveAccessToken && lessonLibraryState.driveTokenExpiresAt > Date.now() + 30000 && !options.force) return lessonLibraryState.driveAccessToken;
  await loadGoogleIdentityServices();
  return new Promise((resolve, reject) => {
    try {
      if (!lessonLibraryState.driveTokenClient) {
        lessonLibraryState.driveTokenClient = window.google.accounts.oauth2.initTokenClient({
          client_id: clientId,
          scope: LESSON_GOOGLE_DRIVE_SCOPE,
          callback: () => {}
        });
      }
      lessonLibraryState.driveTokenClient.callback = response => {
        if (response?.error) {
          reject(new Error(response.error_description || response.error));
          return;
        }
        lessonLibraryState.driveAccessToken = response.access_token || '';
        lessonLibraryState.driveTokenExpiresAt = Date.now() + Math.max(60, Number(response.expires_in || 3600)) * 1000;
        updateLessonDriveSetupUI();
        resolve(lessonLibraryState.driveAccessToken);
      };
      lessonLibraryState.driveTokenClient.requestAccessToken({ prompt: options.force ? 'consent' : '' });
    } catch (error) {
      reject(error);
    }
  });
}

async function googleDriveFetch(url, options = {}) {
  let token = await connectLessonGoogleDrive();
  const request = async accessToken => fetch(url, {
    ...options,
    headers: {
      ...(options.headers || {}),
      Authorization: `Bearer ${accessToken}`
    }
  });
  let response = await request(token);
  if (response.status === 401) {
    lessonLibraryState.driveAccessToken = '';
    lessonLibraryState.driveTokenExpiresAt = 0;
    token = await connectLessonGoogleDrive({ force: true });
    response = await request(token);
  }
  if (!response.ok) {
    let detail = '';
    try {
      const payload = await response.json();
      detail = payload?.error?.message || payload?.error_description || '';
    } catch (_) {
      detail = await response.text().catch(() => '');
    }
    throw new Error(detail || `Google Drive request failed (${response.status}).`);
  }
  if (response.status === 204) return null;
  return response.json();
}

async function uploadLessonPdfToGoogleDrive(file) {
  if (!(file instanceof File) || !file.name) throw new Error('Choose a PDF file first.');
  const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);
  if (!isPdf) throw new Error('Only PDF files can be uploaded as lessons.');
  const boundary = `mcsian_lesson_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const metadata = {
    name: file.name,
    mimeType: 'application/pdf',
    description: 'Uploaded from ICT 8 Connect Lesson Manager',
    appProperties: { mcsianLessonViewer: 'true' }
  };
  const body = new Blob([
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n`,
    JSON.stringify(metadata),
    `\r\n--${boundary}\r\nContent-Type: application/pdf\r\n\r\n`,
    file,
    `\r\n--${boundary}--`
  ], { type: `multipart/related; boundary=${boundary}` });
  const uploaded = await googleDriveFetch(`${LESSON_GOOGLE_UPLOAD_BASE}/files?uploadType=multipart&fields=id,name,mimeType,size,webViewLink`, {
    method: 'POST',
    headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
    body
  });
  if (!uploaded?.id) throw new Error('Google Drive did not return a file ID.');
  try {
    await googleDriveFetch(`${LESSON_GOOGLE_API_BASE}/files/${encodeURIComponent(uploaded.id)}/permissions?fields=id`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'anyone', role: 'reader' })
    });
  } catch (error) {
    await googleDriveFetch(`${LESSON_GOOGLE_API_BASE}/files/${encodeURIComponent(uploaded.id)}`, { method: 'DELETE' }).catch(() => {});
    throw new Error(`The PDF uploaded, but Google Drive could not make it public. ${error?.message || ''}`.trim());
  }
  return {
    fileId: uploaded.id,
    fileName: uploaded.name || file.name,
    fileSize: Number(uploaded.size || file.size || 0),
    ...buildGoogleDriveLessonUrls(uploaded.id),
    source: 'google-drive-upload'
  };
}

async function deleteLessonDriveFile(fileId = '') {
  const id = String(fileId || '').trim();
  if (!id) return false;
  await googleDriveFetch(`${LESSON_GOOGLE_API_BASE}/files/${encodeURIComponent(id)}`, { method: 'DELETE' });
  return true;
}

function setLessonSourceMode(mode = 'upload') {
  lessonLibraryState.sourceMode = mode === 'link' ? 'link' : 'upload';
  lessonFileSourceTabs.forEach(button => {
    const active = button.dataset.lessonSource === lessonLibraryState.sourceMode;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  lessonUploadSourcePanel?.classList.toggle('hidden', lessonLibraryState.sourceMode !== 'upload');
  lessonUploadSourcePanel?.classList.toggle('active', lessonLibraryState.sourceMode === 'upload');
  lessonLinkSourcePanel?.classList.toggle('hidden', lessonLibraryState.sourceMode !== 'link');
  lessonLinkSourcePanel?.classList.toggle('active', lessonLibraryState.sourceMode === 'link');
}

function getNextLessonOrder(term = lessonAdminTerm?.value || 'term1') {
  const orders = lessonLibraryState.lessons.filter(lesson => lesson.term === term).map(lesson => Number(lesson.order || 0));
  return Math.max(0, ...orders) + 1;
}

function resetLessonAdminEditor(options = {}) {
  lessonLibraryState.editingId = '';
  if (lessonAdminTitle) lessonAdminTitle.value = '';
  if (lessonAdminDescription) lessonAdminDescription.value = '';
  if (lessonAdminTerm && !options.keepTerm) lessonAdminTerm.value = 'term1';
  if (lessonAdminOrder) lessonAdminOrder.value = String(getNextLessonOrder(lessonAdminTerm?.value || 'term1'));
  if (lessonAdminFile) lessonAdminFile.value = '';
  if (lessonAdminFileName) lessonAdminFileName.textContent = 'Choose a PDF file';
  if (lessonAdminUrl) lessonAdminUrl.value = '';
  lessonAdminCancelEditBtn?.classList.add('hidden');
  if (lessonEditorModeBadge) lessonEditorModeBadge.textContent = 'New Lesson';
  if (lessonEditorHeading) lessonEditorHeading.textContent = 'Add a PDF Lesson';
  if (lessonAdminPublishBtn) lessonAdminPublishBtn.textContent = 'Publish Lesson';
  setLessonAdminStatus('Ready to add a lesson.');
}

function editLessonAdmin(lessonId = '') {
  const lesson = lessonLibraryState.lessons.find(item => item.id === lessonId);
  if (!lesson) return;
  lessonLibraryState.editingId = lesson.id;
  if (lessonAdminTitle) lessonAdminTitle.value = lesson.title;
  if (lessonAdminTerm) lessonAdminTerm.value = lesson.term;
  if (lessonAdminOrder) lessonAdminOrder.value = String(lesson.order);
  if (lessonAdminDescription) lessonAdminDescription.value = lesson.description;
  if (lessonAdminUrl) lessonAdminUrl.value = lesson.openUrl || lesson.previewUrl;
  if (lessonAdminFile) lessonAdminFile.value = '';
  if (lessonAdminFileName) lessonAdminFileName.textContent = lesson.fileName ? `Keep current: ${lesson.fileName}` : 'Choose a replacement PDF';
  setLessonSourceMode('link');
  lessonAdminCancelEditBtn?.classList.remove('hidden');
  if (lessonEditorModeBadge) lessonEditorModeBadge.textContent = 'Editing Lesson';
  if (lessonEditorHeading) lessonEditorHeading.textContent = lesson.title;
  if (lessonAdminPublishBtn) lessonAdminPublishBtn.textContent = 'Save Changes';
  setLessonAdminStatus('Edit the details. Paste the same link to keep the current PDF, or choose Upload PDF to replace it.', 'warning');
  document.getElementById('lessonManagerAdmin')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  window.setTimeout(() => lessonAdminTitle?.focus({ preventScroll: true }), 300);
}

function getAdminFilteredLessons() {
  const term = lessonAdminTermFilter?.value || 'all';
  const search = String(lessonAdminSearch?.value || '').trim().toLowerCase();
  return sortLessonsForDisplay(lessonLibraryState.lessons.filter(lesson => {
    if (term !== 'all' && lesson.term !== term) return false;
    if (!search) return true;
    return `${lesson.title} ${lesson.description} ${lesson.fileName}`.toLowerCase().includes(search);
  }), 'order-asc').sort((a, b) => Object.keys(LESSON_TERMS).indexOf(a.term) - Object.keys(LESSON_TERMS).indexOf(b.term) || a.order - b.order);
}

function renderAdminLessonList() {
  updateLessonDriveSetupUI();
  if (!lessonAdminList) return;
  const lessons = getAdminFilteredLessons();
  if (lessonAdminListStatus) lessonAdminListStatus.textContent = lessonLibraryState.loaded
    ? `${lessons.length} of ${lessonLibraryState.lessons.length} lesson${lessonLibraryState.lessons.length === 1 ? '' : 's'} shown.`
    : 'Lesson list is not loaded yet.';
  if (!lessons.length) {
    lessonAdminList.innerHTML = '<div class="lesson-admin-empty"><span aria-hidden="true">📚</span><strong>No lessons found</strong><p>Add the first PDF lesson using the form.</p></div>';
    return;
  }
  lessonAdminList.innerHTML = lessons.map(lesson => `
    <article class="lesson-admin-row" data-admin-lesson-id="${escapeAttribute(lesson.id)}">
      <div class="lesson-admin-order">${escapeHTML(String(lesson.order))}</div>
      <div class="lesson-admin-row-main">
        <div class="lesson-admin-row-title">
          <span>${escapeHTML(lessonTermLabel(lesson.term))}</span>
          <strong>${escapeHTML(lesson.title)}</strong>
        </div>
        <p>${escapeHTML(lesson.description || lesson.fileName || 'PDF lesson')}</p>
        <small>${escapeHTML(lesson.fileName || (lesson.fileId ? 'Google Drive PDF' : 'Linked PDF'))}${lesson.fileSize ? ` · ${escapeHTML(formatLessonFileSize(lesson.fileSize))}` : ''}</small>
      </div>
      <div class="lesson-admin-row-actions">
        <button class="ghost-btn" type="button" data-lesson-admin-action="up" title="Move up">↑</button>
        <button class="ghost-btn" type="button" data-lesson-admin-action="down" title="Move down">↓</button>
        <button class="ghost-btn" type="button" data-lesson-admin-action="view">View</button>
        <button class="ghost-btn" type="button" data-lesson-admin-action="edit">Edit</button>
        <button class="ghost-btn danger" type="button" data-lesson-admin-action="delete">Delete</button>
      </div>
    </article>`).join('');
}

async function publishLessonFromAdmin() {
  if (!isTeacherAuthenticated()) {
    setLessonAdminStatus('Log in as teacher before publishing lessons.', 'error');
    return;
  }
  const title = String(lessonAdminTitle?.value || '').trim();
  const description = String(lessonAdminDescription?.value || '').trim();
  const term = Object.prototype.hasOwnProperty.call(LESSON_TERMS, lessonAdminTerm?.value) ? lessonAdminTerm.value : 'term1';
  const order = Math.max(1, Math.min(999, Number.parseInt(lessonAdminOrder?.value, 10) || getNextLessonOrder(term)));
  if (!title) {
    setLessonAdminStatus('Enter the lesson title first.', 'error');
    lessonAdminTitle?.focus();
    return;
  }
  const existing = lessonLibraryState.lessons.find(lesson => lesson.id === lessonLibraryState.editingId) || null;
  let fileData = existing ? {
    fileId: existing.fileId,
    fileName: existing.fileName,
    fileSize: existing.fileSize,
    previewUrl: existing.previewUrl,
    openUrl: existing.openUrl,
    downloadUrl: existing.downloadUrl,
    source: existing.source
  } : null;
  let newlyUploadedFileId = '';
  lessonAdminPublishBtn.disabled = true;
  const oldButtonText = lessonAdminPublishBtn.textContent;
  try {
    if (lessonLibraryState.sourceMode === 'upload') {
      const file = lessonAdminFile?.files?.[0];
      if (file) {
        setLessonAdminStatus('Uploading PDF to your Google Drive...', 'loading');
        fileData = await uploadLessonPdfToGoogleDrive(file);
        newlyUploadedFileId = fileData.fileId;
      } else if (!existing) {
        throw new Error('Choose a PDF file, or use Paste PDF / Drive Link.');
      }
    } else {
      const url = String(lessonAdminUrl?.value || '').trim();
      if (url) fileData = { ...fileData, ...normalizeLessonSourceUrl(url), fileName: fileData?.fileName || '' };
      else if (!existing) throw new Error('Paste a public PDF or Google Drive link first.');
    }
    if (!fileData?.previewUrl) throw new Error('The lesson needs a valid PDF file or link.');
    const now = new Date().toISOString();
    const record = normalizeLesson({
      ...(existing || {}),
      ...fileData,
      id: existing?.id || `lesson-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      title,
      description,
      term,
      order,
      uploadedAt: existing?.uploadedAt || now,
      updatedAt: now
    });
    if (existing) lessonLibraryState.lessons = lessonLibraryState.lessons.map(lesson => lesson.id === existing.id ? record : lesson);
    else lessonLibraryState.lessons.push(record);
    setLessonAdminStatus('Publishing lesson list to Firebase...', 'loading');
    await saveLessonLibraryToCloud();
    if (existing?.fileId && newlyUploadedFileId && existing.fileId !== newlyUploadedFileId) {
      deleteLessonDriveFile(existing.fileId).catch(error => console.warn('Old Drive lesson file was not deleted.', error));
    }
    resetLessonAdminEditor({ keepTerm: true });
    setLessonAdminStatus(existing ? 'Lesson updated successfully.' : 'Lesson published successfully.', 'success');
    setStatus(existing ? 'Lesson updated' : 'Lesson published');
  } catch (error) {
    console.error('Could not publish lesson.', error);
    if (newlyUploadedFileId) deleteLessonDriveFile(newlyUploadedFileId).catch(() => {});
    setLessonAdminStatus(error?.message || 'Could not publish the lesson.', 'error');
  } finally {
    lessonAdminPublishBtn.disabled = false;
    lessonAdminPublishBtn.textContent = lessonLibraryState.editingId ? 'Save Changes' : (oldButtonText || 'Publish Lesson');
  }
}

async function moveLessonWithinTerm(lessonId, direction) {
  const target = lessonLibraryState.lessons.find(lesson => lesson.id === lessonId);
  if (!target) return;
  const termLessons = sortLessonsForDisplay(lessonLibraryState.lessons.filter(lesson => lesson.term === target.term), 'order-asc');
  const index = termLessons.findIndex(lesson => lesson.id === lessonId);
  const swapIndex = direction === 'up' ? index - 1 : index + 1;
  if (index < 0 || swapIndex < 0 || swapIndex >= termLessons.length) return;
  const other = termLessons[swapIndex];
  const currentOrder = target.order;
  target.order = other.order;
  other.order = currentOrder;
  if (target.order === other.order) {
    termLessons.forEach((lesson, itemIndex) => { lesson.order = itemIndex + 1; });
  }
  try {
    setLessonAdminStatus('Saving lesson order...', 'loading');
    await saveLessonLibraryToCloud();
    setLessonAdminStatus('Lesson order updated.', 'success');
  } catch (error) {
    setLessonAdminStatus(error?.message || 'Could not save lesson order.', 'error');
    await loadLessonLibrary({ force: true });
  }
}

async function deleteLessonFromAdmin(lessonId = '') {
  const lesson = lessonLibraryState.lessons.find(item => item.id === lessonId);
  if (!lesson) return;
  const confirmed = await appConfirm(`Delete “${lesson.title}” from the Lesson Viewer?`, {
    title: 'Delete Lesson',
    confirmText: 'Delete Lesson',
    danger: true
  });
  if (!confirmed) return;
  const previous = [...lessonLibraryState.lessons];
  lessonLibraryState.lessons = previous.filter(item => item.id !== lessonId);
  try {
    setLessonAdminStatus('Deleting lesson...', 'loading');
    await saveLessonLibraryToCloud();
    let driveMessage = '';
    if (lesson.fileId && lessonLibraryState.driveAccessToken) {
      try {
        await deleteLessonDriveFile(lesson.fileId);
        driveMessage = ' The PDF was also removed from Google Drive.';
      } catch (error) {
        driveMessage = ' The library entry was removed, but the Drive file remains.';
        console.warn('Could not delete Drive file.', error);
      }
    } else if (lesson.fileId) {
      driveMessage = ' Reconnect Google Drive later if you also want to delete the original Drive file.';
    }
    if (lessonLibraryState.editingId === lessonId) resetLessonAdminEditor();
    setLessonAdminStatus(`Lesson deleted.${driveMessage}`, 'success');
  } catch (error) {
    lessonLibraryState.lessons = previous;
    renderAdminLessonList();
    setLessonAdminStatus(error?.message || 'Could not delete the lesson.', 'error');
  }
}

function initializeLessonManager() {
  updateLessonDriveSetupUI();
  if (lessonAdminOrder && !lessonAdminOrder.value) lessonAdminOrder.value = '1';
  if (!lessonLibraryState.loaded) loadLessonLibrary().catch(error => console.warn('Lesson manager load failed.', error));
  else renderAdminLessonList();
}

function getStoredAdminTab() {
  return localStorage.getItem(ADMIN_TAB_STORAGE_KEY) || 'students';
}

function setAdminTab(tabName = 'students') {
  const allowed = new Set(['students', 'online', 'assistance', 'compliance', 'lessons', 'activities']);
  const nextTab = allowed.has(tabName) ? tabName : 'students';
  localStorage.setItem(ADMIN_TAB_STORAGE_KEY, nextTab);

  adminTabButtons.forEach(button => {
    const isActive = button.dataset.adminTab === nextTab;
    button.classList.toggle('active', isActive);
    button.setAttribute('aria-selected', isActive ? 'true' : 'false');
  });

  adminTabPanels.forEach(panel => {
    const isActive = panel.dataset.adminPanel === nextTab;
    panel.classList.toggle('active', isActive);
  });

  if (nextTab === 'compliance' && isTeacherAuthenticated() && adminComplianceViewerRecords.length === 0) {
    loadAdminComplianceViewer({ silent: true }).catch(error => console.warn('Compliance viewer auto-load failed.', error));
  }
  if (nextTab === 'online' && isTeacherAuthenticated()) {
    loadAdminOnlinePresence({ silent: true }).catch(error => console.warn('Online presence auto-load failed.', error));
  } else {
    scheduleAdminOnlinePresenceRefresh();
  }
  if (nextTab === 'lessons' && isTeacherAuthenticated()) initializeLessonManager();
}

function initAdminTabs() {
  adminTabButtons.forEach(button => {
    if (button.dataset.adminTabBound === '1') return;
    button.dataset.adminTabBound = '1';
    button.addEventListener('click', () => setAdminTab(button.dataset.adminTab || 'students'));
  });
  setAdminTab(getStoredAdminTab());
}

async function openAdminPanel() {
  document.body.classList.add('admin-open');
  adminOverlay.classList.remove('hidden');
  initAdminTabs();
  syncAssistanceSettingsControls();
  syncComplianceSettingsControls();
  updateAssistancePublishUI();
  syncAiRubricSettingsControls(aiRubricSettings);
  if (isTeacherAuthenticated()) loadAiRubricSettingsFromCloud({ silent: true }).catch(error => console.warn('Smart Review settings load failed.', error));
  setAssistanceSettingsStatus(isTeacherAuthenticated()
    ? 'Change the switches, then publish to update every student device.'
    : 'These switches can be used now on this browser. Login is only needed to publish globally.');
  const adminFirebaseReady = await initFirebaseSync();
  if (!adminFirebaseReady) {
    showTeacherLoginError(`Firebase is not ready. ${firebaseSync.lastError || 'Firebase SDK did not load. Check internet connection, CDN access, and make sure all updated files were uploaded.'}`);
  }
  updateTeacherLoginUI(firebaseSync.auth?.currentUser || firebaseSync.currentUser);
  if (isTeacherAuthenticated()) {
    loadComplianceSettingsFromCloud({ silent: true }).catch(error => {
      console.warn('Could not load cloud Compliance settings.', error);
      setComplianceSyncStatus(error?.message || 'Could not load cloud Compliance settings.', 'warning');
    });
  } else {
    setComplianceSyncStatus('Login as teacher to load/save Compliance settings across devices. Local browser settings may be incomplete.', 'warning');
  }

  if (isAdminPanelUnlocked()) {
    showAdminForm();
  } else {
    pinScreen.classList.remove('hidden');
    adminForm.classList.add('hidden');
    adminForm.classList.remove('visible');
    if (adminPassword) adminPassword.value = '';
    setAdminLoginMode('code');
    setTimeout(() => adminQuickCode?.focus(), 50);
  }
}

function closeAdminPanel() {
  adminOverlay.classList.add('hidden');
  window.clearTimeout(adminOnlinePresenceTimer);
  adminOnlinePresenceTimer = null;
  setAdminTab(getStoredAdminTab());
  document.body.classList.remove('admin-open');
}

function showAdminForm(activityId = adminEditingActivityId) {
  if (!isAdminPanelUnlocked()) {
    adminUnlocked = false;
    pinScreen.classList.remove('hidden');
    adminForm.classList.add('hidden');
    adminForm.classList.remove('visible');
    return;
  }

  adminUnlocked = true;
  pinScreen.classList.add('hidden');
  adminForm.classList.remove('hidden');
  adminForm.classList.add('visible');
  initAdminTabs();
  if (adminStudentsCache.length) renderAdminStudentTracker();
  else loadAdminStudents().catch(error => console.warn('Student tracker load failed.', error));
  initializeLessonManager();
  if (isTeacherAuthenticated()) loadAiRubricSettingsFromCloud({ silent: true }).catch(error => console.warn('Smart Review settings load failed.', error));
  const editActivity = getActivityById(activityId) || activity || activities[0] || null;

  if (!editActivity) {
    adminEditingActivityId = '';
    renderAdminActivitySelect();
    adminActivityTitle.value = '';
    adminActivityDescription.value = '';
    adminPassingScore.value = 75;
    renderCriteriaEditor([]);
    if (typeof initManualRubricInputTable === 'function') initManualRubricInputTable();
    setStatus('No saved activities yet');
    return;
  }

  adminEditingActivityId = editActivity.id;
  renderAdminActivitySelect();
  adminActivityTitle.value = editActivity.title;
  adminActivityDescription.value = editActivity.description;
  adminPassingScore.value = editActivity.passingScore;
  renderCriteriaEditor(editActivity.criteria);
}

function editAdminActivity(activityId) {
  const editActivity = getActivityById(activityId);
  if (!editActivity) return;
  adminEditingActivityId = editActivity.id;
  showAdminForm(editActivity.id);
}

async function loginTeacher() {
  showTeacherLoginError('');
  const ready = await initFirebaseSync();
  if (!ready || !firebaseSync.auth || !firebaseSync.authModule) {
    showTeacherLoginError(`Firebase is not ready. ${firebaseSync.lastError || 'Firebase SDK did not load. Check internet connection, CDN access, and make sure all updated files were uploaded.'}`);
    return;
  }

  const fallbackTeacherEmail = getDefaultTeacherEmail();
  const email = (adminEmail.value.trim() || fallbackTeacherEmail).trim();
  const password = adminPassword.value;
  if (adminEmail && !adminEmail.value.trim() && fallbackTeacherEmail) adminEmail.value = fallbackTeacherEmail;

  if (!email || !password) {
    showTeacherLoginError('Please enter teacher email and password.');
    return;
  }

  try {
    setTeacherLoginLoading(true);
    await protectActiveStudentWorkBeforeAuthSwitch('teacher-login');
    const { signInWithEmailAndPassword, signOut } = firebaseSync.authModule;
    const credential = await signInWithEmailAndPassword(firebaseSync.auth, email, password);
    firebaseSync.currentUser = credential.user;

    if (!isAllowedTeacherEmail(credential.user.email)) {
      await signOut(firebaseSync.auth);
      adminUnlocked = false;
      showTeacherLoginError(`This account is signed in but not allowed to manage rubrics. Allowed teacher: ${getTeacherEmailText()}.`);
      return;
    }

    adminSessionLocked = false;
    adminUnlocked = true;
    updateTeacherLoginUI(credential.user);
    showAdminForm();
    setStatus('Teacher logged in');
  } catch (error) {
    console.error('Teacher login failed', error);
    showTeacherLoginError(getFirebaseLoginErrorMessage(error));
  } finally {
    setTeacherLoginLoading(false);
  }
}

async function logoutTeacher() {
  setAdminQuickUnlocked(false);
  const ready = await initFirebaseSync();

  try {
    if (appSession.mode === 'student' && appSession.student && isTeacherAuthenticated()) {
      // A single browser Firebase Auth session cannot be both teacher and student at
      // the same time. When the teacher locks the Admin panel while a student
      // workspace is still open, keep the teacher Firebase session in the
      // background so the student project can continue saving to the same student
      // document. The Admin UI is still locked and requires the code/password again.
      persistLastStudentSession('admin-lock-with-student-session');
      adminSessionLocked = true;
      adminUnlocked = false;
      adminForm.classList.add('hidden');
      adminForm.classList.remove('visible');
      pinScreen.classList.remove('hidden');
      if (adminPassword) adminPassword.value = '';
      if (adminQuickCode) adminQuickCode.value = '';
      updateTeacherLoginUI(getFirebaseActiveUser());
      setAdminLoginMode('code');
      setStatus('Admin locked · student save session kept');
      closeAdminPanel();
      updateManualSaveControls();
      return;
    }

    if (ready && firebaseSync.auth && firebaseSync.authModule && (firebaseSync.auth.currentUser || firebaseSync.currentUser)) {
      const { signOut } = firebaseSync.authModule;
      await signOut(firebaseSync.auth);
    }
    firebaseSync.currentUser = null;
    adminSessionLocked = false;
    adminUnlocked = false;
    adminForm.classList.add('hidden');
    adminForm.classList.remove('visible');
    pinScreen.classList.remove('hidden');
    if (adminPassword) adminPassword.value = '';
    if (adminQuickCode) adminQuickCode.value = '';
    updateTeacherLoginUI(null);
    setAdminLoginMode('code');
    setStatus('Admin locked');
  } catch (error) {
    console.error('Teacher logout failed', error);
    await appAlert('Logout failed. Please try again.', { title: 'Logout failed', danger: true });
  }
}

async function unlockAdminWithCode() {
  showTeacherLoginError('');
  const ready = await initFirebaseSync();
  if (!ready || !firebaseSync.auth || !firebaseSync.authModule) {
    showTeacherLoginError(`Firebase is not ready. ${firebaseSync.lastError || 'Firebase SDK did not load. Check internet connection, CDN access, and make sure all updated files were uploaded.'}`);
    return;
  }

  const email = getDefaultTeacherEmail();
  const passwordCode = String(adminQuickCode?.value || '').trim();
  if (!email) {
    showTeacherLoginError('No teacher email is set in firebase-config.js. Add your teacher email to MCS_TEACHER_EMAILS or use Password mode.');
    return;
  }
  if (!passwordCode) {
    showTeacherLoginError('Enter the teacher account password as your Admin Code, or switch to Password mode.');
    return;
  }

  try {
    setTeacherLoginLoading(true, 'code');
    await protectActiveStudentWorkBeforeAuthSwitch('teacher-code-login');
    const { signInWithEmailAndPassword, signOut } = firebaseSync.authModule;
    const credential = await signInWithEmailAndPassword(firebaseSync.auth, email, passwordCode);
    firebaseSync.currentUser = credential.user;

    if (!isAllowedTeacherEmail(credential.user.email)) {
      await signOut(firebaseSync.auth);
      adminUnlocked = false;
      showTeacherLoginError(`This account is signed in but not allowed to manage rubrics. Allowed teacher: ${getTeacherEmailText()}.`);
      return;
    }

    adminSessionLocked = false;
    adminUnlocked = true;
    if (adminEmail) adminEmail.value = credential.user.email || email;
    updateTeacherLoginUI(credential.user);
    showAdminForm();
    setStatus('Teacher logged in');
  } catch (error) {
    console.error('Teacher code login failed', error);
    showTeacherLoginError(getFirebaseLoginErrorMessage(error));
  } finally {
    setTeacherLoginLoading(false, 'code');
  }
}

function unlockAdmin() {
  loginTeacher();
}

function renderScaleLevelCells(criterion) {
  const normalized = normalizeCriterion(criterion);
  return rubricLevels.map(level => {
    const levelData = normalized.levels[level.key] || {};
    return `
      <td class="rubric-level-cell level-${escapeAttribute(level.key)}" data-level="${escapeAttribute(level.key)}" data-label="${escapeAttribute(level.label)}">
        <label class="rubric-score-label">
          <span>Score</span>
          <input class="level-points" type="number" min="0" step="0.5" value="${escapeAttribute(formatPoints(levelData.points))}" aria-label="${escapeAttribute(level.label)} score" />
        </label>
        <textarea class="level-description" rows="4" placeholder="Describe ${escapeAttribute(level.label)} performance...">${escapeHTML(levelData.description || '')}</textarea>
      </td>
    `;
  }).join('');
}

function renderCriteriaEditor(criteria) {
  const rows = criteria.map((criterion, index) => {
    const normalized = normalizeCriterion({ ...criterion, rule: 'smart_rubric', target: '' });
    return `
      <tr class="rubric-table-row" data-id="${escapeHTML(normalized.id || createId())}">
        <td class="rubric-criterion-cell" data-label="Criterion">
          <div class="criterion-title-row">
            <span class="criterion-number">${index + 1}</span>
            <input class="criterion-title criterion-title-big" type="text" value="${escapeAttribute(normalized.title)}" placeholder="Example: Content and HTML Structure" />
          </div>

          <div class="criterion-mini-grid rubric-builder-simple-grid">
            <label>
              Max
              <input class="criterion-points" type="number" min="0" step="0.5" value="${escapeAttribute(formatPoints(normalized.points))}" />
            </label>
            <p class="helper-note criterion-help">No auto-check here. The rubric is judged later from the code, output, and level descriptions when Result/Feedback runs.</p>
          </div>

          <button class="ghost-btn danger remove-criterion" type="button" aria-label="Remove criterion ${index + 1}">Remove row</button>
        </td>
        ${renderScaleLevelCells(normalized)}
      </tr>
    `;
  }).join('');

  criteriaEditor.innerHTML = `
    <div class="rubric-table-note">
      <strong>Rubric builder:</strong> Create criteria, points, and level descriptions only. No separate checker dropdown is used here.
    </div>
    <div class="rubric-table-scroll">
      <table class="teacher-rubric-table" aria-label="Teacher rubric table input">
        <thead>
          <tr>
            <th>Criteria</th>
            ${rubricLevels.map(level => `<th>${escapeHTML(level.label)}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
    </div>
  `;
}

function collectLevelsFromCard(card, maxPoints) {
  const levels = {};
  card.querySelectorAll('.rubric-level-cell').forEach(cell => {
    const levelKey = cell.dataset.level;
    const pointsInput = cell.querySelector('.level-points');
    const descriptionInput = cell.querySelector('.level-description');
    const fallback = normalizeLevels(null, maxPoints)[levelKey];
    levels[levelKey] = {
      label: rubricLevels.find(item => item.key === levelKey)?.label || levelKey,
      points: Number(pointsInput?.value) || 0,
      description: descriptionInput?.value.trim() || fallback.description
    };
  });
  return levels;
}

function collectCriteriaFromEditor() {
  return [...criteriaEditor.querySelectorAll('.rubric-table-row')].map(row => {
    const maxPoints = Number(row.querySelector('.criterion-points').value) || 0;
    return normalizeCriterion({
      id: row.dataset.id || createId(),
      title: row.querySelector('.criterion-title').value.trim() || 'Untitled criterion',
      points: maxPoints,
      rule: 'smart_rubric',
      target: '',
      levels: collectLevelsFromCard(row, maxPoints)
    });
  }).filter(item => item.points > 0);
}

function addCriterion() {
  const currentCriteria = collectCriteriaFromEditor();
  currentCriteria.push(normalizeCriterion({
    id: createId(),
    title: 'New criterion / row',
    points: 4,
    rule: 'smart_rubric',
    target: ''
  }));
  renderCriteriaEditor(currentCriteria);
}

async function saveRubric(event) {
  event.preventDefault();

  if (!isAdminPanelUnlocked()) {
    showAdminForm();
    showTeacherLoginError('Please unlock Admin using Code or Password before saving rubric changes.');
    return;
  }

  const criteria = collectCriteriaFromEditor();

  if (!criteria.length) {
    await appAlert('Please add at least one rubric criterion.', { title: 'Rubric needed' });
    return;
  }

  const savedActivity = normalizeActivity({
    id: adminEditingActivityId || createId(),
    title: adminActivityTitle.value.trim() || `Activity ${activities.length + 1}`,
    description: adminActivityDescription.value.trim() || 'Complete the activity based on the teacher rubric.',
    passingScore: Number(adminPassingScore.value) || 75,
    criteria
  });

  const existingIndex = activities.findIndex(item => item.id === savedActivity.id);
  if (existingIndex >= 0) {
    activities[existingIndex] = savedActivity;
  } else {
    activities.push(savedActivity);
  }

  initManualRubricInputTable();
  saveActivities({ cloud: false });

  if (isTeacherAuthenticated()) {
    const cloudSaved = await saveActivitiesToCloud();
    if (!cloudSaved && hasFirebaseConfig()) {
      await appAlert('Saved locally, but Firebase rejected the online save. Check if you are logged in and if Firestore Rules were published.', { title: 'Firebase save issue', danger: true });
      return;
    }
  } else if (adminQuickUnlocked) {
    setStatus('Activity saved locally');
  }

  selectActivity(savedActivity.id, { keepLanguage: true });
  closeAdminPanel();
  setStatus(isTeacherAuthenticated() ? 'Activity saved' : 'Activity saved locally');
}

function createNewActivity() {
  adminEditingActivityId = createId();
  renderAdminActivitySelect();
  adminActivityTitle.value = '';
  adminActivityDescription.value = '';
  adminPassingScore.value = 75;
  renderCriteriaEditor([]);
  if (typeof initManualRubricInputTable === 'function') initManualRubricInputTable();
  setStatus('Blank activity form ready');
}

function duplicateActivity() {
  const source = getActivityById(adminEditingActivityId) || activity;
  if (!source) {
    appAlert('No saved activity to duplicate yet.', { title: 'Nothing to duplicate' });
    return;
  }
  const copy = normalizeActivity({
    ...clone(source),
    id: createId(),
    title: `${source.title} (Copy)`,
    criteria: source.criteria.map(criterion => normalizeCriterion({ ...criterion, id: createId() }))
  });

  activities.push(copy);
  saveActivities();
  codeByActivity[copy.id] = normalizeCodeStore(codeByActivity[source.id] || starterCode);
  saveCodeByActivity();
  selectActivity(copy.id, { skipSave: true });
  showAdminForm(copy.id);
  setStatus('Activity duplicated');
}

async function deleteActivity() {
  const activityToDelete = getActivityById(adminEditingActivityId);
  if (!activityToDelete) {
    appAlert('No saved activity selected.', { title: 'No activity selected' });
    return;
  }
  if (!await appConfirm(`Delete "${activityToDelete.title}"? Students will no longer see this activity.`, { title: 'Delete activity', danger: true, confirmText: 'Delete' })) return;

  activities = activities.filter(item => item.id !== activityToDelete.id);
  delete codeByActivity[activityToDelete.id];
  saveActivities();
  saveCodeByActivity();

  if (selectedActivityId === activityToDelete.id) {
    selectActivity('', { skipSave: true });
  }

  const nextActivity = activities[0] || null;
  showAdminForm(nextActivity?.id || '');
  setStatus('Activity deleted');
}

async function restoreDefaultRubric() {
  const existing = getActivityById(adminEditingActivityId) || activity;
  if (!existing) {
    appAlert('No saved activity selected yet. Click + New Activity or save a rubric first.', { title: 'No saved activity' });
    return;
  }
  if (!await appConfirm('Restore the default rubric for this activity?', { title: 'Restore default rubric', danger: true })) return;
  const restored = normalizeActivity({
    ...clone(defaultActivity),
    id: existing.id,
    title: existing.title || defaultActivity.title
  });

  const existingIndex = activities.findIndex(item => item.id === restored.id);
  activities[existingIndex] = restored;
  saveActivities();
  selectActivity(restored.id, { keepLanguage: true });
  showAdminForm(restored.id);
  setStatus('Default rubric restored');
}

function getRubricImageEndpoint() {
  return String(window.MCS_RUBRIC_IMAGE_ENDPOINT || '').trim();
}

function isRubricImageImportEnabled() {
  return window.MCS_RUBRIC_IMAGE_IMPORT_ENABLED !== false;
}

function setRubricImportStatus(message, type = '') {
  if (!rubricImageStatus) return;
  rubricImageStatus.textContent = message || '';
  rubricImageStatus.className = `helper-note rubric-import-status ${type}`.trim();
}

function getSelectedRubricImageFile() {
  return rubricImageInput?.files?.[0] || null;
}

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(reader.error || new Error('Could not read file.'));
    reader.readAsDataURL(file);
  });
}

function clearRubricImageImport() {
  if (rubricImageInput) rubricImageInput.value = '';
  if (rubricImagePreview) rubricImagePreview.removeAttribute('src');
  if (rubricExtractedText) rubricExtractedText.value = '';
  rubricImagePreviewWrap?.classList.add('hidden');
  setRubricImportStatus('No image selected yet.');
}

async function previewRubricImage() {
  const file = getSelectedRubricImageFile();
  if (!file) {
    clearRubricImageImport();
    return;
  }

  if (!/^image\/(png|jpe?g|webp)$/i.test(file.type)) {
    setRubricImportStatus('Please select a PNG, JPG, or WEBP image.', 'error');
    return;
  }

  if (file.size > 6 * 1024 * 1024) {
    setRubricImportStatus('Image is too large. Please use an image below 6 MB.', 'error');
    return;
  }

  const dataUrl = await readFileAsDataURL(file);
  if (rubricImagePreview) rubricImagePreview.src = dataUrl;
  rubricImagePreviewWrap?.classList.remove('hidden');
  setRubricImportStatus(`Selected: ${file.name}. Click Read Image & Fill Table.`, 'ready');
}

function normalizeImportedActivity(rawActivity) {
  const safe = rawActivity && typeof rawActivity === 'object' ? rawActivity : {};
  const rawCriteria = Array.isArray(safe.criteria) ? safe.criteria : [];
  const criteria = rawCriteria.map((criterion, index) => {
    const points = getMaxPointsFromCriterion(criterion) || Number(criterion.points) || 4;
    const levels = criterion.levels && typeof criterion.levels === 'object'
      ? criterion.levels
      : rubricLevels.reduce((acc, level) => {
          const levelText = criterion[level.key] || criterion[level.label] || '';
          acc[level.key] = {
            label: level.label,
            points: defaultLevelPoints(points)[level.key],
            description: String(levelText || defaultLevelDescriptions[level.key] || '').trim()
          };
          return acc;
        }, {});

    return normalizeCriterion({
      id: createId(),
      title: criterion.title || criterion.criterion || criterion.name || `Criterion ${index + 1}`,
      points,
      rule: 'smart_rubric',
      target: '',
      levels
    });
  });

  return normalizeActivity({
    id: adminEditingActivityId || createId(),
    title: safe.title || safe.activityTitle || 'Imported Rubric Activity',
    description: safe.description || safe.instructions || 'Complete the activity based on the imported rubric. Review the rubric table before saving.',
    passingScore: Number(safe.passingScore) || 75,
    criteria: criteria.length ? criteria : clone(defaultActivity.criteria).map(item => normalizeCriterion({ ...item, id: createId() }))
  });
}

function applyImportedActivityToAdminForm(importedActivity) {
  const normalized = normalizeImportedActivity(importedActivity);
  adminActivityTitle.value = normalized.title;
  adminActivityDescription.value = normalized.description;
  adminPassingScore.value = normalized.passingScore;
  renderCriteriaEditor(normalized.criteria);
  setRubricImportStatus('Rubric imported. Please review the table, then click Save Activity.', 'success');
  setStatus('Rubric imported');
}

function getFallbackRubricImportMessage() {
  return 'No online rubric reader is connected, so this app will use the built-in browser image reader. Clear screenshots work best.';
}

function loadRubricOCRLibrary() {
  if (window.Tesseract) return Promise.resolve(window.Tesseract);
  if (window.__rubricOCRPromise) return window.__rubricOCRPromise;

  window.__rubricOCRPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-mcs-rubric-ocr]');
    const script = existing || document.createElement('script');
    const timeoutId = window.setTimeout(() => {
      reject(new Error('The rubric image reader took too long to load. Check the connection and try again.'));
    }, 15000);

    const finish = (error = null) => {
      window.clearTimeout(timeoutId);
      if (error) reject(error);
      else if (window.Tesseract) resolve(window.Tesseract);
      else reject(new Error('The rubric image reader loaded incorrectly. Please try again.'));
    };

    script.addEventListener('load', () => finish(), { once: true });
    script.addEventListener('error', () => finish(new Error('Could not load the rubric image reader. Check the internet connection.')), { once: true });

    if (!existing) {
      script.dataset.mcsRubricOcr = 'true';
      script.async = true;
      script.crossOrigin = 'anonymous';
      script.referrerPolicy = 'no-referrer';
      script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
      document.head.appendChild(script);
    }
  }).catch(error => {
    window.__rubricOCRPromise = null;
    document.querySelector('script[data-mcs-rubric-ocr]')?.remove();
    throw error;
  });

  return window.__rubricOCRPromise;
}

function normalizeOCRText(text) {
  return String(text || '')
    .replace(/\r/g, '\n')
    .replace(/[|¦]/g, ' | ')
    .replace(/[•●▪■]/g, '\n- ')
    .replace(/\t+/g, ' ')
    .replace(/[ ]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeRubricLevelKey(label) {
  const value = String(label || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (value.includes('excellent')) return 'excellent';
  if (value.includes('good')) return 'good';
  if (value.includes('fair')) return 'fair';
  if (value.includes('need') && value.includes('improvement')) return 'needsImprovement';
  if (value.includes('poor') || value.includes('beginning')) return 'needsImprovement';
  return '';
}

function countRubricLevelMarkers(text) {
  return [...String(text || '').matchAll(/excellent|good|fair|needs\s*improvement/gi)].length;
}

function cleanCriterionTitle(rawTitle) {
  return String(rawTitle || '')
    .replace(/^\s*(criteria?|criterion)\s*[:\-]?\s*/i, '')
    .replace(/^\s*[-•*]?\s*\d+[.)-]?\s*/, '')
    .replace(/\(?\b\d+(?:\.\d+)?\s*(?:pts?|points?)\)?/gi, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

function extractScoreValue(text, fallback = null) {
  const source = String(text || '');
  const rangeMatch = source.match(/(\d+(?:\.\d+)?)\s*[-–/]\s*(\d+(?:\.\d+)?)/);
  if (rangeMatch) return Math.max(Number(rangeMatch[1]), Number(rangeMatch[2]));
  const pointMatch = source.match(/(?:^|\b)(\d+(?:\.\d+)?)(?:\s*(?:pts?|points?|\/\s*\d+))?/i);
  if (pointMatch) return Number(pointMatch[1]);
  return fallback;
}

function stripLeadingScoreText(text) {
  return String(text || '')
    .replace(/^\s*[(:-]*\s*(?:\d+(?:\.\d+)?\s*[-–/]\s*)?\d+(?:\.\d+)?\s*(?:pts?|points?)?\s*[):.-]*\s*/i, '')
    .replace(/^\s*[:\-–|]+\s*/, '')
    .trim();
}

function extractGlobalLevelPoints(text) {
  const defaults = {};
  rubricLevels.forEach(level => {
    const labelPattern = level.label.replace(/\s+/g, '\\s*');
    const regex = new RegExp(labelPattern + '\\s*[:\-–]?\\s*(\\d+(?:\\.\\d+)?)(?:\\s*[-–/]\\s*(\\d+(?:\\.\\d+)?))?', 'i');
    const match = String(text || '').match(regex);
    if (match) {
      const points = Math.max(Number(match[1] || 0), Number(match[2] || 0));
      if (Number.isFinite(points) && points >= 0) defaults[level.key] = points;
    }
  });
  return defaults;
}

function getGenericRubricDescription(levelKey, criterionTitle) {
  const title = criterionTitle || 'this criterion';
  if (levelKey === 'excellent') return `Excellent performance in ${title}.`;
  if (levelKey === 'good') return `Good performance in ${title}.`;
  if (levelKey === 'fair') return `Fair performance in ${title}.`;
  return `Needs improvement in ${title}.`;
}

function splitLineByRubricLevels(text) {
  const source = String(text || '');
  const regex = /(Excellent|Good|Fair|Needs\s*Improvement)/gi;
  const matches = [...source.matchAll(regex)];
  if (matches.length < 2) return null;
  const title = cleanCriterionTitle(source.slice(0, matches[0].index));
  const sections = {};
  matches.forEach((match, index) => {
    const key = normalizeRubricLevelKey(match[0]);
    if (!key) return;
    const start = match.index + match[0].length;
    const end = index < matches.length - 1 ? matches[index + 1].index : source.length;
    sections[key] = source.slice(start, end).trim(' :-|');
  });
  return { title, sections };
}

function isLikelyHeaderLine(line) {
  const text = String(line || '').toLowerCase();
  if (!text) return true;
  return (text.includes('criteria') && countRubricLevelMarkers(text) >= 2)
    || /^activity\s*title/i.test(text)
    || /^passing\s*score/i.test(text)
    || /^teacher/i.test(text)
    || /^upload\s+rubric/i.test(text);
}

function isPotentialCriterionTitle(line) {
  const text = cleanCriterionTitle(line);
  if (!text || text.length < 4) return false;
  if (isLikelyHeaderLine(text)) return false;
  if (countRubricLevelMarkers(text) >= 2) return false;
  if (/^(excellent|good|fair|needs\s*improvement)\b/i.test(text)) return false;
  return true;
}

function guessCriterionRule(criterionTitle, descriptionText = '') {
  const combinedText = `${criterionTitle} ${descriptionText}`;
  const source = combinedText.toLowerCase();
  let target = '';

  const quoted = combinedText.match(/["“”']([^"“”']{2,40})["“”']/);
  if (quoted) target = quoted[1].trim();

  const tagTarget = combinedText.match(/<([a-z0-9-]+)>/i);
  if (tagTarget) target = `<${tagTarget[1].toLowerCase()}`;

  const classOrIdTarget = combinedText.match(/(?:class|id)\s*=\s*["“”']?([a-z0-9_-]{2,40})/i);
  if (!target && classOrIdTarget) target = classOrIdTarget[1].trim();

  const cssPropertyMatch = source.match(/\b(background-color|border-radius|font-family|font-size|text-align|box-shadow|grid-template-columns|justify-content|align-items|background|padding|margin|border|display|color|width|height|gap)\b/);
  const jsKeywordMatch = source.match(/\b(addEventListener|onclick|textContent|innerHTML|classList|querySelector|getElementById|function|alert|console\.log)\b/i);

  // HTML structure and semantic tags
  if (/semantic\s+tags?|semantic\s+html|header|footer|nav|main|section|article|aside/.test(source)) {
    return { rule: 'has_semantic_tags', target: '' };
  }
  if (/(complete|full|basic|required|proper).*(html|document|structure)|doctype|<html|<head|<title|<body/.test(source)) {
    return { rule: 'full_html_structure', target: '' };
  }
  if (/closing tag|closed tag|properly closed|balance[ds]? tag|well[-\s]?organized\s+structure|correct\s+structure/.test(source)) {
    return { rule: 'balanced_html_tags', target: '' };
  }

  // Specific HTML elements
  if (/button or link|link or button|clickable/.test(source)) return { rule: 'has_button_or_link', target: '' };
  if (/heading|header\s+text|title\s+heading|\bh1\b|\bh2\b|\bh3\b/.test(source)) return { rule: 'has_heading', target };
  if (/paragraph|\bp\s*tag|\bp\b/.test(source)) return { rule: 'has_paragraph', target };
  if (/button/.test(source)) return { rule: 'has_button', target };
  if (/hyperlink|anchor|\blink\b|\ba\s*tag/.test(source)) return { rule: 'has_link', target };
  if (/image|picture|photo|\bimg\b/.test(source)) return { rule: 'has_image', target };
  if (/list|bullet|numbered|\bul\b|\bol\b|\bli\b/.test(source)) return { rule: 'has_list', target };

  // CSS/design criteria
  if (/css|style|styling|technical application|visual appeal|design|presentation|layout|aesthetic|consistent design|readability|creative|polish|color|background|font|spacing|border/.test(source)) {
    return { rule: 'uses_css_property', target: cssPropertyMatch ? cssPropertyMatch[1].toLowerCase() : '' };
  }

  // JavaScript criteria
  if (/event listener|onclick|interaction|interactive|click event|button action/.test(source)) return { rule: 'uses_event_listener', target: '' };
  if (/change(s|d)? .*page|dom|innerhtml|textcontent|classlist|style\.|setattribute|appendchild|createelement/.test(source)) return { rule: 'js_changes_page', target: '' };
  if (/javascript|script|function|variable|condition|loop/.test(source)) {
    return { rule: 'js_contains', target: jsKeywordMatch ? jsKeywordMatch[1] : target };
  }
  if (/runtime error|no error|error-free|without errors|working code/.test(source)) return { rule: 'no_runtime_error', target: '' };

  // Output/content criteria
  if (/visible text|readable content|content shown|output text|informative page|difficult to read|easy to read/.test(source)) return { rule: 'output_has_visible_text', target: '' };
  if (/output|preview|display|shows?/.test(source)) return { rule: 'output_contains', target };

  // General instructions / requirements are hard to judge automatically, so use minimum effort.
  if (/following instructions|requirements?|completed|accurately|met|expectations|incomplete|missing|effort/.test(source)) {
    return { rule: 'smart_rubric', target: '' };
  }

  if (/html|tag|element|class|id|structure/.test(source)) return { rule: 'html_contains', target };
  return { rule: 'minimum_effort', target: '' };
}

function buildCriterionFromParsedParts(title, sections, globalPoints = {}) {
  const cleanTitle = cleanCriterionTitle(title) || 'Untitled criterion';
  const explicitMax = extractScoreValue(title, null);
  const sectionScores = {};
  const descriptions = {};

  rubricLevels.forEach(level => {
    const rawText = sections[level.key] || '';
    const score = extractScoreValue(rawText, globalPoints[level.key] ?? null);
    if (Number.isFinite(score)) sectionScores[level.key] = score;
    descriptions[level.key] = stripLeadingScoreText(rawText) || getGenericRubricDescription(level.key, cleanTitle);
  });

  const maxPoints = explicitMax || Math.max(...Object.values(sectionScores).filter(Number.isFinite), 4);
  const defaults = defaultLevelPoints(maxPoints);
  const levels = rubricLevels.reduce((acc, level) => {
    acc[level.key] = {
      label: level.label,
      points: Number.isFinite(sectionScores[level.key]) ? sectionScores[level.key] : (globalPoints[level.key] ?? defaults[level.key]),
      description: descriptions[level.key]
    };
    return acc;
  }, {});

  return normalizeCriterion({
    id: createId(),
    title: cleanTitle,
    points: maxPoints,
    rule: 'smart_rubric',
    target: '',
    levels
  });
}

function parseCriteriaFromRubricTextGeneral(text) {
  const normalizedText = normalizeOCRText(text);
  const lines = normalizedText.split('\n').map(line => line.trim()).filter(Boolean);
  const globalPoints = extractGlobalLevelPoints(normalizedText);
  const criteria = [];

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (!line || isLikelyHeaderLine(line)) continue;

    const inlineSplit = splitLineByRubricLevels(line);
    if (inlineSplit && inlineSplit.title) {
      criteria.push(buildCriterionFromParsedParts(inlineSplit.title, inlineSplit.sections, globalPoints));
      continue;
    }

    if (isPotentialCriterionTitle(line)) {
      const sectionLines = {};
      let used = 0;
      let j = i + 1;
      while (j < lines.length && used < 8) {
        const nextLine = lines[j];
        if (!nextLine) break;
        if (isPotentialCriterionTitle(nextLine) && !/^(excellent|good|fair|needs\s*improvement)\b/i.test(nextLine)) break;
        const levelMatch = nextLine.match(/^(Excellent|Good|Fair|Needs\s*Improvement)\b\s*[:\-–|]?\s*(.*)$/i);
        if (levelMatch) {
          const key = normalizeRubricLevelKey(levelMatch[1]);
          sectionLines[key] = levelMatch[2].trim();
          used += 1;
          j += 1;
          continue;
        }
        if (countRubricLevelMarkers(nextLine) >= 2) {
          const parsed = splitLineByRubricLevels(nextLine);
          if (parsed) {
            Object.assign(sectionLines, parsed.sections);
            used += 1;
            j += 1;
            break;
          }
        }
        if (Object.keys(sectionLines).length) {
          const lastKey = Object.keys(sectionLines)[Object.keys(sectionLines).length - 1];
          sectionLines[lastKey] = `${sectionLines[lastKey]} ${nextLine}`.trim();
          used += 1;
          j += 1;
          continue;
        }
        break;
      }

      if (Object.keys(sectionLines).length >= 2) {
        criteria.push(buildCriterionFromParsedParts(line, sectionLines, globalPoints));
        i = j - 1;
      }
    }
  }

  if (criteria.length) return criteria;

  const fallbackLines = lines.filter(line => isPotentialCriterionTitle(line)).slice(0, 8);
  return fallbackLines.map((line, index) => {
    const title = cleanCriterionTitle(line) || `Criterion ${index + 1}`;
    const ruleInfo = guessCriterionRule(title, '');
    return normalizeCriterion({
      id: createId(),
      title,
      points: 4,
      rule: ruleInfo.rule,
      target: ruleInfo.target,
      levels: normalizeLevels(null, 4)
    });
  });
}

function guessImportedActivityTitle(lines) {
  const candidates = lines.filter(line => {
    const lower = line.toLowerCase();
    return line.length > 4
      && line.length < 100
      && !isLikelyHeaderLine(line)
      && !/^(excellent|good|fair|needs\s*improvement)\b/i.test(lower)
      && !/^\d+(?:\.\d+)?\s*(pts?|points?)?$/i.test(lower);
  });
  const explicit = candidates.find(line => /activity|performance task|project|rubric/i.test(line));
  return explicit || candidates[0] || 'Imported Rubric Activity';
}

function guessImportedActivityDescription(lines, title) {
  const titleIndex = lines.findIndex(line => line === title);
  const from = titleIndex >= 0 ? titleIndex + 1 : 1;
  const descriptionLines = lines.slice(from, Math.min(from + 4, lines.length))
    .filter(line => !isLikelyHeaderLine(line) && countRubricLevelMarkers(line) < 2 && line.length > 12);
  if (descriptionLines.length) return descriptionLines.join(' ');
  return 'Complete the activity based on the uploaded rubric. Review the imported rows before saving.';
}

function parseImportedActivityFromText(text) {
  const normalizedText = normalizeOCRText(text);
  const lines = normalizedText.split('\n').map(line => line.trim()).filter(Boolean);
  const title = guessImportedActivityTitle(lines);
  const description = guessImportedActivityDescription(lines, title);
  const passingMatch = normalizedText.match(/passing\s*score\s*[:\-]?\s*(\d+(?:\.\d+)?)/i);
  const passingScore = passingMatch ? Number(passingMatch[1]) : 75;
  const criteria = parseCriteriaFromRubricText(normalizedText);
  return normalizeImportedActivity({ title, description, passingScore, criteria });
}

function fillRubricTableFromExtractedText() {
  const text = rubricExtractedText?.value?.trim() || '';
  if (!text) {
    setRubricImportStatus('No extracted text yet. Upload an image first or paste rubric text into the box.', 'error');
    return;
  }
  const imported = parseImportedActivityFromText(text);
  applyImportedActivityToAdminForm(imported);
}


/* Fixed 5-column rubric reader for Sir JR's rubric image format.
   Expected columns:
   1) Criteria
   2) Excellent
   3) Good
   4) Fair
   5) Needs Improvement
*/

function safeRubricWordText(word) {
  return String(word?.text || word?.symbols?.map(symbol => symbol.text).join('') || '').trim();
}

function getRubricWordBox(word) {
  const box = word?.bbox || word?.boundingBox || {};
  const x0 = Number(box.x0 ?? box.left ?? box.x ?? 0);
  const y0 = Number(box.y0 ?? box.top ?? box.y ?? 0);
  const x1 = Number(box.x1 ?? (Number.isFinite(Number(box.width)) ? x0 + Number(box.width) : x0));
  const y1 = Number(box.y1 ?? (Number.isFinite(Number(box.height)) ? y0 + Number(box.height) : y0));
  return { x0, y0, x1, y1, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, h: Math.max(1, y1 - y0) };
}

function normalizeRubricOCRWords(words) {
  return (Array.isArray(words) ? words : [])
    .map(word => {
      const text = safeRubricWordText(word);
      const box = getRubricWordBox(word);
      return text ? { text, ...box } : null;
    })
    .filter(Boolean)
    .filter(word => Number.isFinite(word.cx) && Number.isFinite(word.cy));
}

function groupRubricWordsIntoLines(words) {
  const cleanWords = normalizeRubricOCRWords(words).sort((a, b) => a.cy - b.cy || a.x0 - b.x0);
  const lines = [];

  cleanWords.forEach(word => {
    const tolerance = Math.max(8, word.h * 0.65);
    let line = lines.find(item => Math.abs(item.cy - word.cy) <= tolerance);
    if (!line) {
      line = { cy: word.cy, words: [] };
      lines.push(line);
    }
    line.words.push(word);
    line.cy = line.words.reduce((sum, item) => sum + item.cy, 0) / line.words.length;
  });

  return lines
    .map(line => ({
      cy: line.cy,
      words: line.words.sort((a, b) => a.x0 - b.x0),
      text: line.words.sort((a, b) => a.x0 - b.x0).map(word => word.text).join(' ')
    }))
    .sort((a, b) => a.cy - b.cy);
}

function detectFiveRubricColumnCenters(words) {
  const cleanWords = normalizeRubricOCRWords(words);
  if (!cleanWords.length) return null;

  const byText = cleanWords.map(word => ({ ...word, lower: word.text.toLowerCase().replace(/[^a-z]/g, '') }));
  const findCenter = patterns => {
    const matches = byText.filter(word => patterns.some(pattern => pattern.test(word.lower)));
    if (!matches.length) return null;
    return matches.reduce((sum, word) => sum + word.cx, 0) / matches.length;
  };

  const criteriaX = findCenter([/^criteria?$/, /^criterion$/]);
  const excellentX = findCenter([/^excellent$/, /^advanced$/, /^outstanding$/]);
  const goodX = findCenter([/^good$/, /^proficient$/]);
  const fairX = findCenter([/^fair$/, /^developing$/, /^satisfactory$/]);

  const needsWords = byText.filter(word => /^needs?$/.test(word.lower));
  const improvementWords = byText.filter(word => /^improvements?$/.test(word.lower));
  let needsX = null;
  if (needsWords.length && improvementWords.length) {
    const pairs = [];
    needsWords.forEach(needs => {
      improvementWords.forEach(improvement => {
        const distance = Math.abs(needs.cy - improvement.cy) + Math.abs(needs.cx - improvement.cx) * 0.15;
        pairs.push({ needs, improvement, distance });
      });
    });
    pairs.sort((a, b) => a.distance - b.distance);
    const best = pairs[0];
    needsX = best ? (best.needs.cx + best.improvement.cx) / 2 : null;
  } else {
    needsX = findCenter([/^needsimprovement$/, /^poor$/, /^beginning$/]);
  }

  let centers = [criteriaX, excellentX, goodX, fairX, needsX];
  const validCenters = centers.filter(value => Number.isFinite(value));

  if (validCenters.length >= 4) {
    const minX = Math.min(...validCenters);
    const maxX = Math.max(...validCenters);
    const width = Math.max(1, maxX - minX);
    centers = centers.map((value, index) => Number.isFinite(value) ? value : minX + (width * index / 4));
    return centers.sort((a, b) => a - b);
  }

  const minX = Math.min(...cleanWords.map(word => word.x0));
  const maxX = Math.max(...cleanWords.map(word => word.x1));
  const width = Math.max(1, maxX - minX);
  return [0.1, 0.32, 0.52, 0.7, 0.88].map(ratio => minX + width * ratio);
}

function getColumnIndexFromCenters(x, centers) {
  if (!Array.isArray(centers) || centers.length !== 5) return 0;
  const boundaries = [
    -Infinity,
    (centers[0] + centers[1]) / 2,
    (centers[1] + centers[2]) / 2,
    (centers[2] + centers[3]) / 2,
    (centers[3] + centers[4]) / 2,
    Infinity
  ];
  for (let i = 0; i < 5; i += 1) {
    if (x >= boundaries[i] && x < boundaries[i + 1]) return i;
  }
  return 0;
}

function lineWordsToFiveCells(line, centers) {
  const cells = ['', '', '', '', ''];
  (line?.words || []).forEach(word => {
    const index = getColumnIndexFromCenters(word.cx, centers);
    cells[index] = `${cells[index]} ${word.text}`.trim();
  });
  return cells.map(cell => cell.trim());
}

function isFiveColumnHeaderCells(cells) {
  const joined = cells.join(' ').toLowerCase();
  return /criteria?|criterion/.test(joined)
    && /excellent/.test(joined)
    && /\bgood\b/.test(joined)
    && /\bfair\b/.test(joined)
    && /needs?\s*improvement/.test(joined);
}

function normalizeFiveColumnCellsToCriterion(cells, globalPoints = {}) {
  const title = cleanCriterionTitle(cells[0]);
  if (!title || title.length < 3) return null;

  const sections = {
    excellent: cells[1] || '',
    good: cells[2] || '',
    fair: cells[3] || '',
    needsImprovement: cells[4] || ''
  };

  const hasUsefulLevelText = Object.values(sections).some(value => String(value || '').trim().length > 4);
  if (!hasUsefulLevelText) return null;

  return buildCriterionFromParsedParts(title, sections, globalPoints);
}

function parseFiveColumnRubricFromOCRResult(ocrResult) {
  const words = ocrResult?.data?.words || ocrResult?.words || [];
  const cleanWords = normalizeRubricOCRWords(words);
  if (cleanWords.length < 10) return [];

  const centers = detectFiveRubricColumnCenters(cleanWords);
  if (!centers) return [];

  const lines = groupRubricWordsIntoLines(cleanWords);
  const globalPoints = extractGlobalLevelPoints(ocrResult?.data?.text || ocrResult?.text || '');
  const rows = [];
  let current = null;

  lines.forEach(line => {
    const cells = lineWordsToFiveCells(line, centers);
    const rowText = cells.join(' ').trim();
    if (!rowText || isFiveColumnHeaderCells(cells) || isLikelyHeaderLine(rowText)) return;

    const hasCriteriaText = cells[0].trim().length > 0;
    const hasLevelText = cells.slice(1).some(cell => cell.trim().length > 0);

    if (hasCriteriaText && hasLevelText) {
      current = cells;
      rows.push(current);
      return;
    }

    if (current && hasLevelText) {
      for (let i = 1; i < 5; i += 1) {
        if (cells[i]) current[i] = `${current[i]} ${cells[i]}`.trim();
      }
      return;
    }

    if (current && hasCriteriaText && !hasLevelText) {
      current[0] = `${current[0]} ${cells[0]}`.trim();
    }
  });

  return rows
    .map(cells => normalizeFiveColumnCellsToCriterion(cells, globalPoints))
    .filter(Boolean);
}

function splitFixedRubricLineIntoFiveCells(line) {
  const source = String(line || '').trim();
  if (!source) return null;

  if (source.includes('|')) {
    const parts = source.split('|').map(part => part.trim()).filter(Boolean);
    if (parts.length >= 5) return [parts[0], parts[1], parts[2], parts[3], parts.slice(4).join(' ')];
  }

  if (/\t/.test(source)) {
    const parts = source.split(/\t+/).map(part => part.trim()).filter(Boolean);
    if (parts.length >= 5) return [parts[0], parts[1], parts[2], parts[3], parts.slice(4).join(' ')];
  }

  const spaced = source.split(/\s{3,}/).map(part => part.trim()).filter(Boolean);
  if (spaced.length >= 5) return [spaced[0], spaced[1], spaced[2], spaced[3], spaced.slice(4).join(' ')];

  const levelSplit = splitLineByRubricLevels(source);
  if (levelSplit && levelSplit.title) {
    return [
      levelSplit.title,
      levelSplit.sections.excellent || '',
      levelSplit.sections.good || '',
      levelSplit.sections.fair || '',
      levelSplit.sections.needsImprovement || ''
    ];
  }

  return null;
}

function parseFiveColumnRubricFromText(text) {
  const normalizedText = normalizeOCRText(text);
  const lines = normalizedText.split('\n').map(line => line.trim()).filter(Boolean);
  const globalPoints = extractGlobalLevelPoints(normalizedText);
  const rows = [];
  let current = null;
  let headerSeen = false;

  lines.forEach(line => {
    const cells = splitFixedRubricLineIntoFiveCells(line);

    if (cells) {
      if (isFiveColumnHeaderCells(cells)) {
        headerSeen = true;
        return;
      }

      const candidate = normalizeFiveColumnCellsToCriterion(cells, globalPoints);
      if (candidate) {
        rows.push(candidate);
        current = rows[rows.length - 1];
      }
      return;
    }

    if (!headerSeen && isLikelyHeaderLine(line)) return;

    const levelMatch = line.match(/^(Excellent|Good|Fair|Needs\s*Improvement)\b\s*[:\-–|]?\s*(.*)$/i);
    if (current && levelMatch) {
      const key = normalizeRubricLevelKey(levelMatch[1]);
      const rawText = levelMatch[2].trim();
      const oldLevels = normalizeLevels(current.levels, current.points);
      oldLevels[key] = {
        ...oldLevels[key],
        description: `${oldLevels[key]?.description || ''} ${stripLeadingScoreText(rawText)}`.trim(),
        points: extractScoreValue(rawText, oldLevels[key]?.points)
      };
      current.levels = oldLevels;
    }
  });

  return rows;
}

// Override the earlier general parser: try the expected 5-column table first.
function parseCriteriaFromRubricText(text) {
  const fixedTableCriteria = parseFiveColumnRubricFromText(text);
  if (fixedTableCriteria.length) return fixedTableCriteria;
  return parseCriteriaFromRubricTextGeneral(text);
}

// Override local OCR: use word positions so the app knows the left column is Criteria and columns 2-5 are levels.
async function runLocalRubricOCR(file) {
  const Tesseract = await loadRubricOCRLibrary();
  const result = await Tesseract.recognize(file, 'eng', {
    logger: message => {
      if (message?.status === 'recognizing text' && Number.isFinite(message.progress)) {
        setRubricImportStatus(`Reading image table... ${Math.round(message.progress * 100)}%`, 'loading');
      }
    }
  });

  const extractedText = normalizeOCRText(result?.data?.text || '');
  const criteriaFromLayout = parseFiveColumnRubricFromOCRResult(result);
  window.__lastRubricOCRActivity = criteriaFromLayout.length
    ? normalizeImportedActivity({
        title: 'Imported Rubric Activity',
        description: 'Complete the activity based on the uploaded 5-column rubric. Review the imported rows before saving.',
        passingScore: 75,
        criteria: criteriaFromLayout
      })
    : null;

  return extractedText;
}


async function importRubricImage() {
  if (!isRubricImageImportEnabled()) {
    setRubricImportStatus('Rubric image import is disabled in firebase-config.js.', 'error');
    return;
  }

  const file = getSelectedRubricImageFile();
  if (!file) {
    setRubricImportStatus('Choose a rubric image first.', 'error');
    return;
  }

  const endpoint = getRubricImageEndpoint();

  try {
    importRubricImageBtn.disabled = true;
    importRubricImageBtn.textContent = 'Reading image...';
    setRubricImportStatus(endpoint ? 'Reading rubric image. Please wait...' : 'No online reader detected. Using built-in browser image reader...', 'loading');

    let importedActivity = null;

    if (endpoint) {
      const imageDataUrl = await readFileAsDataURL(file);
      const currentUser = firebaseSync.auth?.currentUser || firebaseSync.currentUser;
      let idToken = '';
      if (currentUser && typeof currentUser.getIdToken === 'function') {
        idToken = await currentUser.getIdToken();
      }

      const headers = { 'Content-Type': 'application/json' };
      if (idToken) headers.Authorization = `Bearer ${idToken}`;

      const response = await fetch(endpoint, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          imageDataUrl,
          filename: file.name,
          mimeType: file.type,
          currentActivityTitle: adminActivityTitle?.value || '',
          expectedLevels: rubricLevels.map(item => item.label)
        })
      });

      if (!response.ok) throw new Error(`Image import endpoint returned ${response.status}`);
      const data = await response.json();
      importedActivity = data.activity || data.rubric || data;
      if (rubricExtractedText && data.extractedText) rubricExtractedText.value = normalizeOCRText(data.extractedText);
    } else {
      const extractedText = await runLocalRubricOCR(file);
      if (rubricExtractedText) rubricExtractedText.value = extractedText;
      importedActivity = window.__lastRubricOCRActivity || parseImportedActivityFromText(extractedText);
    }

    applyImportedActivityToAdminForm(importedActivity);
  } catch (error) {
    console.warn('Rubric image import failed', error);
    setRubricImportStatus('Could not read the rubric image. Try a clearer screenshot, then review/edit the extracted text.', 'error');
  } finally {
    importRubricImageBtn.disabled = false;
    importRubricImageBtn.textContent = 'Read Image & Fill Table';
  }
}


function setManualRubricStatus(message, type = '') {
  if (!manualRubricStatus) return;
  manualRubricStatus.textContent = message || '';
  manualRubricStatus.className = `helper-note manual-rubric-status ${type}`.trim();
}

function getManualRubricScore(input, fallback) {
  const value = Number(input?.value);
  return Number.isFinite(value) && value >= 0 ? value : fallback;
}

function getManualRubricScoreMap() {
  return {
    excellent: getManualRubricScore(manualExcellentScore, 10),
    good: getManualRubricScore(manualGoodScore, 8),
    fair: getManualRubricScore(manualFairScore, 6),
    needsImprovement: getManualRubricScore(manualNeedsScore, 4)
  };
}

function createManualRubricTextarea(className, placeholder, value = '') {
  const textarea = document.createElement('textarea');
  textarea.className = className;
  textarea.rows = className.includes('manual-criteria-input') ? 3 : 4;
  textarea.placeholder = placeholder;
  textarea.value = value || '';
  return textarea;
}

function addManualRubricInputRow(data = {}) {
  if (!manualRubricInputBody) return;

  const row = document.createElement('tr');
  row.className = 'manual-rubric-input-row';

  const cells = [
    { key: 'criteria', className: 'manual-criteria-input', placeholder: 'Example: HTML Structure & Semantic Tags' },
    { key: 'excellent', className: 'manual-level-input', placeholder: 'All requirements completed accurately; exceeded expectations' },
    { key: 'good', className: 'manual-level-input', placeholder: 'Most requirements completed properly' },
    { key: 'fair', className: 'manual-level-input', placeholder: 'Some requirements missing or inaccurate' },
    { key: 'needsImprovement', className: 'manual-level-input', placeholder: 'Few requirements met; needs improvement' }
  ];

  const cellLabels = {
    criteria: 'Criteria',
    excellent: 'Excellent',
    good: 'Good',
    fair: 'Satisfactory / Fair',
    needsImprovement: 'Needs Improvement'
  };

  cells.forEach(cellInfo => {
    const cell = document.createElement('td');
    cell.dataset.label = cellLabels[cellInfo.key] || cellInfo.key;
    cell.appendChild(createManualRubricTextarea(cellInfo.className, cellInfo.placeholder, data[cellInfo.key] || ''));
    row.appendChild(cell);
  });

  const actionCell = document.createElement('td');
  actionCell.dataset.label = 'Action';
  actionCell.className = 'manual-rubric-row-action';
  const removeButton = document.createElement('button');
  removeButton.type = 'button';
  removeButton.className = 'ghost-btn danger remove-manual-rubric-row';
  removeButton.textContent = 'Remove';
  actionCell.appendChild(removeButton);
  row.appendChild(actionCell);

  manualRubricInputBody.appendChild(row);
}

function ensureManualRubricRows() {
  if (!manualRubricInputBody) return;
  if (manualRubricInputBody.children.length) return;
  for (let index = 0; index < 4; index += 1) {
    addManualRubricInputRow();
  }
}

function clearManualRubricInputTable() {
  if (!manualRubricInputBody) return;
  manualRubricInputBody.innerHTML = '';
  ensureManualRubricRows();
  setManualRubricStatus('Input table cleared. Type your rubric again, then click Apply Rubric Table.');
}

function collectManualRubricInputCriteria() {
  if (!manualRubricInputBody) return [];
  const scores = getManualRubricScoreMap();
  const rows = [...manualRubricInputBody.querySelectorAll('.manual-rubric-input-row')];

  return rows.map((row, index) => {
    const criterionTitle = row.querySelector('.manual-criteria-input')?.value.trim() || '';
    const excellent = row.querySelector('td[data-label="excellent"] textarea')?.value.trim() || '';
    const good = row.querySelector('td[data-label="good"] textarea')?.value.trim() || '';
    const fair = row.querySelector('td[data-label="fair"] textarea')?.value.trim() || '';
    const needsImprovement = row.querySelector('td[data-label="needsImprovement"] textarea')?.value.trim() || '';
    const hasAnyText = [criterionTitle, excellent, good, fair, needsImprovement].some(Boolean);
    if (!hasAnyText) return null;

    const cleanTitle = criterionTitle || `Criterion ${index + 1}`;
    return buildCriterionFromParsedParts(cleanTitle, {
      excellent,
      good,
      fair,
      needsImprovement
    }, scores);
  }).filter(Boolean);
}

function applyManualRubricTableToActualRubric() {
  const criteria = collectManualRubricInputCriteria();
  if (!criteria.length) {
    setManualRubricStatus('Please type at least one criterion and description before applying.', 'error');
    return;
  }

  const imported = normalizeImportedActivity({
    id: adminEditingActivityId || createId(),
    title: adminActivityTitle?.value?.trim() || 'Manual Rubric Activity',
    description: adminActivityDescription?.value?.trim() || 'Complete the activity based on the teacher rubric.',
    passingScore: Number(adminPassingScore?.value) || 75,
    criteria
  });

  applyImportedActivityToAdminForm(imported);
  setManualRubricStatus(`Applied ${criteria.length} row${criteria.length === 1 ? '' : 's'} and generated smart rubric checks. Review them, then click Save Activity.`, 'success');
}


function setAiRubricGeneratorStatus(message, type = '') {
  if (aiRubricGeneratorStatus) {
    aiRubricGeneratorStatus.textContent = message || '';
    aiRubricGeneratorStatus.className = `helper-note ai-rubric-generator-status ${type}`.trim();
  }
  if (message) setManualRubricStatus(message, type);
}

function getManualRubricDraftForAi() {
  const scores = getManualRubricScoreMap();
  const rows = [...(manualRubricInputBody?.querySelectorAll('.manual-rubric-input-row') || [])].map((row, index) => ({
    index: index + 1,
    criterion: row.querySelector('.manual-criteria-input')?.value.trim() || '',
    excellent: row.querySelector('td[data-label="excellent"] textarea')?.value.trim() || '',
    good: row.querySelector('td[data-label="good"] textarea')?.value.trim() || '',
    fair: row.querySelector('td[data-label="fair"] textarea')?.value.trim() || '',
    needsImprovement: row.querySelector('td[data-label="needsImprovement"] textarea')?.value.trim() || ''
  })).filter(row => [row.criterion, row.excellent, row.good, row.fair, row.needsImprovement].some(Boolean));

  return {
    title: adminActivityTitle?.value?.trim() || '',
    description: adminActivityDescription?.value?.trim() || '',
    passingScore: Number(adminPassingScore?.value) || 75,
    scores,
    existingRows: rows,
    currentCriteria: collectCriteriaFromEditor().map(item => ({
      title: item.title,
      points: getCriterionPossiblePoints(item),
      levels: item.levels
    }))
  };
}

function buildAiRubricGeneratorPrompt({ mode = 'generate' } = {}) {
  const draft = getManualRubricDraftForAi();
  const taskTitle = draft.title || 'Web coding activity';
  const taskDescription = draft.description || 'Create a web page using HTML, CSS, and JavaScript as required by the teacher.';
  return `You are an expert Grade 8 ICT teacher and rubric designer. Create or improve a practical web-coding rubric for beginner students.

The rubric must be consistent, specific, and easy for students to understand. Do not create auto-check rules or keyword targets. The rubric descriptions will later be judged against the student's code and rendered output by Gemini or the local fallback.

Return ONLY valid JSON. No markdown.

Required JSON schema:
{
  "title": "activity title",
  "description": "student instructions",
  "passingScore": 75,
  "criteria": [
    {
      "title": "criterion name",
      "points": 10,
      "levels": {
        "excellent": {"points":10,"description":"specific excellent description"},
        "good": {"points":8,"description":"specific good description"},
        "fair": {"points":6,"description":"specific fair description"},
        "needsImprovement": {"points":4,"description":"specific needs improvement description"}
      }
    }
  ]
}

Rubric requirements:
- Use 4 to 6 criteria unless the existing draft clearly needs fewer.
- Use the teacher's score levels: Excellent=${draft.scores.excellent}, Good=${draft.scores.good}, Fair=${draft.scores.fair}, Needs Improvement=${draft.scores.needsImprovement}.
- Make criterion titles short and clear.
- Descriptions must explain observable evidence in code or output.
- Do not create criteria that require private data or external accounts.
- Mode: ${mode}.

CONTEXT JSON:
${JSON.stringify({ taskTitle, taskDescription, draft }, null, 2)}`;
}

function createLocalSmartRubricActivity() {
  const title = adminActivityTitle?.value?.trim() || 'Smart Starter Rubric Activity';
  const description = adminActivityDescription?.value?.trim() || 'Complete the web coding activity based on the teacher rubric.';
  const scores = getManualRubricScoreMap();
  const lower = `${title} ${description}`.toLowerCase();
  const candidates = [
    { title: 'HTML Structure and Content', text: 'complete HTML structure, correct tags, and meaningful visible content' },
    { title: 'CSS Styling and Layout', text: 'colors, spacing, fonts, and layout make the page readable and organized' },
    { title: 'Output Matches the Instructions', text: 'the preview clearly shows the required content and follows the activity task' },
    { title: 'Code Organization and Accuracy', text: 'code is readable, properly closed, and avoids obvious errors' }
  ];
  if (/javascript|button|click|interactive|event/.test(lower)) candidates.splice(2, 0, { title: 'JavaScript Interaction', text: 'JavaScript creates the required interaction or visible page change' });
  if (/responsive|phone|mobile|screen/.test(lower)) candidates.push({ title: 'Responsive Design', text: 'layout remains readable on smaller screens using flexible CSS' });

  const criteria = candidates.slice(0, 6).map(item => buildCriterionFromParsedParts(item.title, {
    excellent: `Complete and accurate ${item.text}.`,
    good: `Mostly complete ${item.text} with only minor issues.`,
    fair: `Partially shows ${item.text}, but some requirements are missing or unclear.`,
    needsImprovement: `Little evidence of ${item.text}; major revision is needed.`
  }, scores)).map(criterion => normalizeCriterion({ ...criterion, rule: 'smart_rubric', target: '' }));

  return normalizeImportedActivity({
    id: adminEditingActivityId || createId(),
    title,
    description,
    passingScore: Number(adminPassingScore?.value) || 75,
    criteria
  });
}

function itemRuleFallback(rule) {
  return ruleOptions.some(option => option.value === rule) ? rule : 'smart_rubric';
}

async function generateRubricWithAi(mode = 'generate') {
  if (!shouldUseGeminiRubricGenerator(getCurrentAiRubricSettings())) {
    const fallback = createLocalSmartRubricActivity();
    applyImportedActivityToAdminForm(fallback);
    setAiRubricGeneratorStatus('Gemini is not enabled for rubric generation, so a smart local starter rubric was created. Review it, then save.', 'warning');
    return;
  }

  const button = mode === 'improve' ? aiImproveRubricBtn : aiGenerateRubricBtn;
  const oldText = button?.textContent || '';
  try {
    if (button) {
      button.disabled = true;
      button.textContent = mode === 'improve' ? 'Improving...' : 'Generating...';
    }
    setAiRubricGeneratorStatus('Gemini is creating a smarter rubric. Please wait...', 'loading');
    const settings = getCurrentAiRubricSettings();
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), 45000);
    const raw = await callGeminiJson(settings, buildAiRubricGeneratorPrompt({ mode }), {
      signal: controller.signal,
      maxOutputTokens: 4096,
      temperature: 0.15
    });
    window.clearTimeout(timeout);
    const imported = normalizeImportedActivity(raw);
    applyImportedActivityToAdminForm(imported);
    setAiRubricGeneratorStatus('Smart rubric generated. Review the table carefully, then click Save Activity.', 'success');
  } catch (error) {
    console.warn('Smart rubric generator failed; using local starter rubric.', error);
    const fallback = createLocalSmartRubricActivity();
    applyImportedActivityToAdminForm(fallback);
    setAiRubricGeneratorStatus(`Smart rubric generation failed, so a local rubric was created. ${error?.message || ''}`.trim(), 'warning');
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = oldText;
    }
  }
}

